import {
  getOfflineMintAgentSteps,
  type OfflineMintAgentStep,
} from "../../offline/mock_data";
import { generateDemoTxHash } from "../stores/crossChainTransferStore";

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type ExecuteOfflineMintAgentParams = {
  displayName: string;
  handle: string;
  memoryMb: number;
  marketSymbol: string;
  agentId: string;
};

export type OfflineMintAgentProgressCallbacks = {
  onStepStart?: (step: OfflineMintAgentStep) => void;
};

export type ExecuteOfflineMintAgentResult = {
  demoTxHash: string;
  agentId: string;
};

export async function executeOfflineMintAgent(
  params: ExecuteOfflineMintAgentParams,
  callbacks?: OfflineMintAgentProgressCallbacks,
): Promise<ExecuteOfflineMintAgentResult> {
  const agentId = params.agentId.trim();
  if (!agentId) {
    throw new Error("Agent id is required");
  }

  const steps = getOfflineMintAgentSteps({
    displayName: params.displayName,
    handle: params.handle,
    memoryMb: params.memoryMb,
    marketSymbol: params.marketSymbol,
  });

  for (const step of steps) {
    callbacks?.onStepStart?.(step);
    await delay(step.delayMs);
  }

  return {
    demoTxHash: generateDemoTxHash(agentId.slice(0, 4)),
    agentId,
  };
}
