/**
 * Wallet-scoped vault deposit / share state (offline demo).
 */

import { addDemoCreatedBucket, applyDemoVaultSpotSettlement } from "./mockBucketState";
import { appendVaultFundsMovementToPortfolio } from "./portfolioWalletState";
import { buildDefaultVaultTradingBucket } from "./vaultBucketFactory";
import {
  addVaultToCatalog,
  getVaultById,
  isVaultIdTaken,
  updateVaultInCatalog,
  type VaultRecord,
} from "./vaultCatalog";
import {
  allocateUniqueVaultId,
  upsertVaultRecord,
} from "./vaultRegistryStorage";
import type {
  VaultDepositorRow,
  VaultFundsMovementRow,
} from "./vaultMockData.types";

const STORAGE_PREFIX = "offline_vault_user_";

export interface VaultUserPosition {
  vaultId: string;
  depositUsd: number;
  shares: number;
  allTimeEarnedUsd: number;
  lockedUsd: number;
  lockedUnlockAtMs: number | null;
}

export interface VaultUserState {
  positions: Record<string, VaultUserPosition>;
  createdVaultIds: string[];
  fundsMovements?: VaultFundsMovementRow[];
}

export type CreateVaultFailureReason =
  | "wallet_required"
  | "invalid_deposit"
  | "insufficient_balance";

export type CreateVaultResult =
  | { ok: true; vault: VaultRecord; position: VaultUserPosition }
  | { ok: false; reason: CreateVaultFailureReason };

let stateRevision = 0;

const listeners = new Set<() => void>();

function storageKey(wallet: string): string {
  return `${STORAGE_PREFIX}${wallet.trim().toLowerCase()}`;
}

function emptyState(): VaultUserState {
  return { positions: {}, createdVaultIds: [], fundsMovements: [] };
}

function normalizeState(state: VaultUserState): VaultUserState {
  return {
    positions: state.positions ?? {},
    createdVaultIds: state.createdVaultIds ?? [],
    fundsMovements: state.fundsMovements ?? [],
  };
}

function fundsMovementsForVault(
  state: VaultUserState,
  vaultId: string,
): VaultFundsMovementRow[] {
  return (state.fundsMovements ?? []).filter((row) => row.vaultId === vaultId);
}

function appendFundsMovement(
  state: VaultUserState,
  row: VaultFundsMovementRow,
): void {
  if (!state.fundsMovements) {
    state.fundsMovements = [];
  }
  state.fundsMovements.push(row);
}

export function getWalletFundsMovements(
  wallet: string,
  vaultId: string,
): VaultFundsMovementRow[] {
  if (!wallet.trim()) return [];
  return fundsMovementsForVault(readState(wallet), vaultId);
}

export function mergeVaultFundsMovements(
  base: VaultFundsMovementRow[],
  overlay: VaultFundsMovementRow[],
): VaultFundsMovementRow[] {
  return [...overlay, ...base].sort((a, b) => b.time - a.time);
}

export function mergeVaultDepositors(
  base: VaultDepositorRow[],
  wallet: string,
  vaultId: string,
  vault: VaultRecord,
): VaultDepositorRow[] {
  const position = wallet.trim()
    ? readState(wallet).positions[vaultId]
    : undefined;
  const walletLower = wallet.trim().toLowerCase();
  const leaderLower = vault.leaderAddress.trim().toLowerCase();

  let rows = base.filter((row) => {
    if (!walletLower) return true;
    return row.address.trim().toLowerCase() !== walletLower;
  });

  if (position && position.depositUsd > 0.01) {
    const isLeader = walletLower === leaderLower;
    rows.push({
      vaultId,
      address: wallet.trim(),
      isLeader,
      vaultAmountUsd: position.depositUsd,
      unrealizedPnlUsd: 0,
      allTimePnlUsd: position.allTimeEarnedUsd,
      daysFollowing: 1,
    });
  }

  const followers = rows.filter((row) => !row.isLeader);
  const leader = rows.find((row) => row.isLeader);
  return leader ? [...followers, leader] : followers;
}

function notify(): void {
  stateRevision += 1;
  listeners.forEach((fn) => fn());
}

export function getVaultUserStateRevision(): number {
  return stateRevision;
}

export function subscribeVaultUserState(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function readState(wallet: string): VaultUserState {
  if (typeof localStorage === "undefined" || !wallet.trim()) return emptyState();
  try {
    const raw = localStorage.getItem(storageKey(wallet));
    if (!raw) return emptyState();
    return normalizeState(JSON.parse(raw) as VaultUserState);
  } catch {
    return emptyState();
  }
}

function writeState(wallet: string, state: VaultUserState): void {
  if (typeof localStorage === "undefined" || !wallet.trim()) return;
  localStorage.setItem(storageKey(wallet), JSON.stringify(state));
}

/** Seed demo deposit once when user first opens Vault with a connected wallet. */
function seedDefaultDeposits(wallet: string): VaultUserState {
  const state: VaultUserState = {
    positions: {
      "delta-neutral-mm-1": {
        vaultId: "delta-neutral-mm-1",
        depositUsd: 500,
        shares: 985.4,
        allTimeEarnedUsd: 42.1,
        lockedUsd: 230.1,
        lockedUnlockAtMs:
          Date.now() + 2 * 24 * 60 * 60 * 1000 + 6 * 60 * 60 * 1000,
      },
    },
    createdVaultIds: [],
  };
  writeState(wallet, state);
  return state;
}

export function ensureVaultUserStateSeeded(wallet: string): void {
  if (typeof localStorage === "undefined" || !wallet.trim()) return;
  if (localStorage.getItem(storageKey(wallet))) return;
  seedDefaultDeposits(wallet);
  notify();
}

export function notifyVaultStateChange(): void {
  notify();
}

export function getVaultUserState(wallet: string): VaultUserState {
  return readState(wallet);
}

export function getVaultDepositUsd(wallet: string, vaultId: string): number {
  return readState(wallet).positions[vaultId]?.depositUsd ?? 0;
}

/** Sum of user depositUsd across all vault positions (wallet-scoped). */
export function getTotalUserValueLockedUsd(wallet: string): number {
  const { positions } = readState(wallet);
  return Object.values(positions).reduce((sum, pos) => sum + pos.depositUsd, 0);
}

/** Count of vault positions with a non-zero deposit (wallet-scoped). */
export function getInvestedVaultCount(wallet: string): number {
  const { positions } = readState(wallet);
  return Object.values(positions).filter((p) => p.depositUsd > 0.01).length;
}

export function getVaultUserPosition(
  wallet: string,
  vaultId: string,
): VaultUserPosition | undefined {
  return readState(wallet).positions[vaultId];
}

function syncUserVaultTvl(vaultId: string, deltaUsd: number): void {
  const vault = getVaultById(vaultId);
  if (!vault || vault.kind !== "user") return;

  const nextTvl = Math.max(0, vault.tvlUsd + deltaUsd);
  const nextBuckets = vault.buckets.map((bucket, index) => {
    if (index !== 0) return bucket;
    return {
      ...bucket,
      equityUsd: Math.max(0, bucket.equityUsd + deltaUsd),
    };
  });

  updateVaultInCatalog(vaultId, {
    tvlUsd: nextTvl,
    buckets: nextBuckets,
    analystVerdict: {
      metrics: {
        ...vault.analystVerdict.metrics,
        tvlUsd: nextTvl,
      },
    },
  });
}

export function recordVaultDeposit(
  wallet: string,
  vaultId: string,
  amountUsd: number,
  vault: VaultRecord,
  options?: { skipSpotSettlement?: boolean },
): VaultUserPosition | undefined {
  if (!wallet.trim() || amountUsd <= 0) return undefined;

  const transferId = `vault-deposit:${vaultId}:${Date.now()}:${amountUsd.toFixed(2)}`;
  if (!options?.skipSpotSettlement) {
    const settled = applyDemoVaultSpotSettlement(wallet, {
      transferId,
      amount: amountUsd,
      mode: "deposit",
    });
    if (!settled) return undefined;
  }

  const state = readState(wallet);
  const existing = state.positions[vaultId];
  const sharePrice =
    vault.tvlUsd > 0 ? vault.tvlUsd / Math.max(vault.tvlUsd / 1000, 1) : 1;
  const newShares = (amountUsd / sharePrice) * 0.985;
  const next: VaultUserPosition = {
    vaultId,
    depositUsd: (existing?.depositUsd ?? 0) + amountUsd,
    shares: (existing?.shares ?? 0) + newShares,
    allTimeEarnedUsd: existing?.allTimeEarnedUsd ?? 0,
    lockedUsd: (existing?.lockedUsd ?? 0) + amountUsd,
    lockedUnlockAtMs: Date.now() + 4 * 24 * 60 * 60 * 1000,
  };
  state.positions[vaultId] = next;
  const movement: VaultFundsMovementRow = {
    vaultId,
    walletAddress: wallet.trim(),
    time: Date.now(),
    status: "Completed",
    action: "Vault Deposit",
    source: "Trading Account",
    destination: vault.name,
    accountValueChangeUsd: amountUsd,
    feeUsd: null,
    txHash: transferId,
  };
  appendFundsMovement(state, movement);
  writeState(wallet, state);
  appendVaultFundsMovementToPortfolio(wallet, movement, vault.name);
  syncUserVaultTvl(vaultId, amountUsd);
  notify();
  return next;
}

export function recordVaultWithdraw(
  wallet: string,
  vaultId: string,
  amountUsd: number,
): VaultUserPosition | undefined {
  const vault = getVaultById(vaultId);
  const state = readState(wallet);
  const existing = state.positions[vaultId];
  if (!existing) return undefined;
  const withdrawable = Math.max(0, existing.depositUsd - existing.lockedUsd);
  const actual = Math.min(amountUsd, withdrawable);
  if (actual <= 0) return undefined;

  const shareRatio = existing.depositUsd > 0 ? actual / existing.depositUsd : 0;
  const next: VaultUserPosition = {
    ...existing,
    depositUsd: existing.depositUsd - actual,
    shares: existing.shares * (1 - shareRatio),
  };
  if (next.depositUsd <= 0.01) {
    delete state.positions[vaultId];
  } else {
    state.positions[vaultId] = next;
  }
  const transferId = `vault-withdraw:${vaultId}:${Date.now()}:${actual.toFixed(2)}`;
  const movement: VaultFundsMovementRow = {
    vaultId,
    walletAddress: wallet.trim(),
    time: Date.now(),
    status: "Completed",
    action: "Vault Withdrawal",
    source: vault?.name ?? vaultId,
    destination: "Trading Account",
    accountValueChangeUsd: -actual,
    feeUsd: null,
    txHash: transferId,
  };
  appendFundsMovement(state, movement);
  writeState(wallet, state);
  appendVaultFundsMovementToPortfolio(
    wallet,
    movement,
    vault?.name ?? vaultId,
  );

  applyDemoVaultSpotSettlement(wallet, {
    transferId,
    amount: actual,
    mode: "withdraw",
  });

  syncUserVaultTvl(vaultId, -actual);
  notify();
  return next;
}

export interface CreateUserVaultDraft
  extends Omit<VaultRecord, "id" | "tvlUsd" | "kind"> {
  id?: string;
}

/**
 * Atomically create a user vault: deposit first, then persist registry + wallet state.
 */
export function createUserVaultWithDeposit(
  wallet: string,
  draft: CreateUserVaultDraft,
  depositUsd: number,
  forcedVaultId?: string,
): CreateVaultResult {
  if (!wallet.trim()) {
    return { ok: false, reason: "wallet_required" };
  }
  if (depositUsd <= 0) {
    return { ok: false, reason: "invalid_deposit" };
  }

  const id = allocateUniqueVaultId(
    draft.name,
    wallet,
    isVaultIdTaken,
    forcedVaultId,
  );

  let primaryBucketId: string;
  try {
    const created = addDemoCreatedBucket(wallet, {
      marginType: "cross",
      collateralAsset: "USDC",
      amount: depositUsd,
      fundFrom: "spot-wallet",
    });
    primaryBucketId = created.bucketId;
  } catch {
    return { ok: false, reason: "insufficient_balance" };
  }

  const draftMarkets = draft.buckets[0]?.markets ?? [];
  const buckets = [
    buildDefaultVaultTradingBucket(primaryBucketId, depositUsd, draftMarkets),
  ];

  const vault: VaultRecord = {
    ...draft,
    id,
    kind: "user",
    tvlUsd: depositUsd,
    buckets,
    analystVerdict: {
      ...draft.analystVerdict,
      metrics: {
        ...draft.analystVerdict.metrics,
        tvlUsd: depositUsd,
      },
    },
  };

  const position = recordVaultDeposit(wallet, id, depositUsd, vault, {
    skipSpotSettlement: true,
  });
  if (!position) {
    return { ok: false, reason: "insufficient_balance" };
  }

  upsertVaultRecord(vault);

  const state = readState(wallet);
  if (!state.createdVaultIds.includes(id)) {
    state.createdVaultIds.push(id);
  }
  writeState(wallet, state);
  notify();

  return { ok: true, vault, position };
}

/** @deprecated Prefer createUserVaultWithDeposit for atomic create. */
export function addCreatedVault(wallet: string, vault: VaultRecord): void {
  const state = readState(wallet);
  if (!state.createdVaultIds.includes(vault.id)) {
    state.createdVaultIds.push(vault.id);
  }
  addVaultToCatalog(vault);
  writeState(wallet, state);
  notify();
}

export function getCreatedVaultIds(wallet: string): string[] {
  return readState(wallet).createdVaultIds;
}

export const VAULT_LOCKUP_DAYS = 4;
export const VAULT_DEPOSIT_FEE_PCT = 0;
export const VAULT_WITHDRAW_FEE_PCT = 0;
