import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import type { VaultBucketSummary, VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import { vaultBucketPath } from "../../routes";
import {
  VAULT_TOUR_BUCKET_ID,
  VAULT_TOUR_TARGETS,
} from "../../tutorials/vault-tour/constants";
import { useOptionalVaultTour } from "../../tutorials/vault-tour";
import {
  TabLayoutHeaderToolBar,
  buildToolbarTabs,
  tabStripUseCompactLabels,
  VAULT_PORTFOLIO_STRIP,
} from "../smartlayout";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import VaultTableFooter from "./VaultTableFooter";
import VaultBalancesTable from "./VaultBalancesTable";
import VaultActivityTable from "./VaultActivityTable";
import VaultDepositsWithdrawalsTable from "./VaultDepositsWithdrawalsTable";
import VaultDepositorsTable from "./VaultDepositorsTable";
import { useVaultDepositors } from "../../hooks/useVaultDepositors";
import { aggregateBucketTotals } from "./vaultPortfolioMetrics";
import { useOptionalSettings } from "../../context/SettingsContext";
import type { VaultPortfolioTablePrefs } from "../preference/SettingsModal";
import {
  resolveVaultPortfolioColumns,
  vaultPortfolioGridTemplate,
  type VaultPortfolioColumnId,
} from "./vaultPortfolioTableLayout";
import {
  renderBucketCell,
  renderColumnHeader,
  renderTotalCell,
} from "./vaultPortfolioTableCells";
import VaultPanelLoadingGate from "./VaultPanelLoadingGate";
import "./vault.css";

type PortfolioTab =
  | "balances"
  | "buckets"
  | "vaultActivity"
  | "depositsWithdrawals"
  | "depositors";

const PORTFOLIO_GRID_CLASS = "vault-portfolio-grid";

function VaultPortfolioColumnToggles({
  prefs,
  onChange,
}: {
  prefs: VaultPortfolioTablePrefs;
  onChange: (patch: Partial<VaultPortfolioTablePrefs>) => void;
}): JSX.Element {
  const toggles: Array<{ key: keyof VaultPortfolioTablePrefs; label: string }> = [
    { key: "showAllocation", label: "Allocation" },
    { key: "showExposureLegs", label: "L/S legs" },
    { key: "showLeverage", label: "Leverage" },
    { key: "showFunding", label: "Funding" },
  ];

  return (
    <div className="vault-portfolio-column-toggles">
      {toggles.map(({ key, label }) => (
        <button
          key={key}
          type="button"
          className={`btn-tab${prefs[key] ? " active" : ""}`}
          aria-pressed={prefs[key]}
          onClick={() => onChange({ [key]: !prefs[key] })}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

export interface VaultTableProps {
  vault: VaultRecord;
  buckets: VaultBucketSummary[];
  columnPrefs: VaultPortfolioTablePrefs;
}

function VaultBucketTotalRow({
  totals,
  columns,
  columnPrefs,
}: {
  totals: ReturnType<typeof aggregateBucketTotals>;
  columns: VaultPortfolioColumnId[];
  columnPrefs: VaultPortfolioTablePrefs;
}): JSX.Element {
  const gridTemplate = vaultPortfolioGridTemplate(columnPrefs);

  return (
    <div
      className="table-row vault-positions-total-row"
      data-tour={VAULT_TOUR_TARGETS.bucketTotalRow}
      style={{ gridTemplateColumns: gridTemplate }}
    >
      {columns.map((column) => renderTotalCell(column, totals, columnPrefs))}
    </div>
  );
}

function VaultTableInner({
  vault,
  buckets,
  columnPrefs,
}: VaultTableProps): JSX.Element {
  const navigate = useNavigate();
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(10);
  const columns = useMemo(
    () => resolveVaultPortfolioColumns(columnPrefs),
    [columnPrefs],
  );
  const gridTemplate = useMemo(
    () => vaultPortfolioGridTemplate(columnPrefs),
    [columnPrefs],
  );

  const sorted = useMemo(
    () => [...buckets].sort((a, b) => b.equityUsd - a.equityUsd),
    [buckets],
  );

  const totals = useMemo(
    () => aggregateBucketTotals(buckets, vault.tvlUsd),
    [buckets, vault.tvlUsd],
  );

  const pageRows = useMemo(() => {
    const start = page * pageSize;
    return sorted.slice(start, start + pageSize);
  }, [sorted, page, pageSize]);

  return (
    <div
      className="vault-portfolio-table-panel vault-bucket-positions-panel"
      data-tour={VAULT_TOUR_TARGETS.bucketTable}
    >
      <div className="vault-bucket-positions-table-frame">
        <div className="vault-bucket-positions-table-header">
          <div
            className={`table-header ${PORTFOLIO_GRID_CLASS}`}
            style={{ gridTemplateColumns: gridTemplate }}
          >
            {columns.map((column) => renderColumnHeader(column))}
          </div>
        </div>
        <div className="vault-bucket-positions-table-scroll">
          <div className="table-container shrinkable vault-activity-table">
            {pageRows.map((bucket) => (
              <div
                key={bucket.id}
                className={`table-row clickable ${PORTFOLIO_GRID_CLASS}`}
                role="row"
                tabIndex={0}
                style={{ gridTemplateColumns: gridTemplate }}
                data-tour={
                  bucket.id === VAULT_TOUR_BUCKET_ID
                    ? VAULT_TOUR_TARGETS.bucketRow
                    : undefined
                }
                onClick={() => navigate(vaultBucketPath(vault.id, bucket.id))}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    navigate(vaultBucketPath(vault.id, bucket.id));
                  }
                }}
              >
                {columns.map((column) =>
                  renderBucketCell(column, bucket, vault.tvlUsd),
                )}
              </div>
            ))}
          </div>
        </div>
        <div className="vault-bucket-positions-table-footer">
          <VaultBucketTotalRow
            totals={totals}
            columns={columns}
            columnPrefs={columnPrefs}
          />
        </div>
      </div>
      <VaultTableFooter
        page={page}
        pageSize={pageSize}
        totalCount={sorted.length}
        onPageChange={setPage}
        onPageSizeChange={setPageSize}
      />
    </div>
  );
}

export interface VaultPortfolioSectionProps {
  height?: string;
  vault: VaultRecord;
  layoutBreakpoint?: string;
  activityLoading?: boolean;
}

export default function VaultPortfolioSection({
  height = "100%",
  vault,
  layoutBreakpoint = "lg",
  activityLoading = false,
}: VaultPortfolioSectionProps): JSX.Element {
  const vaultTour = useOptionalVaultTour();
  const settingsContext = useOptionalSettings();
  const [tab, setTab] = useState<PortfolioTab>("buckets");
  const columnPrefs =
    settingsContext?.settings.vaultPortfolioTable ??
    ({
      showAllocation: false,
      showExposureLegs: false,
      showLeverage: false,
      showFunding: false,
    } satisfies VaultPortfolioTablePrefs);

  const setColumnPrefs = (patch: Partial<VaultPortfolioTablePrefs>) => {
    if (!settingsContext) return;
    settingsContext.setSettings({
      ...settingsContext.settings,
      vaultPortfolioTable: {
        ...settingsContext.settings.vaultPortfolioTable,
        ...patch,
      },
    });
  };
  const depositors = useVaultDepositors(vault.id);

  const tabs = useMemo(
    () =>
      buildToolbarTabs(VAULT_PORTFOLIO_STRIP, {
        counts: {
          depositors: depositors.length,
        },
        showCount: (id) => id === "depositors",
        useCompactLabels: tabStripUseCompactLabels(layoutBreakpoint),
      }),
    [depositors.length, layoutBreakpoint],
  );

  useEffect(() => {
    if (!vaultTour?.runTour) return;
    return vaultTour.registerEnsureBucketsTab(() => {
      setTab("buckets");
    });
  }, [vaultTour]);

  return (
    <div
      className="vault-slot vault-portfolio-section vault-detail-tab-section"
      style={{ height }}
      aria-label={`${vault.name} vault portfolio`}
      data-tour={VAULT_TOUR_TARGETS.portfolioTabs}
    >
      <div className="layout-container tab-section-root vault-detail-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={tab}
          onTabChange={(id) => setTab(id as PortfolioTab)}
        >
          {tab === "buckets" ? (
            <VaultPortfolioColumnToggles
              prefs={columnPrefs}
              onChange={setColumnPrefs}
            />
          ) : null}
        </TabLayoutHeaderToolBar>

        <VaultPanelLoadingGate loading={activityLoading}>
          <div className="tab-section-content">
            {tab === "buckets" ? (
              <VaultTableInner
                vault={vault}
                buckets={vault.buckets}
                columnPrefs={columnPrefs}
              />
            ) : tab === "balances" ? (
              <VaultBalancesTable vaultId={vault.id} vaultTvlUsd={vault.tvlUsd} />
            ) : tab === "vaultActivity" ? (
              <VaultActivityTable vaultId={vault.id} />
            ) : tab === "depositsWithdrawals" ? (
              <VaultDepositsWithdrawalsTable vaultId={vault.id} />
            ) : (
              <VaultDepositorsTable vaultId={vault.id} />
            )}
          </div>
        </VaultPanelLoadingGate>
      </div>
    </div>
  );
}
