import { useEffect, useMemo } from "react";

/** Pick active tab when it is still visible, otherwise fallback then first visible id. */
export function resolveActiveTabInStrip<T extends string>(
  activeTab: T,
  visibleTabIds: readonly T[],
  fallbackTab: T,
): T {
  if (visibleTabIds.includes(activeTab)) return activeTab;
  if (visibleTabIds.includes(fallbackTab)) return fallbackTab;
  return (visibleTabIds[0] ?? fallbackTab) as T;
}

/** T11: omit short labels at layout lg even when the strip container is narrow. */
export function tabStripUseCompactLabels(layoutBreakpoint?: string): boolean {
  return layoutBreakpoint !== "lg";
}

/** Sync parent/uncontrolled tab state when the visible strip changes. */
export function useSyncedActiveTab<T extends string>(
  activeTab: T,
  setActiveTab: (tab: T) => void,
  visibleTabIds: readonly T[],
  fallbackTab: T,
): T {
  const resolvedActiveTab = useMemo(
    () => resolveActiveTabInStrip(activeTab, visibleTabIds, fallbackTab),
    [activeTab, visibleTabIds, fallbackTab],
  );

  useEffect(() => {
    if (resolvedActiveTab !== activeTab) {
      setActiveTab(resolvedActiveTab);
    }
  }, [resolvedActiveTab, activeTab, setActiveTab]);

  return resolvedActiveTab;
}
