import React, { useCallback, useEffect, useMemo, useState } from "react";

import ModalHeader from "../../ui/ModalHeader";
import { createErrorCopyAction } from "../../ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  toastUpdateLoading,
} from "../../ui/toastTask";
import {
  BASE_AGENT_ALLOCATION_MB,
  useMemoryPoolStore,
} from "../../../store/memoryPoolStore";
import { useTradingAgentStore } from "../../../store/tradingAgentStore";
import {
  buildMintAgentPayload,
  clearMintDraft,
  createMintWizardState,
  isStepValid,
  previewDid,
} from "../../../utils/mintAgent";
import type { MintAgentWizardState } from "../../../utils/mintAgent";
import type { UseMintAgentModalResult } from "../../../hooks/useMintAgentModal";
import { executeOfflineMintAgent } from "../../../utils/executeOfflineMintAgent";
import { OFFLINE_MINT_AGENT_STABLE_TOAST_ID } from "../../../../offline/mock_data/offlineMintAgentSteps";
import MintAgentModalShell, { useMintAgentModalShell } from "./MintAgentModalShell";
import MintAgentStepIndicator from "./MintAgentStepIndicator";
import MintAgentStepRole from "./MintAgentStepRole";
import MintAgentStepIdentity from "./MintAgentStepIdentity";
import MintAgentStepMemory from "./MintAgentStepMemory";
import MintAgentReview from "./MintAgentReview";
import MintAgentExpressDuplicate from "./MintAgentExpressDuplicate";

export interface MintAgentModalProps {
  modal: UseMintAgentModalResult;
}

function MintAgentModalBody({
  modal,
}: MintAgentModalProps): JSX.Element {
  const { overlay } = useMintAgentModalShell();
  const agents = useTradingAgentStore((s) => s.agents);
  const supervisors = useTradingAgentStore((s) => s.supervisors);
  const addAgent = useTradingAgentStore((s) => s.addAgent);
  const poolMb = useMemoryPoolStore((s) => s.poolMb);
  const reservedMb = useMemoryPoolStore((s) => s.reservedMb);
  const reserveForMint = useMemoryPoolStore((s) => s.reserveForMint);
  const topUpMemory = useMemoryPoolStore((s) => s.topUpMemory);
  const canMint = reservedMb + BASE_AGENT_ALLOCATION_MB <= poolMb;

  const [isConfirming, setIsConfirming] = useState(false);

  const { state, setState, goNext, goBack, close, saveDraft, isOpen } = modal;

  useEffect(() => {
    if (!isOpen) setIsConfirming(false);
  }, [isOpen]);
  const sourceAgent = useMemo(
    () =>
      state.duplicateFromAgentId
        ? agents.find((agent) => agent.id === state.duplicateFromAgentId)
        : undefined,
    [agents, state.duplicateFromAgentId],
  );

  const patchState = useCallback(
    (patch: Partial<MintAgentWizardState>) => {
      setState((prev) => ({ ...prev, ...patch }));
    },
    [setState],
  );

  const handleSaveDraft = () => {
    saveDraft();
  };

  const handleConfirm = async () => {
    if (isConfirming || !canMint) return;
    const stepKey = state.step === "express" ? "express" : "review";
    if (!isStepValid(stepKey, state, agents)) return;
    if (!state.pendingAgentId) return;

    setIsConfirming(true);
    const agentId = state.pendingAgentId;
    const payload = buildMintAgentPayload(state, agentId);
    const toastId = toastLoading("Minting agent…", {
      stableId: OFFLINE_MINT_AGENT_STABLE_TOAST_ID,
      description: "Signing transaction…",
    });

    try {
      const result = await executeOfflineMintAgent(
        {
          displayName: payload.displayName,
          handle: payload.handle,
          memoryMb: BASE_AGENT_ALLOCATION_MB,
          marketSymbol: payload.marketSymbol,
          agentId,
        },
        {
          onStepStart: (step) => {
            toastUpdateLoading(toastId, step.loadingMessage, {
              description: step.loadingDescription,
            });
          },
        },
      );

      if (!reserveForMint()) {
        toastCompleteError(toastId, "Mint failed", {
          description: "Not enough on-chain memory to reserve for this agent.",
        });
        return;
      }

      addAgent(payload);
      clearMintDraft();
      close();

      const didPreview = previewDid(agentId);
      toastCompleteSuccess(toastId, "Agent minted", {
        description: `${payload.displayName} (${payload.handle}) · ${didPreview} · ${payload.marketSymbol}\ntxhash: ${result.demoTxHash}`,
      });
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "Failed to mint agent";
      toastCompleteError(toastId, "Mint failed", {
        description: errorMessage,
        action: createErrorCopyAction(errorMessage),
      });
    } finally {
      setIsConfirming(false);
    }
  };

  const stepValid = isStepValid(state.step, state, agents);
  const title =
    state.step === "review"
      ? "Mint Agent · Review"
      : state.step === "express"
        ? "Mint Agent · Duplicate & bump version"
        : "Mint Agent";

  const showStepIndicator = state.step !== "express" && state.step !== "review";
  const footerDisabled = overlay.isClosing || isConfirming;

  return (
    <>
      <ModalHeader
        title={title}
        onClose={close}
        closeDisabled={footerDisabled}
      />

      <div className="modal-body mint-agent-modal-body">
        {showStepIndicator ? <MintAgentStepIndicator step={state.step} /> : null}
        {state.step === "role" ? (
          <MintAgentStepRole state={state} onChange={patchState} />
        ) : null}
        {state.step === "identity" ? (
          <MintAgentStepIdentity
            state={state}
            agents={agents}
            onChange={patchState}
          />
        ) : null}
        {state.step === "memory" ? (
          <MintAgentStepMemory
            state={state}
            poolMb={poolMb}
            reservedMb={reservedMb}
            canMint={canMint}
            onTopUp={topUpMemory}
          />
        ) : null}
        {state.step === "review" ? (
          <MintAgentReview
            state={state}
            supervisors={supervisors}
            canMint={canMint}
            onTopUp={topUpMemory}
          />
        ) : null}
        {state.step === "express" ? (
          <MintAgentExpressDuplicate
            state={state}
            sourceAgent={sourceAgent}
            agents={agents}
            onChange={patchState}
          />
        ) : null}
      </div>

      <div className="modal-footer bucket-modal-footer mint-agent-modal-footer">
        {state.step === "role" || state.step === "express" ? (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={close}
            disabled={footerDisabled}
          >
            Cancel
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={goBack}
            disabled={footerDisabled}
          >
            Back
          </button>
        )}

        {state.step !== "review" && state.step !== "express" ? (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={handleSaveDraft}
            disabled={footerDisabled}
          >
            Save draft
          </button>
        ) : null}

        {state.step === "review" || state.step === "express" ? (
          <button
            type="button"
            className="btn btn-primary"
            onClick={handleConfirm}
            disabled={!canMint || !stepValid || footerDisabled}
          >
            {isConfirming ? "Minting…" : "Mint Agent"}
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-primary"
            onClick={goNext}
            disabled={!stepValid || footerDisabled}
          >
            Next
          </button>
        )}
      </div>
    </>
  );
}

export default function MintAgentModal({ modal }: MintAgentModalProps): JSX.Element | null {
  const handleAfterUnmount = useCallback(() => {
    modal.setState(createMintWizardState());
  }, [modal.setState]);

  return (
    <MintAgentModalShell
      open={modal.isOpen}
      onClose={modal.close}
      onAfterUnmount={handleAfterUnmount}
      ariaLabel="Mint Agent"
    >
      <MintAgentModalBody modal={modal} />
    </MintAgentModalShell>
  );
}
