import { useMemo, useSyncExternalStore } from "react";

import {
  getAllVaults,
  getVaultById,
  type VaultRecord,
} from "../../offline/mock_data/vaultCatalog";
import {
  getRegistryRevision,
  subscribeVaultRegistry,
} from "../../offline/mock_data/vaultRegistryStorage";
import {
  getCreatedVaultIds,
  getVaultUserStateRevision,
  subscribeVaultUserState,
} from "../../offline/mock_data/vaultUserState";

export function isVaultOwner(
  walletAddress: string,
  vault: Pick<VaultRecord, "leaderAddress">,
): boolean {
  const wallet = walletAddress.trim().toLowerCase();
  if (!wallet) return false;
  return vault.leaderAddress.trim().toLowerCase() === wallet;
}

export function getOwnedVaults(walletAddress: string): VaultRecord[] {
  const wallet = walletAddress.trim();
  if (!wallet) return [];
  return getAllVaults().filter((vault) => isVaultOwner(wallet, vault));
}

/** User vaults led by this wallet (leaderAddress === wallet). */
export function getOwnedUserVaults(walletAddress: string): VaultRecord[] {
  return getOwnedVaults(walletAddress).filter((vault) => vault.kind === "user");
}

export function useOwnedUserVaults(walletAddress: string): VaultRecord[] {
  const userRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  return useMemo(() => {
    void userRevision;
    void registryRevision;
    return getOwnedUserVaults(walletAddress);
  }, [walletAddress, userRevision, registryRevision]);
}

/** User vaults this wallet created via Create Vault (wallet-scoped registry). */
export function getCreatedUserVaults(walletAddress: string): VaultRecord[] {
  const wallet = walletAddress.trim();
  if (!wallet) return [];

  const vaults: VaultRecord[] = [];
  for (const id of getCreatedVaultIds(wallet)) {
    const vault = getVaultById(id);
    if (vault?.kind === "user") {
      vaults.push(vault);
    }
  }
  return vaults;
}

export function useCreatedUserVaults(walletAddress: string): VaultRecord[] {
  const userRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  return useMemo(() => {
    void userRevision;
    void registryRevision;
    return getCreatedUserVaults(walletAddress);
  }, [walletAddress, userRevision, registryRevision]);
}

export function useOwnedVaults(walletAddress: string): VaultRecord[] {
  const userRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  return useMemo(() => {
    void userRevision;
    void registryRevision;
    return getOwnedVaults(walletAddress);
  }, [walletAddress, userRevision, registryRevision]);
}
