import React from "react";

import type { FleetSupervisor } from "../../../store/types";
import type { MintAgentWizardState } from "../../../utils/mintAgent";
import {
  BASE_AGENT_ALLOCATION_MB,
  DEFAULT_TOP_UP_MB,
} from "../../../store/memoryPoolStore";
import {
  CUSTODY_MODE_LABELS,
  PERMISSION_MODE_LABELS,
  deriveMarketSymbol,
  previewDid,
} from "../../../utils/mintAgent";
import { AGENT_ROLE_LABELS } from "../../../utils/agentRoles";

export interface MintAgentReviewProps {
  state: MintAgentWizardState;
  supervisors: FleetSupervisor[];
  canMint: boolean;
  onTopUp?: () => void;
}

export default function MintAgentReview({
  state,
  supervisors,
  canMint,
  onTopUp,
}: MintAgentReviewProps): JSX.Element {
  const did = previewDid(state.pendingAgentId);
  const marketSymbol = deriveMarketSymbol(
    `did:morpheum:agent:${state.pendingAgentId}`,
  );
  const supervisor = supervisors.find((entry) => entry.id === state.supervisorId);

  return (
    <div className="mint-agent-step mint-agent-review">
      <dl className="mint-agent-review-dl">
        <div>
          <dt className="terminal-label">Role</dt>
          <dd>
            {AGENT_ROLE_LABELS[state.role]}
            {supervisor ? ` · ${supervisor.displayName}` : ""}
          </dd>
        </div>
        <div>
          <dt className="terminal-label">Name tag</dt>
          <dd>
            {state.displayName} ({state.handle})
          </dd>
        </div>
        <div>
          <dt className="terminal-label">Permission</dt>
          <dd>{PERMISSION_MODE_LABELS[state.permissionMode]}</dd>
        </div>
        <div>
          <dt className="terminal-label">Custody</dt>
          <dd>{CUSTODY_MODE_LABELS[state.custodyMode]}</dd>
        </div>
        <div>
          <dt className="terminal-label">KYA DID</dt>
          <dd>
            {did} · minted on confirm
          </dd>
        </div>
        <div>
          <dt className="terminal-label">Symbol</dt>
          <dd>{marketSymbol} (hash-hex)</dd>
        </div>
        <div>
          <dt className="terminal-label">Memory</dt>
          <dd>≈ {BASE_AGENT_ALLOCATION_MB} MB · cost paid in MORM</dd>
        </div>
      </dl>

      <p className="mint-agent-review-locked">
        Locked forever: role · handle · DID
      </p>

      <p className="mint-agent-review-inert terminal-text-muted">
        Born inert: Watch-only · unlisted · gateway off · unfunded
      </p>

      {!canMint ? (
        <div className="mint-agent-memory-warning" role="alert">
          <p className="mint-agent-memory-warning-title">
            Not enough on-chain memory
          </p>
          <p className="transfer-field-hint">
            Memory is the only thing that can block a mint.
          </p>
          {onTopUp ? (
            <button type="button" className="btn btn-secondary" onClick={onTopUp}>
              Top up memory (MORM) +{DEFAULT_TOP_UP_MB} MB
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
