/** Staking fee tier row — discount from baseline trading fees. */
export interface StakingFeeTier {
  tier: number;
  /** Minimum staked MORM (inclusive). */
  minStakedMorm: number;
  /** Fee discount as a fraction, e.g. 0.25 = −25%. */
  feeDiscountPct: number;
}

const STAKING_FEE_TIERS_DESC: StakingFeeTier[] = [
  { tier: 4, minStakedMorm: 250_000, feeDiscountPct: 0.55 },
  { tier: 3, minStakedMorm: 50_000, feeDiscountPct: 0.4 },
  { tier: 2, minStakedMorm: 10_000, feeDiscountPct: 0.25 },
];

const STAKING_FEE_TIER_1: StakingFeeTier = {
  tier: 1,
  minStakedMorm: 0,
  feeDiscountPct: 0,
};

export function resolveStakingFeeTier(stakedMorm: number): StakingFeeTier {
  const amount = Math.max(0, stakedMorm);
  for (const tier of STAKING_FEE_TIERS_DESC) {
    if (amount >= tier.minStakedMorm) {
      return tier;
    }
  }
  return STAKING_FEE_TIER_1;
}

export function formatStakingFeeTierLabel(tier: StakingFeeTier): string {
  if (tier.feeDiscountPct <= 0) {
    return `Tier ${tier.tier}`;
  }
  const pct = Math.round(tier.feeDiscountPct * 100);
  return `Tier ${tier.tier} · −${pct}%`;
}

export function formatStakingFeeDiscountPct(tier: StakingFeeTier): string {
  if (tier.feeDiscountPct <= 0) return "0%";
  return `−${Math.round(tier.feeDiscountPct * 100)}%`;
}

export type StakingFeePreviewMode = "stake" | "unstake";

export function previewStakingFeeTier(
  currentStakedMorm: number,
  deltaAmount: number,
  mode: StakingFeePreviewMode,
): {
  currentTier: StakingFeeTier;
  nextTier: StakingFeeTier;
  tierChanges: boolean;
} {
  const delta = Math.max(0, deltaAmount);
  const currentTier = resolveStakingFeeTier(currentStakedMorm);
  const nextStaked =
    mode === "stake"
      ? currentStakedMorm + delta
      : Math.max(0, currentStakedMorm - delta);
  const nextTier = resolveStakingFeeTier(nextStaked);
  return {
    currentTier,
    nextTier,
    tierChanges: nextTier.tier !== currentTier.tier,
  };
}

export function formatStakingFeePreviewLine(
  currentStakedMorm: number,
  deltaAmount: number,
  mode: StakingFeePreviewMode,
): string | null {
  const preview = previewStakingFeeTier(currentStakedMorm, deltaAmount, mode);
  if (mode === "unstake" && !preview.tierChanges) {
    return null;
  }
  if (mode === "stake" && deltaAmount <= 0) {
    return null;
  }
  if (preview.tierChanges) {
    return `Fee tier: Tier ${preview.currentTier.tier} → Tier ${preview.nextTier.tier} (${formatStakingFeeDiscountPct(preview.nextTier)} fees)`;
  }
  if (mode === "stake") {
    return `Fee tier: Tier ${preview.currentTier.tier} (${formatStakingFeeDiscountPct(preview.currentTier)} fees)`;
  }
  return "May lower your fee tier.";
}

export function formatStakingPanelPreviewLine(
  currentStakedMorm: number,
  deltaAmount: number,
  mode: StakingFeePreviewMode,
): string | null {
  const delta = Math.max(0, deltaAmount);
  if (delta <= 0) return null;
  const preview = previewStakingFeeTier(currentStakedMorm, delta, mode);
  if (mode === "stake") {
    if (preview.tierChanges) {
      return `After staking: Fee Tier ${preview.currentTier.tier} → Tier ${preview.nextTier.tier} (${formatStakingFeeDiscountPct(preview.nextTier)})`;
    }
    return `After staking: Fee Tier ${preview.currentTier.tier} (${formatStakingFeeDiscountPct(preview.currentTier)})`;
  }
  if (!preview.tierChanges) return null;
  return `After unstaking: Fee Tier ${preview.currentTier.tier} → Tier ${preview.nextTier.tier} (${formatStakingFeeDiscountPct(preview.nextTier)})`;
}
