import React from "react";

import type { TradingAgent } from "../../../store/types";
import type { MintAgentWizardState } from "../../../utils/mintAgent";
import { isHandleAvailable } from "../../../utils/mintAgent";

export interface MintAgentExpressDuplicateProps {
  state: MintAgentWizardState;
  sourceAgent: TradingAgent | undefined;
  agents: TradingAgent[];
  onChange: (patch: Partial<MintAgentWizardState>) => void;
}

export default function MintAgentExpressDuplicate({
  state,
  sourceAgent,
  agents,
  onChange,
}: MintAgentExpressDuplicateProps): JSX.Element {
  const handleAvailable = isHandleAvailable(
    state.handle,
    agents,
    state.duplicateFromAgentId,
  );

  return (
    <div className="mint-agent-step mint-agent-express">
      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label">From</label>
        <p className="terminal-value">
          {sourceAgent?.displayName ?? "—"} ({sourceAgent?.handle ?? sourceAgent?.displayName})
        </p>
      </div>

      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label" htmlFor="express-handle">
          New handle
        </label>
        <input
          id="express-handle"
          className="form-input"
          value={state.handle}
          onChange={(e) => onChange({ handle: e.target.value })}
        />
        <p
          className={`transfer-field-hint${
            handleAvailable ? " transfer-field-ok" : " transfer-field-error"
          }`}
        >
          {handleAvailable ? "✓ auto-bumped" : "Handle already in use"}
        </p>
      </div>

      <div className="mint-agent-express-inherits">
        <p className="terminal-label">Inherits</p>
        <p className="terminal-text-muted">
          role · custody type · mandate · caps
        </p>
      </div>

      <div className="mint-agent-express-fresh">
        <p className="terminal-label">Fresh</p>
        <p className="terminal-text-muted">
          new KYA DID · new hash-hex symbol · memory
        </p>
      </div>
    </div>
  );
}
