import React from "react";

import type { AgentRegistryRow, AgentRolesRegistryView } from "../../utils/agentRoles";
import {
  formatAgentRevenue,
  formatPaymentUsd,
  formatSpendCapSummary,
  getAgentPaymentLabel,
  getAgentPaymentShortLabel,
  getAgentRoleLabel,
  getListingLabel,
  getAgentStatusDotClass,
  resolveAgentPaymentState,
} from "../../utils/agentRoles";
import AgentRolesRegistryWalletCell from "./AgentRolesRegistryWalletCell";
import "./agentroles.css";

export interface AgentRolesRegistryCardListProps {
  height?: string;
  rows: AgentRegistryRow[];
  viewMode?: AgentRolesRegistryView;
  onRowSelect: (agentId: string) => void;
}

export default function AgentRolesRegistryCardList({
  height = "100%",
  rows,
  viewMode = "fleet",
  onRowSelect,
}: AgentRolesRegistryCardListProps): JSX.Element {
  const isPaymentsView = viewMode === "payments";

  return (
    <div className="agentroles-slot agentroles-card-list" style={{ height }}>
      {rows.length === 0 ? (
        <p className="agentroles-empty terminal-text-muted">
          No agents match the current filters.
        </p>
      ) : (
        rows.map(({ agent, activeTaskCount, needsYouCount }) => {
          const paymentStateKey = resolveAgentPaymentState(agent);
          return (
            <button
              key={agent.id}
              type="button"
              className="agentroles-agent-card"
              onClick={() => onRowSelect(agent.id)}
            >
              <div className="agentroles-agent-card-head">
                <span className="agentroles-agent-icon-wrap">
                  <span className="agentroles-agent-icon" aria-hidden>
                    {agent.icon ?? "🤖"}
                  </span>
                  <span
                    className={getAgentStatusDotClass(agent)}
                    aria-hidden
                  />
                </span>
                <div>
                  <div className="agentroles-agent-name">
                    {agent.displayName}
                    {needsYouCount > 0 ? (
                      <span className="agentroles-needs-you-pill agentroles-needs-you-pill--inline">
                        Needs you {needsYouCount}
                      </span>
                    ) : null}
                  </div>
                  <div className="agentroles-agent-subtitle terminal-text-muted">
                    {getAgentRoleLabel(agent.role)} · {agent.versionTag}
                    {!isPaymentsView && activeTaskCount > 0
                      ? ` · ${activeTaskCount} active`
                      : null}
                  </div>
                </div>
                {isPaymentsView ? (
                  <span
                    className={`agentroles-payment-chip agentroles-payment-chip--${paymentStateKey}`}
                  >
                    {getAgentPaymentLabel(agent)}
                  </span>
                ) : (
                  <span
                    className={`agentroles-listing-badge agentroles-listing-badge--${agent.listingStatus}`}
                  >
                    {getListingLabel(agent.listingStatus)}
                  </span>
                )}
              </div>
              {!isPaymentsView ? (
                <div
                  className="agentroles-agent-card-wallet"
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => event.stopPropagation()}
                >
                  <AgentRolesRegistryWalletCell walletAddress={agent.walletAddress} />
                </div>
              ) : null}
              {isPaymentsView ? (
                <div className="agentroles-agent-card-meta">
                  <span>{formatSpendCapSummary(agent)}</span>
                  <span>
                    {formatPaymentUsd(agent.paymentOut30dUsd)} out ·{" "}
                    {formatPaymentUsd(agent.paymentIn30dUsd)} in
                  </span>
                </div>
              ) : (
                <div className="agentroles-agent-card-meta">
                  <span>{getAgentPaymentShortLabel(agent)}</span>
                  <span>{formatAgentRevenue(agent.revenue30d)}</span>
                </div>
              )}
              {isPaymentsView ? (
                <div className="agentroles-agent-card-foot">
                  <span>
                    Allowlist{" "}
                    {agent.counterpartyAllowlistCount != null
                      ? agent.counterpartyAllowlistCount
                      : "—"}
                  </span>
                </div>
              ) : null}
              {needsYouCount > 0 ? (
                <p className="agentroles-card-console-hint terminal-text-muted">
                  Act via Open in Agent Console
                </p>
              ) : null}
            </button>
          );
        })
      )}
    </div>
  );
}
