import React, { useMemo, useState } from "react";

import type { StakingValidatorRow } from "../../../offline/mock_data/stakingValidators.types";
import {
  TableHeaderCell,
  TableHeaderCellStatic,
} from "../smartlayout";
import VaultActivityTableShell from "../vault/VaultActivityTableShell";
import {
  formatValidatorPct,
  formatValidatorStake,
  formatYourStake,
} from "./stakingFormat";
import type { StakingDelegateMode } from "../../utils/executeOfflineDelegateFunds";
import "./staking.css";

export type StakingValidatorsSortKey =
  | "name"
  | "stakeMorm"
  | "uptimePct"
  | "estAprPct"
  | "commissionPct"
  | "status";

export interface StakingValidatorsTableProps {
  rows: StakingValidatorRow[];
  height?: string;
  onManage?: (validatorId: string, mode: StakingDelegateMode) => void;
}

function compareValidators(
  a: StakingValidatorRow,
  b: StakingValidatorRow,
  sortKey: StakingValidatorsSortKey,
  sortDir: "asc" | "desc",
): number {
  let cmp = 0;
  switch (sortKey) {
    case "name":
      cmp = a.name.localeCompare(b.name);
      break;
    case "stakeMorm":
      cmp = a.stakeMorm - b.stakeMorm;
      break;
    case "uptimePct":
      cmp = a.uptimePct - b.uptimePct;
      break;
    case "estAprPct":
      cmp = a.estAprPct - b.estAprPct;
      break;
    case "commissionPct":
      cmp = a.commissionPct - b.commissionPct;
      break;
    case "status":
      cmp = a.status.localeCompare(b.status);
      break;
    default:
      cmp = 0;
  }
  return sortDir === "asc" ? cmp : -cmp;
}

function StakingValidatorsTable({
  rows,
  height = "100%",
  onManage,
}: StakingValidatorsTableProps): JSX.Element {
  const [sortKey, setSortKey] = useState<StakingValidatorsSortKey>("stakeMorm");
  const [sortDir, setSortDir] = useState<"asc" | "desc">("desc");

  const handleSort = (key: StakingValidatorsSortKey): void => {
    if (sortKey === key) {
      setSortDir((dir) => (dir === "asc" ? "desc" : "asc"));
      return;
    }
    setSortKey(key);
    setSortDir(key === "name" ? "asc" : "desc");
  };

  const sortedRows = useMemo(
    () =>
      [...rows].sort((a, b) => compareValidators(a, b, sortKey, sortDir)),
    [rows, sortDir, sortKey],
  );

  return (
    <div className="staking-validators-table-root" style={{ height }}>
      <VaultActivityTableShell
        layout="terminal"
        tableClassName="position-table staking-validators-table"
        gridClassName="staking-validators-grid"
        minWidth={960}
        isEmpty={sortedRows.length === 0}
        emptyMessage="No validators available."
        header={
          <>
            <TableHeaderCell
              field="name"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={handleSort}
              left
            >
              Name
            </TableHeaderCell>
            <TableHeaderCellStatic left>Description</TableHeaderCellStatic>
            <TableHeaderCell
              field="stakeMorm"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={handleSort}
              left
            >
              Stake
            </TableHeaderCell>
            <TableHeaderCellStatic left>Your Stake</TableHeaderCellStatic>
            <TableHeaderCell
              field="uptimePct"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={handleSort}
              left
            >
              Uptime
            </TableHeaderCell>
            <TableHeaderCell
              field="estAprPct"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={handleSort}
              left
            >
              Est. APR
            </TableHeaderCell>
            <TableHeaderCell
              field="status"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={handleSort}
              left
            >
              Status
            </TableHeaderCell>
            <TableHeaderCell
              field="commissionPct"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={handleSort}
              left
            >
              Commission
            </TableHeaderCell>
            <TableHeaderCellStatic left>Action</TableHeaderCellStatic>
          </>
        }
      >
        {sortedRows.map((row) => {
          const yourStake = row.yourStakeMorm ?? 0;
          const canDelegate = row.status === "active";
          const canUndelegate = yourStake > 0;
          const canManage = canDelegate || canUndelegate;
          const actionLabel =
            canDelegate && canUndelegate
              ? "Manage"
              : canDelegate
                ? "Delegate"
                : canUndelegate
                  ? "Undelegate"
                  : "—";

          return (
          <div key={row.validatorId} className="table-row staking-validators-grid">
            <span className="staking-validators-name">{row.name}</span>
            <span
              className="staking-validators-description terminal-label"
              title={row.description}
            >
              {row.description}
            </span>
            <span>{formatValidatorStake(row.stakeMorm)}</span>
            <span className="terminal-label">
              {formatYourStake(row.yourStakeMorm)}
            </span>
            <span>{formatValidatorPct(row.uptimePct)}</span>
            <span>{formatValidatorPct(row.estAprPct)}</span>
            <span
              className={`staking-validator-status staking-validator-status--${row.status}`}
            >
              {row.status === "active" ? "Active" : "Inactive"}
            </span>
            <span>{formatValidatorPct(row.commissionPct)}</span>
            <span className="staking-validators-action">
              {onManage && canManage ? (
                <button
                  type="button"
                  className="btn btn-secondary btn-compact"
                  onClick={() =>
                    onManage(
                      row.validatorId,
                      canUndelegate && !canDelegate ? "undelegate" : "delegate",
                    )
                  }
                >
                  {actionLabel}
                </button>
              ) : (
                <span className="terminal-label">—</span>
              )}
            </span>
          </div>
          );
        })}
      </VaultActivityTableShell>
    </div>
  );
}

export default React.memo(StakingValidatorsTable);
