import React from "react";

import { Link, useNavigate } from "react-router-dom";

import type { AgentRegistryRow } from "../../utils/agentRoles";
import {
  formatAgentRevenue,
  formatPaymentUsd,
  formatSpendCapSummary,
  getAgentPaymentLabel,
  getAgentPaymentShortLabel,
  getAgentRoleLabel,
  getListingLabel,
  getAgentStatusDotClass,
  resolveAgentPaymentState,
  type AgentRolesRegistryView,
  type AgentRolesSortKey,
} from "../../utils/agentRoles";
import { agentRolesConsolePath } from "../../routes";
import {
  TableHeaderCell,
  TableHeaderCellStatic,
} from "../smartlayout";
import AgentRolesRegistryWalletCell from "./AgentRolesRegistryWalletCell";
import "../smartlayout/layout.css";
import "./agentroles.css";

const FLEET_GRID_CLASS = "agentroles-registry-grid";
const PAYMENTS_GRID_CLASS = "agentroles-registry-grid agentroles-registry-grid--payments";

export interface AgentRolesRegistryTableProps {
  height?: string;
  rows: AgentRegistryRow[];
  sortKey: AgentRolesSortKey;
  sortDir: "asc" | "desc";
  selectedAgentId: string | null;
  detailOpen: boolean;
  viewMode?: AgentRolesRegistryView;
  showReputation?: boolean;
  onSort: (key: AgentRolesSortKey) => void;
  onRowSelect: (agentId: string) => void;
  detailPanel?: React.ReactNode;
}

export default function AgentRolesRegistryTable({
  height = "100%",
  rows,
  sortKey,
  sortDir,
  selectedAgentId,
  detailOpen,
  viewMode = "fleet",
  showReputation = true,
  onSort,
  onRowSelect,
  detailPanel,
}: AgentRolesRegistryTableProps): JSX.Element {
  const navigate = useNavigate();
  const isPaymentsView = viewMode === "payments";
  const gridClass = isPaymentsView ? PAYMENTS_GRID_CLASS : FLEET_GRID_CLASS;

  const handleSendPayment = (
    event: React.MouseEvent,
    agentId: string,
  ): void => {
    event.stopPropagation();
    navigate(agentRolesConsolePath(agentId));
  };

  return (
    <div
      className={`agentroles-slot agentroles-registry-root${
        detailOpen ? " agentroles-registry-root--detail-open" : ""
      }`}
      style={{ height }}
    >
      <div className="agentroles-registry-main">
        <div className="agentroles-registry-table table-container shrinkable">
          <div className={`table-header ${gridClass}`} role="row">
            <TableHeaderCell
              field="name"
              currentSortField={sortKey}
              sortDirection={sortDir}
              onSort={onSort}
              left
            >
              Agent
            </TableHeaderCell>
            {isPaymentsView ? (
              <>
                <TableHeaderCell
                  field="payments"
                  currentSortField={sortKey}
                  sortDirection={sortDir}
                  onSort={onSort}
                  left
                >
                  Payments
                </TableHeaderCell>
                <TableHeaderCellStatic left>Spend cap</TableHeaderCellStatic>
                <TableHeaderCellStatic left>30d activity</TableHeaderCellStatic>
                <TableHeaderCellStatic left>Allowlist</TableHeaderCellStatic>
                <TableHeaderCellStatic left>Actions</TableHeaderCellStatic>
              </>
            ) : (
              <>
                <TableHeaderCell
                  field="custody"
                  currentSortField={sortKey}
                  sortDirection={sortDir}
                  onSort={onSort}
                  left
                >
                  Wallet
                </TableHeaderCell>
                <TableHeaderCell
                  field="payments"
                  currentSortField={sortKey}
                  sortDirection={sortDir}
                  onSort={onSort}
                  left
                >
                  Pay
                </TableHeaderCell>
                <TableHeaderCell
                  field="listing"
                  currentSortField={sortKey}
                  sortDirection={sortDir}
                  onSort={onSort}
                  left
                >
                  Listing
                </TableHeaderCell>
                {showReputation ? (
                  <TableHeaderCell
                    field="revenue"
                    currentSortField={sortKey}
                    sortDirection={sortDir}
                    onSort={onSort}
                    left
                  >
                    Reputation
                  </TableHeaderCell>
                ) : (
                  <TableHeaderCellStatic left>
                    Reputation
                  </TableHeaderCellStatic>
                )}
              </>
            )}
          </div>
          <div className="table-body">
            {rows.length === 0 ? (
              <p className="agentroles-empty terminal-text-muted">
                No agents match the current filters.
              </p>
            ) : (
              rows.map(({ agent, activeTaskCount, needsYouCount }) => {
                const isSelected = selectedAgentId === agent.id;
                const paymentStateKey = resolveAgentPaymentState(agent);
                const paymentState = getAgentPaymentLabel(agent);
                return (
                  <button
                    key={agent.id}
                    type="button"
                    className={`table-row clickable ${gridClass} agentroles-registry-row${
                      isSelected ? " selected" : ""
                    }`}
                    onClick={() => onRowSelect(agent.id)}
                  >
                    <div className="agentroles-agent-cell table-cell primary">
                      <span className="agentroles-agent-icon-wrap">
                        <span className="agentroles-agent-icon" aria-hidden>
                          {agent.icon ?? "🤖"}
                        </span>
                        <span
                          className={getAgentStatusDotClass(agent)}
                          aria-hidden
                        />
                      </span>
                      <span>
                        <span className="agentroles-agent-name">
                          {agent.displayName}
                          {needsYouCount > 0 ? (
                            <span className="agentroles-needs-you-pill agentroles-needs-you-pill--inline">
                              Needs you {needsYouCount}
                            </span>
                          ) : null}
                        </span>
                        <span className="agentroles-agent-subtitle terminal-text-muted">
                          {getAgentRoleLabel(agent.role)} · {agent.versionTag}
                          {activeTaskCount > 0
                            ? ` · ${activeTaskCount} active`
                            : null}
                        </span>
                      </span>
                    </div>
                    {isPaymentsView ? (
                      <>
                        <div className="table-cell">
                          <span
                            className={`agentroles-payment-chip agentroles-payment-chip--${paymentStateKey}`}
                          >
                            {paymentState}
                          </span>
                        </div>
                        <div className="table-cell agentroles-spend-cap-cell">
                          {formatSpendCapSummary(agent)}
                        </div>
                        <div className="table-cell agentroles-payment-activity-cell">
                          <span>{formatPaymentUsd(agent.paymentOut30dUsd)} out</span>
                          <span className="terminal-text-muted">
                            {formatPaymentUsd(agent.paymentIn30dUsd)} in
                          </span>
                        </div>
                        <div className="table-cell">
                          {agent.counterpartyAllowlistCount != null
                            ? `${agent.counterpartyAllowlistCount} parties`
                            : "—"}
                        </div>
                        <div className="table-cell agentroles-payment-actions-cell">
                          {paymentState !== "No payments" ? (
                            <button
                              type="button"
                              className="agentroles-payment-action-btn"
                              onClick={(event) => handleSendPayment(event, agent.id)}
                            >
                              Send payment
                            </button>
                          ) : (
                            <span className="terminal-text-muted">—</span>
                          )}
                          <button
                            type="button"
                            className="agentroles-payment-action-btn agentroles-payment-action-btn--ghost"
                            onClick={(event) => {
                              event.stopPropagation();
                              navigate(agentRolesConsolePath(agent.id));
                            }}
                          >
                            Console
                          </button>
                        </div>
                      </>
                    ) : (
                      <>
                        <div className="table-cell">
                          <AgentRolesRegistryWalletCell
                            walletAddress={agent.walletAddress}
                          />
                        </div>
                        <div className="table-cell">
                          <span
                            className={`agentroles-payment-chip agentroles-payment-chip--compact agentroles-payment-chip--${paymentStateKey}`}
                          >
                            {getAgentPaymentShortLabel(agent)}
                          </span>
                        </div>
                        <div className="table-cell">
                          {agent.listingStatus === "listed" && agent.catalogAgentId ? (
                            <Link
                              to={`/agents/${agent.catalogAgentId}`}
                              className="agentroles-listing-badge agentroles-listing-badge--listed"
                              onClick={(e) => e.stopPropagation()}
                            >
                              Listed
                            </Link>
                          ) : (
                            <span
                              className={`agentroles-listing-badge agentroles-listing-badge--${agent.listingStatus}`}
                            >
                              {getListingLabel(agent.listingStatus)}
                            </span>
                          )}
                        </div>
                        <div className="table-cell agentroles-reputation-cell">
                          {showReputation ? (
                            <>
                              <span>{formatAgentRevenue(agent.revenue30d)}</span>
                              <span className="terminal-text-muted">
                                {agent.riskScore ?? "—"}
                              </span>
                            </>
                          ) : (
                            <span className="terminal-text-muted">—</span>
                          )}
                        </div>
                      </>
                    )}
                  </button>
                );
              })
            )}
          </div>
        </div>
      </div>
      {detailPanel}
    </div>
  );
}
