import React from "react";

import { formatCurrency } from "../../sdk/utils/display";
import {
  formatLeaderboardTraderLabel,
  formatSignedCurrency,
  formatSignedPercent,
  LEADERBOARD_TIMEFRAME_LABELS,
  type LeaderboardSortField,
  type LeaderboardTimeframe,
  type TraderLeaderboardViewRow,
} from "../../utils/leaderboardMetrics";
import {
  TableHeaderCell,
  TableHeaderCellStatic,
} from "../smartlayout";
import VaultPanelLoadingGate from "../vault/VaultPanelLoadingGate";
import "../smartlayout/layout.css";
import "../portfolio/portfolio.css";
import LeaderboardTableFooter from "./LeaderboardTableFooter";
import "../vault/vault.css";
import "./leaderboard.css";

const GRID_CLASS = "leaderboard-grid";
const GRID_COLUMNS =
  "3.5rem minmax(160px, 1.6fr) minmax(120px, 1.1fr) minmax(100px, 1fr) minmax(90px, 0.9fr) minmax(120px, 1.1fr)";
const GRID_STYLE = { gridTemplateColumns: GRID_COLUMNS };

export interface LeaderboardTableProps {
  timeframe: LeaderboardTimeframe;
  sortField: LeaderboardSortField;
  sortDirection: "asc" | "desc";
  onSort: (field: LeaderboardSortField) => void;
  pinnedRow: TraderLeaderboardViewRow | null;
  pageRows: TraderLeaderboardViewRow[];
  page: number;
  pageSize: number;
  totalCount: number;
  loading?: boolean;
  error?: string | null;
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;
}

function timeframeSuffix(timeframe: LeaderboardTimeframe): string {
  return LEADERBOARD_TIMEFRAME_LABELS[timeframe];
}

function signedClassName(value: number): string {
  if (value > 0) return " positive";
  if (value < 0) return " negative";
  return "";
}

function PnlCell({ value }: { value: number }): JSX.Element {
  return (
    <div className={`table-cell numeric left${signedClassName(value)}`}>
      {formatSignedCurrency(value)}
    </div>
  );
}

function RoiCell({ value }: { value: number }): JSX.Element {
  return (
    <div className={`table-cell numeric left${signedClassName(value)}`}>
      {formatSignedPercent(value)}
    </div>
  );
}

function LeaderboardDataRow({
  row,
  variant = "default",
}: {
  row: TraderLeaderboardViewRow;
  variant?: "default" | "you";
}): JSX.Element {
  const rowClassName = [
    "table-row",
    GRID_CLASS,
    variant === "you" ? "leaderboard-row--you" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={rowClassName} role="row" style={GRID_STYLE}>
      <div className="table-cell left leaderboard-rank-cell">
        {row.rank.toLocaleString("en-US")}
      </div>
      <div className="table-cell left primary leaderboard-trader-cell">
        {variant === "you" ? (
          <span className="leaderboard-edit-icon" aria-hidden>
            ✎
          </span>
        ) : null}
        <span className="leaderboard-trader-name">
          {formatLeaderboardTraderLabel(row)}
        </span>
        {variant === "you" ? (
          <span className="leaderboard-you-badge">YOU</span>
        ) : null}
      </div>
      <div className="table-cell numeric left">
        {formatCurrency(row.accountValueUsd)}
      </div>
      <PnlCell value={row.pnlUsd} />
      <RoiCell value={row.roiPct} />
      <div className="table-cell numeric left">
        {formatCurrency(row.volumeUsd)}
      </div>
    </div>
  );
}

function LeaderboardTableHeader({
  suffix,
  sortField,
  sortDirection,
  onSort,
}: {
  suffix: string;
  sortField: LeaderboardSortField;
  sortDirection: "asc" | "desc";
  onSort: (field: LeaderboardSortField) => void;
}): JSX.Element {
  return (
    <div className={`table-header ${GRID_CLASS}`} role="row" style={GRID_STYLE}>
      <TableHeaderCellStatic left>Rank</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Trader</TableHeaderCellStatic>
      <TableHeaderCell<LeaderboardSortField>
        field="accountValueUsd"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={onSort}
        left
      >
        Account Value
      </TableHeaderCell>
      <TableHeaderCell<LeaderboardSortField>
        field="pnlUsd"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={onSort}
        left
      >
        {`PnL (${suffix})`}
      </TableHeaderCell>
      <TableHeaderCell<LeaderboardSortField>
        field="roiPct"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={onSort}
        left
      >
        {`ROI (${suffix})`}
      </TableHeaderCell>
      <TableHeaderCell<LeaderboardSortField>
        field="volumeUsd"
        currentSortField={sortField}
        sortDirection={sortDirection}
        onSort={onSort}
        left
      >
        {`Volume (${suffix})`}
      </TableHeaderCell>
    </div>
  );
}

export default function LeaderboardTable({
  timeframe,
  sortField,
  sortDirection,
  onSort,
  pinnedRow,
  pageRows,
  page,
  pageSize,
  totalCount,
  loading = false,
  error = null,
  onPageChange,
  onPageSizeChange,
}: LeaderboardTableProps): JSX.Element {
  const suffix = timeframeSuffix(timeframe);
  const isEmpty = !loading && pageRows.length === 0 && !pinnedRow;

  return (
    <section className="leaderboard-table-panel" aria-label="Trader leaderboard">
      <VaultPanelLoadingGate
        loading={loading}
        label="Loading leaderboard…"
        className="leaderboard-table-loading-gate"
      >
        <div className="leaderboard-table-scroll">
          <div className="table-container shrinkable leaderboard-table">
            <LeaderboardTableHeader
              suffix={suffix}
              sortField={sortField}
              sortDirection={sortDirection}
              onSort={onSort}
            />

            {!loading && error ? (
              <p className="terminal-text-muted leaderboard-empty leaderboard-error">
                {error}
              </p>
            ) : null}

            {!loading && pinnedRow ? (
              <LeaderboardDataRow row={pinnedRow} variant="you" />
            ) : null}

            {isEmpty ? (
              <p className="terminal-text-muted leaderboard-empty">
                No traders match your filters.
              </p>
            ) : null}

            {!loading
              ? pageRows.map((row) => (
                  <LeaderboardDataRow key={row.address} row={row} />
                ))
              : null}
          </div>
        </div>

        <LeaderboardTableFooter
          page={page}
          pageSize={pageSize}
          totalCount={loading ? 0 : totalCount}
          onPageChange={onPageChange}
          onPageSizeChange={onPageSizeChange}
        />
      </VaultPanelLoadingGate>
    </section>
  );
}
