import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { useNavigate } from "react-router-dom";

import { buildDefaultVaultTradingBucket } from "../../../offline/mock_data/vaultBucketFactory";
import {
  buildStandardVaultFeeModel,
  formatFeeExampleSummary,
  isValidStandardPerformanceFee,
  STANDARD_PERFORMANCE_FEE_DEFAULT_PCT,
  STANDARD_PERFORMANCE_FEE_MAX_PCT,
  STANDARD_PERFORMANCE_FEE_MIN_PCT,
  type VaultVisibility,
} from "../../../offline/mock_data/vaultFeeModel";
import { createUserVaultWithDeposit } from "../../../offline/mock_data/vaultUserState";
import { vaultDetailPath, tradeVaultPath, APP_ROUTES } from "../../routes";
import { useVaultOperate } from "../../context/VaultOperateContext";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { formatCurrency } from "../../sdk/utils/display";
import type { CreateVaultTourStepId } from "../../tutorials/create-vault-tour/constants";
import { CREATE_VAULT_TOUR_TARGETS } from "../../tutorials/create-vault-tour/constants";
import { useOptionalCreateVaultTour } from "../../tutorials/create-vault-tour";
import { NumberPad } from "../smartlayout/number-pad";
import "../smartlayout/layout.css";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import ModalHeader from "../ui/ModalHeader";
import { PresetCardGrid } from "../ui/PresetCardGrid";
import type { PresetCardOption } from "../ui/PresetCardGrid";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import "./vault.css";

const OFFLINE_BASE_URL = "offline://local";

type StrategyType =
  | "market_making"
  | "momentum"
  | "basis"
  | "carry"
  | "funding";

type CreateVaultStep =
  | "details"
  | "strategy"
  | "funding"
  | "fee_model"
  | "visibility";

const CREATE_VAULT_STEPS: CreateVaultStep[] = [
  "details",
  "strategy",
  "funding",
  "fee_model",
  "visibility",
];

const STEP_LABELS: Record<CreateVaultStep, string> = {
  details: "Details",
  strategy: "Strategy",
  funding: "Funding",
  fee_model: "Fee Model",
  visibility: "Visibility",
};

const STRATEGY_OPTIONS: PresetCardOption<StrategyType>[] = [
  {
    value: "market_making",
    label: "Market Making",
    description: "Balanced quotes around fair value; low directional bias",
  },
  {
    value: "momentum",
    label: "Momentum",
    description: "Trend-following exposure across major perps",
  },
  {
    value: "basis",
    label: "Basis Arb",
    description: "Spot–perp basis and funding spread capture",
  },
  {
    value: "carry",
    label: "Carry",
    description: "Roll yield and term-structure carry",
  },
  {
    value: "funding",
    label: "Funding Harvest",
    description: "Systematic funding-rate harvesting",
  },
];

const VISIBILITY_OPTIONS: PresetCardOption<VaultVisibility>[] = [
  {
    value: "public",
    label: "Public",
    description: "Appears on the Vault listing after creation.",
  },
  {
    value: "private",
    label: "Private",
    description: "Only visible to you until you publish.",
  },
];

const DEFAULT_MARKETS = ["BTC", "ETH", "SOL"];
const MIN_DEPOSIT = 100;

export interface CreateVaultTourPrefill {
  name: string;
  description: string;
  strategyType: StrategyType;
  initialDeposit: number;
  performanceFeePct: number;
  visibility: VaultVisibility;
}

export interface CreateVaultModalProps {
  isOpen: boolean;
  onClose: () => void;
  walletAddress: string;
  tourActive?: boolean;
  tourPrefill?: CreateVaultTourPrefill;
  tourForcedVaultId?: string;
}

function stepIndex(step: CreateVaultStep): number {
  return CREATE_VAULT_STEPS.indexOf(step);
}

function previousStep(step: CreateVaultStep): CreateVaultStep | null {
  const index = stepIndex(step);
  return index > 0 ? CREATE_VAULT_STEPS[index - 1] : null;
}

function nextStep(step: CreateVaultStep): CreateVaultStep | null {
  const index = stepIndex(step);
  return index < CREATE_VAULT_STEPS.length - 1
    ? CREATE_VAULT_STEPS[index + 1]
    : null;
}

export default function CreateVaultModal({
  isOpen,
  onClose,
  walletAddress,
  tourActive = false,
  tourPrefill,
  tourForcedVaultId,
}: CreateVaultModalProps): JSX.Element | null {
  const navigate = useNavigate();
  const { enterOperate } = useVaultOperate();
  const createVaultTour = useOptionalCreateVaultTour();
  const notifyModalState = createVaultTour?.notifyModalState;
  const registerSetModalStep = createVaultTour?.registerSetModalStep;
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);
  const isClosing = mounted && !isOpen;

  const [step, setStep] = useState<CreateVaultStep>("details");
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [strategyType, setStrategyType] = useState<StrategyType>("market_making");
  const [markets, setMarkets] = useState<string[]>([...DEFAULT_MARKETS]);
  const [initialDeposit, setInitialDeposit] = useState(MIN_DEPOSIT);
  const [visibility, setVisibility] = useState<VaultVisibility>("public");
  const [performanceFeePct, setPerformanceFeePct] = useState(
    STANDARD_PERFORMANCE_FEE_DEFAULT_PCT,
  );
  const [isNumberPadOpen, setIsNumberPadOpen] = useState(false);
  const [createdVault, setCreatedVault] = useState<{
    id: string;
    name: string;
  } | null>(null);

  const { spotWalletBalance } = useBucketCollections({
    baseURL: OFFLINE_BASE_URL,
    walletAddress,
    refreshInterval: 5000,
    useWebSocket: false,
  });

  const maxDeposit = spotWalletBalance;
  const canFundDeposit = maxDeposit >= MIN_DEPOSIT;
  const currentStepIndex = stepIndex(step);

  useEffect(() => {
    if (!isOpen) {
      setStep("details");
      if (!tourActive) {
        setName("");
        setDescription("");
        setStrategyType("market_making");
        setMarkets([...DEFAULT_MARKETS]);
        setInitialDeposit(MIN_DEPOSIT);
        setVisibility("public");
        setPerformanceFeePct(STANDARD_PERFORMANCE_FEE_DEFAULT_PCT);
      }
      setIsNumberPadOpen(false);
      setCreatedVault(null);
    }
  }, [isOpen, tourActive]);

  useOverlayEscapeKey(
    isOpen && !isNumberPadOpen && !tourActive && !createdVault,
    onClose,
  );

  useEffect(() => {
    if (!isOpen || maxDeposit <= 0) return;
    setInitialDeposit((prev) =>
      Math.min(Math.max(prev, MIN_DEPOSIT), maxDeposit),
    );
  }, [isOpen, maxDeposit]);

  useEffect(() => {
    if (!isOpen || !tourPrefill) return;
    setName(tourPrefill.name);
    setDescription(tourPrefill.description);
    setStrategyType(tourPrefill.strategyType);
    setMarkets([...DEFAULT_MARKETS]);
    setInitialDeposit(tourPrefill.initialDeposit);
    setVisibility(tourPrefill.visibility);
    setPerformanceFeePct(tourPrefill.performanceFeePct);
    setStep("details");
  }, [isOpen, tourPrefill]);

  useEffect(() => {
    if (!registerSetModalStep) return;
    return registerSetModalStep((nextStep: CreateVaultTourStepId) => {
      setStep(nextStep);
    });
  }, [registerSetModalStep]);

  useEffect(() => {
    notifyModalState?.({
      isOpen,
      step,
      showSuccess: Boolean(createdVault),
    });
  }, [notifyModalState, isOpen, step, createdVault]);

  const canCreate =
    walletAddress.trim().length > 0 &&
    name.trim().length > 0 &&
    initialDeposit >= MIN_DEPOSIT &&
    initialDeposit <= maxDeposit &&
    isValidStandardPerformanceFee(performanceFeePct);

  const feeExampleSummary = useMemo(
    () => formatFeeExampleSummary(performanceFeePct),
    [performanceFeePct],
  );

  const canContinue = useMemo(() => {
    switch (step) {
      case "details":
        return name.trim().length > 0;
      case "strategy":
        return true;
      case "funding":
        return initialDeposit >= MIN_DEPOSIT && initialDeposit <= maxDeposit;
      case "fee_model":
        return isValidStandardPerformanceFee(performanceFeePct);
      case "visibility":
        return canCreate;
      default:
        return false;
    }
  }, [step, name, initialDeposit, maxDeposit, canCreate, performanceFeePct]);

  const openNumberPad = useCallback(() => {
    if (canFundDeposit) {
      setIsNumberPadOpen(true);
    }
  }, [canFundDeposit]);

  const handleDepositDisplayKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openNumberPad();
      }
    },
    [openNumberPad],
  );

  const handleNumberPadConfirm = useCallback(
    (value: number) => {
      setInitialDeposit(value);
      setIsNumberPadOpen(false);
    },
    [],
  );

  const handleBack = useCallback(() => {
    const prev = previousStep(step);
    if (prev) {
      setStep(prev);
    }
  }, [step]);

  const handleContinue = useCallback(() => {
    if (!canContinue) return;
    const next = nextStep(step);
    if (next) {
      setStep(next);
    }
  }, [canContinue, step]);

  const handleCreate = useCallback(() => {
    if (!canCreate || !walletAddress.trim()) return;

    const trimmedName = name.trim() || "New Vault";
    const strategy = STRATEGY_OPTIONS.find((s) => s.value === strategyType);
    const deposit = initialDeposit;
    const placeholderId = tourForcedVaultId ?? "pending-vault";

    const result = createUserVaultWithDeposit(
      walletAddress,
      {
        name: trimmedName,
        leader: `${walletAddress.slice(0, 4)}..${walletAddress.slice(-2)}`,
        leaderAddress: walletAddress,
        strategyType,
        strategyLabel: strategy?.label.toUpperCase() ?? "CUSTOM",
        description: description.trim() || "User-created vault.",
        grade: null,
        aprPct: null,
        ageDays: 0,
        isFlagship: false,
        isPinned: false,
        snapshotSparkline: [],
        spotlightSparkline90d: [],
        pastMonthReturnPct: null,
        analystVerdict: {
          grade: null,
          score: null,
          verified: false,
          percentileLabel: null,
          confidence: null,
          insufficientPassage:
            "We're not grading this vault yet — it just went live and there's no performance history to work with. Once it's had a full month in market, we'll come back with a proper score and verdict.",
          summary:
            "We're not grading this vault yet — it just went live and there's no performance history to work with. Once it's had a full month in market, we'll come back with a proper score and verdict.",
          spotlightSummary: "Too early to grade — just created.",
          verificationReason: "Pending — new vault",
          flags: [],
          hasFlags: false,
          metrics: {
            return90dPct: null,
            sharpe: null,
            maxDrawdownPct: null,
            trackRecordDays: 0,
            tvlUsd: deposit,
          },
        },
        buckets: [buildDefaultVaultTradingBucket(placeholderId, deposit, markets)],
        feeModel: buildStandardVaultFeeModel(performanceFeePct),
        visibility,
      },
      deposit,
      tourForcedVaultId,
    );

    if (!result.ok) return;

    setCreatedVault({ id: result.vault.id, name: trimmedName });
  }, [
    canCreate,
    name,
    description,
    strategyType,
    initialDeposit,
    performanceFeePct,
    visibility,
    tourForcedVaultId,
    walletAddress,
    markets,
  ]);

  const handleStartOperating = useCallback(() => {
    if (!createdVault) return;
    if (enterOperate(createdVault.id)) {
      onClose();
      navigate(tradeVaultPath(createdVault.id));
    }
  }, [createdVault, enterOperate, navigate, onClose]);

  const handleViewCreatedVault = useCallback(() => {
    if (!createdVault) return;
    onClose();
    navigate(vaultDetailPath(createdVault.id));
  }, [createdVault, navigate, onClose]);

  const handleBackToVaults = useCallback(() => {
    onClose();
    navigate(APP_ROUTES.vault);
  }, [navigate, onClose]);

  const isFirstStep = step === "details";
  const isLastStep = step === "visibility";

  const modalContent = (
    <StaggeredOverlayRoot passThrough={!isOpen}>
      <StaggeredOverlayBackdrop
        visible={backdropVisible && isOpen}
        style={backdropStyle}
        onClose={onClose}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={`modal-content terminal-overlay-panel-shell vault-modal-content staggered-overlay-panel--scale${isClosing ? " bucket-modal-panel--closing" : ""}`}
        aria-label="Create Vault"
      >
        <ModalHeader
          multiline={!createdVault}
          leading={
            <>
              <h3 className="terminal-panel-title">
                {createdVault ? "Vault Created" : "Create Vault"}
              </h3>
              {!createdVault ? (
                <>
                  <p
                    className="vault-create-step-meta"
                    data-tour={CREATE_VAULT_TOUR_TARGETS.stepMeta}
                  >
                    Step {currentStepIndex + 1} of {CREATE_VAULT_STEPS.length} ·{" "}
                    {STEP_LABELS[step]}
                  </p>
                  <div className="vault-create-step-dots" aria-hidden>
                    {CREATE_VAULT_STEPS.map((stepId, index) => (
                      <span
                        key={stepId}
                        className={[
                          "vault-create-step-dot",
                          index === currentStepIndex &&
                            "vault-create-step-dot--active",
                          index < currentStepIndex &&
                            "vault-create-step-dot--complete",
                        ]
                          .filter(Boolean)
                          .join(" ")}
                      />
                    ))}
                  </div>
                </>
              ) : null}
            </>
          }
          onClose={onClose}
          closeDisabled={isClosing}
        />
        <div className="modal-body vault-create-modal-body">
          {createdVault ? (
            <div
              className="vault-create-success-panel"
              data-tour={CREATE_VAULT_TOUR_TARGETS.createSuccess}
            >
              <p className="vault-create-success-title">
                ✅ {createdVault.name} is live
              </p>
              <p className="vault-modal-notice-text">
                Your vault is ready. Start operating to trade from vault buckets,
                or view the vault detail page to manage buckets and deposits.
              </p>
            </div>
          ) : (
          <div className="vault-create-carousel-viewport" aria-live="polite">
            <div
              className="vault-create-carousel-track"
              style={{
                transform: `translateX(-${currentStepIndex * 100}%)`,
              }}
            >
              <fieldset
                className="vault-create-carousel-slide"
                disabled={step !== "details"}
                aria-hidden={step !== "details"}
                data-tour={CREATE_VAULT_TOUR_TARGETS.details}
              >
                <div className="transfer-field-group">
                  <label
                    htmlFor="vault-name"
                    className="terminal-label transfer-field-label"
                  >
                    Vault name
                  </label>
                  <input
                    id="vault-name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Delta-Neutral MM #1"
                    className="form-input transfer-select transfer-input"
                  />
                </div>

                <div className="transfer-field-group">
                  <label
                    htmlFor="vault-desc"
                    className="terminal-label transfer-field-label"
                  >
                    Short description
                  </label>
                  <textarea
                    id="vault-desc"
                    rows={3}
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder="Market-making vault focused on balanced long/short exposure."
                    className="form-input transfer-select transfer-input"
                  />
                </div>
              </fieldset>

              <fieldset
                className="vault-create-carousel-slide"
                disabled={step !== "strategy"}
                aria-hidden={step !== "strategy"}
                data-tour={CREATE_VAULT_TOUR_TARGETS.strategy}
              >
                <section className="transfer-field-group">
                  <h4 className="vault-modal-section-title">Strategy type</h4>
                  <PresetCardGrid
                    options={STRATEGY_OPTIONS}
                    selected={strategyType}
                    onSelect={setStrategyType}
                    columns={2}
                    className="vault-create-strategy-grid"
                    aria-label="Strategy type"
                  />
                </section>

                <div className="transfer-field-group">
                  <span className="terminal-label transfer-field-label">
                    Starting markets
                  </span>
                  <div className="vault-market-chips">
                    {markets.map((m) => (
                      <span key={m} className="vault-market-chip">
                        {m}
                      </span>
                    ))}
                  </div>
                </div>
              </fieldset>

              <fieldset
                className="vault-create-carousel-slide"
                disabled={step !== "funding"}
                aria-hidden={step !== "funding"}
                data-tour={CREATE_VAULT_TOUR_TARGETS.funding}
              >
                <div className="transfer-field-group">
                  <div className="transfer-amount-header">
                    <label className="terminal-label transfer-field-label">
                      Initial deposit
                    </label>
                    <div className="transfer-available-balance">
                      <span className="terminal-label">Wallet</span>
                      <span className="terminal-value">
                        {formatCurrency(maxDeposit)} USDC
                      </span>
                    </div>
                  </div>
                  {canFundDeposit ? (
                    <>
                      <div
                        className="transfer-amount-display transfer-amount-display--interactive"
                        onClick={openNumberPad}
                        onKeyDown={handleDepositDisplayKeyDown}
                        role="button"
                        tabIndex={step === "funding" ? 0 : -1}
                        aria-label="Edit initial deposit"
                      >
                        <span className="terminal-price transfer-amount-value">
                          {formatCurrency(initialDeposit)}
                        </span>
                      </div>
                      <div className="transfer-amount-container">
                        <FilledRangeSlider
                          variant="info"
                          min={MIN_DEPOSIT}
                          max={maxDeposit}
                          step={0.01}
                          value={initialDeposit}
                          onChange={setInitialDeposit}
                        />
                        <div className="transfer-amount-labels">
                          <span className="terminal-value">
                            {formatCurrency(MIN_DEPOSIT)}
                          </span>
                          <span className="terminal-value">
                            {formatCurrency(maxDeposit)}
                          </span>
                        </div>
                      </div>
                    </>
                  ) : (
                    <div className="transfer-insufficient-funds">
                      Insufficient funds. Minimum required:{" "}
                      {formatCurrency(MIN_DEPOSIT)}
                    </div>
                  )}
                </div>
              </fieldset>

              <fieldset
                className="vault-create-carousel-slide"
                disabled={step !== "fee_model"}
                aria-hidden={step !== "fee_model"}
                data-tour={CREATE_VAULT_TOUR_TARGETS.fee}
              >
                <section className="transfer-field-group">
                  <h4 className="vault-modal-section-title">Fee preset</h4>
                  <div className="vault-create-fee-preset-notice">
                    <span className="terminal-label">Standard Vault</span>
                    <p className="vault-modal-notice-text">
                      Investor-aligned: you earn only after depositors earn net
                      new profit. Premium and protocol presets unlock post-beta.
                    </p>
                  </div>
                </section>

                <div className="transfer-field-group">
                  <div className="transfer-amount-header">
                    <label className="terminal-label transfer-field-label">
                      Performance fee
                    </label>
                    <span className="terminal-value">
                      {performanceFeePct.toFixed(1)}%
                    </span>
                  </div>
                  <div className="transfer-amount-container">
                    <FilledRangeSlider
                      variant="info"
                      min={STANDARD_PERFORMANCE_FEE_MIN_PCT}
                      max={STANDARD_PERFORMANCE_FEE_MAX_PCT}
                      step={0.5}
                      value={performanceFeePct}
                      onChange={setPerformanceFeePct}
                    />
                    <div className="transfer-amount-labels">
                      <span className="terminal-value">
                        {STANDARD_PERFORMANCE_FEE_MIN_PCT}%
                      </span>
                      <span className="terminal-value">
                        {STANDARD_PERFORMANCE_FEE_MAX_PCT}%
                      </span>
                    </div>
                  </div>
                </div>

                <div className="vault-create-fee-rows">
                  <div className="vault-create-fee-row">
                    <span className="terminal-label">Management fee</span>
                    <span className="terminal-value">0% (locked)</span>
                  </div>
                  <div className="vault-create-fee-row">
                    <span className="terminal-label">High-water mark</span>
                    <span className="terminal-value">On (always)</span>
                  </div>
                  <div className="vault-create-fee-row">
                    <span className="terminal-label">Deposit fee</span>
                    <span className="terminal-value">0%</span>
                  </div>
                  <div className="vault-create-fee-row">
                    <span className="terminal-label">Withdrawal fee</span>
                    <span className="terminal-value">0%</span>
                  </div>
                  <div className="vault-create-fee-row">
                    <span className="terminal-label">Fee crystallization</span>
                    <span className="terminal-value">
                      On withdrawal + monthly if profitable
                    </span>
                  </div>
                  <div className="vault-create-fee-row">
                    <span className="terminal-label">Fee change policy</span>
                    <span className="terminal-value">
                      Applies to new deposits only
                    </span>
                  </div>
                </div>

                <div className="vault-modal-notice vault-create-fee-example">
                  <span className="terminal-label">Investor example</span>
                  <p className="vault-modal-notice-text">{feeExampleSummary}</p>
                </div>
              </fieldset>

              <fieldset
                className="vault-create-carousel-slide"
                disabled={step !== "visibility"}
                aria-hidden={step !== "visibility"}
                data-tour={CREATE_VAULT_TOUR_TARGETS.visibility}
              >
                <section className="transfer-field-group">
                  <h4 className="vault-modal-section-title">Visibility</h4>
                  <PresetCardGrid
                    options={VISIBILITY_OPTIONS}
                    selected={visibility}
                    onSelect={setVisibility}
                    columns={2}
                    className="vault-create-visibility-grid"
                    aria-label="Vault visibility"
                  />
                </section>

                <div className="vault-modal-notice">
                  <span className="terminal-label">Analyst rating</span>
                  <p className="vault-modal-notice-text">
                    We won&apos;t grade your vault until it has about a month of live
                    history — you&apos;ll see a full analyst verdict on the detail page
                    once there&apos;s enough to score.
                  </p>
                </div>
              </fieldset>
            </div>
          </div>
          )}
        </div>

        <div className="modal-footer">
          {createdVault ? (
            <>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={handleBackToVaults}
                disabled={isClosing}
              >
                Back to vaults
              </button>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={handleViewCreatedVault}
                disabled={isClosing}
              >
                View vault
              </button>
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleStartOperating}
                disabled={isClosing}
              >
                ⚡ Start operating →
              </button>
            </>
          ) : (
            <>
          <button
            type="button"
            className="btn btn-secondary"
            onClick={isFirstStep ? onClose : handleBack}
            disabled={isClosing}
          >
            {isFirstStep ? "Cancel" : "Back"}
          </button>
          {isLastStep ? (
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleCreate}
              disabled={!canCreate || isClosing}
              data-tour={CREATE_VAULT_TOUR_TARGETS.submitBtn}
            >
              Create
            </button>
          ) : (
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleContinue}
              disabled={!canContinue || isClosing}
              data-tour={CREATE_VAULT_TOUR_TARGETS.continueBtn}
            >
              Continue
            </button>
          )}
            </>
          )}
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return (
    <>
      {mounted && typeof document !== "undefined"
        ? createPortal(modalContent, document.body)
        : null}
      <NumberPad
        isOpen={isNumberPadOpen}
        value={initialDeposit}
        min={MIN_DEPOSIT}
        max={maxDeposit}
        onConfirm={handleNumberPadConfirm}
        onCancel={() => setIsNumberPadOpen(false)}
      />
    </>
  );
}
