import React from "react";

import {
  STAKING_PAGE_VIEWS,
  type StakingPageView,
} from "./stakingPageView";
import "../tables/TabSection.css";
import "./staking.css";

export interface StakingHeroViewNavProps {
  activeView: StakingPageView;
  onViewChange: (view: StakingPageView) => void;
}

function StakingHeroViewNav({
  activeView,
  onViewChange,
}: StakingHeroViewNavProps): JSX.Element {
  return (
    <nav
      className="staking-hero-view-nav raw-pro-data-toggle"
      aria-label="Staking page view"
      role="tablist"
    >
      {STAKING_PAGE_VIEWS.map((view) => (
        <button
          key={view.id}
          type="button"
          role="tab"
          aria-selected={activeView === view.id}
          className={`raw-pro-data-toggle-segment${
            activeView === view.id ? " is-active" : ""
          }`}
          onClick={() => onViewChange(view.id)}
        >
          {view.label}
        </button>
      ))}
    </nav>
  );
}

export default React.memo(StakingHeroViewNav);
