const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [VAULT_BUCKET_LAYOUT_MARGIN, VAULT_BUCKET_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = VAULT_BUCKET_ROW_HEIGHT;

function resolveBucketUseCards(
  bucketMode: "cross" | "isolated",
  positionCount: number,
): boolean {
  return (
    bucketMode === "isolated" ||
    positionCount === 1 ||
    positionCount <= 3
  );
}

function buildLayouts(
  viewportHeight?: number,
  positionCount?: number,
  useCards?: boolean,
) {
  const base = buildVaultBucketResponsiveLayoutConfig();
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyVaultBucketLayoutSizing(
    base,
    height,
    positionCount ?? 3,
    useCards ?? false,
  );
  return generateVaultBucketResponsiveLayouts(sized, 0);
}

type BucketTab = "positions" | "openOrders" | "tradeHistory" | "fundingHistory";

function VaultBucketHeader({
  height,
  vaultName,
  vaultId,
  bucketId,
  bucketName,
  mode,
}: {
  height?: string;
  vaultName: string;
  vaultId: string;
  bucketId: string;
  bucketName: string;
  mode: "cross" | "isolated";
}): JSX.Element {
  return (
    <div className="vault-slot vault-slot--flush vault-detail-header" style={{ height }}>
    
      <div className="vault-detail-identity">
        <p className="eyebrow-text">
          BUCKET · {mode === "cross" ? "CROSS" : "ISOLATED"} MODE
        </p>
        <div className="vault-detail-title-row">
          <div>
            <h1 className="vault-detail-title">{bucketName}</h1>
            <span
              className={`vault-mode-chip vault-mode-chip--${mode}`}
            >
              {mode === "cross" ? "Cross" : "Isolated"}
            </span>
            <span className="terminal-label" style={{ marginLeft: 8 }}>
              Bucket · read-only
            </span>
          </div>
        </div>
      </div>

      <p className="vault-breadcrumb">
        <Link to={APP_ROUTES.vault}>Vaults</Link> ›{" "}
        <Link to={vaultDetailPath(vaultId)}>{vaultName}</Link> ›{" "}
        <span className="vault-activity-source-hash" title={bucketId}>
          {shortHashId(bucketId)}
        </span>
      </p>
      
    </div>
  );
}

function VaultBucketPositionsFilters({
  positionsState,
}: {
  positionsState: ReturnType<typeof useVaultBucketPositions>;
}): JSX.Element {
  return (
    <div className="vault-bucket-positions-filters">
      <input
        type="search"
        placeholder="Search"
        value={positionsState.query}
        onChange={(e) => positionsState.setQuery(e.target.value)}
        aria-label="Search market"
      />
      <select
        value={positionsState.sideFilter}
        onChange={(e) =>
          positionsState.setSideFilter(e.target.value as "all" | "long" | "short")
        }
        aria-label="Filter by side"
      >
        <option value="all">Side: All</option>
        <option value="long">Long</option>
        <option value="short">Short</option>
      </select>
      <select
        value={positionsState.marketFilter}
        onChange={(e) => positionsState.setMarketFilter(e.target.value)}
        aria-label="Filter by market"
      >
        <option value="all">Market: All</option>
        {positionsState.markets.map((m) => (
          <option key={m} value={m}>
            {m}
          </option>
        ))}
      </select>
      <select
        value={positionsState.sortKey}
        onChange={(e) =>
          positionsState.setSortKey(e.target.value as typeof positionsState.sortKey)
        }
        aria-label="Sort positions"
      >
        <option value="positionValue">Sort: Value</option>
        <option value="market">Sort: Market</option>
        <option value="unrealizedPnl">Sort: uPnL</option>
        <option value="margin">Sort: Margin</option>
      </select>
    </div>
  );
}

function VaultBucketBody({
  height,
  vaultId,
  bucketId,
  bucketMode,
  allPositions,
  positionsState,
  currentBreakpoint,
}: {
  height?: string;
  vaultId: string;
  bucketId: string;
  bucketMode: "cross" | "isolated";
  allPositions: ReturnType<typeof getBucketPositions>;
  positionsState: ReturnType<typeof useVaultBucketPositions>;
  currentBreakpoint: string;
}): JSX.Element {
  const [tab, setTab] = useState<BucketTab>("positions");
  const openOrders = useVaultOpenOrders(vaultId, bucketId);
  const useCards = resolveBucketUseCards(bucketMode, allPositions.length);
  const showTableFilters =
    tab === "positions" && !useCards && allPositions.length > 3;
  const showTabCounts = currentBreakpoint === "lg";

  const tabs = useMemo(
    () =>
      buildToolbarTabs(VAULT_BUCKET_STRIP, {
        counts: {
          positions: allPositions.length,
          openOrders: openOrders.length,
        },
        showCount: showTabCounts,
        useCompactLabels: tabStripUseCompactLabels(currentBreakpoint),
      }),
    [allPositions.length, openOrders.length, showTabCounts, currentBreakpoint],
  );

  return (
    <div
      className="vault-slot vault-detail-tab-section vault-bucket-positions-section"
      style={{ height }}
      aria-label="Bucket positions"
      data-tour={VAULT_TOUR_TARGETS.bucketPositions}
    >
      <div className="layout-container tab-section-root vault-detail-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={tab}
          onTabChange={(id) => setTab(id as BucketTab)}
        >
          {showTableFilters ? (
            <VaultBucketPositionsFilters positionsState={positionsState} />
          ) : null}
        </TabLayoutHeaderToolBar>

        <div className="tab-section-content vault-bucket-tab-content">
          {tab === "positions" ? (
            useCards ? (
              <div className="vault-position-card-grid">
                {allPositions.map((pos) => (
                  <VaultPositionCard key={pos.id} position={pos} />
                ))}
              </div>
            ) : (
              <VaultPositionsTable
                positionsState={positionsState}
                allPositions={allPositions}
              />
            )
          ) : tab === "openOrders" ? (
            <VaultOpenOrdersTable
              vaultId={vaultId}
              bucketId={bucketId}
              layout="bucket"
            />
          ) : tab === "tradeHistory" ? (
            <VaultTradeHistoryTable
              vaultId={vaultId}
              bucketId={bucketId}
              layout="bucket"
            />
          ) : (
            <VaultFundingHistoryTable
              vaultId={vaultId}
              bucketId={bucketId}
              layout="bucket"
            />
          )}
        </div>
      </div>
    </div>
  );
}

export default function VaultBucketDetailPage(): JSX.Element {
  const { vaultId = "", bucketId = "" } = useParams<{
    vaultId: string;
    bucketId: string;
  }>();

  const vault = getVaultById(vaultId);

  if (!vault) {
    return <Navigate to={APP_ROUTES.vault} replace />;
  }

  return (
    <VaultBucketDetailContent
      key={`${vaultId}-${bucketId}`}
      vaultId={vaultId}
      bucketId={bucketId}
    />
  );
}

function VaultBucketDetailContent({
  vaultId,
  bucketId,
}: {
  vaultId: string;
  bucketId: string;
}): JSX.Element {
  const { loading: activityLoading } = useVaultSystemData(vaultId);
  const vault = getVaultById(vaultId);
  const bucket = getVaultBucket(vaultId, bucketId);

  if (!activityLoading && (!vault || !bucket)) {
    return <Navigate to={APP_ROUTES.vault} replace />;
  }

  if (!vault || !bucket) {
    return (
      <div className="App-dex-content App-dex-content--vault-bucket">
        <VaultPanelLoadingGate loading className="vault-bucket-loading-shell">
          <div className="vault-slot" style={{ minHeight: 480 }} />
        </VaultPanelLoadingGate>
      </div>
    );
  }

  return (
    <VaultBucketDetailLoaded
      key={`${vaultId}-${bucketId}-${bucket.id}`}
      vault={vault}
      bucket={bucket}
      activityLoading={activityLoading}
    />
  );
}

function VaultBucketDetailLoaded({
  vault,
  bucket,
  activityLoading,
}: {
  vault: NonNullable<ReturnType<typeof getVaultById>>;
  bucket: NonNullable<ReturnType<typeof getVaultBucket>>;
  activityLoading: boolean;
}): JSX.Element {
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );
  const allPositions = useMemo(() => {
    void cacheRevision;
    return getBucketPositions(vault.id, bucket.id);
  }, [vault.id, bucket.id, cacheRevision]);
  const positionsState = useVaultBucketPositions(allPositions);
  const useCards = resolveBucketUseCards(bucket.mode, allPositions.length);

  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() =>
    buildLayouts(undefined, allPositions.length, useCards),
  );
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(
        window.innerHeight,
        allPositions.length,
        useCards,
      );
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };
    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, [allPositions.length, useCards]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const slotContent = useMemo(
    () => [
      <VaultBucketHeader
        key="header"
        height={slotDimensions[0]?.height}
        vaultName={vault.name}
        vaultId={vault.id}
        bucketId={bucket.id}
        bucketName={bucket.name}
        mode={bucket.mode}
      />,
      <VaultBucketKpiStrip
        key="kpi"
        height={slotDimensions[1]?.height}
        vault={vault}
        bucket={bucket}
      />,
      <VaultBucketHealthBar
        key="health"
        height={slotDimensions[2]?.height}
        bucket={bucket}
      />,
      <VaultPanelLoadingGate key="body-gate" loading={activityLoading}>
        <VaultBucketBody
          key="body"
          height={slotDimensions[3]?.height ?? "100%"}
          vaultId={vault.id}
          bucketId={bucket.id}
          bucketMode={bucket.mode}
          allPositions={allPositions}
          positionsState={positionsState}
          currentBreakpoint={currentBreakpoint}
        />
      </VaultPanelLoadingGate>,
      null,
      null,
      null,
      null,
      null,
    ],
    [
      slotDimensions,
      vault,
      bucket,
      allPositions,
      positionsState,
      currentBreakpoint,
      activityLoading,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--vault-bucket">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
      />
    </div>
  );
}
