import type { VaultActivityFile } from "./vaultActivityHistory.types";

const cache = new Map<string, VaultActivityFile>();
const listeners = new Set<() => void>();

let revision = 0;

export function getVaultActivityCacheRevision(): number {
  return revision;
}

export function subscribeVaultActivityCache(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notifyVaultActivityCache(): void {
  revision += 1;
  for (const listener of listeners) {
    listener();
  }
}

export function setCachedVaultActivity(
  vaultId: string,
  data: VaultActivityFile,
): void {
  cache.set(vaultId.trim().toLowerCase(), data);
  notifyVaultActivityCache();
}

export function getCachedVaultActivityById(
  vaultId: string,
): VaultActivityFile | null {
  return cache.get(vaultId.trim().toLowerCase()) ?? null;
}

export function clearVaultActivityCache(): void {
  cache.clear();
  notifyVaultActivityCache();
}

export function markVaultActivityMissing(vaultId: string): void {
  cache.set(vaultId.trim().toLowerCase(), {
    vaultId: vaultId.trim(),
    buckets: [],
    positionsByKey: {},
    activity: [],
    tradeHistory: [],
    fundingHistory: [],
    balances: [],
    openOrders: [],
    fundsMovements: [],
    depositors: [],
  });
  notifyVaultActivityCache();
}

export function isVaultActivityKnown(vaultId: string): boolean {
  return cache.has(vaultId.trim().toLowerCase());
}
