import { SECTOR_OPTIONS } from "../hooks/useMarketsPageData";
import type {
  AgentListingType,
  AgentListingVisibility,
  TradingAgent,
} from "../store/types";
import {
  getAgentCustodyKind,
  getAgentRoleLabel,
  getListingLabel,
  pickDeployCatalogAgentId,
} from "./agentRoles";
import { deriveMarketSymbol } from "./mintAgent";

export type DeployWizardStep = "select" | "details" | "review";

export type DeployTarget = "stage" | "stage_and_publish";

export interface DeployPerAgentDetails {
  description: string;
  listingType?: AgentListingType;
}

export interface DeployAgentWizardState {
  step: DeployWizardStep;
  selectedAgentIds: string[];
  target: DeployTarget;
  batchCategory: string;
  batchVisibility: AgentListingVisibility;
  perAgent: Record<string, DeployPerAgentDetails>;
}

export interface DeployEligibility {
  canSelect: boolean;
  canStage: boolean;
  canPublish: boolean;
  reason?: string;
  allowedListingTypes: AgentListingType[];
}

export interface DeployBatchListed {
  agentId: string;
  catalogAgentId: string;
}

export interface DeployBatchStaged {
  agentId: string;
}

export interface DeployBatchFailed {
  agentId: string;
  reason: string;
}

export interface DeployBatchResult {
  listed: DeployBatchListed[];
  staged: DeployBatchStaged[];
  failed: DeployBatchFailed[];
}

export const DEPLOY_LISTING_CATEGORY_OPTIONS = SECTOR_OPTIONS.filter(
  (item) => item !== "All",
);

const DEPLOY_WIZARD_STEPS: DeployWizardStep[] = ["select", "details", "review"];

export const DEFAULT_DEPLOY_WIZARD_STATE: DeployAgentWizardState = {
  step: "select",
  selectedAgentIds: [],
  target: "stage_and_publish",
  batchCategory: "",
  batchVisibility: "public",
  perAgent: {},
};

export function createDeployWizardState(
  overrides?: Partial<DeployAgentWizardState>,
): DeployAgentWizardState {
  return { ...DEFAULT_DEPLOY_WIZARD_STATE, ...overrides };
}

export function hasVaultTrackRecord(agent: TradingAgent): boolean {
  return agent.revenue30d != null && agent.revenue30d > 0;
}

export function isVaultLikeAgent(agent: TradingAgent): boolean {
  return agent.role === "vault_allocator" || getAgentCustodyKind(agent) === "vault";
}

export function computeDeployEligibility(agent: TradingAgent): DeployEligibility {
  if (agent.listingStatus === "listed") {
    return {
      canSelect: false,
      canStage: false,
      canPublish: false,
      reason: "Already listed",
      allowedListingTypes: [],
    };
  }

  if (agent.provisioningStatus === "provisioning") {
    return {
      canSelect: false,
      canStage: false,
      canPublish: false,
      reason: "Still provisioning",
      allowedListingTypes: [],
    };
  }

  const custodyKind = getAgentCustodyKind(agent);

  if (custodyKind === "did_only") {
    return {
      canSelect: true,
      canStage: true,
      canPublish: true,
      allowedListingTypes: ["profile"],
    };
  }

  if (isVaultLikeAgent(agent)) {
    const trackOk = hasVaultTrackRecord(agent);
    return {
      canSelect: true,
      canStage: true,
      canPublish: trackOk,
      reason: trackOk ? undefined : "Needs track record → Agent Console",
      allowedListingTypes: ["vault"],
    };
  }

  const allowedListingTypes: AgentListingType[] = ["profile", "vault"];
  if (agent.gatewayEnabled) {
    allowedListingTypes.push("service");
  }

  return {
    canSelect: true,
    canStage: true,
    canPublish: true,
    allowedListingTypes,
  };
}

export function resolveDefaultListingType(
  agent: TradingAgent,
  eligibility: DeployEligibility,
): AgentListingType {
  if (eligibility.allowedListingTypes.length === 1) {
    return eligibility.allowedListingTypes[0]!;
  }
  if (isVaultLikeAgent(agent)) return "vault";
  if (agent.gatewayEnabled && eligibility.allowedListingTypes.includes("service")) {
    return "service";
  }
  return "profile";
}

export function getAgentMarketSymbol(agent: TradingAgent): string {
  return agent.marketSymbol ?? deriveMarketSymbol(agent.did);
}

export function buildInitialPerAgentDetails(
  agents: TradingAgent[],
  selectedAgentIds: string[],
): Record<string, DeployPerAgentDetails> {
  const perAgent: Record<string, DeployPerAgentDetails> = {};
  for (const agentId of selectedAgentIds) {
    const agent = agents.find((entry) => entry.id === agentId);
    if (!agent) continue;
    const eligibility = computeDeployEligibility(agent);
    perAgent[agentId] = {
      description: agent.listingDescription ?? "",
      listingType: resolveDefaultListingType(agent, eligibility),
    };
  }
  return perAgent;
}

export function isDeployStepValid(
  step: DeployWizardStep,
  state: DeployAgentWizardState,
  agents: TradingAgent[],
): boolean {
  if (step === "select") {
    return state.selectedAgentIds.some((agentId) => {
      const agent = agents.find((entry) => entry.id === agentId);
      if (!agent) return false;
      return computeDeployEligibility(agent).canSelect;
    });
  }

  if (step === "details") {
    if (!state.batchCategory.trim()) return false;
    return state.selectedAgentIds.every((agentId) => {
      const details = state.perAgent[agentId];
      return Boolean(details?.description.trim());
    });
  }

  return true;
}

export function goNextDeployStep(
  state: DeployAgentWizardState,
): DeployAgentWizardState | null {
  const index = DEPLOY_WIZARD_STEPS.indexOf(state.step);
  if (index < 0 || index >= DEPLOY_WIZARD_STEPS.length - 1) return null;
  return { ...state, step: DEPLOY_WIZARD_STEPS[index + 1]! };
}

export function goPrevDeployStep(
  state: DeployAgentWizardState,
): DeployAgentWizardState | null {
  const index = DEPLOY_WIZARD_STEPS.indexOf(state.step);
  if (index <= 0) return null;
  return { ...state, step: DEPLOY_WIZARD_STEPS[index - 1]! };
}

export interface ExecuteDeployBatchParams {
  agents: TradingAgent[];
  selectedAgentIds: string[];
  target: DeployTarget;
  batchCategory: string;
  batchVisibility: AgentListingVisibility;
  perAgent: Record<string, DeployPerAgentDetails>;
  usedCatalogIds: string[];
}

export function executeDeployBatch(
  params: ExecuteDeployBatchParams,
): DeployBatchResult {
  const result: DeployBatchResult = { listed: [], staged: [], failed: [] };
  const usedCatalogIds = new Set(
    params.usedCatalogIds.map((id) => id.trim().toLowerCase()),
  );

  for (const agentId of params.selectedAgentIds) {
    const agent = params.agents.find((entry) => entry.id === agentId);
    if (!agent) {
      result.failed.push({ agentId, reason: "Agent not found" });
      continue;
    }

    const eligibility = computeDeployEligibility(agent);
    if (!eligibility.canSelect) {
      result.failed.push({
        agentId,
        reason: eligibility.reason ?? "Not eligible",
      });
      continue;
    }

    const details = params.perAgent[agentId];
    const listingType =
      details?.listingType ?? resolveDefaultListingType(agent, eligibility);

    if (!eligibility.allowedListingTypes.includes(listingType)) {
      result.failed.push({
        agentId,
        reason: `Listing type "${listingType}" not allowed for this agent`,
      });
      continue;
    }

    const metadata = {
      listingType,
      listingCategory: params.batchCategory,
      listingDescription: details?.description.trim() ?? "",
      listingVisibility: params.batchVisibility,
    };

    const shouldPublish =
      params.target === "stage_and_publish" && eligibility.canPublish;

    if (
      params.target === "stage_and_publish" &&
      !eligibility.canPublish &&
      listingType === "vault"
    ) {
      result.failed.push({
        agentId,
        reason: eligibility.reason ?? "Needs track record → Agent Console",
      });
      continue;
    }

    if (!shouldPublish) {
      result.staged.push({ agentId });
      continue;
    }

    const catalogAgentId = pickDeployCatalogAgentId(agentId, usedCatalogIds);
    if (!catalogAgentId) {
      result.staged.push({ agentId });
      result.failed.push({
        agentId,
        reason: "Markets catalog full",
      });
      continue;
    }

    usedCatalogIds.add(catalogAgentId.toLowerCase());
    result.listed.push({ agentId, catalogAgentId });
  }

  return result;
}

export function formatDeployBatchSummary(result: DeployBatchResult): string {
  const parts: string[] = [];
  if (result.listed.length > 0) {
    parts.push(`${result.listed.length} Listed`);
  }
  if (result.staged.length > 0) {
    parts.push(`${result.staged.length} Staged`);
  }
  if (result.failed.length > 0) {
    parts.push(`${result.failed.length} failed`);
  }
  return parts.length > 0 ? parts.join(" · ") : "No changes";
}

export function getDeployReviewPartitions(
  agents: TradingAgent[],
  state: DeployAgentWizardState,
): {
  willPublish: TradingAgent[];
  willStage: TradingAgent[];
  excluded: { agent: TradingAgent; reason: string }[];
} {
  const willPublish: TradingAgent[] = [];
  const willStage: TradingAgent[] = [];
  const excluded: { agent: TradingAgent; reason: string }[] = [];

  for (const agentId of state.selectedAgentIds) {
    const agent = agents.find((entry) => entry.id === agentId);
    if (!agent) continue;

    const eligibility = computeDeployEligibility(agent);
    if (!eligibility.canSelect) {
      excluded.push({
        agent,
        reason: eligibility.reason ?? "Not eligible",
      });
      continue;
    }

    const details = state.perAgent[agentId];
    const listingType =
      details?.listingType ?? resolveDefaultListingType(agent, eligibility);

    if (!eligibility.allowedListingTypes.includes(listingType)) {
      excluded.push({
        agent,
        reason: `Listing type "${listingType}" not allowed`,
      });
      continue;
    }

    if (state.target === "stage_and_publish" && eligibility.canPublish) {
      willPublish.push(agent);
    } else if (
      state.target === "stage_and_publish" &&
      !eligibility.canPublish &&
      listingType === "vault"
    ) {
      excluded.push({
        agent,
        reason: eligibility.reason ?? "Needs track record → Agent Console",
      });
    } else {
      willStage.push(agent);
    }
  }

  return { willPublish, willStage, excluded };
}

export function buildListingPatchForAgent(
  params: ExecuteDeployBatchParams,
  agentId: string,
  listingStatus: "staged" | "listed",
  catalogAgentId?: string,
) {
  const agent = params.agents.find((entry) => entry.id === agentId);
  if (!agent) return null;
  const eligibility = computeDeployEligibility(agent);
  const details = params.perAgent[agentId];
  const listingType =
    details?.listingType ?? resolveDefaultListingType(agent, eligibility);

  return {
    listingStatus,
    catalogAgentId,
    listingType,
    listingCategory: params.batchCategory,
    listingDescription: details?.description.trim() ?? "",
    listingVisibility: params.batchVisibility,
  };
}

export function formatDeployAgentRowLabel(agent: TradingAgent): string {
  return `${agent.displayName} · ${getAgentRoleLabel(agent.role)} · ${getListingLabel(agent.listingStatus)}`;
}
