import React from "react";

import VaultFiltersPanel, {
  type VaultFiltersPanelProps,
} from "./VaultFiltersPanel";
import { CREATE_VAULT_TOUR_TARGETS } from "../../tutorials/create-vault-tour/constants";
import "./vault.css";

export interface VaultFiltersBarProps extends VaultFiltersPanelProps {
  height?: string;
  twoRow?: boolean;
}

export default function VaultFiltersBar({
  height = "100%",
  twoRow = false,
  ...panelProps
}: VaultFiltersBarProps): JSX.Element {
  return (
    <div
      className={`vault-slot vault-header-band vault-header-band--filters vault-filters-bar${
        twoRow ? " vault-filters-bar--two-row" : ""
      }`}
      style={{ height }}
      data-tour={CREATE_VAULT_TOUR_TARGETS.listFilters}
    >
      <VaultFiltersPanel
        variant="bar"
        barLayout={twoRow ? "stacked" : "inline"}
        {...panelProps}
      />
    </div>
  );
}
