import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  getLayoutBottomRow,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

export const STAKING_SLOT_INDICES = {
  title: 0,
  kpi: 1,
  primary: 2,
  unlocks: 3,
  tabs: 4,
} as const;

export const STAKING_TAB_SLOT_INDEX = STAKING_SLOT_INDICES.tabs;
export const STAKING_COLLAPSED_SLOTS = [5, 6, 7, 8] as const;

export const STAKING_ROW_HEIGHT = 30;
export const STAKING_MENUBAR_HEIGHT = 54;
export const STAKING_LAYOUT_MARGIN = 10;
export const STAKING_VIEWPORT_FUDGE_PX = 4;

export const STAKING_TITLE_ROWS = 2;
export const STAKING_TITLE_STACKED_ROWS = 3;
export const STAKING_KPI_ROWS = 2;
/** KPI stat band on sm (768–995px) — 2×2 grid with stacked sublines; extra row vs phones. */
export const STAKING_KPI_STACKED_ROWS_SM = 4;
/** KPI stat band on xs/xxs — 2×2 grid; wrapped sublines need ~175px. */
export const STAKING_KPI_STACKED_ROWS_XS = 5;

/** @deprecated Use STAKING_KPI_STACKED_ROWS_SM */
export const STAKING_KPI_STACKED_ROWS = STAKING_KPI_STACKED_ROWS_SM;
export const STAKING_PRIMARY_ROWS = 8;
export const STAKING_PRIMARY_COLS_LG = 7;
export const STAKING_UNLOCKS_COLS_LG = 5;

export const STAKING_HERO_START_ROW =
  STAKING_TITLE_ROWS + STAKING_KPI_ROWS;

export const STAKING_TAB_START_ROW =
  STAKING_HERO_START_ROW + STAKING_PRIMARY_ROWS;

export const STAKING_BASE_TAB_ROWS = 3;
export const STAKING_SCROLL_TAB_ROWS = 26;
export const STAKING_DEFAULT_BOTTOM_ROW =
  STAKING_TAB_START_ROW + STAKING_BASE_TAB_ROWS;
export const STAKING_MAX_BOTTOM_ROW = 33;
export const STAKING_MIN_BOTTOM_ROW = STAKING_DEFAULT_BOTTOM_ROW;

export const STAKING_STACKED_PRIMARY_ROWS = 8;
export const STAKING_STACKED_UNLOCKS_ROWS = 6;

const STACKED_BREAKPOINTS = new Set<GridBreakpoint>(["sm", "xs", "xxs"]);

export function isStakingStackedBreakpoint(breakpoint: string): boolean {
  return STACKED_BREAKPOINTS.has(breakpoint as GridBreakpoint);
}

export function getStakingStackedKpiRows(breakpoint: string): number {
  return breakpoint === "sm"
    ? STAKING_KPI_STACKED_ROWS_SM
    : STAKING_KPI_STACKED_ROWS_XS;
}

/** Row index where KPI band starts on sm–xxs. */
export function getStakingStackedKpiStartRow(): number {
  return STAKING_TITLE_STACKED_ROWS;
}

/** Row index where primary / tables tab band starts on sm–xxs. */
export function getStakingStackedHeroStartRow(breakpoint: string): number {
  return STAKING_TITLE_STACKED_ROWS + getStakingStackedKpiRows(breakpoint);
}

export function getStakingStackedTabStartRow(breakpoint: string): number {
  return (
    getStakingStackedHeroStartRow(breakpoint) +
    STAKING_STACKED_PRIMARY_ROWS +
    STAKING_STACKED_UNLOCKS_ROWS
  );
}

/** @deprecated Use getStakingStackedHeroStartRow("sm") */
export const STAKING_STACKED_HERO_START_ROW =
  STAKING_TITLE_STACKED_ROWS + STAKING_KPI_STACKED_ROWS_SM;

/** @deprecated Use getStakingStackedTabStartRow("sm") */
export const STAKING_STACKED_TAB_START_ROW =
  STAKING_STACKED_HERO_START_ROW +
  STAKING_STACKED_PRIMARY_ROWS +
  STAKING_STACKED_UNLOCKS_ROWS;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [
  COLLAPSED,
  COLLAPSED,
  COLLAPSED,
  COLLAPSED,
];

function desktopStakingLayout(cols: number): LayoutConfigLest {
  const primaryW =
    cols === 12 ? STAKING_PRIMARY_COLS_LG : Math.max(4, Math.floor(cols * 0.58));
  const unlocksW = cols - primaryW;
  return [
    [0, 0, cols, STAKING_TITLE_ROWS],
    [0, STAKING_TITLE_ROWS, cols, STAKING_KPI_ROWS],
    [0, STAKING_HERO_START_ROW, primaryW, STAKING_PRIMARY_ROWS],
    [primaryW, STAKING_HERO_START_ROW, unlocksW, STAKING_PRIMARY_ROWS],
    [0, STAKING_TAB_START_ROW, cols, STAKING_BASE_TAB_ROWS],
    ...COLLAPSED_TAIL,
  ];
}

function stackedStakingLayout(cols: number, kpiRows: number): LayoutConfigLest {
  const yKpi = STAKING_TITLE_STACKED_ROWS;
  const yPrimary = yKpi + kpiRows;
  const yUnlocks = yPrimary + STAKING_STACKED_PRIMARY_ROWS;
  const yTabs = yUnlocks + STAKING_STACKED_UNLOCKS_ROWS;
  return [
    [0, 0, cols, STAKING_TITLE_STACKED_ROWS],
    [0, yKpi, cols, kpiRows],
    [0, yPrimary, cols, STAKING_STACKED_PRIMARY_ROWS],
    [0, yUnlocks, cols, STAKING_STACKED_UNLOCKS_ROWS],
    [0, yTabs, cols, STAKING_BASE_TAB_ROWS],
    ...COLLAPSED_TAIL,
  ];
}

export const stakingLayoutLg: LayoutConfigLest = desktopStakingLayout(12);
export const stakingLayoutMd: LayoutConfigLest = desktopStakingLayout(10);
export const stakingLayoutSm: LayoutConfigLest = stackedStakingLayout(
  6,
  STAKING_KPI_STACKED_ROWS_SM,
);
export const stakingLayoutXs: LayoutConfigLest = stackedStakingLayout(
  4,
  STAKING_KPI_STACKED_ROWS_XS,
);
export const stakingLayoutXxs: LayoutConfigLest = stackedStakingLayout(
  2,
  STAKING_KPI_STACKED_ROWS_XS,
);

export function buildStakingResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseInactive = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, STAKING_COLLAPSED_SLOTS);

  return {
    lg: collapseInactive(stakingLayoutLg),
    md: collapseInactive(stakingLayoutMd),
    sm: collapseInactive(stakingLayoutSm),
    xs: collapseInactive(stakingLayoutXs),
    xxs: collapseInactive(stakingLayoutXxs),
  };
}

export function generateStakingResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(configs[bp], totalItems) as ResponsiveLayouts[string];
  }
  return result;
}

export function computeStakingTargetBottomRow(
  viewportHeight: number,
  menubarHeight = STAKING_MENUBAR_HEIGHT,
): number {
  const available = viewportHeight - menubarHeight - STAKING_VIEWPORT_FUDGE_PX;
  const rowUnit = STAKING_ROW_HEIGHT + STAKING_LAYOUT_MARGIN;
  const rows = Math.floor((available + STAKING_LAYOUT_MARGIN) / rowUnit);
  return Math.max(
    STAKING_MIN_BOTTOM_ROW,
    Math.min(STAKING_MAX_BOTTOM_ROW, rows),
  );
}

function patchTabSlotHeight(
  layout: LayoutConfigLest,
  targetBottomRow: number,
): LayoutConfigLest {
  const tabSlot = layout[STAKING_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const tabStart = tabSlot[1];
  const tabHeight = Math.max(STAKING_BASE_TAB_ROWS, targetBottomRow - tabStart);
  const next: LayoutDefinition = [tabSlot[0], tabStart, tabSlot[2], tabHeight];

  return layout.map((item, index) =>
    index === STAKING_TAB_SLOT_INDEX ? next : item,
  );
}

function patchTabSlotFixedHeight(
  layout: LayoutConfigLest,
  tabRows: number,
): LayoutConfigLest {
  const tabSlot = layout[STAKING_TAB_SLOT_INDEX];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const next: LayoutDefinition = [tabSlot[0], tabSlot[1], tabSlot[2], tabRows];

  return layout.map((item, index) =>
    index === STAKING_TAB_SLOT_INDEX ? next : item,
  );
}

export function patchStakingScrollTabHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTabSlotFixedHeight(layout, STAKING_SCROLL_TAB_ROWS);

  return {
    lg: config.lg,
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

export type StakingPageView = "staking" | "tables";

function patchStakingTablesViewLayout(layout: LayoutConfigLest): LayoutConfigLest {
  const tabSlot = layout[STAKING_TAB_SLOT_INDEX];
  const kpiSlot = layout[STAKING_SLOT_INDICES.kpi];
  if (!tabSlot || tabSlot[2] === 0 || tabSlot[3] === 0) return layout;

  const [, , tabW, tabH] = tabSlot;
  const tabStart = kpiSlot
    ? kpiSlot[1] + kpiSlot[3]
    : STAKING_HERO_START_ROW;

  return layout.map((item, index) => {
    if (
      index === STAKING_SLOT_INDICES.primary ||
      index === STAKING_SLOT_INDICES.unlocks
    ) {
      return COLLAPSED;
    }
    if (index === STAKING_TAB_SLOT_INDEX) {
      return [0, tabStart, tabW, tabH];
    }
    return item;
  });
}

/** Collapse stake panel + unlocks; expand tab section from KPI row. */
export function patchStakingPageView(
  config: ResponsiveLayoutConfig,
  view: StakingPageView,
): ResponsiveLayoutConfig {
  if (view === "staking") return config;

  return {
    lg: patchStakingTablesViewLayout(config.lg),
    md: patchStakingTablesViewLayout(config.md),
    sm: patchStakingTablesViewLayout(config.sm),
    xs: patchStakingTablesViewLayout(config.xs),
    xxs: patchStakingTablesViewLayout(config.xxs),
  };
}

export function applyStakingLayoutSizing(
  config: ResponsiveLayoutConfig,
  viewportHeight: number,
): ResponsiveLayoutConfig {
  const targetBottomRow = computeStakingTargetBottomRow(viewportHeight);
  const scrollSized = patchStakingScrollTabHeights(config);

  return {
    lg: patchTabSlotHeight(config.lg, targetBottomRow),
    md: scrollSized.md,
    sm: scrollSized.sm,
    xs: scrollSized.xs,
    xxs: scrollSized.xxs,
  };
}

export function assertStakingLayoutValid(config: ResponsiveLayoutConfig): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `staking ${bp}`);
  }
}

export function getStakingLayoutBottomRow(config: ResponsiveLayoutConfig): number {
  return getLayoutBottomRow(config.lg);
}
