import React, { useCallback, useMemo, useRef, useState } from "react";

import ModalHeader from "../../ui/ModalHeader";
import { createErrorCopyAction } from "../../ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  toastUpdateLoading,
} from "../../ui/toastTask";
import type { UseDeployAgentModalResult } from "../../../hooks/useDeployAgentModal";
import { useTradingAgentStore } from "../../../store/tradingAgentStore";
import {
  buildListingPatchForAgent,
  createDeployWizardState,
  executeDeployBatch,
  formatDeployBatchSummary,
  getAgentMarketSymbol,
  isDeployStepValid,
  type DeployBatchResult,
  type ExecuteDeployBatchParams,
} from "../../../utils/deployAgent";
import { executeOfflineDeployAgent } from "../../../utils/executeOfflineDeployAgent";
import { OFFLINE_DEPLOY_AGENT_STABLE_TOAST_ID } from "../../../../offline/mock_data/offlineDeployAgentSteps";
import DeployAgentCatalogFullDialog from "./DeployAgentCatalogFullDialog";
import DeployAgentModalShell, {
  useDeployAgentModalShell,
} from "./DeployAgentModalShell";
import DeployAgentStepDetails from "./DeployAgentStepDetails";
import DeployAgentStepIndicator from "./DeployAgentStepIndicator";
import DeployAgentStepReview from "./DeployAgentStepReview";
import DeployAgentStepSelect from "./DeployAgentStepSelect";
import "./deployAgent.css";

export interface DeployAgentModalProps {
  modal: UseDeployAgentModalResult;
  onMintAgent?: () => void;
}

function applyDeployBatchResult(
  result: DeployBatchResult,
  params: ExecuteDeployBatchParams,
  patchAgentListing: ReturnType<
    typeof useTradingAgentStore.getState
  >["patchAgentListing"],
): void {
  for (const entry of result.staged) {
    const patch = buildListingPatchForAgent(params, entry.agentId, "staged");
    if (patch) patchAgentListing(entry.agentId, patch);
  }
  for (const entry of result.listed) {
    const patch = buildListingPatchForAgent(
      params,
      entry.agentId,
      "listed",
      entry.catalogAgentId,
    );
    if (patch) patchAgentListing(entry.agentId, patch);
  }
}

function DeployAgentModalBody({
  modal,
  onMintAgent,
}: DeployAgentModalProps): JSX.Element {
  const { overlay } = useDeployAgentModalShell();
  const agents = useTradingAgentStore((s) => s.agents);
  const patchAgentListing = useTradingAgentStore((s) => s.patchAgentListing);

  const { state, setState, goNext, goBack, close, isOpen } = modal;
  const [isConfirming, setIsConfirming] = useState(false);
  const [catalogFullOpen, setCatalogFullOpen] = useState(false);
  const [catalogFullNames, setCatalogFullNames] = useState<string[]>([]);
  const [pendingRetryParams, setPendingRetryParams] =
    useState<ExecuteDeployBatchParams | null>(null);

  const usedCatalogIds = useMemo(
    () =>
      agents
        .map((entry) => entry.catalogAgentId)
        .filter((id): id is string => Boolean(id)),
    [agents],
  );

  const buildBatchParams = useCallback(
    (override?: Partial<ExecuteDeployBatchParams>): ExecuteDeployBatchParams => ({
      agents,
      selectedAgentIds: state.selectedAgentIds,
      target: state.target,
      batchCategory: state.batchCategory,
      batchVisibility: state.batchVisibility,
      perAgent: state.perAgent,
      usedCatalogIds,
      ...override,
    }),
    [agents, state, usedCatalogIds],
  );

  const patchState = useCallback(
    (patch: Partial<typeof state>) => {
      setState((prev) => ({ ...prev, ...patch }));
    },
    [setState],
  );

  const runDeploy = useCallback(
    async (params: ExecuteDeployBatchParams) => {
      const primaryAgent = params.selectedAgentIds
        .map((id) => agents.find((entry) => entry.id === id))
        .find(Boolean);

      if (!primaryAgent) {
        throw new Error("No agents selected for deploy");
      }

      const toastId = toastLoading("Publishing listings…", {
        stableId: OFFLINE_DEPLOY_AGENT_STABLE_TOAST_ID,
        description: "Signing transaction…",
      });

      try {
        const chainResult = await executeOfflineDeployAgent(
          {
            agentCount: params.selectedAgentIds.length,
            target: params.target,
            category: params.batchCategory,
            visibility: params.batchVisibility,
            primaryDisplayName: primaryAgent.displayName,
            primarySymbol: getAgentMarketSymbol(primaryAgent),
            batchSeed: params.selectedAgentIds.join("-"),
          },
          {
            onStepStart: (step) => {
              toastUpdateLoading(toastId, step.loadingMessage, {
                description: step.loadingDescription,
              });
            },
          },
        );

        const result = executeDeployBatch(params);
        applyDeployBatchResult(result, params, patchAgentListing);

        const catalogFullAgents = result.failed.filter(
          (entry) => entry.reason === "Markets catalog full",
        );
        if (catalogFullAgents.length > 0) {
          const names = catalogFullAgents
            .map(
              (entry) => agents.find((a) => a.id === entry.agentId)?.displayName,
            )
            .filter((name): name is string => Boolean(name));
          setCatalogFullNames(names);
          setPendingRetryParams({
            ...params,
            target: "stage_and_publish",
            selectedAgentIds: catalogFullAgents.map((e) => e.agentId),
          });
          setCatalogFullOpen(true);
        }

        toastCompleteSuccess(toastId, "Deploy complete", {
          description: `${formatDeployBatchSummary(result)}\ntxhash: ${chainResult.demoTxHash}`,
        });

        if (catalogFullAgents.length === 0) {
          close();
        }
        return result;
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : "Failed to deploy listings";
        toastCompleteError(toastId, "Deploy failed", {
          description: errorMessage,
          action: createErrorCopyAction(errorMessage),
        });
        throw err;
      }
    },
    [agents, close, patchAgentListing],
  );

  const handleConfirm = async () => {
    if (isConfirming) return;
    setIsConfirming(true);
    try {
      await runDeploy(buildBatchParams());
    } catch {
      // Toast already surfaced the error.
    } finally {
      setIsConfirming(false);
    }
  };

  const handleCatalogFullRetry = async () => {
    if (!pendingRetryParams) {
      setCatalogFullOpen(false);
      close();
      return;
    }
    setIsConfirming(true);
    try {
      await runDeploy(pendingRetryParams);
      setCatalogFullOpen(false);
      setPendingRetryParams(null);
    } catch {
      // Toast already surfaced the error.
    } finally {
      setIsConfirming(false);
    }
  };

  const handleCatalogFullClose = () => {
    setCatalogFullOpen(false);
    setPendingRetryParams(null);
    close();
  };

  const stepValid = isDeployStepValid(state.step, state, agents);
  const selectedCount = state.selectedAgentIds.length;

  const title =
    state.step === "select"
      ? `Deploy to Market · Select agents${selectedCount > 0 ? ` · ${selectedCount} selected` : ""}`
      : state.step === "details"
        ? `Deploy to Market · Listing details · ${selectedCount} agents`
        : `Deploy to Market · Review · ${selectedCount} agents`;

  const footerDisabled = overlay.isClosing || isConfirming;
  const deployCount =
    state.step === "review"
      ? state.selectedAgentIds.length
      : 0;

  return (
    <>
      <ModalHeader
        title={title}
        onClose={close}
        closeDisabled={footerDisabled}
      />

      <div className="modal-body deploy-agent-modal-body">
        {state.step !== "review" ? (
          <DeployAgentStepIndicator step={state.step} />
        ) : null}
        {state.step === "select" ? (
          <DeployAgentStepSelect
            agents={agents}
            state={state}
            onChange={patchState}
            onMintAgent={onMintAgent}
          />
        ) : null}
        {state.step === "details" ? (
          <DeployAgentStepDetails
            agents={agents}
            state={state}
            onChange={patchState}
          />
        ) : null}
        {state.step === "review" ? (
          <DeployAgentStepReview agents={agents} state={state} />
        ) : null}
      </div>

      <div className="modal-footer bucket-modal-footer deploy-agent-modal-footer">
        {state.step === "select" ? (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={close}
            disabled={footerDisabled}
          >
            Cancel
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={goBack}
            disabled={footerDisabled}
          >
            Back
          </button>
        )}

        {state.step === "review" ? (
          <button
            type="button"
            className="btn btn-primary"
            onClick={handleConfirm}
            disabled={!stepValid || footerDisabled || deployCount === 0}
          >
            {isConfirming
              ? "Deploying…"
              : `Deploy ${deployCount} agent${deployCount === 1 ? "" : "s"}`}
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-primary"
            onClick={goNext}
            disabled={!stepValid || footerDisabled}
          >
            Next
          </button>
        )}
      </div>

      <DeployAgentCatalogFullDialog
        open={catalogFullOpen && isOpen}
        agentNames={catalogFullNames}
        onClose={handleCatalogFullClose}
        onRetry={handleCatalogFullRetry}
      />
    </>
  );
}

export default function DeployAgentModal({
  modal,
  onMintAgent,
}: DeployAgentModalProps): JSX.Element | null {
  const pendingMintOpenRef = useRef(false);

  const handleMintAgent = useCallback(() => {
    if (!onMintAgent) return;
    pendingMintOpenRef.current = true;
    modal.close();
  }, [modal.close, onMintAgent]);

  const handleAfterUnmount = useCallback(() => {
    modal.setState(createDeployWizardState());
    if (pendingMintOpenRef.current) {
      pendingMintOpenRef.current = false;
      onMintAgent?.();
    }
  }, [modal.setState, onMintAgent]);

  return (
    <DeployAgentModalShell
      open={modal.isOpen}
      onClose={modal.close}
      onAfterUnmount={handleAfterUnmount}
      ariaLabel="Deploy to Market"
    >
      <DeployAgentModalBody
        modal={modal}
        onMintAgent={onMintAgent ? handleMintAgent : undefined}
      />
    </DeployAgentModalShell>
  );
}
