import {
  STAKING_HERO_START_ROW,
  STAKING_LAYOUT_MARGIN,
  STAKING_ROW_HEIGHT,
  STAKING_TAB_START_ROW,
  STAKING_TITLE_ROWS,
  STAKING_TITLE_STACKED_ROWS,
  getStakingStackedHeroStartRow,
  getStakingStackedKpiStartRow,
  getStakingStackedTabStartRow,
  isStakingStackedBreakpoint,
} from "../../configs/stakingLayoutConfig";
import type { StakingPageView } from "./stakingPageView";

export interface StakingHeroBandBounds {
  topPx: number;
  heightPx: number;
}

function rowStride(): number {
  return STAKING_ROW_HEIGHT + STAKING_LAYOUT_MARGIN;
}

function getStakingContentTopRow(breakpoint: string): number {
  return isStakingStackedBreakpoint(breakpoint)
    ? getStakingStackedKpiStartRow()
    : STAKING_TITLE_ROWS;
}

export function getStakingTabStartRow(
  breakpoint: string,
  pageView: StakingPageView = "staking",
): number {
  if (pageView === "tables") {
    if (isStakingStackedBreakpoint(breakpoint)) {
      return getStakingStackedHeroStartRow(breakpoint);
    }
    return STAKING_HERO_START_ROW;
  }
  if (isStakingStackedBreakpoint(breakpoint)) {
    return getStakingStackedTabStartRow(breakpoint);
  }
  return STAKING_TAB_START_ROW;
}

export function getStakingHeroBandBounds(
  breakpoint: string,
  pageView: StakingPageView = "staking",
): StakingHeroBandBounds {
  const stride = rowStride();
  const topRow = getStakingContentTopRow(breakpoint);
  const topPx = topRow * stride;
  const tabStartRow = getStakingTabStartRow(breakpoint, pageView);
  const heightPx = (tabStartRow - topRow) * stride;
  return { topPx, heightPx };
}

/** Connect gate covers KPI + primary/unlocks skeletons and dimmed tab band. */
export function getStakingConnectGateBounds(
  breakpoint: string,
  tabRowCount: number,
  pageView: StakingPageView = "staking",
): StakingHeroBandBounds {
  const stride = rowStride();
  const topRow = getStakingContentTopRow(breakpoint);
  const topPx = topRow * stride;
  const tabStartRow = getStakingTabStartRow(breakpoint, pageView);
  const bottomRow = tabStartRow + Math.max(0, tabRowCount);
  const heightPx = (bottomRow - topRow) * stride;
  return { topPx, heightPx };
}
