import React from "react";
import { createPortal } from "react-dom";

import type { AgentTask, TradingAgent } from "../../store/types";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "../ui/overlay";
import AgentRolesDetailContent from "./AgentRolesDetailContent";
import "./agentroles.css";

export interface AgentRolesDetailSheetProps {
  isOpen: boolean;
  agent: TradingAgent | undefined;
  tasks: AgentTask[];
  needsYouCount: number;
  onClose: () => void;
  onDeployToMarket?: () => void;
  onRelistToMarket?: () => void;
  onDuplicateAgent?: () => void;
}

export default function AgentRolesDetailSheet({
  isOpen,
  agent,
  tasks,
  needsYouCount,
  onClose,
  onDeployToMarket,
  onRelistToMarket,
  onDuplicateAgent,
}: AgentRolesDetailSheetProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: OVERLAY_TIMING.mobileSheetMs,
  });

  useOverlayEscapeKey(isOpen, onClose);
  useOverlayScrollLock(isOpen && mounted);

  if (!mounted || !agent) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="agentroles-detail-sheet-overlay bucket-modal-overlay bucket-modal-overlay--sheet">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content agentroles-detail-sheet-panel bucket-modal-panel--sheet"
        role="dialog"
        aria-modal={true}
        aria-label={`${agent.displayName} details`}
      >
        <AgentRolesDetailContent
          agent={agent}
          tasks={tasks}
          needsYouCount={needsYouCount}
          onClose={onClose}
          onDeployToMarket={onDeployToMarket}
          onRelistToMarket={onRelistToMarket}
          onDuplicateAgent={onDuplicateAgent}
          layout="sheet"
        />
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
