import React from "react";

export type StakingPanelSkeletonVariant = "kpi" | "primary" | "unlocks";

export interface StakingPanelSkeletonProps {
  height?: string;
  variant?: StakingPanelSkeletonVariant;
}

function StakingPanelSkeletonKpi(): JSX.Element {
  return (
    <>
      {Array.from({ length: 4 }, (_, index) => (
        <div key={index} className="staking-stat-card staking-panel-skeleton-kpi-cell">
          <div className="staking-panel-skeleton-block staking-panel-skeleton-block--label" />
          <div className="staking-panel-skeleton-block staking-panel-skeleton-block--value" />
        </div>
      ))}
    </>
  );
}

function StakingPanelSkeletonPrimary(): JSX.Element {
  return (
    <>
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--label" />
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--bar-short" />
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--label" />
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--bar" />
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--bar-short" />
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--bar" />
    </>
  );
}

function StakingPanelSkeletonUnlocks(): JSX.Element {
  return (
    <>
      <div className="staking-panel-skeleton-block staking-panel-skeleton-block--label" />
      {Array.from({ length: 4 }, (_, index) => (
        <div
          key={index}
          className="staking-panel-skeleton-block staking-panel-skeleton-block--bar"
        />
      ))}
    </>
  );
}

function StakingPanelSkeleton({
  height = "100%",
  variant = "primary",
}: StakingPanelSkeletonProps): JSX.Element {
  const slotClass =
    variant === "kpi"
      ? "staking-slot staking-slot--flush staking-stat-cards-slot"
      : "staking-slot";

  return (
    <div
      className={slotClass}
      style={{ height }}
      aria-hidden="true"
      data-variant={variant}
    >
      <div className={`staking-panel-skeleton staking-panel-skeleton--${variant}`}>
        {variant === "kpi" ? <StakingPanelSkeletonKpi /> : null}
        {variant === "primary" ? (
          <>
            <div className="staking-panel-skeleton-tab-bar" aria-hidden="true" />
            <div className="staking-panel-body">
              <StakingPanelSkeletonPrimary />
            </div>
          </>
        ) : null}
        {variant === "unlocks" ? (
          <div className="staking-panel-body">
            <StakingPanelSkeletonUnlocks />
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default React.memo(StakingPanelSkeleton);
