import type { VaultBucketSummary } from "../../../offline/mock_data/vaultCatalog";
import type { VaultBalanceRow } from "../../../offline/mock_data/vaultMockData.types";

export function allocationPct(equityUsd: number, vaultTvlUsd: number): number {
  if (vaultTvlUsd <= 0) return 0;
  return (equityUsd / vaultTvlUsd) * 100;
}

export function weightPct(valueUsd: number, vaultTvlUsd: number): number {
  if (vaultTvlUsd <= 0) return 0;
  return (valueUsd / vaultTvlUsd) * 100;
}

export function deploymentPct(buckets: VaultBucketSummary[], vaultTvlUsd: number): number {
  if (vaultTvlUsd <= 0) return 0;
  const deployed = buckets.reduce((sum, bucket) => sum + bucket.equityUsd, 0);
  return (deployed / vaultTvlUsd) * 100;
}

export function deployedEquityUsd(buckets: VaultBucketSummary[]): number {
  return buckets.reduce((sum, bucket) => sum + bucket.equityUsd, 0);
}

export function bucketLeverage(bucket: VaultBucketSummary): number {
  if (bucket.equityUsd <= 0) return 0;
  return (bucket.longNotionalUsd + bucket.shortNotionalUsd) / bucket.equityUsd;
}

export function formatMarketsLabel(markets: string[]): string {
  if (markets.length === 0) return "";
  if (markets.length <= 2) return markets.join(", ");
  return `${markets[0]}, ${markets[1]} +${markets.length - 2}`;
}

export function formatPct(value: number, digits = 1): string {
  return `${value.toFixed(digits)}%`;
}

export function formatSignedPct(value: number, digits = 1): string {
  const prefix = value >= 0 ? "+" : "";
  return `${prefix}${value.toFixed(digits)}%`;
}

export function formatLeverage(value: number): string {
  return `${value.toFixed(1)}×`;
}

export function riskHealthLabel(health: VaultBucketSummary["riskHealth"]): string {
  if (health === "healthy") return "Healthy";
  if (health === "watch") return "Watch";
  return "Critical";
}

export function sortIdleBalances(rows: VaultBalanceRow[]): VaultBalanceRow[] {
  return [...rows].sort((a, b) => {
    if (a.symbol === "USDC" && b.symbol !== "USDC") return -1;
    if (b.symbol === "USDC" && a.symbol !== "USDC") return 1;
    return b.valueUsd - a.valueUsd;
  });
}

export function idleSpotTotalUsd(rows: VaultBalanceRow[]): number {
  return rows.reduce((sum, row) => sum + row.valueUsd, 0);
}

export interface VaultBucketTotals {
  deployedEquityUsd: number;
  deploymentPct: number;
  fundingPnlUsd: number;
  totalPnlUsd: number;
}

export function aggregateBucketTotals(
  buckets: VaultBucketSummary[],
  vaultTvlUsd: number,
): VaultBucketTotals {
  const deployedEquityUsd = buckets.reduce((sum, bucket) => sum + bucket.equityUsd, 0);
  return {
    deployedEquityUsd,
    deploymentPct: allocationPct(deployedEquityUsd, vaultTvlUsd),
    fundingPnlUsd: buckets.reduce((sum, bucket) => sum + bucket.fundingPnlUsd, 0),
    totalPnlUsd: buckets.reduce((sum, bucket) => sum + bucket.pnlUsd, 0),
  };
}

export function pnlHoverTitle(bucket: VaultBucketSummary): string {
  return `Price P&L ${bucket.pricePnlUsd >= 0 ? "+" : ""}${bucket.pricePnlUsd.toFixed(2)} · Funding P&L ${bucket.fundingPnlUsd >= 0 ? "+" : ""}${bucket.fundingPnlUsd.toFixed(2)}`;
}
