/**
 * Runtime accessors for vault activity data loaded from mock-system-data.
 * Populated by vaultActivityClient after fetch; empty until loaded.
 */
import type { VaultActivityFilter } from "./vaultMockData.types";
import type {
  VaultActivityRow,
  VaultBalanceRow,
  VaultDepositorRow,
  VaultFundingRow,
  VaultFundsMovementRow,
  VaultOpenOrderRow,
  VaultTradeFill,
} from "./vaultMockData.types";
import { getCachedVaultActivityById } from "./vaultActivityCache";
import { fundingRowFromActivity, tradeFillFromActivityRow } from "./vaultActivityUtils";

function filterActivity(
  rows: VaultActivityRow[],
  opts?: VaultActivityFilter,
): VaultActivityRow[] {
  return rows.filter((row) => {
    if (opts?.bucketId != null && row.bucketId !== opts.bucketId) return false;
    if (opts?.types?.length && !opts.types.includes(row.activityType)) return false;
    if (opts?.sourceKind != null && row.sourceKind !== opts.sourceKind) return false;
    return true;
  });
}

export function getVaultActivity(
  vaultId: string,
  opts?: VaultActivityFilter,
): VaultActivityRow[] {
  const data = getCachedVaultActivityById(vaultId);
  if (!data) return [];
  return filterActivity(data.activity, opts);
}

export function cloneVaultActivity(
  vaultId: string,
  opts?: VaultActivityFilter,
): VaultActivityRow[] {
  return getVaultActivity(vaultId, opts).map((row) => ({ ...row }));
}

export function getVaultTradeHistory(
  vaultId: string,
  bucketId?: string,
): VaultTradeFill[] {
  return getVaultActivity(vaultId, {
    bucketId,
    types: ["perp"],
    sourceKind: "bucket",
  })
    .map(tradeFillFromActivityRow)
    .filter((row): row is VaultTradeFill => row != null);
}

export function cloneVaultTradeHistory(
  vaultId: string,
  bucketId?: string,
): VaultTradeFill[] {
  return getVaultTradeHistory(vaultId, bucketId).map((row) => ({ ...row }));
}

export function getVaultFundingHistory(
  vaultId: string,
  bucketId?: string,
): VaultFundingRow[] {
  return getVaultActivity(vaultId, {
    bucketId,
    types: ["funding"],
    sourceKind: "bucket",
  })
    .map(fundingRowFromActivity)
    .filter((row): row is VaultFundingRow => row != null);
}

export function cloneVaultFundingHistory(
  vaultId: string,
  bucketId?: string,
): VaultFundingRow[] {
  return getVaultFundingHistory(vaultId, bucketId).map((row) => ({ ...row }));
}

export function getVaultBalances(vaultId: string): VaultBalanceRow[] {
  return getCachedVaultActivityById(vaultId)?.balances ?? [];
}

export function cloneVaultBalances(vaultId: string): VaultBalanceRow[] {
  return getVaultBalances(vaultId).map((row) => ({ ...row }));
}

export function getVaultOpenOrders(
  vaultId: string,
  bucketId?: string,
): VaultOpenOrderRow[] {
  const rows = getCachedVaultActivityById(vaultId)?.openOrders ?? [];
  return rows.filter(
    (row) => bucketId == null || row.bucketId === bucketId,
  );
}

export function cloneVaultOpenOrders(
  vaultId: string,
  bucketId?: string,
): VaultOpenOrderRow[] {
  return getVaultOpenOrders(vaultId, bucketId).map((row) => ({ ...row }));
}

export function getVaultFundsMovements(vaultId: string): VaultFundsMovementRow[] {
  return getCachedVaultActivityById(vaultId)?.fundsMovements ?? [];
}

export function cloneVaultFundsMovements(vaultId: string): VaultFundsMovementRow[] {
  return getVaultFundsMovements(vaultId).map((row) => ({ ...row }));
}

export function getVaultDepositors(vaultId: string): VaultDepositorRow[] {
  return getCachedVaultActivityById(vaultId)?.depositors ?? [];
}

export function cloneVaultDepositors(vaultId: string): VaultDepositorRow[] {
  return getVaultDepositors(vaultId).map((row) => ({ ...row }));
}

export function getVaultPositionsByKey(
  vaultId: string,
  bucketId: string,
) {
  const key = `${vaultId}:${bucketId}`;
  return getCachedVaultActivityById(vaultId)?.positionsByKey[key] ?? [];
}
