import React, { useCallback, useMemo, useState } from "react";

import { useVaultDepositors } from "../../hooks/useVaultDepositors";
import type { VaultDepositorRow } from "../../../offline/mock_data/vaultMockData.types";
import { formatCurrency } from "../../sdk/utils/display";
import { TableHeaderCell, TableHeaderCellStatic } from "../smartlayout";
import VaultActivityTableShell, {
  type VaultActivityTableLayout,
} from "./VaultActivityTableShell";
import VaultTableFooter from "./VaultTableFooter";
import "./vault.css";

const GRID =
  "minmax(140px, 1.4fr) minmax(100px, 1fr) minmax(110px, 1fr) minmax(110px, 1fr) minmax(90px, 0.8fr)";

type SortField = "unrealizedPnlUsd";

export interface VaultDepositorsTableProps {
  vaultId: string;
  layout?: VaultActivityTableLayout;
}

function truncateAddress(addr: string): string {
  if (addr.length <= 14) return addr;
  return `${addr.slice(0, 6)}...${addr.slice(-4)}`;
}

function pnlClassName(value: number): string {
  return value >= 0 ? "vault-grade-a" : "vault-grade-d";
}

export default function VaultDepositorsTable({
  vaultId,
  layout = "bucket",
}: VaultDepositorsTableProps): JSX.Element {
  const allRows = useVaultDepositors(vaultId);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);
  const [sortField, setSortField] = useState<SortField | null>("unrealizedPnlUsd");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");

  const handleSort = useCallback(
    (field: SortField) => {
      if (sortField === field) {
        setSortDirection((d) => (d === "asc" ? "desc" : "asc"));
      } else {
        setSortField(field);
        setSortDirection("desc");
      }
    },
    [sortField],
  );

  const sortedRows = useMemo(() => {
    const followers = allRows.filter((row) => !row.isLeader);
    const leader = allRows.find((row) => row.isLeader);
    const field = sortField ?? "unrealizedPnlUsd";
    const dir = sortDirection === "asc" ? 1 : -1;

    followers.sort((a, b) => (a[field] - b[field]) * dir);

    return leader ? [...followers, leader] : followers;
  }, [allRows, sortField, sortDirection]);

  const pageRows = useMemo(() => {
    const start = page * pageSize;
    return sortedRows.slice(start, start + pageSize);
  }, [sortedRows, page, pageSize]);

  return (
    <VaultActivityTableShell
      gridColumns={GRID}
      layout={layout}
      minWidth={640}
      isEmpty={allRows.length === 0}
      emptyMessage="No depositors."
      header={
        <>
          <TableHeaderCellStatic left>Depositor</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Vault Amount</TableHeaderCellStatic>
          <TableHeaderCell<SortField>
            field="unrealizedPnlUsd"
            currentSortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            right
          >
            Unrealized PNL
          </TableHeaderCell>
          <TableHeaderCellStatic right>All-time PNL</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Days Following</TableHeaderCellStatic>
        </>
      }
      footer={
        <VaultTableFooter
          page={page}
          pageSize={pageSize}
          totalCount={sortedRows.length}
          onPageChange={setPage}
          onPageSizeChange={setPageSize}
        />
      }
    >
      {pageRows.map((row: VaultDepositorRow) => (
        <div
          key={row.address}
          className="table-row"
          style={{ gridTemplateColumns: GRID }}
        >
          <div className="table-cell primary">
            {row.isLeader ? "Leader" : truncateAddress(row.address)}
          </div>
          <div className="table-cell numeric">
            {formatCurrency(row.vaultAmountUsd)}
          </div>
          <div className={`table-cell numeric ${pnlClassName(row.unrealizedPnlUsd)}`}>
            {formatCurrency(row.unrealizedPnlUsd)}
          </div>
          <div className={`table-cell numeric ${pnlClassName(row.allTimePnlUsd)}`}>
            {formatCurrency(row.allTimePnlUsd)}
          </div>
          <div className="table-cell numeric">{row.daysFollowing}</div>
        </div>
      ))}
    </VaultActivityTableShell>
  );
}
