import React, { useEffect, useRef, type RefObject } from "react";

import { formatVaultTvl } from "../../../offline/mock_data/vaultCatalog";
import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import "./vault.css";

export interface VaultOperateSwitcherProps {
  ownedVaults: VaultRecord[];
  activeVaultId: string;
  open: boolean;
  onClose: () => void;
  onSelectVault: (vaultId: string) => void;
  onVaultHome: () => void;
  className?: string;
  style?: React.CSSProperties;
  /** Clicks on this element do not count as outside-dismiss (e.g. brand trigger). */
  anchorRef?: RefObject<HTMLElement | null>;
}

export default function VaultOperateSwitcher({
  ownedVaults,
  activeVaultId,
  open,
  onClose,
  onSelectVault,
  onVaultHome,
  className,
  style,
  anchorRef,
}: VaultOperateSwitcherProps): JSX.Element | null {
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (panelRef.current?.contains(target)) return;
      if (anchorRef?.current?.contains(target)) return;
      onClose();
    };
    document.addEventListener("mousedown", onPointerDown);
    return () => document.removeEventListener("mousedown", onPointerDown);
  }, [open, onClose, anchorRef]);

  if (!open) return null;

  return (
    <div
      className={["vault-operate-switcher", className].filter(Boolean).join(" ")}
      ref={panelRef}
      role="menu"
      style={style}
    >
      {ownedVaults.map((vault) => (
        <button
          key={vault.id}
          type="button"
          role="menuitem"
          className={[
            "vault-operate-switcher-row",
            vault.id === activeVaultId ? "vault-operate-switcher-row--active" : "",
          ]
            .filter(Boolean)
            .join(" ")}
          onClick={() => {
            if (vault.id !== activeVaultId) {
              onSelectVault(vault.id);
            }
            onClose();
          }}
        >
          <span className="vault-operate-switcher-name">
            {vault.id === activeVaultId ? "● " : ""}
            {vault.name}
          </span>
          <span className="vault-operate-switcher-tvl">
            {formatVaultTvl(vault.tvlUsd)}
          </span>
        </button>
      ))}
      <div className="vault-operate-switcher-divider" />
      <button
        type="button"
        role="menuitem"
        className="vault-operate-switcher-row vault-operate-switcher-row--exit"
        onClick={() => {
          onVaultHome();
          onClose();
        }}
      >
        ⌂ Back to vault
      </button>
    </div>
  );
}
