import React, { useLayoutEffect, useMemo, useState } from "react";

import type { VaultAnalystVerdict, VaultGrade } from "../../../offline/mock_data/vaultCatalog";
import {
  formatVaultGrade,
  formatVaultTvl,
} from "../../../offline/mock_data/vaultCatalog";
import { Typewriter } from "../ui/Typewriter";
import "../ui/typewriter.css";
import "./vault.css";
import {
  isInsufficientVerdict,
  resolveInsufficientPassage,
} from "./vaultAnalystVerdictUtils";

const SCORE_WEIGHTS_TOOLTIP =
  "Return 30% · Consistency 25% · Drawdown 20% · Track record 15% · Capacity 10%";

/** Chars/sec for analyst verdict lines — faster than default Typewriter (40). */
const ANALYST_TYPEWRITER_SPEED = 100;

const ANALYST_TYPEWRITER_PROPS = {
  speed: ANALYST_TYPEWRITER_SPEED,
  holdCursor: false,
  active: true as const,
};

export interface VaultAnalystVerdictContentProps {
  verdict: VaultAnalystVerdict;
}

type VaultMetrics = VaultAnalystVerdict["metrics"];

type AnalystContentLine = {
  id: string;
  text: string;
  wrap: boolean;
  isFooter?: boolean;
};

function gradeClassName(grade: VaultGrade | null): string {
  if (!grade) return "vault-grade-unrated";
  return `vault-grade-${grade.toLowerCase()}`;
}

function formatSignedPct(value: number | null): string {
  if (value == null) return "—";
  return `${value >= 0 ? "+" : ""}${value}%`;
}

function valueToneClass(value: number | null): string {
  if (value == null) return "";
  if (value > 0) return "vault-analyst-tone--positive";
  if (value < 0) return "vault-analyst-tone--negative";
  return "";
}

function hasTrustMeta(verdict: VaultAnalystVerdict): boolean {
  return verdict.verified || verdict.percentileLabel != null || verdict.confidence != null;
}

function stripVerifiedLead(text: string): string {
  return text.replace(/^Verified\s*[—-]\s*/u, "").trim();
}

function buildGradeScoreText(verdict: VaultAnalystVerdict): string {
  const grade = verdict.grade
    ? `Grade ${formatVaultGrade(verdict.grade)}`
    : "Not yet rated";
  if (verdict.score == null) {
    return grade;
  }
  return `${grade} Score ${verdict.score}/100 ⓘ`;
}

function buildInputsText(metrics: VaultMetrics): string {
  const segments = [
    "Inputs",
    `Return 90d ${formatSignedPct(metrics.return90dPct)}`,
    `Sharpe ${metrics.sharpe ?? "—"}`,
    `MaxDD ${formatSignedPct(metrics.maxDrawdownPct)}`,
    `Track ${metrics.trackRecordDays}d`,
    `TVL ${formatVaultTvl(metrics.tvlUsd)}`,
  ];
  return segments.join(" ");
}

function buildTrustMetaText(verdict: VaultAnalystVerdict): string {
  const { verified, percentileLabel, confidence } = verdict;
  const showPercentile = percentileLabel != null && percentileLabel.length > 0;
  const showConfidence = confidence != null;

  if (verified) {
    let text = "✓ Verified";
    if (showPercentile || showConfidence) {
      text += " — ";
    }
    if (showPercentile) {
      text += percentileLabel;
    }
    if (showPercentile && showConfidence) {
      text += " / ";
    }
    if (showConfidence) {
      text += `Confidence: ${confidence}`;
    }
    return text;
  }

  let text = "";
  if (showPercentile) {
    text += percentileLabel;
  }
  if (showPercentile && showConfidence) {
    text += " — ";
  }
  if (showConfidence) {
    text += `Confidence: ${confidence}`;
  }
  return text;
}

function buildNarrativeText(verdict: VaultAnalystVerdict): string | null {
  const reasonDetail = stripVerifiedLead(verdict.verificationReason.trim());
  const prose = verdict.summary.trim();
  const hasReason = reasonDetail.length > 0;
  const hasProse = prose.length > 0;

  if (!hasReason && !hasProse) {
    return null;
  }

  if (verdict.verified) {
    let text = "✓ Verified — ";
    if (hasReason) {
      text += reasonDetail;
    }
    if (hasReason && hasProse) {
      text += ". ";
    }
    if (hasProse) {
      text += prose;
    }
    return text;
  }

  let text = "";
  if (hasReason) {
    text += verdict.verificationReason.trim();
  }
  if (hasReason && hasProse) {
    text += ". ";
  }
  if (hasProse) {
    text += prose;
  }
  return text;
}

function buildAnalystLines(verdict: VaultAnalystVerdict): AnalystContentLine[] {
  const lines: AnalystContentLine[] = [
    {
      id: "grade-score",
      text: buildGradeScoreText(verdict),
      wrap: false,
    },
    {
      id: "inputs",
      text: buildInputsText(verdict.metrics),
      wrap: false,
    },
  ];

  if (hasTrustMeta(verdict)) {
    lines.push({
      id: "trust-meta",
      text: buildTrustMetaText(verdict),
      wrap: true,
    });
  }

  const narrative = buildNarrativeText(verdict);
  if (narrative) {
    lines.push({
      id: "narrative",
      text: narrative,
      wrap: true,
    });
  }

  for (const flag of verdict.flags) {
    lines.push({
      id: `flag-${flag}`,
      text: `⚑ ${flag}`,
      wrap: true,
    });
  }

  lines.push({
    id: "as-of",
    text: "Data as of: Today",
    wrap: false,
    isFooter: true,
  });

  return lines;
}

function AnalystLine({
  children,
  variant = "compact",
}: {
  children: React.ReactNode;
  variant?: "compact" | "wrap";
}): JSX.Element {
  return (
    <p
      className={
        variant === "wrap"
          ? "vault-analyst-line vault-analyst-line--wrap"
          : "vault-analyst-line"
      }
    >
      {children}
    </p>
  );
}

function AnalystGradeScoreLine({ verdict }: { verdict: VaultAnalystVerdict }): JSX.Element {
  return (
    <AnalystLine>
      {verdict.grade ? (
        <span className={gradeClassName(verdict.grade)}>
          Grade {formatVaultGrade(verdict.grade)}
        </span>
      ) : (
        <span className="vault-grade-unrated">Not yet rated</span>
      )}
      {verdict.score != null ? (
        <>
          {" "}
          Score {verdict.score}/100
          <span
            className="vault-analyst-info"
            title={`Score = ${SCORE_WEIGHTS_TOOLTIP}`}
            aria-label={`Score weights: ${SCORE_WEIGHTS_TOOLTIP}`}
          >
            ⓘ
          </span>
        </>
      ) : null}
    </AnalystLine>
  );
}

const INPUT_METRICS: Array<{
  key: string;
  label: string;
  renderValue: (metrics: VaultMetrics) => React.ReactNode;
}> = [
  {
    key: "return90d",
    label: "Return 90d",
    renderValue: (metrics) => (
      <span className={valueToneClass(metrics.return90dPct)}>
        {formatSignedPct(metrics.return90dPct)}
      </span>
    ),
  },
  {
    key: "sharpe",
    label: "Sharpe",
    renderValue: (metrics) => metrics.sharpe ?? "—",
  },
  {
    key: "maxDrawdown",
    label: "MaxDD",
    renderValue: (metrics) => (
      <span className={valueToneClass(metrics.maxDrawdownPct)}>
        {formatSignedPct(metrics.maxDrawdownPct)}
      </span>
    ),
  },
  {
    key: "track",
    label: "Track",
    renderValue: (metrics) => `${metrics.trackRecordDays}d`,
  },
  {
    key: "tvl",
    label: "TVL",
    renderValue: (metrics) => formatVaultTvl(metrics.tvlUsd),
  },
];

function AnalystInputsStrip({ metrics }: { metrics: VaultMetrics }): JSX.Element {
  return (
    <AnalystLine>
      <span className="vault-analyst-label">Inputs</span>
      {INPUT_METRICS.map((metric) => (
        <React.Fragment key={metric.key}>
          {" "}
          <span className="vault-analyst-label">{metric.label}</span>{" "}
          {metric.renderValue(metrics)}
        </React.Fragment>
      ))}
    </AnalystLine>
  );
}

function AnalystTrustMetaLine({ verdict }: { verdict: VaultAnalystVerdict }): JSX.Element {
  const { verified, percentileLabel, confidence } = verdict;
  const showPercentile = percentileLabel != null && percentileLabel.length > 0;
  const showConfidence = confidence != null;

  if (!verified) {
    return (
      <AnalystLine variant="wrap">
        {showPercentile ? percentileLabel : null}
        {showPercentile && showConfidence ? " — " : null}
        {showConfidence ? `Confidence: ${confidence}` : null}
      </AnalystLine>
    );
  }

  return (
    <AnalystLine variant="wrap">
      <span className="vault-analyst-tone--positive" aria-hidden="true">
        ✓
      </span>{" "}
      Verified
      {showPercentile || showConfidence ? " — " : null}
      {showPercentile ? percentileLabel : null}
      {showPercentile && showConfidence ? " / " : null}
      {showConfidence ? `Confidence: ${confidence}` : null}
    </AnalystLine>
  );
}

function AnalystNarrativeLine({
  verified,
  verificationReason,
  summary,
}: {
  verified: boolean;
  verificationReason: string;
  summary: string;
}): JSX.Element | null {
  const reasonDetail = stripVerifiedLead(verificationReason.trim());
  const prose = summary.trim();
  const hasReason = reasonDetail.length > 0;
  const hasProse = prose.length > 0;

  if (!hasReason && !hasProse) {
    return null;
  }

  if (verified) {
    return (
      <AnalystLine variant="wrap">
        <span className="vault-analyst-tone--positive" aria-hidden="true">
          ✓
        </span>{" "}
        Verified — {hasReason ? reasonDetail : null}
        {hasReason && hasProse ? ". " : null}
        {hasProse ? prose : null}
      </AnalystLine>
    );
  }

  return (
    <AnalystLine variant="wrap">
      {hasReason ? verificationReason.trim() : null}
      {hasReason && hasProse ? ". " : null}
      {hasProse ? prose : null}
    </AnalystLine>
  );
}

function AnalystFlagLine({ flag }: { flag: string }): JSX.Element {
  return (
    <AnalystLine variant="wrap">
      <span className="vault-analyst-tone--warning" aria-hidden="true">
        ⚑
      </span>{" "}
      {flag}
    </AnalystLine>
  );
}

function renderCompletedLine(id: string, verdict: VaultAnalystVerdict): JSX.Element | null {
  const { metrics, flags, verificationReason, summary, verified } = verdict;

  if (id === "grade-score") {
    return <AnalystGradeScoreLine verdict={verdict} />;
  }
  if (id === "inputs") {
    return <AnalystInputsStrip metrics={metrics} />;
  }
  if (id === "trust-meta") {
    return <AnalystTrustMetaLine verdict={verdict} />;
  }
  if (id === "narrative") {
    return (
      <AnalystNarrativeLine
        verified={verified}
        verificationReason={verificationReason}
        summary={summary}
      />
    );
  }
  if (id.startsWith("flag-")) {
    const flag = flags.find((entry) => `flag-${entry}` === id);
    return flag ? <AnalystFlagLine flag={flag} /> : null;
  }
  return null;
}

function AnalystTypedLine({
  line,
  isTyping,
  isComplete,
  onComplete,
  completedContent,
}: {
  line: AnalystContentLine;
  isTyping: boolean;
  isComplete: boolean;
  onComplete: () => void;
  completedContent: React.ReactNode;
}): JSX.Element | null {
  if (isComplete) {
    return <>{completedContent}</>;
  }

  if (!isTyping) {
    return null;
  }

  if (line.isFooter) {
    return (
      <footer className="vault-analyst-footer">
        <p className="vault-analyst-footer-label">
          <Typewriter
            text={line.text}
            className="vault-analyst-typewriter vault-analyst-typewriter--footer"
            multiline={false}
            onComplete={onComplete}
            {...ANALYST_TYPEWRITER_PROPS}
          />
        </p>
      </footer>
    );
  }

  return (
    <AnalystLine variant={line.wrap ? "wrap" : "compact"}>
      <Typewriter
        text={line.text}
        className="vault-analyst-typewriter"
        multiline={line.wrap ? "auto" : false}
        onComplete={onComplete}
        {...ANALYST_TYPEWRITER_PROPS}
      />
    </AnalystLine>
  );
}

const ANALYST_FOOTER_TEXT = "Data as of: Today";

function InsufficientVerdictContent({ passage }: { passage: string }): JSX.Element {
  const [footerVisible, setFooterVisible] = useState(false);

  useLayoutEffect(() => {
    setFooterVisible(false);
  }, [passage]);

  return (
    <article
      className="vault-analyst-content vault-analyst-content--insufficient"
      aria-label="Analyst verdict"
    >
      <div className="vault-analyst-body">
        <p className="vault-analyst-line vault-analyst-line--wrap vault-analyst-passage">
          {footerVisible ? (
            passage
          ) : (
            <Typewriter
              text={passage}
              className="vault-analyst-typewriter"
              multiline="auto"
              onComplete={() => setFooterVisible(true)}
              {...ANALYST_TYPEWRITER_PROPS}
            />
          )}
        </p>
      </div>

      {footerVisible ? (
        <footer className="vault-analyst-footer">
          <p className="vault-analyst-footer-label">{ANALYST_FOOTER_TEXT}</p>
        </footer>
      ) : null}
    </article>
  );
}

export default function VaultAnalystVerdictContent({
  verdict,
}: VaultAnalystVerdictContentProps): JSX.Element {
  if (isInsufficientVerdict(verdict)) {
    return (
      <InsufficientVerdictContent passage={resolveInsufficientPassage(verdict)} />
    );
  }

  return <FullVerdictContent verdict={verdict} />;
}

function FullVerdictContent({ verdict }: VaultAnalystVerdictContentProps): JSX.Element {
  const lines = useMemo(() => buildAnalystLines(verdict), [verdict]);
  const bodyLines = useMemo(() => lines.filter((line) => !line.isFooter), [lines]);
  const footerLine = lines.find((line) => line.isFooter);
  const [stepIndex, setStepIndex] = useState(0);

  useLayoutEffect(() => {
    setStepIndex(0);
  }, [lines]);

  const advanceStep = () => {
    setStepIndex((index) => Math.min(index + 1, lines.length));
  };

  const footerComplete = stepIndex >= lines.length;
  const footerTyping = footerLine != null && stepIndex === bodyLines.length;

  return (
    <article className="vault-analyst-content" aria-label="Analyst verdict">
      <div className="vault-analyst-body">
        {bodyLines.map((line, index) => (
          <AnalystTypedLine
            key={line.id}
            line={line}
            isTyping={stepIndex === index}
            isComplete={stepIndex > index}
            onComplete={advanceStep}
            completedContent={renderCompletedLine(line.id, verdict)}
          />
        ))}
      </div>

      {footerLine && (footerTyping || footerComplete) ? (
        footerComplete ? (
          <footer className="vault-analyst-footer">
            <p className="vault-analyst-footer-label">{footerLine.text}</p>
          </footer>
        ) : (
          <AnalystTypedLine
            line={footerLine}
            isTyping
            isComplete={false}
            onComplete={advanceStep}
            completedContent={null}
          />
        )
      ) : null}
    </article>
  );
}
