import React from "react";

import type { TradingAgent } from "../../../store/types";
import type { DeployAgentWizardState } from "../../../utils/deployAgent";
import {
  getAgentMarketSymbol,
  getDeployReviewPartitions,
} from "../../../utils/deployAgent";
import { getListingLabel } from "../../../utils/agentRoles";

export interface DeployAgentStepReviewProps {
  agents: TradingAgent[];
  state: DeployAgentWizardState;
}

export default function DeployAgentStepReview({
  agents,
  state,
}: DeployAgentStepReviewProps): JSX.Element {
  const { willPublish, willStage, excluded } = getDeployReviewPartitions(
    agents,
    state,
  );

  const targetLabel =
    state.target === "stage_and_publish" ? "Stage → Publish" : "Stage draft";

  return (
    <div className="deploy-agent-step">
      <p className="terminal-label deploy-agent-step-intro">
        {targetLabel} · {state.batchCategory || "—"} ·{" "}
        {state.batchVisibility === "public" ? "Public" : "Unlisted preview"}
      </p>

      {willPublish.length > 0 ? (
        <section className="deploy-agent-review-section">
          <h4 className="terminal-label">Will publish to Markets</h4>
          <ul className="deploy-agent-review-list">
            {willPublish.map((agent) => (
              <li key={agent.id} className="deploy-agent-review-item">
                <span className="terminal-value">{agent.displayName}</span>
                <span className="terminal-label">
                  → Listed ({getAgentMarketSymbol(agent)}) → Markets row
                </span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {willStage.length > 0 ? (
        <section className="deploy-agent-review-section">
          <h4 className="terminal-label">Will stage</h4>
          <ul className="deploy-agent-review-list">
            {willStage.map((agent) => (
              <li key={agent.id} className="deploy-agent-review-item">
                <span className="terminal-value">{agent.displayName}</span>
                <span className="terminal-label">
                  → Staged ({getListingLabel(agent.listingStatus)} now)
                </span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {excluded.length > 0 ? (
        <section className="deploy-agent-review-section">
          <h4 className="terminal-label">Excluded</h4>
          <ul className="deploy-agent-review-list">
            {excluded.map(({ agent, reason }) => (
              <li key={agent.id} className="deploy-agent-review-item">
                <span className="terminal-value">{agent.displayName}</span>
                <span className="terminal-label">— {reason}</span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
    </div>
  );
}
