import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

export const VAULT_LIST_SLOT_INDICES = {
  hero: 0,
  tvl: 1,
  spotlight: 2,
  filters: 3,
  table: 4,
} as const;

export const VAULT_LIST_TABLE_SLOT_INDEX = VAULT_LIST_SLOT_INDICES.table;

export const VAULT_LIST_COLLAPSED_SLOTS = [5, 6, 7, 8] as const;

export const VAULT_LIST_ROW_HEIGHT = 30;
export const VAULT_LIST_LAYOUT_MARGIN = 10;

export const VAULT_LIST_HERO_ROWS = 2;
export const VAULT_LIST_TVL_ROWS = 5;
export const VAULT_LIST_SPOTLIGHT_ROWS = 6;
/** lg — TVL row span matches spotlight height (slot 1 h = slot 2 h) */
export const VAULT_LIST_TVL_ROWS_LG = VAULT_LIST_SPOTLIGHT_ROWS;
/** Taller spotlight in split-band / stacked layouts — room for identity + summary + CTA */
export const VAULT_LIST_SPOTLIGHT_ROWS_STACKED = 7;
export const VAULT_LIST_FILTERS_ROWS = 2;
/** sm — slot 3 grows one row when Invested + My Vaults + Create Vault all show */
export const VAULT_LIST_FILTERS_ROWS_SM_EXPANDED =
  VAULT_LIST_FILTERS_ROWS + 1;
export const VAULT_LIST_BASE_TABLE_ROWS = 18;
/** Fixed table height on sm/xs/xxs — page scrolls instead of viewport squeeze (see portfolio `PORTFOLIO_SCROLL_TAB_ROWS`). */
export const VAULT_LIST_SCROLL_TABLE_ROWS = 24;
export const VAULT_LIST_TABLE_MIN_ROWS = 6;

/** MenuBar height — must match MenuBar.css */
export const VAULT_LIST_MENUBAR_HEIGHT = 54;
/** Small fudge for grid chrome / sub-pixel rounding */
export const VAULT_LIST_VIEWPORT_FUDGE_PX = 4;
/** Sanity cap for viewport-fit bottom row */
export const VAULT_LIST_MAX_BOTTOM_ROW = 48;

export const VAULT_LIST_HERO_COLS_LG = 3;
export const VAULT_LIST_FILTERS_X_LG = 3;
export const VAULT_LIST_FILTERS_COLS_LG = 9;
export const VAULT_LIST_TVL_COLS_LG = 4;
export const VAULT_LIST_SPOTLIGHT_X_LG = 4;
export const VAULT_LIST_SPOTLIGHT_COLS_LG = 8;

/** Aliases for mlp-listing.md spec naming */
export const VAULT_LIST_HERO_COLS_LG_TARGET = VAULT_LIST_HERO_COLS_LG;
export const VAULT_LIST_FILTERS_X_LG_TARGET = VAULT_LIST_FILTERS_X_LG;
export const VAULT_LIST_FILTERS_COLS_LG_TARGET = VAULT_LIST_FILTERS_COLS_LG;

/** @deprecated Use VAULT_LIST_SPOTLIGHT_ROWS — kept for tests referencing band row budget */
export const VAULT_LIST_SPOTLIGHT_BAND_ROWS = VAULT_LIST_SPOTLIGHT_ROWS;

export const VAULT_LIST_TABLE_START_ROW_LG =
  VAULT_LIST_HERO_ROWS + VAULT_LIST_SPOTLIGHT_ROWS;

export const VAULT_LIST_STACKED_FILTERS_START_ROW =
  VAULT_LIST_HERO_ROWS +
  VAULT_LIST_TVL_ROWS +
  VAULT_LIST_SPOTLIGHT_ROWS_STACKED;
export const VAULT_LIST_STACKED_TABLE_START_ROW =
  VAULT_LIST_STACKED_FILTERS_START_ROW + VAULT_LIST_FILTERS_ROWS;
/** xs/xxs — table y when slot 3 collapsed (filters in bottom sheet) */
export const VAULT_LIST_STACKED_TABLE_START_ROW_MOBILE =
  VAULT_LIST_STACKED_FILTERS_START_ROW;

/** md (10 cols) — left stack w=4 + spotlight top-right w=6 */
export const VAULT_LIST_MD_COLS = 10;
export const VAULT_LIST_LEFT_COLS_MD = 4;
export const VAULT_LIST_TVL_COLS_MD = VAULT_LIST_LEFT_COLS_MD;
export const VAULT_LIST_SPOTLIGHT_X_MD = VAULT_LIST_LEFT_COLS_MD;
export const VAULT_LIST_SPOTLIGHT_COLS_MD =
  VAULT_LIST_MD_COLS - VAULT_LIST_LEFT_COLS_MD;

/** sm (6 cols) — left stack w=2 + spotlight top-right w=4 */
export const VAULT_LIST_SM_COLS = 6;
export const VAULT_LIST_LEFT_COLS_SM = 2;
export const VAULT_LIST_TVL_COLS_SM = VAULT_LIST_LEFT_COLS_SM;
export const VAULT_LIST_SPOTLIGHT_X_SM = VAULT_LIST_LEFT_COLS_SM;
export const VAULT_LIST_SPOTLIGHT_COLS_SM =
  VAULT_LIST_SM_COLS - VAULT_LIST_LEFT_COLS_SM;

/** md/sm share the same row anchors — hero+TVL band, then full-width filters + table */
export const VAULT_LIST_SPLIT_BAND_END_ROW =
  VAULT_LIST_HERO_ROWS + VAULT_LIST_TVL_ROWS;
export const VAULT_LIST_SPLIT_FILTERS_START_ROW =
  VAULT_LIST_SPLIT_BAND_END_ROW;
export const VAULT_LIST_SPLIT_TABLE_START_ROW =
  VAULT_LIST_SPLIT_FILTERS_START_ROW + VAULT_LIST_FILTERS_ROWS;
export const VAULT_LIST_SPLIT_TABLE_START_ROW_SM_EXPANDED =
  VAULT_LIST_SPLIT_FILTERS_START_ROW + VAULT_LIST_FILTERS_ROWS_SM_EXPANDED;
/** sm — table y when slot 3 collapsed (filters in bottom sheet) */
export const VAULT_LIST_SPLIT_TABLE_START_ROW_MOBILE =
  VAULT_LIST_SPLIT_FILTERS_START_ROW;

/** @deprecated Use VAULT_LIST_SPLIT_* — sm-specific aliases */
export const VAULT_LIST_SM_BAND_END_ROW = VAULT_LIST_SPLIT_BAND_END_ROW;
export const VAULT_LIST_SM_FILTERS_START_ROW = VAULT_LIST_SPLIT_FILTERS_START_ROW;
export const VAULT_LIST_SM_TABLE_START_ROW = VAULT_LIST_SPLIT_TABLE_START_ROW;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED, COLLAPSED];

/** lg — hero w=3 + filters w=9 top band; TVL w=4 + spotlight w=8 mid band. See mlp-listing.md */
function vaultListLayoutLgSplit(): LayoutConfigLest {
  return [
    [0, 0, VAULT_LIST_HERO_COLS_LG, VAULT_LIST_HERO_ROWS],
    [
      0,
      VAULT_LIST_HERO_ROWS,
      VAULT_LIST_TVL_COLS_LG,
      VAULT_LIST_TVL_ROWS_LG,
    ],
    [
      VAULT_LIST_SPOTLIGHT_X_LG,
      VAULT_LIST_HERO_ROWS,
      VAULT_LIST_SPOTLIGHT_COLS_LG,
      VAULT_LIST_SPOTLIGHT_ROWS,
    ],
    [
      VAULT_LIST_FILTERS_X_LG,
      0,
      VAULT_LIST_FILTERS_COLS_LG,
      VAULT_LIST_FILTERS_ROWS,
    ],
    [
      0,
      VAULT_LIST_TABLE_START_ROW_LG,
      12,
      VAULT_LIST_BASE_TABLE_ROWS,
    ],
    ...COLLAPSED_TAIL,
  ];
}

function vaultListStackedLayout(
  cols: number,
  filtersRows = VAULT_LIST_FILTERS_ROWS,
): LayoutConfigLest {
  let y = 0;
  const hero: LayoutDefinition = [0, y, cols, VAULT_LIST_HERO_ROWS];
  y += VAULT_LIST_HERO_ROWS;
  const tvl: LayoutDefinition = [0, y, cols, VAULT_LIST_TVL_ROWS];
  y += VAULT_LIST_TVL_ROWS;
  const spotlight: LayoutDefinition = [0, y, cols, VAULT_LIST_SPOTLIGHT_ROWS_STACKED];
  y += VAULT_LIST_SPOTLIGHT_ROWS_STACKED;
  const filters: LayoutDefinition = [0, y, cols, filtersRows];
  y += filtersRows;
  const table: LayoutDefinition = [0, y, cols, VAULT_LIST_BASE_TABLE_ROWS];
  return [hero, tvl, spotlight, filters, table, ...COLLAPSED_TAIL];
}

/** md/sm — left stack + spotlight top-right, then full-width filters + table */
function vaultListLayoutSplitBand(
  cols: number,
  leftCols: number,
  filtersRows = VAULT_LIST_FILTERS_ROWS,
): LayoutConfigLest {
  const spotlightCols = cols - leftCols;
  const tableStartRow = VAULT_LIST_SPLIT_FILTERS_START_ROW + filtersRows;
  return [
    [0, 0, leftCols, VAULT_LIST_HERO_ROWS],
    [0, VAULT_LIST_HERO_ROWS, leftCols, VAULT_LIST_TVL_ROWS],
    [
      leftCols,
      0,
      spotlightCols,
      VAULT_LIST_SPOTLIGHT_ROWS_STACKED,
    ],
    [
      0,
      VAULT_LIST_SPLIT_FILTERS_START_ROW,
      cols,
      filtersRows,
    ],
    [
      0,
      tableStartRow,
      cols,
      VAULT_LIST_BASE_TABLE_ROWS,
    ],
    ...COLLAPSED_TAIL,
  ];
}

/** sm — split band with slot 3 collapsed; filters live in bottom sheet */
function vaultListLayoutSplitBandNoFilters(
  cols: number,
  leftCols: number,
): LayoutConfigLest {
  const spotlightCols = cols - leftCols;
  return [
    [0, 0, leftCols, VAULT_LIST_HERO_ROWS],
    [0, VAULT_LIST_HERO_ROWS, leftCols, VAULT_LIST_TVL_ROWS],
    [
      leftCols,
      0,
      spotlightCols,
      VAULT_LIST_SPOTLIGHT_ROWS_STACKED,
    ],
    COLLAPSED,
    [
      0,
      VAULT_LIST_SPLIT_TABLE_START_ROW_MOBILE,
      cols,
      VAULT_LIST_BASE_TABLE_ROWS,
    ],
    ...COLLAPSED_TAIL,
  ];
}

/** xs/xxs — stacked layout with slot 3 collapsed */
function vaultListStackedLayoutNoFilters(cols: number): LayoutConfigLest {
  let y = 0;
  const hero: LayoutDefinition = [0, y, cols, VAULT_LIST_HERO_ROWS];
  y += VAULT_LIST_HERO_ROWS;
  const tvl: LayoutDefinition = [0, y, cols, VAULT_LIST_TVL_ROWS];
  y += VAULT_LIST_TVL_ROWS;
  const spotlight: LayoutDefinition = [0, y, cols, VAULT_LIST_SPOTLIGHT_ROWS_STACKED];
  y += VAULT_LIST_SPOTLIGHT_ROWS_STACKED;
  const table: LayoutDefinition = [
    0,
    VAULT_LIST_STACKED_TABLE_START_ROW_MOBILE,
    cols,
    VAULT_LIST_BASE_TABLE_ROWS,
  ];
  return [hero, tvl, spotlight, COLLAPSED, table, ...COLLAPSED_TAIL];
}

export const vaultListLayoutLg: LayoutConfigLest = vaultListLayoutLgSplit();
export const vaultListLayoutMd: LayoutConfigLest = vaultListLayoutSplitBand(
  VAULT_LIST_MD_COLS,
  VAULT_LIST_LEFT_COLS_MD,
);
export const vaultListLayoutSm: LayoutConfigLest = vaultListLayoutSplitBand(
  VAULT_LIST_SM_COLS,
  VAULT_LIST_LEFT_COLS_SM,
);
export const vaultListLayoutXs: LayoutConfigLest = vaultListStackedLayoutNoFilters(4);
export const vaultListLayoutXxs: LayoutConfigLest = vaultListStackedLayoutNoFilters(2);

export function buildVaultListResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseAll = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, VAULT_LIST_COLLAPSED_SLOTS);

  return {
    lg: collapseAll(vaultListLayoutLg),
    md: collapseAll(vaultListLayoutMd),
    sm: collapseAll(vaultListLayoutSm),
    xs: collapseAll(vaultListLayoutXs),
    xxs: collapseAll(vaultListLayoutXxs),
  };
}

export function generateVaultListResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

function patchTableSlotHeight(
  layout: LayoutConfigLest,
  tableRows: number,
): LayoutConfigLest {
  const tableSlot = layout[VAULT_LIST_TABLE_SLOT_INDEX];
  if (!tableSlot || tableSlot[2] === 0 || tableSlot[3] === 0) return layout;
  return layout.map((item, index) =>
    index === VAULT_LIST_TABLE_SLOT_INDEX
      ? [tableSlot[0], tableSlot[1], tableSlot[2], tableRows]
      : item,
  );
}

/** sm — taller filters slot + table y push when all three wallet actions show. */
export function patchVaultListSmFiltersExpanded(
  layout: LayoutConfigLest,
  expanded: boolean,
): LayoutConfigLest {
  const filtersRows = expanded
    ? VAULT_LIST_FILTERS_ROWS_SM_EXPANDED
    : VAULT_LIST_FILTERS_ROWS;
  const tableStartY =
    VAULT_LIST_SPLIT_FILTERS_START_ROW + filtersRows;

  return layout.map((item, index) => {
    if (index === VAULT_LIST_SLOT_INDICES.filters) {
      return [
        0,
        VAULT_LIST_SPLIT_FILTERS_START_ROW,
        VAULT_LIST_SM_COLS,
        filtersRows,
      ];
    }
    if (index === VAULT_LIST_SLOT_INDICES.table) {
      const tableSlot = item;
      if (!tableSlot || tableSlot[2] === 0 || tableSlot[3] === 0) {
        return item;
      }
      return [tableSlot[0], tableStartY, tableSlot[2], tableSlot[3]];
    }
    return item;
  });
}

/** Compute max grid bottom row that fits in the viewport without page scroll. */
export function computeVaultListTargetBottomRow(
  viewportHeight: number,
  tableStartY = VAULT_LIST_TABLE_START_ROW_LG,
  menubarHeight = VAULT_LIST_MENUBAR_HEIGHT,
): number {
  const minBottomRow = tableStartY + VAULT_LIST_TABLE_MIN_ROWS;
  const available =
    viewportHeight - menubarHeight - VAULT_LIST_VIEWPORT_FUDGE_PX;
  const rowUnit = VAULT_LIST_ROW_HEIGHT + VAULT_LIST_LAYOUT_MARGIN;
  const rows = Math.floor((available + VAULT_LIST_LAYOUT_MARGIN) / rowUnit);
  return Math.max(
    minBottomRow,
    Math.min(VAULT_LIST_MAX_BOTTOM_ROW, rows),
  );
}

function patchTableViewportFit(
  layout: LayoutConfigLest,
  targetBottomRow: number,
): LayoutConfigLest {
  const tableSlot = layout[VAULT_LIST_TABLE_SLOT_INDEX];
  if (!tableSlot || tableSlot[2] === 0 || tableSlot[3] === 0) return layout;
  const tableStart = tableSlot[1];
  const tableRows = Math.max(
    VAULT_LIST_TABLE_MIN_ROWS,
    targetBottomRow - tableStart,
  );
  return patchTableSlotHeight(layout, tableRows);
}

/** Fixed table heights for sm/xs/xxs scroll mode (lg/md unchanged). */
export function patchVaultListScrollTableHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTableSlotHeight(layout, VAULT_LIST_SCROLL_TABLE_ROWS);

  return {
    lg: config.lg,
    md: config.md,
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

/**
 * lg/md: stretch table to viewport. sm/xs/xxs: fixed table rows; page scrolls.
 */
export function applyVaultListLayoutSizing(
  config: ResponsiveLayoutConfig,
  viewportHeight = 900,
  smFiltersExpanded = false,
): ResponsiveLayoutConfig {
  const patchViewport = (layout: LayoutConfigLest) => {
    const tableSlot = layout[VAULT_LIST_TABLE_SLOT_INDEX];
    const tableStartY = tableSlot?.[1] ?? VAULT_LIST_TABLE_START_ROW_LG;
    const targetBottomRow = computeVaultListTargetBottomRow(
      viewportHeight,
      tableStartY,
    );
    return patchTableViewportFit(layout, targetBottomRow);
  };

  const scrollSized = patchVaultListScrollTableHeights(config);

  return {
    lg: patchViewport(config.lg),
    md: patchViewport(config.md),
    sm: patchVaultListSmFiltersExpanded(scrollSized.sm, smFiltersExpanded),
    xs: scrollSized.xs,
    xxs: scrollSized.xxs,
  };
}

export function validateVaultListLayout(config: ResponsiveLayoutConfig): void {
  for (const bp of GRID_BREAKPOINTS) {
    assertNoLayoutOverlap(config[bp], `vault-list-${bp}`);
  }
}
