export const OFFLINE_VAULT_FUNDS_STABLE_TOAST_ID = "offline:vault-funds";

export type OfflineVaultFundsStepId =
  | "sign"
  | "submit"
  | "consensus"
  | "settle";

export type OfflineVaultFundsStep = {
  id: OfflineVaultFundsStepId;
  loadingMessage: string;
  loadingDescription: string;
  delayMs: number;
};

export type OfflineVaultFundsStepParams = {
  mode: "deposit" | "withdraw";
  amount: number;
  vaultName: string;
};

const BASE_STEPS: OfflineVaultFundsStep[] = [
  {
    id: "sign",
    loadingMessage: "Signing transaction…",
    loadingDescription: "Building EIP-712 vault payload",
    delayMs: 400,
  },
  {
    id: "submit",
    loadingMessage: "Submitting to morphcore…",
    loadingDescription: "Broadcasting /tx/v1/submit",
    delayMs: 500,
  },
  {
    id: "consensus",
    loadingMessage: "Awaiting consensus…",
    loadingDescription: "Confirming vault share update",
    delayMs: 600,
  },
];

/** Staged on-chain steps for offline vault deposit / withdraw demo toasts. */
export function getOfflineVaultFundsSteps(
  params: OfflineVaultFundsStepParams,
): OfflineVaultFundsStep[] {
  const steps = [...BASE_STEPS];

  const formattedAmount = params.amount.toFixed(2);

  if (params.mode === "deposit") {
    steps.push({
      id: "settle",
      loadingMessage: "Transferring collateral…",
      loadingDescription: `${formattedAmount} USDC from Spot Wallet → ${params.vaultName}`,
      delayMs: 500,
    });
  } else {
    steps[2] = {
      ...steps[2],
      loadingDescription: "Burning vault shares",
    };
    steps.push({
      id: "settle",
      loadingMessage: "Releasing funds…",
      loadingDescription: `${formattedAmount} USDC from ${params.vaultName} → Spot Wallet`,
      delayMs: 500,
    });
  }

  return steps;
}
