import { VAULT_TOUR_STORAGE_KEY } from "../../mormv1/tutorials/vault-tour/constants";

export function hasSeenVaultTour(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return localStorage.getItem(VAULT_TOUR_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

export function markVaultTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(VAULT_TOUR_STORAGE_KEY, "1");
  } catch {
    // ignore
  }
}

export function clearVaultTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(VAULT_TOUR_STORAGE_KEY);
  } catch {
    // ignore
  }
}
