import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from "react";

import type { StakingValidatorRow } from "../../offline/mock_data/stakingValidators.types";
import {
  getStakingValidatorsCacheRevision,
  subscribeStakingValidatorsCache,
} from "../../offline/mock_data/stakingValidatorsCache";
import { cloneStakingValidatorsForWallet } from "../../offline/mock_data/stakingValidatorsData";
import {
  getStakingDelegationRevision,
  subscribeStakingDelegationState,
} from "../../offline/mock_data/stakingDelegationState";
import {
  fetchStakingValidators,
  isStakingValidatorsDataLoaded,
} from "../sdk/api/stakingValidators/stakingValidatorsClient";

export interface UseStakingValidatorsResult {
  validators: StakingValidatorRow[];
  loading: boolean;
  error: string | null;
  reload: () => void;
}

export function useStakingValidators(
  walletAddress = "",
): UseStakingValidatorsResult {
  const cacheRevision = useSyncExternalStore(
    subscribeStakingValidatorsCache,
    getStakingValidatorsCacheRevision,
    getStakingValidatorsCacheRevision,
  );
  const delegationRevision = useSyncExternalStore(
    subscribeStakingDelegationState,
    getStakingDelegationRevision,
    getStakingDelegationRevision,
  );

  const [loading, setLoading] = useState(
    () => !isStakingValidatorsDataLoaded(),
  );
  const [error, setError] = useState<string | null>(null);
  const [reloadToken, setReloadToken] = useState(0);

  const reload = useCallback(() => {
    setReloadToken((value) => value + 1);
  }, []);

  useEffect(() => {
    if (isStakingValidatorsDataLoaded()) {
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchStakingValidators()
      .then(() => {
        if (cancelled) return;
        setError(null);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error
            ? err.message
            : "Failed to load staking validators",
        );
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [reloadToken]);

  const validators = useMemo(() => {
    void cacheRevision;
    void delegationRevision;
    return cloneStakingValidatorsForWallet(walletAddress);
  }, [cacheRevision, delegationRevision, walletAddress]);

  return { validators, loading, error, reload };
}
