import React, { useEffect, useState } from "react";

import type { StakingFeeTier } from "../../utils/stakingFeeSchedule";
import { formatStakingFeeTierLabel } from "../../utils/stakingFeeSchedule";
import { formatCurrency } from "../../sdk/utils/display";
import { BubbleTip, BUBBLE_TIP_IDS } from "../../tutorials/bubble-tip";
import type { BubbleTipId } from "../../tutorials/bubble-tip/bubbleTipIds";
import { formatStakingMormAmount } from "./stakingFormat";
import "./staking.css";

const DESKTOP_STAT_QUERY = "(min-width: 996px)";

function useDesktopStatBand(): boolean {
  const [desktop, setDesktop] = useState(() =>
    typeof window !== "undefined"
      ? window.matchMedia(DESKTOP_STAT_QUERY).matches
      : false,
  );

  useEffect(() => {
    const mediaQuery = window.matchMedia(DESKTOP_STAT_QUERY);
    const sync = () => setDesktop(mediaQuery.matches);
    sync();
    mediaQuery.addEventListener("change", sync);
    return () => mediaQuery.removeEventListener("change", sync);
  }, []);

  return desktop;
}

function StakingStatLabel({
  label,
  tipId,
  bubbleEnabled,
}: {
  label: string;
  tipId?: BubbleTipId;
  bubbleEnabled: boolean;
}): JSX.Element {
  const className = `staking-stat-label${
    bubbleEnabled && tipId ? " staking-stat-label--tip" : ""
  }`;
  const labelNode = <p className={className}>{label}</p>;

  if (bubbleEnabled && tipId) {
    return (
      <BubbleTip id={tipId} side="top" align="start">
        {labelNode}
      </BubbleTip>
    );
  }

  return labelNode;
}

export interface StakingKpiRowProps {
  height?: string;
  feeTier: StakingFeeTier;
  stakedMorm: number;
  totalStakedNetworkMorm: number;
  stakedSupplyPct: number;
  usdcYieldPaidToDate: number;
  enableUsdcYield: boolean;
}

function StakingKpiRow({
  height = "100%",
  feeTier,
  stakedMorm,
  totalStakedNetworkMorm,
  stakedSupplyPct,
  usdcYieldPaidToDate,
  enableUsdcYield,
}: StakingKpiRowProps): JSX.Element {
  const bubbleEnabled = useDesktopStatBand();

  const yieldDisplay =
    enableUsdcYield && usdcYieldPaidToDate > 0
      ? `$${formatCurrency(usdcYieldPaidToDate)} paid to date`
      : "$0 paid to date";

  return (
    <div
      className="staking-slot staking-slot--flush staking-stat-cards-slot"
      style={{ height }}
    >
      <div className="staking-stat-cards" aria-label="Staking overview">
        <div className="staking-stat-card">
          <StakingStatLabel
            label="Your Fee Tier"
            tipId={BUBBLE_TIP_IDS.stakingFeeTier}
            bubbleEnabled={bubbleEnabled}
          />
          <p className="staking-stat-value">
            <span className="staking-stat-value-primary">
              {formatStakingFeeTierLabel(feeTier)}
            </span>
            <span className="terminal-label staking-stat-subline">
              Based on staked MORM
            </span>
          </p>
        </div>
        <div className="staking-stat-card">
          <p className="staking-stat-label">Your Staked</p>
          <p className="staking-stat-value">
            {formatStakingMormAmount(stakedMorm)} MORM
          </p>
        </div>
        <div className="staking-stat-card">
          <StakingStatLabel
            label="Total Staked"
            tipId={BUBBLE_TIP_IDS.stakingTotalStaked}
            bubbleEnabled={bubbleEnabled}
          />
          <p className="staking-stat-value">
            <span>{formatStakingMormAmount(totalStakedNetworkMorm)} MORM</span>
            <span className="terminal-label staking-stat-subline">
              {stakedSupplyPct.toFixed(2)}% of circ. supply
            </span>
          </p>
        </div>
        <div className="staking-stat-card">
          <StakingStatLabel
            label="USDC Yield (trailing)"
            tipId={BUBBLE_TIP_IDS.stakingUsdcYield}
            bubbleEnabled={bubbleEnabled}
          />
          <p className="staking-stat-value">
            <span>{yieldDisplay}</span>
            <span className="terminal-label staking-stat-subline">
              Real USDC from protocol revenue — not emissions.
            </span>
          </p>
        </div>
      </div>
    </div>
  );
}

export default React.memo(StakingKpiRow);
