import React, { type JSX, type ReactNode } from "react";

import MorpheumLoadingOverlay from "../ui/MorpheumLoadingOverlay";

export interface VaultPanelLoadingGateProps {
  loading: boolean;
  label?: string;
  children: ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

export default function VaultPanelLoadingGate({
  loading,
  label = "Loading vault data…",
  children,
  className,
  style,
}: VaultPanelLoadingGateProps): JSX.Element {
  return (
    <div
      className={["vault-panel-loading-gate", className].filter(Boolean).join(" ")}
      style={style}
    >
      {loading ? (
        <MorpheumLoadingOverlay layout="absolute" label={label} matrixText />
      ) : null}
      {children}
    </div>
  );
}
