import { useMemo, useSyncExternalStore } from "react";
import { cloneVaultDepositors } from "../../offline/mock_data/vaultActivityData";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import { getVaultById } from "../../offline/mock_data/vaultCatalog";
import type { VaultDepositorRow } from "../../offline/mock_data/vaultMockData.types";
import {
  getVaultUserStateRevision,
  mergeVaultDepositors,
  subscribeVaultUserState,
} from "../../offline/mock_data/vaultUserState";
import { useOnboard } from "./useOnboard";

export function useVaultDepositors(vaultId: string): VaultDepositorRow[] {
  const { walletAddress } = useOnboard();
  const revision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  return useMemo(() => {
    void revision;
    void cacheRevision;
    const vault = getVaultById(vaultId);
    if (!vault) return [];
    const base = cloneVaultDepositors(vaultId);
    return mergeVaultDepositors(base, walletAddress, vaultId, vault);
  }, [vaultId, walletAddress, revision, cacheRevision]);
}
