import React from "react";

import type { AgentRolesFleetStats } from "../../hooks/useAgentRolesPageData";
import "./agentroles.css";

export interface AgentRolesFleetStatsProps {
  height?: string;
  stats: AgentRolesFleetStats;
}

export default function AgentRolesFleetStats({
  height = "100%",
  stats,
}: AgentRolesFleetStatsProps): JSX.Element {
  const chips = [
    { label: "Online", value: stats.online },
    { label: "Wallet", value: stats.withWallet },
    { label: "Pay-enabled", value: stats.payEnabled },
    { label: "DID-only", value: stats.didOnly },
    { label: "Listed", value: stats.listed },
    { label: "Needs you", value: stats.needsYou, highlight: stats.needsYou > 0 },
    { label: "Executing", value: stats.executing },
    { label: "Idle", value: stats.idle },
  ];

  return (
    <div
      className="agentroles-slot agentroles-header-band agentroles-header-band--metrics agentroles-fleet-stats"
      style={{ height }}
      aria-label="Fleet stats"
    >
      <div className="agentroles-fleet-stats-inner">
        {chips.map((chip) => (
          <div key={chip.label} className="agentroles-stat-chip">
            <span className="agentroles-stat-label">{chip.label}</span>
            <strong
              className={`agentroles-stat-value${
                chip.highlight ? " agentroles-stat-value--signal" : ""
              }`}
            >
              {chip.value}
            </strong>
          </div>
        ))}
      </div>
    </div>
  );
}
