import React, { useCallback, useState } from "react";

export interface AgentRolesCopyableValueProps {
  value: string;
  copyLabel?: string;
  className?: string;
}

export default function AgentRolesCopyableValue({
  value,
  copyLabel = "value",
  className,
}: AgentRolesCopyableValueProps): JSX.Element {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      setCopied(false);
    }
  }, [value]);

  const rootClassName = ["agentroles-copyable-value", className]
    .filter(Boolean)
    .join(" ");

  return (
    <span className={rootClassName}>
      <code className="agentroles-copyable-value__text">{value}</code>
      <button
        type="button"
        className="agentroles-copyable-value__btn"
        onClick={handleCopy}
        aria-label={`Copy ${copyLabel}`}
      >
        {copied ? "Copied" : "Copy"}
      </button>
    </span>
  );
}
