import { useCallback, useMemo, useState } from "react";
import { useSyncExternalStore } from "react";

import {
  getAllVaults,
  type VaultKind,
  type VaultRecord,
} from "../../offline/mock_data/vaultCatalog";
import { resolveVaultVisibility } from "../../offline/mock_data/vaultFeeModel";
import {
  getRegistryRevision,
  subscribeVaultRegistry,
} from "../../offline/mock_data/vaultRegistryStorage";
import {
  getInvestedVaultCount,
  getVaultDepositUsd,
  getVaultUserStateRevision,
  subscribeVaultUserState,
} from "../../offline/mock_data/vaultUserState";
import { isVaultOwner } from "./vaultOwnership";

export type VaultListSortKey = "analystScore" | "apr" | "tvl" | "age";
export type VaultListFilterKey = "all" | "leading" | "deposited" | "others";
export type VaultListTimeframe = "all-time" | "90d" | "30d";

export interface VaultListingRow extends VaultRecord {
  yourDepositUsd: number;
  isOwner: boolean;
}

export function matchesVaultListingSearch(
  vault: Pick<VaultRecord, "id" | "name" | "leader" | "leaderAddress">,
  query: string,
): boolean {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return true;
  const haystack = [vault.id, vault.name, vault.leader, vault.leaderAddress]
    .join(" ")
    .toLowerCase();
  return haystack.includes(normalized);
}

export function hasActiveVaultListingFilters(input: {
  searchQuery: string;
  filterKey: VaultListFilterKey;
  myVaultsOnly: boolean;
}): boolean {
  return (
    input.searchQuery.trim() !== "" ||
    input.filterKey !== "all" ||
    input.myVaultsOnly ||
    input.filterKey === "deposited"
  );
}

export function useVaultListingData(walletAddress = "") {
  const depositRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  const [sortKey, setSortKey] = useState<VaultListSortKey>("analystScore");
  const [filterKey, setFilterKey] = useState<VaultListFilterKey>("all");
  const [timeframe, setTimeframe] = useState<VaultListTimeframe>("all-time");
  const [pageSize, setPageSize] = useState(10);
  const [page, setPage] = useState(0);
  const [myVaultsOnly, setMyVaultsOnly] = useState(false);
  const [searchQuery, setSearchQueryState] = useState("");

  const setSearchQuery = useCallback((value: string) => {
    setSearchQueryState(value);
    setPage(0);
  }, []);

  const rows = useMemo((): VaultListingRow[] => {
    void depositRevision;
    void registryRevision;
    let list = getAllVaults()
      .filter((vault) => isVaultVisibleToWallet(vault, walletAddress))
      .map((vault) => ({
        ...vault,
        yourDepositUsd: getVaultDepositUsd(walletAddress, vault.id),
        isOwner: isVaultOwner(walletAddress, vault),
      }));

    if (myVaultsOnly) {
      list = list.filter((v) => v.kind === "user" && v.isOwner);
    }

    if (filterKey === "deposited") {
      list = list.filter((v) => v.yourDepositUsd > 0);
    } else if (filterKey === "leading") {
      list = list.filter((v) => v.grade === "A" || v.isFlagship);
    } else if (filterKey === "others") {
      list = list.filter((v) => v.kind === "user" && !v.isFlagship);
    }

    if (searchQuery.trim()) {
      list = list.filter((v) => matchesVaultListingSearch(v, searchQuery));
    }

    void timeframe;

    list.sort((a, b) => {
      if (sortKey === "analystScore") {
        return (b.analystVerdict.score ?? -1) - (a.analystVerdict.score ?? -1);
      }
      if (sortKey === "apr") {
        return (b.aprPct ?? -999) - (a.aprPct ?? -999);
      }
      if (sortKey === "tvl") {
        return b.tvlUsd - a.tvlUsd;
      }
      return b.ageDays - a.ageDays;
    });

    return list;
  }, [walletAddress, depositRevision, registryRevision, sortKey, filterKey, timeframe, myVaultsOnly, searchQuery]);

  const protocolVaults = useMemo(() => {
    const protocol = rows.filter((v) => v.kind === "protocol");
    return protocol.sort((a, b) => (b.isPinned ? 1 : 0) - (a.isPinned ? 1 : 0));
  }, [rows]);

  const userVaults = useMemo(
    () => rows.filter((v) => v.kind === "user"),
    [rows],
  );

  const paginatedUserVaults = useMemo(() => {
    const start = page * pageSize;
    return userVaults.slice(start, start + pageSize);
  }, [userVaults, page, pageSize]);

  const totalUserPages = Math.max(1, Math.ceil(userVaults.length / pageSize));

  const investedVaultCount = useMemo(() => {
    void depositRevision;
    return getInvestedVaultCount(walletAddress);
  }, [walletAddress, depositRevision]);

  return {
    sortKey,
    setSortKey,
    filterKey,
    setFilterKey,
    timeframe,
    setTimeframe,
    pageSize,
    setPageSize,
    page,
    setPage,
    protocolVaults,
    userVaults,
    paginatedUserVaults,
    totalUserPages,
    totalUserCount: userVaults.length,
    myVaultsOnly,
    setMyVaultsOnly,
    investedVaultCount,
    searchQuery,
    setSearchQuery,
  };
}

export function vaultKindLabel(kind: VaultKind): string {
  return kind === "protocol" ? "Protocol" : "User";
}

function isVaultVisibleToWallet(vault: VaultRecord, walletAddress: string): boolean {
  if (vault.kind === "protocol") {
    return true;
  }

  if (resolveVaultVisibility(vault) === "public") {
    return true;
  }

  return isVaultOwner(walletAddress, vault);
}
