import React from "react";

import type { VaultBucketSummary } from "../../../offline/mock_data/vaultCatalog";
import { VAULT_TOUR_TARGETS } from "../../tutorials/vault-tour/constants";
import "./vault.css";

export interface VaultBucketHealthBarProps {
  height?: string;
  bucket: VaultBucketSummary;
}

type HealthTone = "strong" | "thin" | "critical";

function getHealthMeta(bucket: VaultBucketSummary) {
  const bufferPct = Math.min(100, Math.max(0, 100 - bucket.marginUsagePct));
  const displayPct = Math.max(20, bufferPct);

  let tone: HealthTone = "strong";
  if (bucket.riskHealth === "critical" || bufferPct < 15) tone = "critical";
  else if (bucket.riskHealth === "watch" || bufferPct < 30) tone = "thin";

  const label =
    tone === "critical"
      ? "liq. buffer critical"
      : tone === "thin"
        ? "liq. buffer thin"
        : "liq. buffer strong";

  return { bufferPct, displayPct, tone, label };
}

export default function VaultBucketHealthBar({
  height = "100%",
  bucket,
}: VaultBucketHealthBarProps): JSX.Element {
  const { bufferPct, displayPct, tone, label } = getHealthMeta(bucket);

  return (
    <div
      className="vault-slot vault-slot--flush vault-health-bar-wrap"
      style={{ height }}
      data-tour={VAULT_TOUR_TARGETS.bucketHealth}
    >
      <span className="terminal-label">Health</span>
      <div
        className="vault-health-bar"
        style={{ ["--vault-health-fill" as string]: `${displayPct}%` }}
        role="progressbar"
        aria-valuenow={bufferPct}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={`Margin health ${bufferPct}%`}
      >
        <div className="vault-health-bar-fill" />
      </div>
      <span className={`vault-health-status vault-health-status--${tone}`}>
        {label}
      </span>
      <span className="vault-health-positions-count">
        Open positions: {bucket.openPositionCount}
      </span>
    </div>
  );
}
