import type { BubbleTipId } from "../../tutorials/bubble-tip";
import type { TabLayoutHeaderToolBarTab } from "./tab-layout-header-toolbar";
import { resolveTabLabels, type TabLabelKey } from "./tabLabels";
import { normalizeTabStripEntry, type TabStripEntry } from "./tabStrips";

export interface BuildToolbarTabsOptions {
  counts?: Partial<Record<string, number>>;
  showCount?: boolean | ((id: string) => boolean);
  badges?: Partial<
    Record<string, { count: number; pulse?: boolean }>
  >;
  bubbleTips?: Partial<Record<string, BubbleTipId>>;
  /** Override registry label key for a tab id (e.g. memoryAudit → memoryAuditHil). */
  labelKeyOverrides?: Partial<Record<string, TabLabelKey>>;
  /**
   * When false, omit shortLabel so CSS container compact mode cannot collapse labels.
   * Use when the grid breakpoint is lg but the tab strip panel is still narrower than 42rem.
   */
  useCompactLabels?: boolean;
}

function shouldShowCount(
  id: string,
  showCount: BuildToolbarTabsOptions["showCount"],
): boolean {
  if (showCount == null) return false;
  return typeof showCount === "function" ? showCount(id) : showCount;
}

export function buildToolbarTabs(
  strip: readonly TabStripEntry[],
  options?: BuildToolbarTabsOptions,
): TabLayoutHeaderToolBarTab[] {
  return strip.map((entry) => {
    const { id, labelKey: defaultLabelKey } = normalizeTabStripEntry(entry);
    const labelKey = options?.labelKeyOverrides?.[id] ?? defaultLabelKey;
    const count = options?.counts?.[id];
    const showCount = shouldShowCount(id, options?.showCount);
    const { label, shortLabel } = resolveTabLabels(labelKey, {
      count,
      showCount,
    });
    const badge = options?.badges?.[id];
    const bubbleTipId = options?.bubbleTips?.[id];

    const includeShort =
      options?.useCompactLabels !== false && shortLabel != null;

    return {
      id,
      label,
      ...(includeShort ? { shortLabel } : {}),
      ...(badge && badge.count > 0
        ? {
            badgeCount: badge.count,
            ...(badge.pulse ? { badgePulse: true } : {}),
          }
        : {}),
      ...(bubbleTipId ? { bubbleTipId } : {}),
    };
  });
}
