import { useMemo, useSyncExternalStore } from "react";
import { cloneVaultOpenOrders } from "../../offline/mock_data/vaultActivityData";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import {
  getRemovedBaseOrderIds,
  getVaultOpenOrdersOverlay,
  getVaultOperateStateRevision,
  subscribeVaultOperateState,
} from "../../offline/mock_data/vaultOperateState";
import type { VaultOpenOrderRow } from "../../offline/mock_data/vaultMockData.types";

export function useVaultOpenOrders(
  vaultId: string,
  bucketId?: string,
): VaultOpenOrderRow[] {
  const revision = useSyncExternalStore(
    subscribeVaultOperateState,
    getVaultOperateStateRevision,
    getVaultOperateStateRevision,
  );
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  return useMemo(() => {
    void revision;
    void cacheRevision;
    const removed = getRemovedBaseOrderIds(vaultId);
    const base = cloneVaultOpenOrders(vaultId, bucketId).filter(
      (row) => !removed.has(row.orderId),
    );
    const overlay = getVaultOpenOrdersOverlay(vaultId, bucketId);
    return [...overlay, ...base];
  }, [vaultId, bucketId, revision, cacheRevision]);
}
