import React, { useMemo } from "react";

import { useVaultBalances } from "../../hooks/useVaultBalances";
import { formatCurrency } from "../../sdk/utils/display";
import { TableHeaderCellStatic } from "../smartlayout";
import VaultActivityTableShell from "./VaultActivityTableShell";
import {
  formatPct,
  idleSpotTotalUsd,
  sortIdleBalances,
  weightPct,
} from "./vaultPortfolioMetrics";
import "./vault.css";

const GRID_CLASS = "vault-balances-grid";

export interface VaultBalancesTableProps {
  vaultId: string;
  vaultTvlUsd: number;
}

function formatAmount(value: number, symbol: string): string {
  const digits = symbol === "USDC" ? 2 : 4;
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  }).format(value);
}

function VaultBalancesTotalRow({
  idleTotalUsd,
  vaultTvlUsd,
}: {
  idleTotalUsd: number;
  vaultTvlUsd: number;
}): JSX.Element {
  return (
    <div className={`table-row vault-positions-total-row ${GRID_CLASS}`}>
      <div className="table-cell primary">TOTAL idle spot</div>
      <div className="table-cell primary">—</div>
      <div className="table-cell numeric">—</div>
      <div className="table-cell numeric">—</div>
      <div className="table-cell numeric">—</div>
      <div className="table-cell numeric">
        {formatCurrency(idleTotalUsd)} · {formatPct(weightPct(idleTotalUsd, vaultTvlUsd))} of TVL
      </div>
    </div>
  );
}

export default function VaultBalancesTable({
  vaultId,
  vaultTvlUsd,
}: VaultBalancesTableProps): JSX.Element {
  const rows = useVaultBalances(vaultId);

  const sortedRows = useMemo(() => sortIdleBalances(rows), [rows]);
  const idleTotalUsd = useMemo(() => idleSpotTotalUsd(rows), [rows]);

  return (
    <VaultActivityTableShell
      gridClassName={GRID_CLASS}
      minWidth={840}
      isEmpty={rows.length === 0}
      emptyMessage="No idle spot balances."
      header={
        <>
          <TableHeaderCellStatic left>Asset</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Name</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Total</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Available</TableHeaderCellStatic>
          <TableHeaderCellStatic left>In Margin/Orders</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Value</TableHeaderCellStatic>
        </>
      }
      pinnedFooter={
        rows.length > 0 ? (
          <VaultBalancesTotalRow
            idleTotalUsd={idleTotalUsd}
            vaultTvlUsd={vaultTvlUsd}
          />
        ) : undefined
      }
    >
      {sortedRows.map((row) => (
        <div key={row.symbol} className={`table-row ${GRID_CLASS}`}>
          <div className="table-cell primary">
            <span>{row.symbol}</span>
          </div>
          <div className="table-cell primary" title={row.name}>
            {row.name}
          </div>
          <div className="table-cell numeric">
            {formatAmount(row.amount, row.symbol)}
          </div>
          <div className="table-cell numeric">
            {formatAmount(row.amount, row.symbol)}
          </div>
          <div className="table-cell numeric">—</div>
          <div className="table-cell numeric">{formatCurrency(row.valueUsd)}</div>
        </div>
      ))}
    </VaultActivityTableShell>
  );
}
