import { useCallback, useEffect, useMemo, useState } from "react";

import {
  getStakingUserState,
  getStakingUserStateRevision,
  recordClaimRewards,
  subscribeStakingUserState,
} from "../../offline/mock_data";
import {
  MOCK_MORM_CIRCULATING_SUPPLY,
  MOCK_TOTAL_STAKED_MORM,
} from "../constants/staking";
import { useSettings } from "../context/SettingsContext";
import { usePortfolioBalances } from "./usePortfolioBalances";
import { resolveStakingFeeTier } from "../utils/stakingFeeSchedule";

const OFFLINE_BASE_URL = "offline://local";

export interface UseStakingPageDataConfig {
  walletAddress: string;
  refreshInterval?: number;
}

export function useStakingPageData({
  walletAddress,
  refreshInterval = 5000,
}: UseStakingPageDataConfig) {
  const { settings } = useSettings();
  const [stakingRevision, setStakingRevision] = useState(
    getStakingUserStateRevision(),
  );

  useEffect(() => {
    return subscribeStakingUserState(() => {
      setStakingRevision(getStakingUserStateRevision());
    });
  }, []);

  const { sortedRows } = usePortfolioBalances({
    baseURL: OFFLINE_BASE_URL,
    walletAddress,
    refreshInterval,
  });

  const walletMormAvailable = useMemo(() => {
    const row = sortedRows.find((entry) => entry.symbol === "MORM");
    return row?.amount ?? 0;
  }, [sortedRows]);

  const stakingState = useMemo(() => {
    void stakingRevision;
    return getStakingUserState(walletAddress);
  }, [stakingRevision, walletAddress]);

  const stakedMorm = stakingState.stakedMorm;
  const pendingUnstakes = stakingState.pendingUnstakes;
  const activity = stakingState.activity;
  const usdcYieldPaidToDate = stakingState.usdcYieldPaidToDate;
  const claimableUsdc = stakingState.claimableUsdc;

  useEffect(() => {
    if (!walletAddress?.trim()) return;
    if (pendingUnstakes.length === 0) return;

    const tick = () => {
      const revisionBefore = getStakingUserStateRevision();
      getStakingUserState(walletAddress);
      const revisionAfter = getStakingUserStateRevision();
      if (revisionAfter !== revisionBefore) {
        setStakingRevision(revisionAfter);
      }
    };

    const intervalId = window.setInterval(tick, 1000);
    return () => window.clearInterval(intervalId);
  }, [pendingUnstakes.length, walletAddress]);

  const feeTier = useMemo(
    () => resolveStakingFeeTier(stakedMorm),
    [stakedMorm],
  );

  const totalStakedNetworkMorm = MOCK_TOTAL_STAKED_MORM;
  const circulatingSupply = MOCK_MORM_CIRCULATING_SUPPLY;
  const stakedSupplyPct =
    circulatingSupply > 0
      ? (totalStakedNetworkMorm / circulatingSupply) * 100
      : 0;

  const enableUsdcYield = settings.staking.enableUsdcYield;
  const enableDelegation = settings.staking.enableDelegation;

  const refresh = useCallback(() => {
    setStakingRevision(getStakingUserStateRevision());
  }, []);

  const claimRewards = useCallback(() => {
    if (!walletAddress?.trim()) {
      return { ok: false as const, reason: "invalid" as const };
    }
    const result = recordClaimRewards(walletAddress);
    if (result.ok) {
      refresh();
    }
    return result;
  }, [refresh, walletAddress]);

  return {
    walletMormAvailable,
    stakedMorm,
    pendingUnstakes,
    activity,
    usdcYieldPaidToDate,
    claimableUsdc,
    feeTier,
    totalStakedNetworkMorm,
    stakedSupplyPct,
    enableUsdcYield,
    enableDelegation,
    refresh,
    claimRewards,
  };
}
