/**
 * Runtime accessors for trader leaderboard data loaded from mock-system-data.
 * Populated by traderLeaderboardClient after fetch; empty until loaded.
 */
import { getCachedTraderLeaderboard } from "./traderLeaderboardCache";
import type { TraderLeaderboardRow } from "./traderLeaderboard.types";

export function getTraderLeaderboardRows(): TraderLeaderboardRow[] {
  return getCachedTraderLeaderboard()?.traders ?? [];
}

export function cloneTraderLeaderboardRows(): TraderLeaderboardRow[] {
  return getTraderLeaderboardRows().map((row) => ({
    ...row,
    byTimeframe: {
      all: { ...row.byTimeframe.all },
      "30d": { ...row.byTimeframe["30d"] },
      "7d": { ...row.byTimeframe["7d"] },
    },
  }));
}
