import {
  getOfflineStakingSteps,
  recordStake,
  recordUnstake,
  type OfflineStakingStep,
} from "../../offline/mock_data";

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type ExecuteOfflineStakeFundsParams = {
  wallet: string;
  mode: "stake" | "unstake";
  amountMorm: number;
};

export type OfflineStakeFundsProgressCallbacks = {
  onStepStart?: (step: OfflineStakingStep) => void;
};

export type ExecuteOfflineStakeFundsResult = {
  txHash: string;
  pendingId?: string;
};

export async function executeOfflineStakeFunds(
  params: ExecuteOfflineStakeFundsParams,
  callbacks?: OfflineStakeFundsProgressCallbacks,
): Promise<ExecuteOfflineStakeFundsResult> {
  const wallet = params.wallet.trim();
  if (!wallet) {
    throw new Error("Wallet address is required");
  }
  if (!Number.isFinite(params.amountMorm) || params.amountMorm <= 0) {
    throw new Error("Amount must be greater than zero");
  }

  const steps = getOfflineStakingSteps({
    mode: params.mode,
    amount: params.amountMorm,
  });

  for (const step of steps) {
    callbacks?.onStepStart?.(step);
    await delay(step.delayMs);
  }

  if (params.mode === "stake") {
    const result = recordStake(wallet, params.amountMorm);
    if (!result.ok) {
      throw new Error(
        result.reason === "insufficient"
          ? "Insufficient MORM balance"
          : "Invalid stake amount",
      );
    }
    return { txHash: result.txHash };
  }

  const result = recordUnstake(wallet, params.amountMorm);
  if (!result.ok) {
    throw new Error(
      result.reason === "insufficient"
        ? "Insufficient staked balance"
        : "Invalid unstake amount",
    );
  }
  return { txHash: result.txHash, pendingId: result.pendingId };
}
