import React, { useEffect, useMemo, useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import { AGENT_TASK_STATUS_CONFIG } from "../../constants";
import type {
  AgentPermissionMode,
  AgentTask,
  AgentTaskStatus,
  TradingAgent,
} from "../../store/types";
import { PERMISSION_MODE_DESCRIPTIONS, PERMISSION_MODE_LABELS } from "../../utils/mintAgent";
import {
  AGENT_STATUS_LABELS,
  formatAgentRevenue,
  formatPaymentUsd,
  formatSpendCapSummary,
  getAgentCustodyKind,
  getAgentCustodyKindLabel,
  getAgentCustodyTabLabel,
  getAgentPaymentLabel,
  getAgentRoleLabel,
  getAgentStatusDotClass,
  getListingLabel,
  resolveAgentPaymentState,
} from "../../utils/agentRoles";
import { agentRolesConsolePath } from "../../routes";
import { ModalTabBar } from "../smartlayout/modal-tab-bar";
import AgentRolesCopyableValue from "./AgentRolesCopyableValue";
import AgentRolesCustodyAddressRows from "./AgentRolesCustodyAddressRows";
import AgentMemoryCapacityBlock from "./AgentMemoryCapacityBlock";
import "./agentroles.css";

export type AgentRolesDetailTabId =
  | "overview"
  | "memory"
  | "intents"
  | "wallet"
  | "payments"
  | "listing";

const DETAIL_TABS: { id: AgentRolesDetailTabId; label: string }[] = [
  { id: "overview", label: "Overview" },
  { id: "memory", label: "Memory" },
  { id: "intents", label: "Intents" },
  { id: "wallet", label: "Wallet" },
  { id: "payments", label: "Payments" },
  { id: "listing", label: "Listing" },
];

function buildVisibleDetailTabs(
  agent: TradingAgent,
  agentTaskCount: number,
): { id: AgentRolesDetailTabId; label: string }[] {
  const paymentState = resolveAgentPaymentState(agent);
  const custodyTabLabel = getAgentCustodyTabLabel(agent);

  return DETAIL_TABS.filter((tab) => {
    if (tab.id === "intents") return agentTaskCount > 0;
    if (tab.id === "payments") return paymentState !== "no_payments";
    return true;
  }).map((tab) =>
    tab.id === "wallet" ? { ...tab, label: custodyTabLabel } : tab,
  );
}

export interface AgentRolesDetailContentProps {
  agent: TradingAgent;
  tasks: AgentTask[];
  needsYouCount: number;
  onDeployToMarket?: () => void;
  onRelistToMarket?: () => void;
  onDuplicateAgent?: () => void;
  onClose?: () => void;
  layout?: "slider" | "sheet";
}

function formatRelativeTime(iso: string): string {
  const delta = Date.now() - new Date(iso).getTime();
  const minutes = Math.floor(delta / 60000);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

function getTaskStatusPresentation(status: AgentTaskStatus): {
  label: string;
  tone: string;
} {
  const config = AGENT_TASK_STATUS_CONFIG[status];
  return {
    label: config?.label ?? status,
    tone: config?.tone ?? "muted",
  };
}

interface DetailDlRowProps {
  label: string;
  children: React.ReactNode;
  valueClassName?: string;
}

function DetailDlRow({
  label,
  children,
  valueClassName,
}: DetailDlRowProps): JSX.Element {
  return (
    <div>
      <dt className="terminal-label">{label}</dt>
      <dd className={valueClassName}>{children}</dd>
    </div>
  );
}

interface DetailListingBadgeProps {
  agent: TradingAgent;
}

function DetailListingBadge({ agent }: DetailListingBadgeProps): JSX.Element {
  const label = getListingLabel(agent.listingStatus);

  if (agent.listingStatus === "listed" && agent.catalogAgentId) {
    return (
      <Link
        to={`/agents/${agent.catalogAgentId}`}
        className="agentroles-listing-badge agentroles-listing-badge--listed"
      >
        {label}
      </Link>
    );
  }

  return (
    <span
      className={`agentroles-listing-badge agentroles-listing-badge--${agent.listingStatus}`}
    >
      {label}
    </span>
  );
}

interface DetailPaymentChipProps {
  agent: TradingAgent;
}

function DetailPaymentChip({ agent }: DetailPaymentChipProps): JSX.Element {
  const paymentState = resolveAgentPaymentState(agent);
  return (
    <span
      className={`agentroles-payment-chip agentroles-payment-chip--${paymentState}`}
    >
      {getAgentPaymentLabel(agent)}
    </span>
  );
}

function resolveAgentPermissionMode(agent: TradingAgent): AgentPermissionMode {
  return agent.permissionMode ?? "watch_only";
}

interface DetailPermissionChipProps {
  mode: AgentPermissionMode;
}

function DetailPermissionChip({ mode }: DetailPermissionChipProps): JSX.Element {
  return (
    <span
      className={`agentroles-permission-chip agentroles-permission-chip--${mode}`}
    >
      {PERMISSION_MODE_LABELS[mode]}
    </span>
  );
}

interface DetailStatusValueProps {
  agent: TradingAgent;
}

function DetailStatusValue({ agent }: DetailStatusValueProps): JSX.Element {
  return (
    <span className="agentroles-detail-status-row">
      <span className={getAgentStatusDotClass(agent)} aria-hidden />
      <span className="terminal-value">
        {AGENT_STATUS_LABELS[agent.status]}
      </span>
    </span>
  );
}

export default function AgentRolesDetailContent({
  agent,
  tasks,
  needsYouCount,
  onDeployToMarket,
  onRelistToMarket,
  onDuplicateAgent,
  onClose,
  layout = "slider",
}: AgentRolesDetailContentProps): JSX.Element {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<AgentRolesDetailTabId>("overview");
  const custodyKind = getAgentCustodyKind(agent);
  const paymentState = resolveAgentPaymentState(agent);
  const permissionMode = resolveAgentPermissionMode(agent);

  useEffect(() => {
    setActiveTab("overview");
  }, [agent.id]);

  const agentTasks = useMemo(
    () => tasks.filter((task) => task.agentId === agent.id),
    [tasks, agent.id],
  );

  const visibleTabs = useMemo(
    () => buildVisibleDetailTabs(agent, agentTasks.length),
    [agent, agentTasks.length],
  );

  useEffect(() => {
    if (!visibleTabs.some((tab) => tab.id === activeTab)) {
      setActiveTab("overview");
    }
  }, [activeTab, visibleTabs]);

  const handleOpenConsole = () => {
    navigate(agentRolesConsolePath(agent.id));
  };

  return (
    <div className={`agentroles-detail agentroles-detail--${layout}`}>
      <header className="agentroles-detail-header">
        <div>
          <p className="agentroles-detail-eyebrow">Fleet agent</p>
          <h3 className="agentroles-detail-title">
            {agent.icon ? <span aria-hidden>{agent.icon}</span> : null}
            {agent.displayName}{" "}
            <span className="agentroles-agent-version">{agent.versionTag}</span>
          </h3>
          <p className="agentroles-detail-subtitle">
            {getAgentRoleLabel(agent.role)} · {getAgentCustodyKindLabel(agent)}
          </p>
        </div>
        {onClose ? (
          <button
            type="button"
            className="agentroles-detail-close"
            onClick={onClose}
            aria-label="Close agent detail"
          >
            ×
          </button>
        ) : null}
      </header>

      <div className="agentroles-detail-context">
        <AgentRolesCopyableValue
          value={agent.did}
          copyLabel="KYA DID"
          className="agentroles-detail-chip"
        />
        {needsYouCount > 0 ? (
          <button
            type="button"
            className="agentroles-needs-you-link"
            onClick={handleOpenConsole}
          >
            Needs you: {needsYouCount} → Open Console
          </button>
        ) : null}
      </div>

      <div className="agentroles-detail-tabs">
        <ModalTabBar
          tabs={visibleTabs}
          activeTabId={activeTab}
          onTabChange={(id) => setActiveTab(id as AgentRolesDetailTabId)}
          aria-label="Agent detail tabs"
        />
      </div>

      <div className="agentroles-detail-body">
        {activeTab === "overview" ? (
          <div className="agentroles-detail-section">
            <dl className="agentroles-detail-dl">
              <DetailDlRow label="Role" valueClassName="terminal-value">
                {getAgentRoleLabel(agent.role)}
              </DetailDlRow>
              <DetailDlRow label="Custody" valueClassName="terminal-value">
                {getAgentCustodyKindLabel(agent)}
              </DetailDlRow>
              <AgentRolesCustodyAddressRows agent={agent} />
              <DetailDlRow label="Payments">
                <DetailPaymentChip agent={agent} />
              </DetailDlRow>
              <DetailDlRow label="Status">
                <DetailStatusValue agent={agent} />
              </DetailDlRow>
              <DetailDlRow label="30d yield" valueClassName="terminal-value">
                {formatAgentRevenue(agent.revenue30d)}
              </DetailDlRow>
              <DetailDlRow label="Risk score" valueClassName="terminal-value">
                {agent.riskScore ?? "—"}
              </DetailDlRow>
              <DetailDlRow label="Listing">
                <DetailListingBadge agent={agent} />
              </DetailDlRow>
            </dl>
            {onDuplicateAgent ? (
              <button
                type="button"
                className="agentroles-deploy-btn"
                onClick={onDuplicateAgent}
              >
                Duplicate &amp; bump version
              </button>
            ) : null}
          </div>
        ) : null}

        {activeTab === "memory" ? (
          <div className="agentroles-detail-section">
            <AgentMemoryCapacityBlock agent={agent} variant="full" />
            <div className="agentroles-memory-log">
              <p className="terminal-label agentroles-memory-log-label">Memory log</p>
              {agent.memory.length === 0 ? (
                <p className="terminal-text-muted">No memory notes yet.</p>
              ) : (
                <ul className="agentroles-memory-list">
                  {agent.memory.map((item) => (
                    <li key={item.id} className="agentroles-memory-item">
                      <p className="terminal-value agentroles-memory-item__text">
                        {item.text}
                      </p>
                      <time
                        className="terminal-label agentroles-memory-item__time"
                        dateTime={item.at}
                      >
                        {formatRelativeTime(item.at)}
                      </time>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        ) : null}

        {activeTab === "intents" ? (
          <div className="agentroles-detail-section">
            {agentTasks.length === 0 ? (
              <p className="terminal-text-muted">No intents for this agent.</p>
            ) : (
              <ul className="agentroles-intent-list">
                {agentTasks.map((task) => {
                  const status = getTaskStatusPresentation(task.status);
                  return (
                    <li key={task.id} className="agentroles-intent-item">
                      <div className="agentroles-intent-item__head">
                        <p className="terminal-value agentroles-intent-item__desc">
                          {task.description}
                        </p>
                        <span
                          className={`agentroles-intent-status agentroles-intent-status--${status.tone}`}
                        >
                          {status.label}
                        </span>
                      </div>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        ) : null}

        {activeTab === "wallet" ? (
          <div className="agentroles-detail-section">
            {custodyKind === "wallet" ? (
              <>
                <dl className="agentroles-detail-dl">
                  <AgentRolesCustodyAddressRows agent={agent} />
                </dl>
                <p className="terminal-text-muted">
                  Signing wallet — executes on-chain intents.
                </p>
              </>
            ) : null}
            {custodyKind === "vault" ? (
              <>
                <dl className="agentroles-detail-dl">
                  <div>
                    <dt className="terminal-label">Vault address</dt>
                    <dd>
                      <AgentRolesCopyableValue
                        value={agent.vaultAddress!}
                        copyLabel="vault address"
                      />
                    </dd>
                  </div>
                </dl>
                <p className="terminal-text-muted">
                  Delegated custody — not a signing wallet.
                </p>
              </>
            ) : null}
            {custodyKind === "did_only" ? (
              <>
                <dl className="agentroles-detail-dl">
                  <div>
                    <dt className="terminal-label">KYA DID</dt>
                    <dd>
                      <AgentRolesCopyableValue
                        value={agent.did}
                        copyLabel="KYA DID"
                      />
                    </dd>
                  </div>
                  <DetailDlRow label="Permission mode">
                    <DetailPermissionChip mode={permissionMode} />
                  </DetailDlRow>
                </dl>
                {permissionMode !== "watch_only" ? (
                  <p className="agentroles-non-custodial-note">
                    {PERMISSION_MODE_DESCRIPTIONS[permissionMode]}
                  </p>
                ) : null}
                <p className="terminal-text-muted">
                  DID only — no wallet. No on-chain signing by role convention.
                </p>
              </>
            ) : null}
          </div>
        ) : null}

        {activeTab === "payments" ? (
          <div className="agentroles-detail-section">
            {paymentState === "no_payments" ? (
              <p className="agentroles-non-custodial-note">
                No payment rail — route via a wallet agent
              </p>
            ) : (
              <dl className="agentroles-detail-dl">
                <DetailDlRow label="Payment state">
                  <DetailPaymentChip agent={agent} />
                </DetailDlRow>
                <DetailDlRow label="Spend cap" valueClassName="terminal-value">
                  {formatSpendCapSummary(agent)}
                </DetailDlRow>
                <DetailDlRow label="Allowlist" valueClassName="terminal-value">
                  {agent.counterpartyAllowlistCount != null
                    ? `${agent.counterpartyAllowlistCount} parties`
                    : "—"}
                </DetailDlRow>
                <DetailDlRow label="30d out" valueClassName="terminal-value">
                  {formatPaymentUsd(agent.paymentOut30dUsd)}
                </DetailDlRow>
                <DetailDlRow label="30d in" valueClassName="terminal-value">
                  {formatPaymentUsd(agent.paymentIn30dUsd)}
                </DetailDlRow>
                {agent.mandateSummary ? (
                  <DetailDlRow label="Mandate" valueClassName="terminal-value">
                    {agent.mandateSummary}
                  </DetailDlRow>
                ) : null}
              </dl>
            )}
            {paymentState === "spend_paused" ? (
              <p className="agentroles-non-custodial-note">
                Spend paused — over-cap payments route to Agent Console.
              </p>
            ) : null}
          </div>
        ) : null}

        {activeTab === "listing" ? (
          <div className="agentroles-detail-section">
            <dl className="agentroles-detail-dl">
              <DetailDlRow label="Listing status">
                <DetailListingBadge agent={agent} />
              </DetailDlRow>
              {agent.marketSymbol ? (
                <DetailDlRow label="Market symbol" valueClassName="terminal-value">
                  {agent.marketSymbol}
                </DetailDlRow>
              ) : null}
              {agent.listingCategory ? (
                <DetailDlRow label="Category" valueClassName="terminal-value">
                  {agent.listingCategory}
                </DetailDlRow>
              ) : null}
              {agent.listingDescription ? (
                <DetailDlRow label="Description" valueClassName="terminal-value">
                  {agent.listingDescription}
                </DetailDlRow>
              ) : null}
              {agent.listingType ? (
                <DetailDlRow label="Listing type" valueClassName="terminal-value">
                  {agent.listingType}
                </DetailDlRow>
              ) : null}
              {agent.catalogAgentId ? (
                <DetailDlRow label="Catalog id" valueClassName="terminal-value">
                  {agent.catalogAgentId}
                </DetailDlRow>
              ) : null}
            </dl>
            <div className="agentroles-detail-actions">
              {agent.listingStatus === "listed" && agent.catalogAgentId ? (
                <Link
                  to={`/agents/${agent.catalogAgentId}`}
                  className="agentroles-detail-link"
                >
                  View on Markets →
                </Link>
              ) : null}
              {(agent.listingStatus === "private" ||
                agent.listingStatus === "staged") &&
              onDeployToMarket ? (
                <button
                  type="button"
                  className="agentroles-deploy-btn"
                  onClick={onDeployToMarket}
                >
                  Deploy to Market
                </button>
              ) : null}
              {agent.listingStatus === "delisted" && onRelistToMarket ? (
                <button
                  type="button"
                  className="agentroles-deploy-btn"
                  onClick={onRelistToMarket}
                >
                  Relist to Market
                </button>
              ) : null}
            </div>
          </div>
        ) : null}
      </div>

      <footer className="agentroles-detail-footer">
        <button
          type="button"
          className="agentroles-console-btn"
          onClick={handleOpenConsole}
        >
          Open in Agent Console →
        </button>
      </footer>
    </div>
  );
}
