import type {
  LeaderboardTimeframe,
  TraderLeaderboardMetrics,
  TraderLeaderboardRow,
} from "../../../offline/mock_data/traderLeaderboard.types";

export type {
  LeaderboardTimeframe,
  TraderLeaderboardMetrics,
  TraderLeaderboardRow,
};

export type LeaderboardSortField =
  | "accountValueUsd"
  | "pnlUsd"
  | "roiPct"
  | "volumeUsd";

export interface TraderLeaderboardViewRow {
  rank: number;
  address: string;
  displayName?: string;
  email?: string;
  accountValueUsd: number;
  pnlUsd: number;
  roiPct: number;
  volumeUsd: number;
  isYou?: boolean;
}

export const LEADERBOARD_TIMEFRAME_LABELS: Record<LeaderboardTimeframe, string> =
  {
    all: "All-time",
    "30d": "30d",
    "7d": "7d",
  };

export function computeLeaderboardRoi(
  metrics: Pick<
    TraderLeaderboardMetrics,
    "pnlUsd" | "startingAccountValueUsd" | "maxNetDepositsUsd"
  >,
): number {
  const denominator = Math.max(
    100,
    metrics.startingAccountValueUsd + metrics.maxNetDepositsUsd,
  );
  return (metrics.pnlUsd / denominator) * 100;
}

export function passesLeaderboardEligibility(
  row: TraderLeaderboardRow,
  timeframe: LeaderboardTimeframe,
): boolean {
  if (!row.isActive30d) return false;
  const metrics = row.byTimeframe[timeframe];
  if (
    metrics.accountValueUsd < 100_000 &&
    metrics.volumeUsd < 10_000_000
  ) {
    return false;
  }
  return true;
}

export function matchesLeaderboardQuery(
  row: TraderLeaderboardRow,
  query: string,
): boolean {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return true;
  if (row.address.toLowerCase().includes(normalized)) return true;
  if (row.displayName?.toLowerCase().includes(normalized)) return true;
  if (row.email?.toLowerCase().includes(normalized)) return true;
  return false;
}

export function matchesLeaderboardViewQuery(
  row: TraderLeaderboardViewRow,
  query: string,
): boolean {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return true;
  if (row.address.toLowerCase().includes(normalized)) return true;
  if (row.displayName?.toLowerCase().includes(normalized)) return true;
  if (row.email?.toLowerCase().includes(normalized)) return true;
  return false;
}

export function toLeaderboardViewRow(
  row: TraderLeaderboardRow,
  timeframe: LeaderboardTimeframe,
  rank: number,
  isYou = false,
): TraderLeaderboardViewRow {
  const metrics = row.byTimeframe[timeframe];
  return {
    rank,
    address: row.address,
    displayName: row.displayName,
    email: row.email,
    accountValueUsd: metrics.accountValueUsd,
    pnlUsd: metrics.pnlUsd,
    roiPct: computeLeaderboardRoi(metrics),
    volumeUsd: metrics.volumeUsd,
    isYou,
  };
}

export function buildLeaderboardViewRows(
  rows: TraderLeaderboardRow[],
  timeframe: LeaderboardTimeframe,
  sortField: LeaderboardSortField,
  sortDirection: "asc" | "desc",
  query: string,
): TraderLeaderboardViewRow[] {
  const eligible = rows.filter((row) =>
    passesLeaderboardEligibility(row, timeframe),
  );

  const direction = sortDirection === "asc" ? 1 : -1;
  eligible.sort((left, right) => {
    const leftMetrics = left.byTimeframe[timeframe];
    const rightMetrics = right.byTimeframe[timeframe];
    const leftValue =
      sortField === "roiPct"
        ? computeLeaderboardRoi(leftMetrics)
        : leftMetrics[sortField];
    const rightValue =
      sortField === "roiPct"
        ? computeLeaderboardRoi(rightMetrics)
        : rightMetrics[sortField];
    const delta = (leftValue - rightValue) * direction;
    if (delta !== 0) return delta;
    return left.address.localeCompare(right.address);
  });

  const ranked = eligible.map((row, index) =>
    toLeaderboardViewRow(row, timeframe, index + 1),
  );

  const normalized = query.trim().toLowerCase();
  if (!normalized) return ranked;

  return ranked.filter((row) => matchesLeaderboardViewQuery(row, query));
}

/** Full ranked list before search — used for pinned YOU row global rank. */
export function buildLeaderboardRankedRows(
  rows: TraderLeaderboardRow[],
  timeframe: LeaderboardTimeframe,
  sortField: LeaderboardSortField,
  sortDirection: "asc" | "desc",
): TraderLeaderboardViewRow[] {
  return buildLeaderboardViewRows(rows, timeframe, sortField, sortDirection, "");
}

export function truncateTraderAddress(address: string): string {
  if (address.length <= 14) return address;
  if (address.startsWith("0x") && address.length > 10) {
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  }
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}

export function formatLeaderboardTraderLabel(
  row: Pick<TraderLeaderboardViewRow, "address" | "displayName" | "email">,
): string {
  if (row.displayName) return row.displayName;
  if (row.email) return row.email;
  return truncateTraderAddress(row.address);
}

export function formatSignedCurrency(value: number): string {
  const sign = value >= 0 ? "+" : "-";
  const abs = Math.abs(value);
  return `${sign}$${abs.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

export function formatSignedPercent(value: number): string {
  const sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}%`;
}

export function normalizeLeaderboardAddress(address: string): string {
  return address.trim().toLowerCase();
}
