import React, { useEffect, useState } from "react";

import type { StakingPendingUnstakeRow } from "../../../offline/mock_data/stakingMockData.types";
import VaultActivityTableShell from "../vault/VaultActivityTableShell";
import { formatStakingCountdown, formatStakingMormAmount } from "./stakingFormat";
import "./staking.css";

export interface StakingPendingUnstakesTableProps {
  rows: StakingPendingUnstakeRow[];
  height?: string;
}

function StakingPendingUnstakesTable({
  rows,
  height = "100%",
}: StakingPendingUnstakesTableProps): JSX.Element {
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, []);

  return (
    <div style={{ height }}>
      <VaultActivityTableShell
        layout="terminal"
        tableClassName="position-table"
        gridClassName="staking-pending-grid"
        isEmpty={rows.length === 0}
        emptyMessage="No pending unstakes."
        header={
          <>
            <span>Amount</span>
            <span>Unlocks in</span>
            <span>Tx</span>
          </>
        }
      >
        {rows.map((row) => (
          <div key={row.id} className="table-row staking-pending-grid">
            <span>{formatStakingMormAmount(row.amountMorm)} MORM</span>
            <span className="staking-countdown">
              {formatStakingCountdown(row.unlockAtMs - now)}
            </span>
            <span className="terminal-label">{row.txHash.slice(0, 10)}…</span>
          </div>
        ))}
      </VaultActivityTableShell>
    </div>
  );
}

export default React.memo(StakingPendingUnstakesTable);
