import React from "react";

import type { TradingAgent } from "../../../store/types";
import type { MintCustodyMode } from "../../../store/types";
import type { MintAgentWizardState } from "../../../utils/mintAgent";
import {
  isHandleAvailable,
  previewDid,
  roleAllowsWalletCustody,
  suggestHandle,
} from "../../../utils/mintAgent";

export interface MintAgentStepIdentityProps {
  state: MintAgentWizardState;
  agents: TradingAgent[];
  onChange: (patch: Partial<MintAgentWizardState>) => void;
}

const CUSTODY_OPTIONS: { value: MintCustodyMode; label: string }[] = [
  { value: "generate_wallet", label: "Generate wallet" },
  { value: "link_existing", label: "Link existing" },
  { value: "did_only", label: "DID-only (no wallet)" },
];

export default function MintAgentStepIdentity({
  state,
  agents,
  onChange,
}: MintAgentStepIdentityProps): JSX.Element {
  const didPreview = previewDid(state.pendingAgentId);
  const allowsWallet = roleAllowsWalletCustody(state.role);

  const handleAvailable = isHandleAvailable(
    state.handle,
    agents,
    state.duplicateFromAgentId,
  );

  const handleDisplayNameBlur = () => {
    if (state.handle.trim()) return;
    onChange({ handle: suggestHandle(state.displayName, state.role) });
  };

  return (
    <div className="mint-agent-step">
      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label" htmlFor="mint-name">
          Name tag
        </label>
        <input
          id="mint-name"
          className="form-input"
          value={state.displayName}
          onChange={(e) => onChange({ displayName: e.target.value })}
          onBlur={handleDisplayNameBlur}
          placeholder="Alpha Arb v3"
        />
      </div>

      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label" htmlFor="mint-handle">
          Handle
        </label>
        <input
          id="mint-handle"
          className="form-input"
          value={state.handle}
          onChange={(e) => onChange({ handle: e.target.value })}
          placeholder="arb_alpha_v3"
        />
        {state.handle.trim() ? (
          <p
            className={`transfer-field-hint${
              handleAvailable ? " transfer-field-ok" : " transfer-field-error"
            }`}
          >
            {handleAvailable ? "✓ available" : "Handle already in use"}
          </p>
        ) : null}
      </div>

      <fieldset className="mint-agent-fieldset">
        <legend className="terminal-label transfer-field-label">Custody</legend>
        <div className="mint-agent-radio-group">
          {CUSTODY_OPTIONS.filter((option) =>
            allowsWallet ? true : option.value === "did_only",
          ).map((option) => (
            <label key={option.value} className="mint-agent-radio">
              <input
                type="radio"
                name="mint-custody"
                checked={state.custodyMode === option.value}
                onChange={() => onChange({ custodyMode: option.value })}
              />
              <span>{option.label}</span>
            </label>
          ))}
        </div>
      </fieldset>

      {state.custodyMode === "link_existing" ? (
        <div className="transfer-field-group">
          <label className="terminal-label transfer-field-label" htmlFor="mint-wallet">
            Wallet address
          </label>
          <input
            id="mint-wallet"
            className="form-input"
            value={state.linkedWalletAddress}
            onChange={(e) => onChange({ linkedWalletAddress: e.target.value })}
            placeholder="0x…"
          />
        </div>
      ) : null}

      <div className="mint-agent-did-preview">
        <span className="terminal-label">KYA DID</span>
        <span className="terminal-value">{didPreview}</span>
        <span className="transfer-field-hint terminal-text-muted">
          · minted on confirm
        </span>
      </div>
    </div>
  );
}
