import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";
import { useNavigate } from "react-router-dom";

import {
  GridViewerLayout,
  GRID_COLS,
  VaultFiltersBar,
  VaultFiltersSheet,
  VaultHeroHeader,
  VaultListingTable,
  VaultTopPickSpotlight,
  VaultTvlCard,
  CreateVaultModal,
  type CreateVaultTourPrefill,
} from "../components";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import {
  applyVaultListLayoutSizing,
  buildVaultListResponsiveLayoutConfig,
  generateVaultListResponsiveLayouts,
  VAULT_LIST_LAYOUT_MARGIN,
  VAULT_LIST_ROW_HEIGHT,
} from "../configs/vaultListLayoutConfig";
import {
  hasActiveVaultListingFilters,
  useVaultListingData,
} from "../hooks/useVaultListingData";
import { useOwnedUserVaults } from "../hooks/vaultOwnership";
import { useOnboard } from "../hooks/useOnboard";
import { useVaultOperate } from "../context/VaultOperateContext";
import { tradeVaultPath } from "../routes";
import { isWalletConnected } from "../utils/walletConnection";
import { ensureVaultRegistryHydrated } from "../../offline/mock_data/vaultCatalog";
import { ensureVaultUserStateSeeded } from "../../offline/mock_data/vaultUserState";
import {
  CREATE_VAULT_TOUR_DEMO_VAULT_ID,
} from "../tutorials/create-vault-tour/constants";
import { useOptionalCreateVaultTour } from "../tutorials/create-vault-tour";
import "./VaultListPage.css";
import "../components/vault/vault.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [VAULT_LIST_LAYOUT_MARGIN, VAULT_LIST_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = VAULT_LIST_ROW_HEIGHT;

const MOBILE_FILTER_BREAKPOINTS = new Set(["xs", "xxs"]);

function buildLayouts(viewportHeight?: number, smFiltersExpanded = false) {
  const base = buildVaultListResponsiveLayoutConfig();
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyVaultListLayoutSizing(base, height, smFiltersExpanded);
  return generateVaultListResponsiveLayouts(sized, 0);
}

export default function VaultListPage(): JSX.Element {
  const { walletAddress } = useOnboard();
  const navigate = useNavigate();
  const { enterOperate } = useVaultOperate();
  const createVaultTour = useOptionalCreateVaultTour();
  const registerOpenCreateVault = createVaultTour?.registerOpenCreateVault;
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() => buildLayouts());
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const [createOpen, setCreateOpen] = useState(false);
  const [filtersSheetOpen, setFiltersSheetOpen] = useState(false);
  const [tourPrefill, setTourPrefill] = useState<CreateVaultTourPrefill | null>(
    null,
  );
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);

  const walletConnected = isWalletConnected(walletAddress);
  const listing = useVaultListingData(walletAddress);
  const isMobileFilters = MOBILE_FILTER_BREAKPOINTS.has(currentBreakpoint);
  const filtersActive = hasActiveVaultListingFilters(listing);
  const ownedUserVaults = useOwnedUserVaults(walletAddress);
  const ownedUserVaultCount = ownedUserVaults.length;

  const smFiltersTwoRow = useMemo(
    () =>
      currentBreakpoint === "sm" &&
      walletConnected &&
      listing.investedVaultCount > 0 &&
      ownedUserVaultCount > 0,
    [
      currentBreakpoint,
      walletConnected,
      listing.investedVaultCount,
      ownedUserVaultCount,
    ],
  );

  const { setMyVaultsOnly, setPage, myVaultsOnly, setFilterKey, filterKey } =
    listing;

  const handleMyVaultsToggle = useCallback(() => {
    setMyVaultsOnly((active) => {
      if (!active) {
        setFilterKey("all");
      }
      return !active;
    });
    setPage(0);
  }, [setMyVaultsOnly, setFilterKey, setPage]);

  const handleInvestedToggle = useCallback(() => {
    const activating = filterKey !== "deposited";
    setFilterKey(activating ? "deposited" : "all");
    if (activating) {
      setMyVaultsOnly(false);
    }
    setPage(0);
  }, [filterKey, setFilterKey, setMyVaultsOnly, setPage]);

  useEffect(() => {
    if (ownedUserVaultCount === 0 && myVaultsOnly) {
      setMyVaultsOnly(false);
    }
  }, [ownedUserVaultCount, myVaultsOnly, setMyVaultsOnly]);

  useEffect(() => {
    if (listing.investedVaultCount === 0 && filterKey === "deposited") {
      setFilterKey("all");
    }
  }, [listing.investedVaultCount, filterKey, setFilterKey]);

  useEffect(() => {
    if (!isMobileFilters) {
      setFiltersSheetOpen(false);
    }
  }, [isMobileFilters]);

  useEffect(() => {
    ensureVaultRegistryHydrated();
    if (walletAddress.trim()) {
      ensureVaultUserStateSeeded(walletAddress);
    }
  }, [walletAddress]);

  useEffect(() => {
    if (!registerOpenCreateVault) return;
    return registerOpenCreateVault((prefill) => {
      setTourPrefill(prefill);
      setCreateOpen(true);
    });
  }, [registerOpenCreateVault]);

  const handleCloseCreateModal = useCallback(() => {
    setCreateOpen(false);
    setTourPrefill(null);
  }, []);

  const handleOpenCreateVault = useCallback(() => {
    setCreateOpen(true);
  }, []);

  const handleOperateVault = useCallback(
    (vaultId: string) => {
      if (enterOperate(vaultId)) {
        navigate(tradeVaultPath(vaultId));
      }
    },
    [enterOperate, navigate],
  );

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(window.innerHeight, smFiltersTwoRow);
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };
    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, [smFiltersTwoRow]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const handleOpenFiltersSheet = useCallback(() => {
    setFiltersSheetOpen(true);
  }, []);

  const handleCloseFiltersSheet = useCallback(() => {
    setFiltersSheetOpen(false);
  }, []);

  const filterPanelProps = useMemo(
    () => ({
      sortKey: listing.sortKey,
      onSortChange: listing.setSortKey,
      filterKey: listing.filterKey,
      onFilterChange: listing.setFilterKey,
      timeframe: listing.timeframe,
      onTimeframeChange: listing.setTimeframe,
      searchQuery: listing.searchQuery,
      onSearchChange: listing.setSearchQuery,
      onCreateVault: walletConnected ? handleOpenCreateVault : undefined,
      investedVaultCount: listing.investedVaultCount,
      investedOnly: listing.filterKey === "deposited",
      onInvestedToggle: walletConnected ? handleInvestedToggle : undefined,
      ownedVaultCount: ownedUserVaultCount,
      myVaultsOnly,
      onMyVaultsToggle: handleMyVaultsToggle,
    }),
    [
      listing,
      walletConnected,
      handleOpenCreateVault,
      handleInvestedToggle,
      ownedUserVaultCount,
      myVaultsOnly,
      handleMyVaultsToggle,
    ],
  );

  const slotContent = useMemo(
    () => [
      <VaultHeroHeader
        key="hero"
        height={slotDimensions[0]?.height}
        showMobileActions={isMobileFilters}
        onOpenFilters={isMobileFilters ? handleOpenFiltersSheet : undefined}
        onCreateVault={
          isMobileFilters && walletConnected ? handleOpenCreateVault : undefined
        }
        filtersActive={filtersActive}
        filtersSheetOpen={filtersSheetOpen}
      />,
      <VaultTvlCard
        key="tvl"
        height={slotDimensions[1]?.height}
        walletAddress={walletAddress}
      />,
      <VaultTopPickSpotlight
        key="spotlight"
        height={slotDimensions[2]?.height}
      />,
      isMobileFilters ? null : (
        <VaultFiltersBar
          key="filters"
          height={slotDimensions[3]?.height}
          twoRow={smFiltersTwoRow}
          {...filterPanelProps}
        />
      ),
      <VaultListingTable
        key="table"
        height={slotDimensions[4]?.height ?? "100%"}
        protocolVaults={listing.protocolVaults}
        paginatedUserVaults={listing.paginatedUserVaults}
        totalUserCount={listing.totalUserCount}
        page={listing.page}
        pageSize={listing.pageSize}
        onPageChange={listing.setPage}
        onPageSizeChange={listing.setPageSize}
        onOperateVault={handleOperateVault}
      />,
      null,
      null,
      null,
      null,
    ],
    [
      slotDimensions,
      listing,
      walletAddress,
      isMobileFilters,
      filtersSheetOpen,
      filtersActive,
      filterPanelProps,
      handleOpenFiltersSheet,
      handleOperateVault,
      walletConnected,
      handleOpenCreateVault,
      smFiltersTwoRow,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--vault-list">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
      />
      {isMobileFilters ? (
        <VaultFiltersSheet
          isOpen={filtersSheetOpen}
          onClose={handleCloseFiltersSheet}
          {...filterPanelProps}
          onCreateVault={undefined}
        />
      ) : null}
      <CreateVaultModal
        isOpen={createOpen && walletConnected}
        onClose={handleCloseCreateModal}
        walletAddress={walletAddress}
        tourActive={createVaultTour?.runTour ?? false}
        tourPrefill={tourPrefill ?? undefined}
        tourForcedVaultId={
          createVaultTour?.runTour ? CREATE_VAULT_TOUR_DEMO_VAULT_ID : undefined
        }
      />
    </div>
  );
}
