import React from "react";

import {
  BASE_AGENT_ALLOCATION_MB,
  DEFAULT_TOP_UP_MB,
} from "../../../store/memoryPoolStore";
import type { MintAgentWizardState } from "../../../utils/mintAgent";
import {
  deriveMarketSymbol,
  formatMemoryMeter,
  projectedReservedAfterMint,
} from "../../../utils/mintAgent";

export interface MintAgentStepMemoryProps {
  state: MintAgentWizardState;
  poolMb: number;
  reservedMb: number;
  canMint: boolean;
  onTopUp: () => void;
}

export default function MintAgentStepMemory({
  state,
  poolMb,
  reservedMb,
  canMint,
  onTopUp,
}: MintAgentStepMemoryProps): JSX.Element {
  const marketSymbol = deriveMarketSymbol(
    `did:morpheum:agent:${state.pendingAgentId}`,
  );
  const projected = projectedReservedAfterMint(reservedMb);
  const fillPct = Math.min(100, Math.round((reservedMb / poolMb) * 100));
  const projectedPct = Math.min(100, Math.round((projected / poolMb) * 100));

  return (
    <div className="mint-agent-step">
      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label">Market symbol</label>
        <div className="mint-agent-locked-field">
          <span className="terminal-value">{marketSymbol}</span>
          <span className="mint-agent-lock-icon" aria-hidden>
            🔒
          </span>
        </div>
        <p className="transfer-field-hint terminal-text-muted">
          Custom ticker unlocks after liquidity-proof graduation.
        </p>
      </div>

      <div className="mint-agent-memory-block">
        <div className="mint-agent-memory-head">
          <span className="terminal-label">On-chain memory</span>
          <span className="terminal-value">
            Reserved {formatMemoryMeter(reservedMb, poolMb)}
          </span>
        </div>
        <div
          className="mint-agent-memory-meter"
          role="progressbar"
          aria-valuenow={fillPct}
          aria-valuemin={0}
          aria-valuemax={100}
        >
          <span
            className="mint-agent-memory-meter-fill"
            style={{ width: `${fillPct}%` }}
          />
          <span
            className="mint-agent-memory-meter-projected"
            style={{ width: `${projectedPct}%` }}
          />
        </div>
        <p className="terminal-value mint-agent-memory-after">
          This agent ≈ {BASE_AGENT_ALLOCATION_MB} MB → {projected} / {poolMb} MB
          after mint
        </p>
        <p className="transfer-field-hint terminal-text-muted">
          Paid in MORM from the master account pool.
        </p>
      </div>

      {!canMint ? (
        <div className="mint-agent-memory-warning" role="alert">
          <p className="mint-agent-memory-warning-title">
            Not enough on-chain memory
          </p>
          <p className="transfer-field-hint">
            Pool {formatMemoryMeter(reservedMb, poolMb)} used · need ≈{" "}
            {BASE_AGENT_ALLOCATION_MB} MB for this agent.
          </p>
          <button type="button" className="btn btn-secondary" onClick={onTopUp}>
            Top up memory (MORM) +{DEFAULT_TOP_UP_MB} MB
          </button>
        </div>
      ) : null}
    </div>
  );
}
