import React from "react";

import type { VaultBucketSummary, VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import { formatVaultTvl } from "../../../offline/mock_data/vaultCatalog";
import { formatCurrency } from "../../sdk/utils/display";
import { formatPct } from "./vaultPortfolioMetrics";
import { VAULT_TOUR_TARGETS } from "../../tutorials/vault-tour/constants";
import "./vault.css";

export interface VaultBucketKpiStripProps {
  height?: string;
  vault: VaultRecord;
  bucket: VaultBucketSummary;
}

export default function VaultBucketKpiStrip({
  height = "100%",
  vault: _vault,
  bucket,
}: VaultBucketKpiStripProps): JSX.Element {
  const isIsolated = bucket.mode === "isolated";

  return (
    <div
      className="vault-slot vault-slot--flush vault-bucket-kpi-slot"
      style={{ height }}
      data-tour={VAULT_TOUR_TARGETS.bucketKpi}
    >
      <div className="vault-bucket-kpi-strip">
        <div className="vault-stat-card">
          <p className="vault-stat-label">Bucket Equity</p>
          <p className="vault-stat-value">{formatVaultTvl(bucket.equityUsd)}</p>
        </div>
        <div className="vault-stat-card">
          <p className="vault-stat-label">Risk Ratio</p>
          <p className="vault-stat-value">
            {bucket.riskRatio.toFixed(2)} ·{" "}
            {bucket.riskHealth === "healthy" ? "Healthy" : bucket.riskHealth}
          </p>
        </div>
        <div className="vault-stat-card">
          <p className="vault-stat-label">Margin Usage</p>
          <p className="vault-stat-value">{bucket.marginUsagePct}%</p>
        </div>
        {isIsolated ? (
          <div className="vault-stat-card">
            <p className="vault-stat-label">Liq. Price (distance)</p>
            <p className="vault-stat-value">
              {bucket.liqPriceUsd?.toLocaleString() ?? "—"} (
              {bucket.liqDistancePct ?? "—"}% away)
            </p>
          </div>
        ) : (
          <div className="vault-stat-card">
            <p className="vault-stat-label">Net Exposure</p>
            <p className="vault-stat-value">
              {bucket.netExposureLabel === "Low"
                ? `+${formatVaultTvl(100_000)} (Long)`
                : bucket.netExposureLabel}
            </p>
          </div>
        )}
        <div className="vault-stat-card">
          <p className="vault-stat-label">Unrealized PnL</p>
          <p className="vault-stat-value">
            {bucket.pnlUsd >= 0 ? "+" : ""}
            {formatCurrency(bucket.pnlUsd)}
          </p>
        </div>
        <div className="vault-stat-card">
          <p className="vault-stat-label">Funding</p>
          <p className="vault-stat-value">
            {bucket.fundingPnlUsd >= 0 ? "+" : ""}
            {formatCurrency(bucket.fundingPnlUsd)} · {formatPct(bucket.fundingAprPct, 0)} APR
          </p>
        </div>
      </div>
    </div>
  );
}
