import React, { useMemo, useState } from "react";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import {
  buildVaultAccountValueSeed,
  buildVaultPerfChartData,
  buildVaultPnlSeed,
  type VaultPerfTimeframe,
} from "../../../offline/mock_data/vaultPerfChartData";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import PortfolioLeftAxisTimeSeriesChart from "../portfolio/PortfolioLeftAxisTimeSeriesChart";
import PortfolioTimeSeriesChart from "../portfolio/PortfolioTimeSeriesChart";
import { TabLayoutHeaderToolBar, buildToolbarTabs, VAULT_PERF_CHART_STRIP } from "../smartlayout";
import VaultDetailPerfSummary from "./VaultDetailPerfSummary";
import { VAULT_TOUR_TARGETS } from "../../tutorials/vault-tour/constants";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import "./vault.css";

type ChartTab = "accountValue" | "pnl";

const FOCUS_COLOR = TERMINAL_COLORS.brand;

export interface VaultDetailPerfChartPanelProps {
  height?: string;
  vault: VaultRecord;
}

export default function VaultDetailPerfChartPanel({
  height = "100%",
  vault,
}: VaultDetailPerfChartPanelProps): JSX.Element {
  const [activeTab, setActiveTab] = useState<ChartTab>("pnl");
  const [timeframe, setTimeframe] = useState<VaultPerfTimeframe>("all");

  const accountValueData = useMemo(() => {
    const seed = buildVaultAccountValueSeed(vault, timeframe);
    return buildVaultPerfChartData(seed);
  }, [vault, timeframe]);

  const pnlData = useMemo(() => {
    const seed = buildVaultPnlSeed(vault, timeframe);
    return buildVaultPerfChartData(seed);
  }, [vault, timeframe]);

  const periodPnlUsd = useMemo(() => {
    const seed = buildVaultPnlSeed(vault, timeframe);
    if (seed.length === 0) return 0;
    return seed[seed.length - 1] ?? 0;
  }, [vault, timeframe]);

  const chartSeries = useMemo(() => {
    if (activeTab === "accountValue") {
      return [
        {
          id: "account-value",
          data: accountValueData,
          color: FOCUS_COLOR,
        },
      ];
    }

    return [
      {
        id: "vault-pnl",
        data: pnlData,
        color: FOCUS_COLOR,
      },
    ];
  }, [activeTab, accountValueData, pnlData]);

  const ChartComponent =
    activeTab === "pnl"
      ? PortfolioLeftAxisTimeSeriesChart
      : PortfolioTimeSeriesChart;

  return (
    <div
      className="vault-slot vault-detail-tab-section vault-detail-perf-section"
      style={{ height }}
      aria-label={`${vault.name} vault performance and chart`}
      data-tour={VAULT_TOUR_TARGETS.detailPerf}
    >
      <div className="layout-container tab-section-root vault-detail-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={buildToolbarTabs(VAULT_PERF_CHART_STRIP)}
          activeTabId={activeTab}
          onTabChange={(id) => setActiveTab(id as ChartTab)}
        />

        <div className="tab-section-content">
          <div className="vault-detail-perf-body">
            <VaultDetailPerfSummary
              vault={vault}
              periodPnlUsd={periodPnlUsd}
              timeframeLabel={timeframe}
            />
            <ChartComponent
              series={chartSeries}
              variant="area"
              className="vault-detail-perf-chart"
              emptyMessage={`No ${activeTab === "accountValue" ? "account value" : "PNL"} data`}
            />
            <div className="vault-timeframe-pills" role="group" aria-label="Chart timeframe">
              {(["30d", "90d", "all"] as const).map((tf) => (
                <button
                  key={tf}
                  type="button"
                  className={`vault-timeframe-pill${timeframe === tf ? " is-active" : ""}`}
                  onClick={() => setTimeframe(tf)}
                  aria-pressed={timeframe === tf}
                >
                  {tf === "all" ? "All" : tf}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
