import React, { useEffect, useMemo, useState } from "react";

import type { StakingActivityRow } from "../../../offline/mock_data/stakingMockData.types";
import type { StakingPendingUnstakeRow } from "../../../offline/mock_data/stakingMockData.types";
import { TabLayoutHeaderToolBar } from "../smartlayout/tab-layout-header-toolbar";
import StakingActivityTable from "./StakingActivityTable";
import StakingPendingUnstakesTable from "./StakingPendingUnstakesTable";
import StakingRewardsPanel from "./StakingRewardsPanel";
import StakingValidatorsPanel from "./StakingValidatorsPanel";
import "../tables/TabSection.css";
import "./staking.css";

export type StakingTabId =
  | "rewards"
  | "activity"
  | "pending"
  | "delegate";

export interface StakingTabSectionProps {
  height?: string;
  activity: StakingActivityRow[];
  pendingUnstakes: StakingPendingUnstakeRow[];
  usdcYieldPaidToDate: number;
  claimableUsdc: number;
  enableUsdcYield: boolean;
  enableDelegation: boolean;
  walletAddress?: string;
  stakedMorm?: number;
  onDelegateSuccess?: () => void;
  onClaim?: () => void;
  suppressWalletGate?: boolean;
  defaultTab?: StakingTabId;
}

function resolveInitialStakingTab(
  defaultTab: StakingTabId,
  enableDelegation: boolean,
): StakingTabId {
  if (defaultTab === "delegate" && !enableDelegation) {
    return "activity";
  }
  return defaultTab;
}

function StakingTabSection({
  height = "100%",
  activity,
  pendingUnstakes,
  usdcYieldPaidToDate,
  claimableUsdc,
  enableUsdcYield,
  enableDelegation,
  walletAddress = "",
  stakedMorm = 0,
  onDelegateSuccess,
  onClaim,
  suppressWalletGate = false,
  defaultTab = "delegate",
}: StakingTabSectionProps): JSX.Element {
  const [activeTab, setActiveTab] = useState<StakingTabId>(() =>
    resolveInitialStakingTab(defaultTab, enableDelegation),
  );

  useEffect(() => {
    if (!enableDelegation && activeTab === "delegate") {
      setActiveTab("activity");
    }
  }, [activeTab, enableDelegation]);

  const tabs = useMemo(() => {
    const base: Array<{
      id: StakingTabId;
      label: string;
      badgeCount?: number;
    }> = [
      { id: "rewards", label: "Rewards" },
      { id: "activity", label: "Activity" },
      {
        id: "pending",
        label: "Pending Unstakes",
        badgeCount: pendingUnstakes.length || undefined,
      },
    ];
    if (enableDelegation) {
      base.push({ id: "delegate", label: "Delegate" });
    }
    return base;
  }, [enableDelegation, pendingUnstakes.length]);

  return (
    <div
      className={`staking-tab-section tab-section-root${suppressWalletGate ? " tab-section-root--disconnected" : ""}`}
      style={{ height }}
    >
      <TabLayoutHeaderToolBar
        tabs={tabs}
        activeTabId={activeTab}
        onTabChange={(id) => setActiveTab(id as StakingTabId)}
      />
      <div className="staking-tab-body">
        {!suppressWalletGate && activeTab === "rewards" ? (
          <StakingRewardsPanel
            usdcYieldPaidToDate={usdcYieldPaidToDate}
            claimableUsdc={claimableUsdc}
            enableUsdcYield={enableUsdcYield}
            onClaim={onClaim}
          />
        ) : null}
        {!suppressWalletGate && activeTab === "activity" ? (
          <StakingActivityTable rows={activity} height="100%" />
        ) : null}
        {!suppressWalletGate && activeTab === "pending" ? (
          <StakingPendingUnstakesTable rows={pendingUnstakes} height="100%" />
        ) : null}
        {!suppressWalletGate && activeTab === "delegate" ? (
          <StakingValidatorsPanel
            height="100%"
            walletAddress={walletAddress}
            stakedMorm={stakedMorm}
            onSuccess={onDelegateSuccess}
          />
        ) : null}
      </div>
    </div>
  );
}

export default React.memo(StakingTabSection);
