import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";

import type { StakingValidatorRow } from "../../../offline/mock_data/stakingValidators.types";
import { getTotalDelegatedMorm } from "../../../offline/mock_data";
import { useStakingDelegateSubmit } from "../../hooks/useStakingDelegateSubmit";
import type { StakingDelegateMode } from "../../utils/executeOfflineDelegateFunds";
import { useOverlayContentLatch } from "../tables/useBucketModalOverlay";
import ModalHeader from "../ui/ModalHeader";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import { ModalTabBar, type ModalTab } from "../smartlayout/modal-tab-bar";
import {
  formatStakingMormAmount,
  formatValidatorPct,
  formatValidatorStake,
  formatYourStake,
} from "./stakingFormat";
import "../smartlayout/layout.css";
import "./staking.css";

const DELEGATE_MODE_TABS = [
  { id: "delegate", label: "Delegate" },
  { id: "undelegate", label: "Undelegate" },
] as const satisfies readonly ModalTab<StakingDelegateMode>[];

function parseAmountInput(value: string): number {
  const parsed = Number.parseFloat(value.replace(/,/g, ""));
  return Number.isFinite(parsed) ? parsed : 0;
}

function ValidatorDetailRow({
  label,
  value,
  title,
}: {
  label: string;
  value: React.ReactNode;
  title?: string;
}): JSX.Element {
  return (
    <div className="staking-delegate-modal-row">
      <dt className="terminal-label">{label}</dt>
      <dd className="terminal-value" title={title}>
        {value}
      </dd>
    </div>
  );
}

export interface StakingDelegateModalProps {
  isOpen: boolean;
  onClose: () => void;
  validator: StakingValidatorRow | null;
  walletAddress: string;
  stakedMorm: number;
  initialMode?: StakingDelegateMode;
  onSuccess?: () => void;
}

function StakingDelegateModal({
  isOpen,
  onClose,
  validator,
  walletAddress,
  stakedMorm,
  initialMode = "delegate",
  onSuccess,
}: StakingDelegateModalProps): JSX.Element | null {
  const latchValue = isOpen && validator ? validator : null;
  const { latched, clearLatch } = useOverlayContentLatch(isOpen, latchValue);

  const handleAfterUnmount = useCallback(() => {
    clearLatch();
  }, [clearLatch]);

  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen, { onAfterUnmount: handleAfterUnmount });
  const isClosing = mounted && !isOpen;
  const displayValidator = latched ?? validator;

  const [mode, setMode] = useState<StakingDelegateMode>(initialMode);
  const [amountInput, setAmountInput] = useState("");

  useOverlayEscapeKey(isOpen && !isClosing, onClose);

  useEffect(() => {
    if (!isOpen) return;
    setMode(initialMode);
    setAmountInput("");
  }, [initialMode, isOpen, displayValidator?.validatorId]);

  const amount = useMemo(() => parseAmountInput(amountInput), [amountInput]);
  const yourStakeMorm = displayValidator?.yourStakeMorm ?? 0;
  const validatorActive = displayValidator?.status === "active";

  const { ctaLabel, ctaDisabled, isSubmitting, available, handlePrimaryClick } =
    useStakingDelegateSubmit({
      mode,
      amount,
      stakedMorm,
      walletAddress,
      validatorId: displayValidator?.validatorId ?? "",
      validatorName: displayValidator?.name ?? "Validator",
      validatorActive,
      yourStakeMorm,
      onSuccess: () => {
        setAmountInput("");
        onSuccess?.();
        onClose();
      },
    });

  const handleMax = () => {
    setAmountInput(String(available));
  };

  const delegateZeroHint = useMemo(() => {
    if (mode !== "delegate" || available > 0) return null;
    if (stakedMorm <= 0) {
      return "Stake MORM first — delegation uses staked balance, not wallet MORM.";
    }
    if (getTotalDelegatedMorm(walletAddress) >= stakedMorm) {
      return "All staked MORM is already assigned to validators.";
    }
    return null;
  }, [available, mode, stakedMorm, walletAddress]);

  if (!mounted || !displayValidator) return null;

  const modalContent = (
    <StaggeredOverlayRoot passThrough={!isOpen}>
      <StaggeredOverlayBackdrop
        visible={backdropVisible && isOpen}
        onClose={isSubmitting ? () => {} : onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={`modal-content staking-funds-modal-content staggered-overlay-panel--scale${isClosing ? " bucket-modal-panel--closing" : ""}`}
        aria-label={mode === "delegate" ? "Delegate MORM" : "Undelegate MORM"}
      >
        <ModalHeader
          onClose={onClose}
          closeDisabled={isClosing || isSubmitting}
          leading={<h3 className="terminal-panel-title">Delegate MORM</h3>}
        />

        <ModalTabBar
          tabs={DELEGATE_MODE_TABS}
          activeTabId={mode}
          onTabChange={(id) => {
            setMode(id);
            setAmountInput("");
          }}
          disabled={isClosing || isSubmitting}
          aria-label="Delegate or undelegate"
        />

        <div className="modal-body">
          <section
            className="staking-delegate-modal-validator"
            aria-label="Validator details"
          >
            <p className="staking-delegate-modal-validator-name">
              {displayValidator.name}
            </p>
            {displayValidator.description ? (
              <p
                className="staking-delegate-modal-validator-description terminal-label"
                title={displayValidator.description}
              >
                {displayValidator.description}
              </p>
            ) : null}
            <dl className="staking-delegate-modal-grid">
              <ValidatorDetailRow
                label="Total stake"
                value={`${formatValidatorStake(displayValidator.stakeMorm)} MORM`}
              />
              <ValidatorDetailRow
                label="Your stake"
                value={
                  displayValidator.yourStakeMorm != null &&
                  displayValidator.yourStakeMorm > 0
                    ? `${formatYourStake(displayValidator.yourStakeMorm)} MORM`
                    : formatYourStake(displayValidator.yourStakeMorm)
                }
              />
              <ValidatorDetailRow
                label="Uptime"
                value={formatValidatorPct(displayValidator.uptimePct)}
              />
              <ValidatorDetailRow
                label="Est. APR"
                value={formatValidatorPct(displayValidator.estAprPct)}
              />
              <ValidatorDetailRow
                label="Commission"
                value={formatValidatorPct(displayValidator.commissionPct)}
              />
              <ValidatorDetailRow
                label="Status"
                value={
                  <span
                    className={`staking-validator-status staking-validator-status--${displayValidator.status}`}
                  >
                    {displayValidator.status === "active" ? "Active" : "Inactive"}
                  </span>
                }
              />
            </dl>
          </section>

          <label className="terminal-label" htmlFor="staking-delegate-amount">
            Amount
          </label>
          <div className="staking-amount-row">
            <input
              id="staking-delegate-amount"
              className="form-input staking-amount-input"
              value={amountInput}
              onChange={(event) => setAmountInput(event.target.value)}
              inputMode="decimal"
              placeholder="0"
              disabled={isClosing || isSubmitting}
            />
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleMax}
              disabled={isClosing || isSubmitting || available <= 0}
            >
              MAX
            </button>
          </div>

          <p className="terminal-label">
            {mode === "delegate"
              ? "Undelegated staked balance"
              : "Available to undelegate"}
            : {formatStakingMormAmount(available)} MORM
          </p>

          {delegateZeroHint ? (
            <p className="staking-notice-line">{delegateZeroHint}</p>
          ) : null}

          <p className="staking-notice-line">
            {mode === "delegate"
              ? "Delegated stake stays in your position and accrues validator rewards."
              : "MORM returns to your undelegated staked balance."}
          </p>
        </div>

        <div className="modal-footer">
          <button
            type="button"
            className="btn btn-primary"
            disabled={isClosing || ctaDisabled}
            onClick={handlePrimaryClick}
          >
            {ctaLabel}
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return createPortal(modalContent, document.body);
}

export default React.memo(StakingDelegateModal);
