import { useMemo } from "react";
import { useVaultActivity } from "./useVaultActivity";
import type { VaultFundingRow, VaultTradeFill } from "../../offline/mock_data/vaultMockData.types";

function activityRowToTradeFill(row: {
  vaultId: string;
  bucketId?: string;
  time: number;
  market: string;
  side: string;
  size: number | null;
  price: number | null;
  fee: number | null;
  realizedPnl: number | null;
}): VaultTradeFill | null {
  if (!row.bucketId || row.size == null || row.price == null || row.fee == null) {
    return null;
  }
  const sideLower = row.side.toLowerCase();
  const side: "B" | "A" =
    sideLower.includes("short") && sideLower.startsWith("open")
      ? "A"
      : sideLower.includes("long") && sideLower.startsWith("open")
        ? "B"
        : sideLower.includes("close long")
          ? "A"
          : sideLower.includes("close short")
            ? "B"
            : "B";
  return {
    vaultId: row.vaultId,
    bucketId: row.bucketId,
    address: "",
    time: row.time,
    coin: row.market,
    dir: row.side,
    side,
    size: row.size,
    price: row.price,
    fee: row.fee,
    closedPnl: row.realizedPnl ?? 0,
  };
}

export function useVaultTradeHistory(
  vaultId: string,
  bucketId?: string,
): VaultTradeFill[] {
  const rows = useVaultActivity(vaultId, {
    bucketId,
    types: ["perp"],
  });

  return useMemo(
    () =>
      rows
        .map(activityRowToTradeFill)
        .filter((row): row is VaultTradeFill => row != null),
    [rows],
  );
}

function activityRowToFundingRow(row: {
  vaultId: string;
  bucketId?: string;
  time: number;
  market: string;
  side: string;
  size: number | null;
  realizedPnl: number | null;
}): VaultFundingRow | null {
  if (!row.bucketId || row.size == null || row.realizedPnl == null) {
    return null;
  }
  const payout = row.realizedPnl;
  const positionSide = row.side === "Pay" ? "Short" : "Long";
  return {
    vaultId: row.vaultId,
    bucketId: row.bucketId,
    address: "",
    time: new Date(row.time).toISOString(),
    symbol: row.market.replace(/-PERP$/i, "-USDT"),
    side: positionSide,
    positionSize: row.size,
    payout,
    rate: 0,
  };
}

export function useVaultFundingHistory(
  vaultId: string,
  bucketId?: string,
): VaultFundingRow[] {
  const rows = useVaultActivity(vaultId, {
    bucketId,
    types: ["funding"],
  });

  return useMemo(
    () =>
      rows
        .map(activityRowToFundingRow)
        .filter((row): row is VaultFundingRow => row != null),
    [rows],
  );
}
