import { useMemo, useSyncExternalStore } from "react";
import { getBucketPositions, getVaultBuckets } from "../../offline/mock_data/vaultCatalog";
import type { VaultPositionRow } from "../../offline/mock_data/vaultCatalog";
import {
  getVaultOperateStateRevision,
  mergeVaultPositions,
  subscribeVaultOperateState,
} from "../../offline/mock_data/vaultOperateState";

export type VaultPositionWithBucket = VaultPositionRow & {
  vaultBucketId: string;
};

export function useVaultPositions(
  vaultId: string,
  bucketId?: string,
): VaultPositionWithBucket[] {
  const revision = useSyncExternalStore(
    subscribeVaultOperateState,
    getVaultOperateStateRevision,
    getVaultOperateStateRevision,
  );

  return useMemo(() => {
    void revision;
    if (!vaultId) return [];

    if (bucketId) {
      const base = getBucketPositions(vaultId, bucketId);
      return mergeVaultPositions(base, vaultId, bucketId).map((row) => ({
        ...row,
        vaultBucketId: bucketId,
      }));
    }

    return getVaultBuckets(vaultId).flatMap((bucket) => {
      const base = getBucketPositions(vaultId, bucket.id);
      return mergeVaultPositions(base, vaultId, bucket.id).map((row) => ({
        ...row,
        vaultBucketId: bucket.id,
      }));
    });
  }, [vaultId, bucketId, revision]);
}
