/**
 * Vault fee model — types, Standard preset defaults, and resolver helpers.
 */

export type VaultFeePreset = "standard" | "premium" | "protocol";

export type VaultVisibility = "public" | "private";

export type VaultFeeCrystallization =
  | "withdrawal_and_monthly_if_profitable";

export type VaultFeeChangePolicy = "new_deposits_only";

export interface VaultFeeSplit {
  creatorPct: number;
  protocolPct: number;
  reservePct: number;
}

export interface VaultFeeModel {
  preset: VaultFeePreset;
  performanceFeePct: number;
  performanceFeeMinPct: number;
  performanceFeeMaxPct: number;
  managementFeePct: number;
  highWaterMarkEnabled: boolean;
  depositFeePct: number;
  withdrawalFeePct: number;
  crystallization: VaultFeeCrystallization;
  feeChangePolicy: VaultFeeChangePolicy;
  split: VaultFeeSplit;
}

export interface VaultFeeResolvable {
  feeModel?: VaultFeeModel;
  visibility?: VaultVisibility;
  kind?: "protocol" | "user";
}

export const STANDARD_PERFORMANCE_FEE_DEFAULT_PCT = 10;
export const STANDARD_PERFORMANCE_FEE_MIN_PCT = 5;
export const STANDARD_PERFORMANCE_FEE_MAX_PCT = 15;

export const DEFAULT_FEE_SPLIT: VaultFeeSplit = {
  creatorPct: 70,
  protocolPct: 20,
  reservePct: 10,
};

const FEE_EXAMPLE_DEPOSIT_USD = 10_000;
const FEE_EXAMPLE_EXIT_USD = 11_000;

export function isValidStandardPerformanceFee(pct: number): boolean {
  return (
    Number.isFinite(pct) &&
    pct >= STANDARD_PERFORMANCE_FEE_MIN_PCT &&
    pct <= STANDARD_PERFORMANCE_FEE_MAX_PCT
  );
}

export function buildStandardVaultFeeModel(
  performanceFeePct: number = STANDARD_PERFORMANCE_FEE_DEFAULT_PCT,
): VaultFeeModel {
  if (!isValidStandardPerformanceFee(performanceFeePct)) {
    throw new RangeError(
      `Performance fee must be between ${STANDARD_PERFORMANCE_FEE_MIN_PCT}% and ${STANDARD_PERFORMANCE_FEE_MAX_PCT}%`,
    );
  }

  return {
    preset: "standard",
    performanceFeePct,
    performanceFeeMinPct: STANDARD_PERFORMANCE_FEE_MIN_PCT,
    performanceFeeMaxPct: STANDARD_PERFORMANCE_FEE_MAX_PCT,
    managementFeePct: 0,
    highWaterMarkEnabled: true,
    depositFeePct: 0,
    withdrawalFeePct: 0,
    crystallization: "withdrawal_and_monthly_if_profitable",
    feeChangePolicy: "new_deposits_only",
    split: { ...DEFAULT_FEE_SPLIT },
  };
}

export function resolveVaultFeeModel(vault: VaultFeeResolvable): VaultFeeModel {
  if (vault.feeModel) {
    return vault.feeModel;
  }

  if (vault.kind === "protocol") {
    return {
      ...buildStandardVaultFeeModel(STANDARD_PERFORMANCE_FEE_DEFAULT_PCT),
      preset: "protocol",
    };
  }

  return buildStandardVaultFeeModel(STANDARD_PERFORMANCE_FEE_DEFAULT_PCT);
}

export function resolveVaultVisibility(vault: VaultFeeResolvable): VaultVisibility {
  return vault.visibility ?? "public";
}

export interface VaultFeeExample {
  depositUsd: number;
  exitUsd: number;
  grossProfitUsd: number;
  performanceFeeUsd: number;
  investorKeepsUsd: number;
  performanceFeePct: number;
}

export function computeFeeExample(
  performanceFeePct: number,
): VaultFeeExample {
  const grossProfitUsd = FEE_EXAMPLE_EXIT_USD - FEE_EXAMPLE_DEPOSIT_USD;
  const performanceFeeUsd = grossProfitUsd * (performanceFeePct / 100);
  const investorKeepsUsd = grossProfitUsd - performanceFeeUsd;

  return {
    depositUsd: FEE_EXAMPLE_DEPOSIT_USD,
    exitUsd: FEE_EXAMPLE_EXIT_USD,
    grossProfitUsd,
    performanceFeeUsd,
    investorKeepsUsd,
    performanceFeePct,
  };
}

export function formatFeeExampleSummary(
  performanceFeePct: number,
): string {
  const example = computeFeeExample(performanceFeePct);
  return (
    `If a depositor invests ${example.depositUsd.toLocaleString()} USDC and the vault grows to ${example.exitUsd.toLocaleString()} USDC, gross profit is ${example.grossProfitUsd.toLocaleString()} USDC. ` +
    `With a ${example.performanceFeePct}% performance fee, the fee is ${example.performanceFeeUsd.toLocaleString()} USDC and the investor keeps ${example.investorKeepsUsd.toLocaleString()} USDC. ` +
    `If the vault is recovering from a previous loss, no performance fee is charged until the depositor reaches a new high-water mark.`
  );
}
