import React, { useCallback } from "react";
import { Link } from "react-router-dom";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import { APP_ROUTES } from "../../routes";
import VaultDetailHeaderActions from "./VaultDetailHeaderActions";
import "./vault.css";

export interface VaultDetailHeaderProps {
  height?: string;
  vault: VaultRecord;
  isOwner?: boolean;
  onManageFunds?: () => void;
  onOperateVault?: () => void;
  /** lg/md: actions inline in header. sm–xxs: actions live in slot 5. */
  showActions?: boolean;
}

function truncateAddress(addr: string): string {
  if (addr.length <= 12) return addr;
  return `${addr.slice(0, 6)}..${addr.slice(-2)}`;
}

export default function VaultDetailHeader({
  height = "100%",
  vault,
  isOwner = false,
  onManageFunds,
  onOperateVault,
  showActions = true,
}: VaultDetailHeaderProps): JSX.Element {
  const copyAddress = useCallback(() => {
    void navigator.clipboard?.writeText(vault.leaderAddress);
  }, [vault.leaderAddress]);

  const eyebrow =
    vault.kind === "protocol"
      ? `PROTOCOL VAULT · ${vault.strategyLabel}`
      : `USER VAULT · ${vault.strategyLabel}`;

  return (
    <div className="vault-slot vault-slot--flush vault-detail-header" style={{ height }}>
      <div className="vault-detail-identity">
        <p className="eyebrow-text">{eyebrow}</p>
        <div
          className={`vault-detail-title-row${showActions ? "" : " vault-detail-title-row--identity-only"}`}
        >
          <div>
            <h1 className="vault-detail-title">{vault.name}</h1>
            <span className="vault-detail-address">
              {truncateAddress(vault.leaderAddress)}{" "}
              <button
                type="button"
                className="vault-table-footer-btn"
                onClick={copyAddress}
                aria-label="Copy address"
              >
                ⧉
              </button>
            </span>
          </div>
          {showActions ? (
            <VaultDetailHeaderActions
              inline
              isOwner={isOwner}
              onManageFunds={onManageFunds}
              onOperateVault={onOperateVault}
            />
          ) : null}
        </div>
      </div>
      <p className="vault-breadcrumb">
        <Link to={APP_ROUTES.vault}>Vaults</Link> › {vault.name}
      </p>
    </div>
  );
}
