import React from "react";

import {
  LEADERBOARD_TIMEFRAME_LABELS,
  type LeaderboardTimeframe,
} from "../../utils/leaderboardMetrics";
import { PORTFOLIO_TOOLBAR_SELECT_CLASS } from "../portfolio/portfolioToolbarSelect";
import "../portfolio/portfolio.css";
import "./leaderboard.css";

export interface LeaderboardToolbarProps {
  query: string;
  timeframe: LeaderboardTimeframe;
  onQueryChange: (value: string) => void;
  onTimeframeChange: (value: LeaderboardTimeframe) => void;
}

const TIMEFRAME_OPTIONS: LeaderboardTimeframe[] = ["all", "30d", "7d"];

function SearchIcon(): JSX.Element {
  return (
    <svg
      className="leaderboard-search-icon"
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden
    >
      <path
        d="M7.25 12.5a5.25 5.25 0 1 0 0-10.5 5.25 5.25 0 0 0 0 10.5Z"
        stroke="currentColor"
        strokeWidth="1.25"
      />
      <path
        d="M11.25 11.25 14 14"
        stroke="currentColor"
        strokeWidth="1.25"
        strokeLinecap="round"
      />
    </svg>
  );
}

export default function LeaderboardToolbar({
  query,
  timeframe,
  onQueryChange,
  onTimeframeChange,
}: LeaderboardToolbarProps): JSX.Element {
  return (
    <div className="leaderboard-toolbar">
      <div className="terminal-search-field leaderboard-search-field">
        <SearchIcon />
        <input
          className="terminal-search-input"
          type="search"
          value={query}
          onChange={(event) => onQueryChange(event.target.value)}
          placeholder="Search by wallet address..."
          aria-label="Search by wallet address"
        />
      </div>
      <select
        className={PORTFOLIO_TOOLBAR_SELECT_CLASS}
        value={timeframe}
        onChange={(event) =>
          onTimeframeChange(event.target.value as LeaderboardTimeframe)
        }
        aria-label="Leaderboard timeframe"
      >
        {TIMEFRAME_OPTIONS.map((option) => (
          <option key={option} value={option}>
            {LEADERBOARD_TIMEFRAME_LABELS[option]}
          </option>
        ))}
      </select>
    </div>
  );
}
