import React, { useMemo } from "react";
import ConnectWalletPanel from "../wallet/ConnectWalletPanel";
import type { PortfolioHeroView } from "./portfolioHeroView";
import { getPortfolioHeroBandBounds } from "./portfolioHeroBandBounds";

export interface PortfolioConnectGateOverlayProps {
  breakpoint: string;
  heroView: PortfolioHeroView;
}

function PortfolioConnectGateOverlay({
  breakpoint,
  heroView,
}: PortfolioConnectGateOverlayProps): JSX.Element {
  const bandStyle = useMemo(() => {
    const { topPx, heightPx } = getPortfolioHeroBandBounds(breakpoint, heroView);
    return {
      top: `${topPx}px`,
      height: `${heightPx}px`,
    };
  }, [breakpoint, heroView]);

  return (
    <div
      className="portfolio-connect-gate-overlay"
      style={bandStyle}
      role="region"
      aria-label="Connect wallet"
    >
      <div className="portfolio-connect-gate-overlay-card">
        <ConnectWalletPanel variant="portfolio" layout="inline" />
      </div>
    </div>
  );
}

export default React.memo(PortfolioConnectGateOverlay);
