import {
  getOfflineStakingSteps,
  recordDelegate,
  recordUndelegate,
  type OfflineStakingStep,
} from "../../offline/mock_data";

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type StakingDelegateMode = "delegate" | "undelegate";

export type ExecuteOfflineDelegateFundsParams = {
  wallet: string;
  mode: StakingDelegateMode;
  validatorId: string;
  validatorName: string;
  amountMorm: number;
};

export type OfflineDelegateFundsProgressCallbacks = {
  onStepStart?: (step: OfflineStakingStep) => void;
};

export type ExecuteOfflineDelegateFundsResult = {
  txHash: string;
};

export async function executeOfflineDelegateFunds(
  params: ExecuteOfflineDelegateFundsParams,
  callbacks?: OfflineDelegateFundsProgressCallbacks,
): Promise<ExecuteOfflineDelegateFundsResult> {
  const wallet = params.wallet.trim();
  if (!wallet) {
    throw new Error("Wallet address is required");
  }
  if (!params.validatorId.trim()) {
    throw new Error("Validator is required");
  }
  if (!Number.isFinite(params.amountMorm) || params.amountMorm <= 0) {
    throw new Error("Amount must be greater than zero");
  }

  const steps = getOfflineStakingSteps({
    mode: params.mode,
    amount: params.amountMorm,
    validatorName: params.validatorName,
  });

  for (const step of steps) {
    callbacks?.onStepStart?.(step);
    await delay(step.delayMs);
  }

  if (params.mode === "delegate") {
    const result = recordDelegate(wallet, params.validatorId, params.amountMorm);
    if (!result.ok) {
      throw new Error(
        result.reason === "insufficient"
          ? "Insufficient undelegated staked balance"
          : "Invalid delegate amount",
      );
    }
    return { txHash: result.txHash };
  }

  const result = recordUndelegate(wallet, params.validatorId, params.amountMorm);
  if (!result.ok) {
    throw new Error(
      result.reason === "insufficient"
        ? "Insufficient delegated balance"
        : "Invalid undelegate amount",
    );
  }
  return { txHash: result.txHash };
}
