import { useCallback, useEffect, useState, useSyncExternalStore } from "react";

import type { VaultActivityFile } from "../../offline/mock_data/vaultActivityHistory.types";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import {
  fetchVaultActivityById,
  getCachedVaultActivityById,
  isVaultActivityLoaded,
} from "../sdk/api/vaultActivity/vaultActivityClient";

export interface UseVaultSystemDataResult {
  data: VaultActivityFile | null;
  loading: boolean;
  error: string | null;
  reload: () => void;
}

export function useVaultSystemData(vaultId: string): UseVaultSystemDataResult {
  const normalizedId = vaultId.trim();
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  const [loading, setLoading] = useState(
    () => normalizedId.length > 0 && !isVaultActivityLoaded(normalizedId),
  );
  const [error, setError] = useState<string | null>(null);
  const [reloadToken, setReloadToken] = useState(0);

  const reload = useCallback(() => {
    setReloadToken((value) => value + 1);
  }, []);

  useEffect(() => {
    if (!normalizedId) {
      setLoading(false);
      setError("Missing vault id");
      return;
    }

    if (isVaultActivityLoaded(normalizedId)) {
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchVaultActivityById(normalizedId)
      .then(() => {
        if (cancelled) return;
        setError(null);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error
            ? err.message
            : "Failed to load vault activity data",
        );
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [normalizedId, reloadToken]);

  const data = normalizedId
    ? getCachedVaultActivityById(normalizedId)
    : null;

  void cacheRevision;

  return { data, loading, error, reload };
}

export function useVaultDataLoading(vaultId: string): boolean {
  const { loading } = useVaultSystemData(vaultId);
  return loading;
}
