import React from "react";

import type { AgentTask, TradingAgent } from "../../store/types";
import AgentRolesDetailContent from "./AgentRolesDetailContent";
import "./agentroles.css";

export interface AgentRolesDetailSliderProps {
  isOpen: boolean;
  agent: TradingAgent | undefined;
  tasks: AgentTask[];
  needsYouCount: number;
  onClose: () => void;
  onDeployToMarket?: () => void;
  onRelistToMarket?: () => void;
  onDuplicateAgent?: () => void;
}

export default function AgentRolesDetailSlider({
  isOpen,
  agent,
  tasks,
  needsYouCount,
  onClose,
  onDeployToMarket,
  onRelistToMarket,
  onDuplicateAgent,
}: AgentRolesDetailSliderProps): JSX.Element | null {
  if (!agent) return null;

  return (
    <aside
      className={`agentroles-detail-slider${isOpen ? " is-open" : ""}`}
      aria-hidden={!isOpen}
    >
      {isOpen ? (
        <AgentRolesDetailContent
          agent={agent}
          tasks={tasks}
          needsYouCount={needsYouCount}
          onClose={onClose}
          onDeployToMarket={onDeployToMarket}
          onRelistToMarket={onRelistToMarket}
          onDuplicateAgent={onDuplicateAgent}
          layout="slider"
        />
      ) : null}
    </aside>
  );
}
