import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

export const VAULT_DETAIL_SLOT_INDICES = {
  header: 0,
  stats: 1,
  main: 2,
  perfChart: 3,
  portfolio: 4,
  actions: 5,
} as const;

/** @deprecated Use VAULT_DETAIL_COLLAPSED_SLOTS_LG */
export const VAULT_DETAIL_COLLAPSED_SLOTS = [5, 6, 7, 8] as const;
export const VAULT_DETAIL_COLLAPSED_SLOTS_LG = [5, 6, 7, 8] as const;
export const VAULT_DETAIL_COLLAPSED_SLOTS_SM_XXS = [6, 7, 8] as const;
export const VAULT_DETAIL_ROW_HEIGHT = 30;
export const VAULT_DETAIL_LAYOUT_MARGIN = 10;

/** Fits breadcrumb + eyebrow + title row + actions without grid clipping. */
export const VAULT_DETAIL_HEADER_ROWS = 3;
/** Compact header on sm–xxs (768px and below) — identity + breadcrumb only; actions in slot 5. */
export const VAULT_DETAIL_HEADER_SM_ROWS = 2;
/** Action button band on sm–xxs (slot 5), directly under header. */
export const VAULT_DETAIL_ACTIONS_ROWS = 2;
/** @deprecated Use VAULT_DETAIL_HEADER_SM_ROWS — xs/xxs no longer use a six-row header band. */
export const VAULT_DETAIL_HEADER_MOBILE_ROWS = VAULT_DETAIL_HEADER_SM_ROWS;
/** Single-row 4-across stat cards on lg/md. */
export const VAULT_DETAIL_STATS_ROWS = 2;
/** 2×2 stat cards on sm (768–995px) — three grid rows (~110px). */
export const VAULT_DETAIL_STATS_STACKED_ROWS = 3;
/** 2×2 stat cards on xs/xxs. */
export const VAULT_DETAIL_STATS_MOBILE_ROWS = 3;
/** Tabbed main + perf/chart band (side-by-side lg/md; stacked sm–xxs). */
export const VAULT_DETAIL_MAIN_ROWS = 7;
/** Shorter main panel when stacked on sm–xxs so portfolio can viewport-fit. */
export const VAULT_DETAIL_MAIN_ROWS_STACKED = 4;
/** Perf/chart panel row span when stacked on sm–xxs (slot 3). */
export const VAULT_DETAIL_PERF_ROWS_STACKED = VAULT_DETAIL_MAIN_ROWS_STACKED + 4;
/** Main panel row span when stacked on sm–xxs (perf rail stays STACKED). */
export const VAULT_DETAIL_MAIN_ROWS_SM = VAULT_DETAIL_MAIN_ROWS_STACKED + 1;
/** Portfolio fallback when bucket count is unknown (md–xxs). */
export const VAULT_DETAIL_PORTFOLIO_ROWS = 7;
export const VAULT_DETAIL_PORTFOLIO_MIN_ROWS = 6;
export const VAULT_DETAIL_PORTFOLIO_MAX_ROWS = 12;
/** Extra portfolio row span on sm–xxs (slot 4). */
export const VAULT_DETAIL_PORTFOLIO_SM_XXS_EXTRA_ROWS = 3;

/** MenuBar height — must match MenuBar.css */
export const VAULT_DETAIL_MENUBAR_HEIGHT = 54;
/** Small fudge for grid chrome / sub-pixel rounding */
export const VAULT_DETAIL_VIEWPORT_FUDGE_PX = 4;
/** lg: minimum grid bottom row (fixed bands + min portfolio height) */
export const VAULT_DETAIL_MIN_BOTTOM_ROW =
  VAULT_DETAIL_HEADER_ROWS +
  VAULT_DETAIL_STATS_ROWS +
  VAULT_DETAIL_MAIN_ROWS +
  VAULT_DETAIL_PORTFOLIO_MIN_ROWS;
/** lg: sanity cap for viewport-fit bottom row */
export const VAULT_DETAIL_MAX_BOTTOM_ROW = 48;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED, COLLAPSED];
const COLLAPSED_TAIL_SM_XXS: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED];

function vaultDetailSmXxsStackedLayout(
  cols: number,
  portfolioRows = VAULT_DETAIL_PORTFOLIO_ROWS,
  headerRows = VAULT_DETAIL_HEADER_SM_ROWS,
  statsRows = VAULT_DETAIL_STATS_STACKED_ROWS,
  mainRows = VAULT_DETAIL_MAIN_ROWS_SM,
  perfRows = VAULT_DETAIL_PERF_ROWS_STACKED,
): LayoutConfigLest {
  let y = 0;
  const header: LayoutDefinition = [0, y, cols, headerRows];
  y += headerRows;
  const actions: LayoutDefinition = [0, y, cols, VAULT_DETAIL_ACTIONS_ROWS];
  y += VAULT_DETAIL_ACTIONS_ROWS;
  const stats: LayoutDefinition = [0, y, cols, statsRows];
  y += statsRows;

  const mainY = y;
  const main: LayoutDefinition = [0, mainY, cols, mainRows];
  const perfChart: LayoutDefinition = [0, mainY + mainRows, cols, perfRows];
  y = mainY + mainRows + perfRows;

  const portfolio: LayoutDefinition = [0, y, cols, portfolioRows];
  return [header, stats, main, perfChart, portfolio, actions, ...COLLAPSED_TAIL_SM_XXS];
}

function vaultDetailLayout(
  cols: number,
  portfolioRows = VAULT_DETAIL_PORTFOLIO_ROWS,
  headerRows = VAULT_DETAIL_HEADER_ROWS,
  statsRows = VAULT_DETAIL_STATS_ROWS,
  stackedMainBand = false,
  mainRows = VAULT_DETAIL_MAIN_ROWS,
  perfRows = mainRows,
): LayoutConfigLest {
  let y = 0;
  const header: LayoutDefinition = [0, y, cols, headerRows];
  y += headerRows;
  const stats: LayoutDefinition = [0, y, cols, statsRows];
  y += statsRows;

  const mainY = y;
  const mainH = stackedMainBand ? mainRows : VAULT_DETAIL_MAIN_ROWS;
  const perfH = stackedMainBand ? perfRows : VAULT_DETAIL_MAIN_ROWS;
  let main: LayoutDefinition;
  let perfChart: LayoutDefinition;

  if (stackedMainBand) {
    main = [0, mainY, cols, mainH];
    perfChart = [0, mainY + mainH, cols, perfH];
    y = mainY + mainH + perfH;
  } else {
    const mainW = Math.floor(cols / 2);
    const perfW = cols - mainW;
    main = [0, mainY, mainW, mainH];
    perfChart = [mainW, mainY, perfW, mainH];
    y = mainY + mainH;
  }

  const portfolio: LayoutDefinition = [0, y, cols, portfolioRows];
  return [header, stats, main, perfChart, portfolio, ...COLLAPSED_TAIL];
}

export function buildVaultDetailResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseLg = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, VAULT_DETAIL_COLLAPSED_SLOTS_LG);
  const collapseSmXxs = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, VAULT_DETAIL_COLLAPSED_SLOTS_SM_XXS);

  return {
    lg: collapseLg(vaultDetailLayout(12)),
    md: collapseLg(vaultDetailLayout(10)),
    sm: collapseSmXxs(
      vaultDetailSmXxsStackedLayout(
        6,
        VAULT_DETAIL_PORTFOLIO_ROWS,
        VAULT_DETAIL_HEADER_SM_ROWS,
        VAULT_DETAIL_STATS_STACKED_ROWS,
      ),
    ),
    xs: collapseSmXxs(
      vaultDetailSmXxsStackedLayout(
        4,
        VAULT_DETAIL_PORTFOLIO_ROWS,
        VAULT_DETAIL_HEADER_SM_ROWS,
        VAULT_DETAIL_STATS_MOBILE_ROWS,
      ),
    ),
    xxs: collapseSmXxs(
      vaultDetailSmXxsStackedLayout(
        2,
        VAULT_DETAIL_PORTFOLIO_ROWS,
        VAULT_DETAIL_HEADER_SM_ROWS,
        VAULT_DETAIL_STATS_MOBILE_ROWS,
      ),
    ),
  };
}

export function generateVaultDetailResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

/** lg: stretch portfolio slot to fill remaining viewport height. md–xxs: content-based portfolio rows; page scrolls. */
export function applyVaultDetailLayoutSizing(
  config: ResponsiveLayoutConfig,
  viewportHeight = 900,
  bucketCount = 3,
): ResponsiveLayoutConfig {
  const patchViewportFit = (layout: LayoutConfigLest) => {
    const portfolioSlot = layout[VAULT_DETAIL_SLOT_INDICES.portfolio];
    const portfolioStartY = portfolioSlot?.[1] ?? 0;
    const targetBottomRow = computeVaultDetailTargetBottomRow(
      viewportHeight,
      portfolioStartY,
    );
    return patchPortfolioViewportFit(layout, targetBottomRow);
  };
  const contentRows = resolveVaultDetailPortfolioRows(bucketCount);
  const smXxsPortfolioRows = resolveVaultDetailPortfolioRowsSmXxs(bucketCount);
  const patchContentPortfolio = (layout: LayoutConfigLest) =>
    patchPortfolioSlotHeight(layout, contentRows);
  const patchSmXxsPortfolio = (layout: LayoutConfigLest) =>
    patchPortfolioSlotHeight(layout, smXxsPortfolioRows);

  return {
    lg: patchViewportFit(config.lg),
    md: patchContentPortfolio(config.md),
    sm: patchSmXxsPortfolio(config.sm),
    xs: patchSmXxsPortfolio(config.xs),
    xxs: patchSmXxsPortfolio(config.xxs),
  };
}

/** Compute max grid bottom row that fits in the viewport without page scroll. */
export function computeVaultDetailTargetBottomRow(
  viewportHeight: number,
  portfolioStartY = VAULT_DETAIL_HEADER_ROWS +
    VAULT_DETAIL_STATS_ROWS +
    VAULT_DETAIL_MAIN_ROWS,
  menubarHeight = VAULT_DETAIL_MENUBAR_HEIGHT,
): number {
  const minBottomRow = portfolioStartY + VAULT_DETAIL_PORTFOLIO_MIN_ROWS;
  const available =
    viewportHeight - menubarHeight - VAULT_DETAIL_VIEWPORT_FUDGE_PX;
  const rowUnit = VAULT_DETAIL_ROW_HEIGHT + VAULT_DETAIL_LAYOUT_MARGIN;
  const rows = Math.floor((available + VAULT_DETAIL_LAYOUT_MARGIN) / rowUnit);
  return Math.max(
    minBottomRow,
    Math.min(VAULT_DETAIL_MAX_BOTTOM_ROW, rows),
  );
}

function patchPortfolioViewportFit(
  layout: LayoutConfigLest,
  targetBottomRow: number,
): LayoutConfigLest {
  const portfolioSlot = layout[VAULT_DETAIL_SLOT_INDICES.portfolio];
  if (!portfolioSlot || portfolioSlot[2] === 0 || portfolioSlot[3] === 0) {
    return layout;
  }
  const portfolioStart = portfolioSlot[1];
  const portfolioRows = Math.max(
    VAULT_DETAIL_PORTFOLIO_MIN_ROWS,
    targetBottomRow - portfolioStart,
  );
  return patchPortfolioSlotHeight(layout, portfolioRows);
}

/** Map bucket table content height to grid rows (md–xxs scroll mode). */
export function resolveVaultDetailPortfolioRows(bucketCount: number): number {
  const visibleRows = Math.min(Math.max(bucketCount, 1), 10);
  const chromePx = 104;
  const tablePx = 30 + visibleRows * 44;
  const totalPx = chromePx + tablePx;
  const rows = Math.floor(
    (totalPx + VAULT_DETAIL_LAYOUT_MARGIN) /
      (VAULT_DETAIL_ROW_HEIGHT + VAULT_DETAIL_LAYOUT_MARGIN),
  );
  return Math.min(
    VAULT_DETAIL_PORTFOLIO_MAX_ROWS,
    Math.max(VAULT_DETAIL_PORTFOLIO_MIN_ROWS, rows),
  );
}

/** sm–xxs portfolio rows — base bucket-count height plus extra band for scroll layout. */
export function resolveVaultDetailPortfolioRowsSmXxs(bucketCount: number): number {
  const base = resolveVaultDetailPortfolioRows(bucketCount);
  return Math.min(
    VAULT_DETAIL_PORTFOLIO_MAX_ROWS + VAULT_DETAIL_PORTFOLIO_SM_XXS_EXTRA_ROWS,
    base + VAULT_DETAIL_PORTFOLIO_SM_XXS_EXTRA_ROWS,
  );
}

function patchPortfolioSlotHeight(
  layout: LayoutConfigLest,
  portfolioRows: number,
): LayoutConfigLest {
  const portfolioSlot = layout[VAULT_DETAIL_SLOT_INDICES.portfolio];
  if (!portfolioSlot || portfolioSlot[2] === 0 || portfolioSlot[3] === 0) return layout;
  return layout.map((item, index) =>
    index === VAULT_DETAIL_SLOT_INDICES.portfolio
      ? [portfolioSlot[0], portfolioSlot[1], portfolioSlot[2], portfolioRows]
      : item,
  );
}

export function validateVaultDetailLayout(config: ResponsiveLayoutConfig): void {
  for (const bp of GRID_BREAKPOINTS) {
    assertNoLayoutOverlap(config[bp], `vault-detail-${bp}`);
  }
}
