import { useCallback, useMemo, useState } from "react";

import {
  getDelegatableMorm,
  OFFLINE_STAKING_STABLE_TOAST_ID,
} from "../../offline/mock_data";
import { useWalletConnectRequest } from "../context/WalletConnectHostContext";
import { formatStakingMormAmount } from "../components/staking/stakingFormat";
import { isWalletConnected } from "../utils/walletConnection";
import { createErrorCopyAction } from "../components/ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  toastUpdateLoading,
} from "../components/ui/toastTask";
import {
  executeOfflineDelegateFunds,
  type StakingDelegateMode,
} from "../utils/executeOfflineDelegateFunds";

type CtaKind =
  | "connect"
  | "enter_amount"
  | "insufficient"
  | "inactive"
  | "submit"
  | "submitting";

export interface UseStakingDelegateSubmitOptions {
  mode: StakingDelegateMode;
  amount: number;
  stakedMorm: number;
  walletAddress: string;
  validatorId: string;
  validatorName: string;
  validatorActive: boolean;
  yourStakeMorm: number;
  onSuccess?: () => void;
}

export function useStakingDelegateSubmit({
  mode,
  amount,
  stakedMorm,
  walletAddress,
  validatorId,
  validatorName,
  validatorActive,
  yourStakeMorm,
  onSuccess,
}: UseStakingDelegateSubmitOptions): {
  ctaLabel: string;
  ctaDisabled: boolean;
  ctaKind: CtaKind;
  isSubmitting: boolean;
  available: number;
  handlePrimaryClick: () => void;
} {
  const requestConnect = useWalletConnectRequest();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const connected = isWalletConnected(walletAddress);
  const available =
    mode === "delegate"
      ? getDelegatableMorm(walletAddress, stakedMorm)
      : yourStakeMorm;

  const cta = useMemo((): { kind: CtaKind; label: string; disabled: boolean } => {
    if (isSubmitting) {
      return {
        kind: "submitting",
        label: mode === "delegate" ? "Delegating…" : "Undelegating…",
        disabled: true,
      };
    }
    if (!connected) {
      return { kind: "connect", label: "Connect Wallet", disabled: false };
    }
    if (mode === "delegate" && !validatorActive) {
      return { kind: "inactive", label: "Validator inactive", disabled: true };
    }
    if (amount <= 0) {
      return { kind: "enter_amount", label: "Enter an amount", disabled: true };
    }
    if (amount > available) {
      return {
        kind: "insufficient",
        label: "Insufficient balance",
        disabled: true,
      };
    }
    return {
      kind: "submit",
      label: mode === "delegate" ? "Delegate" : "Undelegate",
      disabled: false,
    };
  }, [amount, available, connected, isSubmitting, mode, validatorActive]);

  const runSubmit = useCallback(async () => {
    const toastId = toastLoading(
      mode === "delegate" ? "Delegating MORM…" : "Undelegating MORM…",
      {
        stableId: OFFLINE_STAKING_STABLE_TOAST_ID,
        description: "Signing transaction…",
      },
    );
    setIsSubmitting(true);

    try {
      await executeOfflineDelegateFunds(
        {
          wallet: walletAddress,
          mode,
          validatorId,
          validatorName,
          amountMorm: amount,
        },
        {
          onStepStart: (step) => {
            toastUpdateLoading(toastId, step.loadingMessage, {
              description: step.loadingDescription,
            });
          },
        },
      );

      toastCompleteSuccess(
        toastId,
        mode === "delegate" ? "Delegation completed" : "Undelegation completed",
        {
          description: `${formatStakingMormAmount(amount)} MORM ${
            mode === "delegate"
              ? `delegated to ${validatorName}`
              : `returned from ${validatorName}`
          }`,
        },
      );
      onSuccess?.();
    } catch (err) {
      const msg = err instanceof Error ? err.message : "Transaction failed";
      toastCompleteError(toastId, "Transaction failed", {
        description: msg,
        action: createErrorCopyAction(msg),
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [amount, mode, onSuccess, validatorId, validatorName, walletAddress]);

  const handlePrimaryClick = useCallback(() => {
    if (cta.disabled) return;

    if (cta.kind === "connect") {
      requestConnect?.();
      return;
    }

    if (cta.kind === "submit") {
      void runSubmit();
    }
  }, [cta.disabled, cta.kind, requestConnect, runSubmit]);

  return {
    ctaLabel: cta.label,
    ctaDisabled: cta.disabled,
    ctaKind: cta.kind,
    isSubmitting,
    available,
    handlePrimaryClick,
  };
}
