import type { TraderLeaderboardFile } from "./traderLeaderboard.types";

let cachedLeaderboard: TraderLeaderboardFile | null = null;
const listeners = new Set<() => void>();

let revision = 0;

export function getTraderLeaderboardCacheRevision(): number {
  return revision;
}

export function subscribeTraderLeaderboardCache(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notifyTraderLeaderboardCache(): void {
  revision += 1;
  for (const listener of listeners) {
    listener();
  }
}

export function setCachedTraderLeaderboard(data: TraderLeaderboardFile): void {
  cachedLeaderboard = data;
  notifyTraderLeaderboardCache();
}

export function getCachedTraderLeaderboard(): TraderLeaderboardFile | null {
  return cachedLeaderboard;
}

export function clearTraderLeaderboardCache(): void {
  cachedLeaderboard = null;
  notifyTraderLeaderboardCache();
}

export function isTraderLeaderboardLoaded(): boolean {
  return cachedLeaderboard != null;
}

export function markTraderLeaderboardEmpty(): void {
  cachedLeaderboard = { traders: [] };
  notifyTraderLeaderboardCache();
}
