/**
 * Wallet-scoped portfolio funds ledger (offline demo).
 * Authoritative store for Deposits/Withdrawals table user actions.
 */

import type { PortfolioFundsMovementRow } from "./portfolioFundsMovements.types";
import type { VaultFundsMovementRow } from "./vaultMockData.types";

const STORAGE_PREFIX = "offline_portfolio_wallet_";

export interface PortfolioWalletState {
  movements: PortfolioFundsMovementRow[];
}

let stateRevision = 0;

const listeners = new Set<() => void>();

function storageKey(wallet: string): string {
  return `${STORAGE_PREFIX}${wallet.trim().toLowerCase()}`;
}

function emptyState(): PortfolioWalletState {
  return { movements: [] };
}

function normalizeState(state: PortfolioWalletState): PortfolioWalletState {
  return { movements: state.movements ?? [] };
}

function notify(): void {
  stateRevision += 1;
  for (const listener of listeners) {
    listener();
  }
}

export function getPortfolioWalletStateRevision(): number {
  return stateRevision;
}

export function subscribePortfolioWalletState(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function readState(wallet: string): PortfolioWalletState {
  if (typeof localStorage === "undefined" || !wallet.trim()) return emptyState();
  try {
    const raw = localStorage.getItem(storageKey(wallet));
    if (!raw) return emptyState();
    return normalizeState(JSON.parse(raw) as PortfolioWalletState);
  } catch {
    return emptyState();
  }
}

function writeState(wallet: string, state: PortfolioWalletState): void {
  if (typeof localStorage === "undefined" || !wallet.trim()) return;
  localStorage.setItem(storageKey(wallet), JSON.stringify(state));
}

export function getWalletPortfolioFundsMovements(
  wallet: string,
): PortfolioFundsMovementRow[] {
  if (!wallet.trim()) return [];
  return [...readState(wallet).movements].sort((a, b) => b.time - a.time);
}

export function appendPortfolioFundsMovement(
  wallet: string,
  row: PortfolioFundsMovementRow,
): boolean {
  if (!wallet.trim() || !row.id.trim()) return false;

  const state = readState(wallet);
  if (state.movements.some((existing) => existing.id === row.id)) {
    return false;
  }

  state.movements.unshift({
    ...row,
    walletAddress: wallet.trim(),
  });
  writeState(wallet, state);
  notify();
  return true;
}

export function appendVaultFundsMovementToPortfolio(
  wallet: string,
  row: VaultFundsMovementRow,
  vaultName: string,
): boolean {
  return appendPortfolioFundsMovement(wallet, {
    id: `vault-overlay-${row.vaultId}-${row.time}-${row.action}-${row.txHash}`,
    walletAddress: wallet.trim(),
    time: row.time,
    status: row.status,
    action: row.action,
    source: row.source,
    destination: row.destination || vaultName,
    amount: row.accountValueChangeUsd,
    asset: "USDC",
    fee: row.feeUsd,
    txHash: row.txHash,
    vaultId: row.vaultId,
  });
}
