/**
 * Wallet-scoped staking state (offline demo).
 */

import { STAKING_UNBONDING_MS } from "../../mormv1/constants/staking";
import { generateDemoTxHash } from "../../mormv1/stores/crossChainTransferStore";
import { applyDemoStakingSpotSettlement } from "./mockBucketState";
import type {
  StakingActivityRow,
  StakingPendingUnstakeRow,
  StakingUserState,
} from "./stakingMockData.types";

const STORAGE_PREFIX = "offline_staking_user_";

let stateRevision = 0;
const listeners = new Set<() => void>();
const memoryState = new Map<string, StakingUserState>();

function storageKey(wallet: string): string {
  return `${STORAGE_PREFIX}${wallet.trim().toLowerCase()}`;
}

function emptyState(): StakingUserState {
  return {
    stakedMorm: 0,
    usdcYieldPaidToDate: 0,
    claimableUsdc: 0,
    pendingUnstakes: [],
    activity: [],
  };
}

function normalizeState(state: StakingUserState): StakingUserState {
  return {
    stakedMorm: state.stakedMorm ?? 0,
    usdcYieldPaidToDate: state.usdcYieldPaidToDate ?? 0,
    claimableUsdc: state.claimableUsdc ?? 0,
    pendingUnstakes: state.pendingUnstakes ?? [],
    activity: state.activity ?? [],
  };
}

function loadState(wallet: string): StakingUserState {
  const key = storageKey(wallet);
  if (typeof localStorage !== "undefined") {
    try {
      const raw = localStorage.getItem(key);
      if (raw) return normalizeState(JSON.parse(raw) as StakingUserState);
    } catch {
      return memoryState.get(key) ?? emptyState();
    }
  }
  return memoryState.get(key) ?? emptyState();
}

function saveState(wallet: string, state: StakingUserState): void {
  const key = storageKey(wallet);
  if (typeof localStorage !== "undefined") {
    localStorage.setItem(key, JSON.stringify(state));
  }
  memoryState.set(key, state);
}

function bumpRevision(): void {
  stateRevision += 1;
  listeners.forEach((listener) => listener());
}

function appendActivity(
  state: StakingUserState,
  row: StakingActivityRow,
): void {
  state.activity = [row, ...state.activity].slice(0, 100);
}

/** Settle matured pending unstakes — credit MORM back to spot wallet. */
function processMaturedPendingUnstakes(
  wallet: string,
  state: StakingUserState,
): StakingUserState {
  const now = Date.now();
  const stillPending: StakingPendingUnstakeRow[] = [];

  for (const pending of state.pendingUnstakes) {
    if (pending.unlockAtMs <= now) {
      applyDemoStakingSpotSettlement(wallet, {
        transferId: `staking-unbond-${pending.id}`,
        amount: pending.amountMorm,
        mode: "unbond_complete",
      });
    } else {
      stillPending.push(pending);
    }
  }

  return { ...state, pendingUnstakes: stillPending };
}

export function getStakingUserStateRevision(): number {
  return stateRevision;
}

export function subscribeStakingUserState(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function getStakingUserState(
  wallet: string | null | undefined,
): StakingUserState {
  if (!wallet?.trim()) return emptyState();
  const state = loadState(wallet);
  const settled = processMaturedPendingUnstakes(wallet, state);
  if (
    settled.pendingUnstakes.length !== state.pendingUnstakes.length
  ) {
    saveState(wallet, settled);
    bumpRevision();
  }
  return settled;
}

export function recordStake(
  wallet: string,
  amountMorm: number,
): { ok: true; txHash: string } | { ok: false; reason: "insufficient" | "invalid" } {
  if (!wallet?.trim() || !Number.isFinite(amountMorm) || amountMorm <= 0) {
    return { ok: false, reason: "invalid" };
  }

  const txHash = generateDemoTxHash("st");
  const settled = applyDemoStakingSpotSettlement(wallet, {
    transferId: `staking-stake-${txHash}`,
    amount: amountMorm,
    mode: "stake",
  });
  if (!settled) {
    return { ok: false, reason: "insufficient" };
  }

  const state = getStakingUserState(wallet);
  state.stakedMorm += amountMorm;
  appendActivity(state, {
    id: txHash,
    kind: "stake",
    amountMorm,
    timestampMs: Date.now(),
    txHash,
  });
  saveState(wallet, state);
  bumpRevision();
  return { ok: true, txHash };
}

export function recordUnstake(
  wallet: string,
  amountMorm: number,
): { ok: true; txHash: string; pendingId: string } | { ok: false; reason: "insufficient" | "invalid" } {
  if (!wallet?.trim() || !Number.isFinite(amountMorm) || amountMorm <= 0) {
    return { ok: false, reason: "invalid" };
  }

  const state = getStakingUserState(wallet);
  if (amountMorm > state.stakedMorm) {
    return { ok: false, reason: "insufficient" };
  }

  const txHash = generateDemoTxHash("un");
  const pendingId = `pending-${txHash.slice(2, 10)}`;
  const now = Date.now();

  state.stakedMorm -= amountMorm;
  state.pendingUnstakes = [
    {
      id: pendingId,
      amountMorm,
      requestedAtMs: now,
      unlockAtMs: now + STAKING_UNBONDING_MS,
      txHash,
    },
    ...state.pendingUnstakes,
  ];
  appendActivity(state, {
    id: txHash,
    kind: "unstake",
    amountMorm,
    timestampMs: now,
    txHash,
  });
  saveState(wallet, state);
  bumpRevision();
  return { ok: true, txHash, pendingId };
}

export function recordClaimRewards(
  wallet: string,
): { ok: true; txHash: string; amountUsdc: number } | { ok: false; reason: "nothing_to_claim" | "invalid" } {
  if (!wallet?.trim()) {
    return { ok: false, reason: "invalid" };
  }

  const state = getStakingUserState(wallet);
  const amountUsdc = state.claimableUsdc;
  if (!Number.isFinite(amountUsdc) || amountUsdc <= 0) {
    return { ok: false, reason: "nothing_to_claim" };
  }

  const txHash = generateDemoTxHash("cl");
  state.claimableUsdc = 0;
  state.usdcYieldPaidToDate += amountUsdc;
  appendActivity(state, {
    id: txHash,
    kind: "claim",
    amountMorm: amountUsdc,
    timestampMs: Date.now(),
    txHash,
  });
  saveState(wallet, state);
  bumpRevision();
  return { ok: true, txHash, amountUsdc };
}

export function pushStakingActivity(
  wallet: string,
  row: StakingActivityRow,
): void {
  if (!wallet?.trim()) return;
  const state = getStakingUserState(wallet);
  appendActivity(state, row);
  saveState(wallet, state);
  bumpRevision();
}

/** Test helper: reset staking state for a wallet. */
export function resetStakingUserState(wallet?: string | null): void {
  if (wallet?.trim()) {
    const key = storageKey(wallet);
    if (typeof localStorage !== "undefined") {
      localStorage.removeItem(key);
    }
    memoryState.delete(key);
  }
  bumpRevision();
}

/** Test helper: set staked MORM without spot-wallet settlement. */
export function seedStakingStakedMormForDemo(
  wallet: string,
  stakedMorm: number,
): void {
  if (!wallet?.trim() || !Number.isFinite(stakedMorm) || stakedMorm < 0) return;
  const state = emptyState();
  state.stakedMorm = stakedMorm;
  saveState(wallet, state);
  bumpRevision();
}
