import { CREATE_VAULT_TOUR_STORAGE_KEY } from "../../mormv1/tutorials/create-vault-tour/constants";

export function hasSeenCreateVaultTour(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return localStorage.getItem(CREATE_VAULT_TOUR_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

export function markCreateVaultTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(CREATE_VAULT_TOUR_STORAGE_KEY, "1");
  } catch {
    // ignore
  }
}

export function clearCreateVaultTourSeen(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(CREATE_VAULT_TOUR_STORAGE_KEY);
  } catch {
    // ignore
  }
}
