import React from "react";
import { createPortal } from "react-dom";

import ModalHeader from "../../ui/ModalHeader";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
} from "../../ui/overlay";
import { useCopyAgentModalOverlay } from "../../tables/useBucketModalOverlay";
import "./deployAgent.css";

export interface DeployAgentCatalogFullDialogProps {
  open: boolean;
  agentNames: string[];
  onClose: () => void;
  onRetry: () => void;
}

export default function DeployAgentCatalogFullDialog({
  open,
  agentNames,
  onClose,
  onRetry,
}: DeployAgentCatalogFullDialogProps): JSX.Element | null {
  const overlay = useCopyAgentModalOverlay(open);
  useOverlayEscapeKey(open, onClose);

  if (!overlay.mounted) return null;

  const panelClassName = [
    "modal-content",
    "terminal-overlay-panel-shell",
    "deploy-agent-catalog-full-content",
    "staggered-overlay-panel--scale",
    overlay.isClosing ? "bucket-modal-panel--closing" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const content = (
    <StaggeredOverlayRoot passThrough={!open}>
      <StaggeredOverlayBackdrop
        visible={overlay.backdropVisible && open}
        onClose={onClose}
        style={overlay.backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={overlay.panelOpen}
        className={panelClassName}
        aria-label="Markets catalog full"
        role="dialog"
        aria-modal={true}
      >
        <ModalHeader title="Markets catalog full" onClose={onClose} />
        <div className="modal-body deploy-agent-catalog-full-body">
          <p className="terminal-text-muted">
            Staged, but no public row could be bound for:
          </p>
          <ul className="deploy-agent-review-list">
            {agentNames.map((name) => (
              <li key={name} className="terminal-value">
                {name}
              </li>
            ))}
          </ul>
          <p className="terminal-label">Kept as Staged · retry publish later.</p>
        </div>
        <div className="modal-footer bucket-modal-footer deploy-agent-modal-footer">
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            OK
          </button>
          <button type="button" className="btn btn-primary" onClick={onRetry}>
            Retry
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined" ? createPortal(content, document.body) : null;
}
