import type { Step } from "react-joyride";
import { CREATE_VAULT_TOUR_STEPS_CONTENT } from "./content";
import { CREATE_VAULT_TOUR_TARGETS } from "./constants";
import type { CreateVaultTourStepId } from "./constants";

function tourTarget(value: string): string {
  return `[data-tour="${value}"]`;
}

/** Carousel fieldset anchors used while the tour spotlights footer actions. */
const MODAL_FIELD_TARGETS: Record<string, string> = {
  details: CREATE_VAULT_TOUR_TARGETS.details,
  strategy: CREATE_VAULT_TOUR_TARGETS.strategy,
  funding: CREATE_VAULT_TOUR_TARGETS.funding,
  fee: CREATE_VAULT_TOUR_TARGETS.fee,
  visibility: CREATE_VAULT_TOUR_TARGETS.visibility,
};

const STEP_TARGETS: Record<string, string> = {
  "list-filters": CREATE_VAULT_TOUR_TARGETS.listFilters,
  "create-btn": CREATE_VAULT_TOUR_TARGETS.createBtn,
  details: CREATE_VAULT_TOUR_TARGETS.details,
  strategy: CREATE_VAULT_TOUR_TARGETS.continueBtn,
  funding: CREATE_VAULT_TOUR_TARGETS.continueBtn,
  fee: CREATE_VAULT_TOUR_TARGETS.continueBtn,
  visibility: CREATE_VAULT_TOUR_TARGETS.visibility,
  submit: CREATE_VAULT_TOUR_TARGETS.submitBtn,
  "create-success": CREATE_VAULT_TOUR_TARGETS.createSuccess,
  "new-stat-cards": CREATE_VAULT_TOUR_TARGETS.newVaultStatCards,
};

const WIZARD_CONTINUE_STEP_IDS = new Set(["strategy", "funding", "fee"]);

const MODAL_STEP_FIELD_TARGET: Record<CreateVaultTourStepId, string> = {
  details: CREATE_VAULT_TOUR_TARGETS.details,
  strategy: CREATE_VAULT_TOUR_TARGETS.strategy,
  funding: CREATE_VAULT_TOUR_TARGETS.funding,
  fee_model: CREATE_VAULT_TOUR_TARGETS.fee,
  visibility: CREATE_VAULT_TOUR_TARGETS.visibility,
};

type CreateVaultTourStepContent = (typeof CREATE_VAULT_TOUR_STEPS_CONTENT)[number];

export interface CreateVaultTourStepMeta {
  stepId: string;
  stepNumber: number;
  targetSelector: string;
  prepareSelector?: string;
  requiresClick: boolean;
  syncModalStep?: CreateVaultTourStepContent["syncModalStep"];
  gateUntilModalStep?: CreateVaultTourStepContent["gateUntilModalStep"];
  gateUntilPath?: CreateVaultTourStepContent["gateUntilPath"];
  gateUntilModalSuccess?: CreateVaultTourStepContent["gateUntilModalSuccess"];
}

const WIZARD_MODAL_STEP_IDS = new Set([
  "details",
  "strategy",
  "funding",
  "fee",
  "visibility",
  "submit",
  "create-success",
]);

export function resolveCreateVaultTourPrepareSelector(
  stepId: string,
  syncModalStep?: CreateVaultTourStepId,
): string | undefined {
  if (syncModalStep) {
    return tourTarget(MODAL_STEP_FIELD_TARGET[syncModalStep]);
  }
  const fieldTarget = MODAL_FIELD_TARGETS[stepId];
  return fieldTarget ? tourTarget(fieldTarget) : undefined;
}

export function buildCreateVaultTourSteps(): Step[] {
  return CREATE_VAULT_TOUR_STEPS_CONTENT.map((step, index) => {
    const targetKey = STEP_TARGETS[step.id] ?? step.id;
    const targetSelector = targetKey.startsWith("[")
      ? targetKey
      : tourTarget(targetKey);
    const prepareSelector = resolveCreateVaultTourPrepareSelector(
      step.id,
      step.syncModalStep,
    );
    const requiresClick = Boolean(step.requiresClick);
    const placement = WIZARD_CONTINUE_STEP_IDS.has(step.id)
      ? "top"
      : ((step.placement ?? "auto") as Step["placement"]);

    return {
      target: targetSelector,
      title: step.title,
      content: step.content,
      placement,
      skipBeacon: true,
      isFixed: WIZARD_MODAL_STEP_IDS.has(step.id) || step.id.startsWith("create"),
      spotlightClicks: requiresClick,
      disableOverlay: requiresClick,
      disableOverlayClose: true,
      hideBackButton: requiresClick,
      hideCloseButton: true,
      showSkipButton: true,
      buttons: requiresClick
        ? (["skip"] as ("back" | "skip" | "primary")[])
        : (["skip", "primary"] as ("back" | "skip" | "primary")[]),
      blockTargetInteraction: false,
      skipScroll: true,
      data: {
        stepId: step.id,
        stepNumber: index + 1,
        targetSelector,
        prepareSelector,
        requiresClick,
        syncModalStep: step.syncModalStep,
        gateUntilModalStep: step.gateUntilModalStep,
        gateUntilPath: step.gateUntilPath,
        gateUntilModalSuccess: step.gateUntilModalSuccess,
      } satisfies CreateVaultTourStepMeta,
    };
  });
}

export function getCreateVaultTourStepCount(): number {
  return CREATE_VAULT_TOUR_STEPS_CONTENT.length;
}

export function findCreateVaultTourStepIndex(steps: Step[], stepId: string): number {
  return steps.findIndex(
    (s) => (s.data as CreateVaultTourStepMeta | undefined)?.stepId === stepId,
  );
}
