import React, { useMemo } from "react";

import {
  usePortfolioBalances,
  weightPct,
} from "../../hooks/usePortfolioBalances";
import { formatCurrency } from "../../sdk/utils/display";
import {
  ErrorMessage,
  TableHeaderCellStatic,
  TableHeaderLabel,
} from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import MorpheumInlineLoading from "../ui/MorpheumInlineLoading";
import VaultActivityTableShell from "../vault/VaultActivityTableShell";
import { formatPct } from "../vault/vaultPortfolioMetrics";
import "../vault/vault.css";
import "./portfolio.css";

const GRID_CLASS = "vault-balances-grid";

export interface PortfolioBalancesTableProps {
  baseURL: string;
  walletAddress: string;
  authToken?: string;
  height?: string;
  refreshInterval?: number;
  onRequestFundAccount?: () => void;
  onRequestOpenWalletTransferModal?: () => void;
}

function formatAmount(value: number, symbol: string): string {
  const digits = symbol === "USDC" || symbol === "USDT" ? 2 : 4;
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  }).format(value);
}

function formatPrice(value: number): string {
  return formatCurrency(value);
}

function PortfolioBalancesTotalRow({
  idleTotalUsd,
  accountEquity,
}: {
  idleTotalUsd: number;
  accountEquity: number;
}): JSX.Element {
  return (
    <div className={`table-row vault-positions-total-row ${GRID_CLASS}`}>
      <div className="table-cell primary">TOTAL idle spot</div>
      <div className="table-cell primary" />
      <div className="table-cell numeric" />
      <div className="table-cell numeric" />
      <div className="table-cell numeric">{formatCurrency(idleTotalUsd)}</div>
      <div className="table-cell numeric">
        {formatPct(weightPct(idleTotalUsd, accountEquity))} of equity
      </div>
    </div>
  );
}

export default function PortfolioBalancesTable({
  baseURL,
  walletAddress,
  authToken,
  height = "100%",
  refreshInterval,
  onRequestFundAccount,
  onRequestOpenWalletTransferModal,
}: PortfolioBalancesTableProps): JSX.Element {
  const {
    sortedRows,
    accountEquity,
    idleSpotTotalUsd,
    loading,
    error,
  } = usePortfolioBalances({
    baseURL,
    walletAddress,
    authToken,
    refreshInterval,
  });

  const showFundEmptyState = useMemo(
    () => idleSpotTotalUsd <= 0 && Boolean(onRequestFundAccount),
    [idleSpotTotalUsd, onRequestFundAccount],
  );

  if (loading) {
    return (
      <div className="portfolio-balances-table" style={{ height }}>
        <MorpheumInlineLoading label="Loading balances…" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="portfolio-balances-table" style={{ height }}>
        <ErrorMessage error={error} />
      </div>
    );
  }

  if (showFundEmptyState) {
    return (
      <div className="portfolio-balances-table" style={{ height }}>
        <div className="message empty portfolio-balances-empty">
          <p>Your spot balance is 0.</p>
          <div className="portfolio-balances-empty-actions">
            <button
              type="button"
              className="btn btn-primary"
              onClick={onRequestFundAccount}
            >
              Fund account →
            </button>
            {onRequestOpenWalletTransferModal ? (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onRequestOpenWalletTransferModal}
              >
                Send to address
              </button>
            ) : null}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="portfolio-balances-table" style={{ height }}>
      <VaultActivityTableShell
        gridClassName={GRID_CLASS}
        minWidth={840}
        isEmpty={sortedRows.length === 0}
        emptyMessage="No idle spot balances."
        header={
          <>
            <TableHeaderCellStatic left>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.asset} />
            </TableHeaderCellStatic>
            <TableHeaderCellStatic left>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.name} />
            </TableHeaderCellStatic>
            <TableHeaderCellStatic right>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.amount} />
            </TableHeaderCellStatic>
            <TableHeaderCellStatic right>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.price} />
            </TableHeaderCellStatic>
            <TableHeaderCellStatic right>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.value} />
            </TableHeaderCellStatic>
            <TableHeaderCellStatic right>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.weight} />
            </TableHeaderCellStatic>
          </>
        }
        pinnedFooter={
          sortedRows.length > 0 ? (
            <PortfolioBalancesTotalRow
              idleTotalUsd={idleSpotTotalUsd}
              accountEquity={accountEquity}
            />
          ) : undefined
        }
      >
        {sortedRows.map((row) => (
          <div key={row.symbol} className={`table-row ${GRID_CLASS}`}>
            <div className="table-cell primary">
              <span>{row.symbol}</span>
            </div>
            <div className="table-cell primary" title={row.name}>
              {row.name}
            </div>
            <div className="table-cell numeric">
              {formatAmount(row.amount, row.symbol)}
            </div>
            <div className="table-cell numeric">{formatPrice(row.priceUsd)}</div>
            <div className="table-cell numeric">{formatCurrency(row.valueUsd)}</div>
            <div className="table-cell numeric">
              {formatPct(weightPct(row.valueUsd, accountEquity))}
            </div>
          </div>
        ))}
      </VaultActivityTableShell>
    </div>
  );
}
