export const OFFLINE_STAKING_STABLE_TOAST_ID = "offline:staking";

export type OfflineStakingStepId = "sign" | "submit" | "consensus" | "settle";

export type OfflineStakingStep = {
  id: OfflineStakingStepId;
  loadingMessage: string;
  loadingDescription: string;
  delayMs: number;
};

export type OfflineStakingStepParams = {
  mode: "stake" | "unstake" | "delegate" | "undelegate";
  amount: number;
  validatorName?: string;
};

const BASE_STEPS: OfflineStakingStep[] = [
  {
    id: "sign",
    loadingMessage: "Signing transaction…",
    loadingDescription: "Building EIP-712 staking payload",
    delayMs: 400,
  },
  {
    id: "submit",
    loadingMessage: "Submitting to morphcore…",
    loadingDescription: "Broadcasting /staking/v1/stake",
    delayMs: 500,
  },
  {
    id: "consensus",
    loadingMessage: "Awaiting consensus…",
    loadingDescription: "Confirming stake update",
    delayMs: 600,
  },
];

export function getOfflineStakingSteps(
  params: OfflineStakingStepParams,
): OfflineStakingStep[] {
  const steps = [...BASE_STEPS];
  const formattedAmount = params.amount.toLocaleString(undefined, {
    maximumFractionDigits: 4,
  });

  if (params.mode === "stake") {
    steps.push({
      id: "settle",
      loadingMessage: "Locking MORM…",
      loadingDescription: `${formattedAmount} MORM from Spot Wallet → Staked`,
      delayMs: 500,
    });
  } else if (params.mode === "unstake") {
    steps[1] = {
      ...steps[1],
      loadingDescription: "Broadcasting /staking/v1/unstake",
    };
    steps[2] = {
      ...steps[2],
      loadingDescription: "Starting 7-day unbonding",
    };
    steps.push({
      id: "settle",
      loadingMessage: "Queueing unbond…",
      loadingDescription: `${formattedAmount} MORM enters Pending Unstakes`,
      delayMs: 500,
    });
  } else {
    const validatorLabel = params.validatorName?.trim() || "validator";
    steps[1] = {
      ...steps[1],
      loadingDescription:
        params.mode === "delegate"
          ? "Broadcasting /staking/v1/delegate"
          : "Broadcasting /staking/v1/undelegate",
    };
    steps[2] = {
      ...steps[2],
      loadingDescription:
        params.mode === "delegate"
          ? `Assigning stake to ${validatorLabel}`
          : `Releasing stake from ${validatorLabel}`,
    };
    steps.push({
      id: "settle",
      loadingMessage:
        params.mode === "delegate" ? "Delegating MORM…" : "Undelegating MORM…",
      loadingDescription:
        params.mode === "delegate"
          ? `${formattedAmount} MORM → ${validatorLabel}`
          : `${formattedAmount} MORM returns to undelegated stake`,
      delayMs: 500,
    });
  }

  return steps;
}
