import {
  getOfflineDeployAgentSteps,
  type OfflineDeployAgentStep,
} from "../../offline/mock_data/offlineDeployAgentSteps";
import { generateDemoTxHash } from "../stores/crossChainTransferStore";

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type ExecuteOfflineDeployAgentParams = {
  agentCount: number;
  target: "stage" | "stage_and_publish";
  category: string;
  visibility: "public" | "preview";
  primaryDisplayName: string;
  primarySymbol: string;
  /** Seed for demo tx hash derivation. */
  batchSeed: string;
};

export type OfflineDeployAgentProgressCallbacks = {
  onStepStart?: (step: OfflineDeployAgentStep) => void;
};

export type ExecuteOfflineDeployAgentResult = {
  demoTxHash: string;
};

export async function executeOfflineDeployAgent(
  params: ExecuteOfflineDeployAgentParams,
  callbacks?: OfflineDeployAgentProgressCallbacks,
): Promise<ExecuteOfflineDeployAgentResult> {
  const batchSeed = params.batchSeed.trim();
  if (!batchSeed) {
    throw new Error("Batch seed is required");
  }
  if (params.agentCount < 1) {
    throw new Error("At least one agent is required");
  }

  const steps = getOfflineDeployAgentSteps({
    agentCount: params.agentCount,
    target: params.target,
    category: params.category,
    visibility: params.visibility,
    primaryDisplayName: params.primaryDisplayName,
    primarySymbol: params.primarySymbol,
  });

  for (const step of steps) {
    callbacks?.onStepStart?.(step);
    await delay(step.delayMs);
  }

  return {
    demoTxHash: generateDemoTxHash(batchSeed.slice(0, 4)),
  };
}
