import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";
import { Navigate, useNavigate, useParams } from "react-router-dom";

import {
  ensureVaultRegistryHydrated,
  getVaultById,
} from "../../offline/mock_data/vaultCatalog";
import {
  getRegistryRevision,
  subscribeVaultRegistry,
} from "../../offline/mock_data/vaultRegistryStorage";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import {
  ensureVaultUserStateSeeded,
  getVaultDepositUsd,
  getVaultUserPosition,
  getVaultUserStateRevision,
  subscribeVaultUserState,
} from "../../offline/mock_data/vaultUserState";
import { GridViewerLayout, GRID_COLS } from "../components";
import {
  VaultDetailHeader,
  VaultDetailHeaderActions,
  VaultDetailMainPanel,
  VaultDetailPerfChartPanel,
  VaultPortfolioSection,
  VaultStatCards,
} from "../components/vault";
import VaultFundsModal from "../components/vault/VaultFundsModal";
import { getLayoutForBreakpoint, resolveGridBreakpoint } from "../components/smartlayout/util";
import {
  applyVaultDetailLayoutSizing,
  buildVaultDetailResponsiveLayoutConfig,
  generateVaultDetailResponsiveLayouts,
  VAULT_DETAIL_LAYOUT_MARGIN,
  VAULT_DETAIL_ROW_HEIGHT,
} from "../configs/vaultDetailLayoutConfig";
import { useOnboard } from "../hooks/useOnboard";
import { isVaultOwner } from "../hooks/vaultOwnership";
import { useVaultOperate } from "../context/VaultOperateContext";
import { useVaultSystemData } from "../hooks/useVaultSystemData";
import { APP_ROUTES, tradeVaultPath } from "../routes";
import { isWalletConnected } from "../utils/walletConnection";
import "./VaultListPage.css";
import "../components/vault/vault.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [VAULT_DETAIL_LAYOUT_MARGIN, VAULT_DETAIL_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = VAULT_DETAIL_ROW_HEIGHT;

function buildLayouts(viewportHeight?: number, bucketCount?: number) {
  const base = buildVaultDetailResponsiveLayoutConfig();
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyVaultDetailLayoutSizing(base, height, bucketCount);
  return generateVaultDetailResponsiveLayouts(sized, 0);
}

export default function VaultDetailPage(): JSX.Element {
  const { id = "" } = useParams<{ id: string }>();

  useEffect(() => {
    ensureVaultRegistryHydrated();
  }, []);

  const vault = getVaultById(id);

  if (!vault) {
    return <Navigate to={APP_ROUTES.vault} replace />;
  }

  return <VaultDetailPageContent key={vault.id} vault={vault} />;
}

function VaultDetailPageContent({
  vault,
}: {
  vault: NonNullable<ReturnType<typeof getVaultById>>;
}): JSX.Element {
  const { walletAddress } = useOnboard();
  const walletConnected = isWalletConnected(walletAddress);
  const navigate = useNavigate();
  const { enterOperate } = useVaultOperate();
  const { loading: activityLoading } = useVaultSystemData(vault.id);
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() =>
    buildLayouts(undefined, vault.buckets.length),
  );
  const [currentBreakpoint, setCurrentBreakpoint] = useState<string>(() =>
    typeof window !== "undefined" ? resolveGridBreakpoint(window.innerWidth) : "lg",
  );
  const [fundsOpen, setFundsOpen] = useState(false);
  const [fundsTab, setFundsTab] = useState<"deposit" | "withdraw">("deposit");
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);

  const depositRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );

  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  const liveVault = useMemo(() => {
    void registryRevision;
    void cacheRevision;
    return getVaultById(vault.id) ?? vault;
  }, [vault, registryRevision, cacheRevision]);

  const bucketCount = liveVault.buckets.length;

  useEffect(() => {
    ensureVaultRegistryHydrated();
  }, []);

  useEffect(() => {
    if (walletAddress.trim()) {
      ensureVaultUserStateSeeded(walletAddress);
    }
  }, [walletAddress]);

  const userPosition = useMemo(() => {
    void depositRevision;
    return getVaultUserPosition(walletAddress, liveVault.id);
  }, [walletAddress, liveVault.id, depositRevision]);

  const yourDeposits =
    userPosition?.depositUsd ?? getVaultDepositUsd(walletAddress, liveVault.id);
  const allTimeEarned = userPosition?.allTimeEarnedUsd ?? 0;

  const openManageFunds = useCallback(() => {
    setFundsTab("deposit");
    setFundsOpen(true);
  }, []);

  const handleOperateVault = useCallback(() => {
    if (enterOperate(liveVault.id)) {
      navigate(tradeVaultPath(liveVault.id));
    }
  }, [enterOperate, navigate, liveVault.id]);

  const isOwner = isVaultOwner(walletAddress, liveVault);

  useEffect(() => {
    const applyViewportLayouts = () => {
      const nextLayouts = buildLayouts(
        window.innerHeight,
        bucketCount,
      );
      setLayouts(nextLayouts);
      gridRef.current?.applyLayouts(nextLayouts);
    };
    applyViewportLayouts();
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, [bucketCount]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const isSmXxs = currentBreakpoint === "sm" ||
    currentBreakpoint === "xs" ||
    currentBreakpoint === "xxs";

  const slotContent = useMemo(
    () => [
      <VaultDetailHeader
        key="header"
        height="100%"
        vault={liveVault}
        isOwner={isOwner}
        showActions={!isSmXxs}
        onManageFunds={walletConnected ? openManageFunds : undefined}
        onOperateVault={handleOperateVault}
      />,
      <VaultStatCards
        key="stats"
        height={slotDimensions[1]?.height}
        vault={liveVault}
        yourDepositsUsd={yourDeposits}
        allTimeEarnedUsd={allTimeEarned}
      />,
      <VaultDetailMainPanel
        key="main"
        height={slotDimensions[2]?.height}
        vault={liveVault}
        walletConnected={walletConnected}
        userPosition={userPosition}
        yourDepositsUsd={yourDeposits}
        allTimeEarnedUsd={allTimeEarned}
      />,
      <VaultDetailPerfChartPanel
        key="perfChart"
        height={slotDimensions[3]?.height}
        vault={liveVault}
      />,
      <VaultPortfolioSection
        key="portfolio"
        height={slotDimensions[4]?.height ?? "100%"}
        vault={liveVault}
        layoutBreakpoint={currentBreakpoint}
        activityLoading={activityLoading}
      />,
      isSmXxs ? (
        <VaultDetailHeaderActions
          key="headerActions"
          height={slotDimensions[5]?.height}
          isOwner={isOwner}
          onManageFunds={walletConnected ? openManageFunds : undefined}
          onOperateVault={handleOperateVault}
        />
      ) : null,
      null,
      null,
      null,
    ],
    [
      slotDimensions,
      liveVault,
      yourDeposits,
      allTimeEarned,
      userPosition,
      openManageFunds,
      isOwner,
      handleOperateVault,
      currentBreakpoint,
      isSmXxs,
      walletConnected,
      activityLoading,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--vault-detail">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
      />
      <VaultFundsModal
        isOpen={fundsOpen && walletConnected}
        onClose={() => setFundsOpen(false)}
        vault={liveVault}
        walletAddress={walletAddress}
        initialTab={fundsTab}
        userPosition={userPosition}
      />
    </div>
  );
}
