import React, { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";

import { usePortfolioFundsMovements } from "../../hooks/usePortfolioFundsMovements";
import type { PortfolioFundsMovementRow } from "../../../offline/mock_data/portfolioFundsMovements.types";
import { TableHeaderCellStatic } from "../smartlayout";
import VaultActivityTableShell from "../vault/VaultActivityTableShell";
import {
  exportPortfolioFundsCsv,
  formatPortfolioFundsAmount,
  formatPortfolioFundsDateTime,
} from "../../utils/portfolioFundsMovements";
import PortfolioFundsTableFooter from "./PortfolioFundsTableFooter";
import "../smartlayout/cross-chain/cross-chain.css";
import "../vault/vault.css";
import "./portfolio.css";

const GRID = "1.4fr 0.8fr 1.1fr 1fr 1fr 1.2fr 0.6fr";
export const PORTFOLIO_FUNDS_PREVIEW_ROW_LIMIT = 10;

export interface PortfolioDepositsWithdrawalsTableProps {
  walletAddress: string;
  height?: string;
}

function downloadCsv(filename: string, content: string): void {
  const blob = new Blob([content], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

function FundsMovementRow({
  row,
  onExplorerClick,
}: {
  row: PortfolioFundsMovementRow;
  onExplorerClick: (txHash: string) => void;
}): JSX.Element {
  const isPositive = row.amount >= 0;

  return (
    <div className="table-row" style={{ gridTemplateColumns: GRID }}>
      <div className="table-cell portfolio-funds-time-cell">
        <span>{formatPortfolioFundsDateTime(row.time)}</span>
        {row.txHash ? (
          <button
            type="button"
            className="cross-chain-explorer-link portfolio-funds-explorer-link"
            onClick={() => onExplorerClick(row.txHash!)}
            aria-label="View transaction on explorer"
            title={row.txHash}
          >
            ↗
          </button>
        ) : null}
      </div>
      <div className="table-cell">{row.status}</div>
      <div className="table-cell">{row.action}</div>
      <div className="table-cell">{row.source}</div>
      <div className="table-cell">{row.destination}</div>
      <div
        className={`table-cell numeric ${
          isPositive ? "vault-grade-a" : "vault-grade-d"
        }`}
      >
        {formatPortfolioFundsAmount(row.amount, row.asset)}
      </div>
      <div className="table-cell numeric">
        {row.fee == null ? "--" : formatPortfolioFundsAmount(row.fee, row.asset)}
      </div>
    </div>
  );
}

function PortfolioDepositsWithdrawalsTable({
  walletAddress,
  height = "100%",
}: PortfolioDepositsWithdrawalsTableProps): JSX.Element {
  const allRows = usePortfolioFundsMovements(walletAddress);
  const [showAll, setShowAll] = useState(false);

  const visibleRows = useMemo(() => {
    if (showAll) return allRows;
    return allRows.slice(0, PORTFOLIO_FUNDS_PREVIEW_ROW_LIMIT);
  }, [allRows, showAll]);

  const handleExplorerClick = useCallback(() => {
    toast.message("Demo explorer link", {
      description: "Explorer links are disabled in demo mode.",
    });
  }, []);

  const handleExportCsv = useCallback(() => {
    if (allRows.length === 0) {
      toast.message("Nothing to export", {
        description: "No deposits or withdrawals recorded yet.",
      });
      return;
    }
    const stamp = new Date().toISOString().slice(0, 10);
    downloadCsv(
      `portfolio-deposits-withdrawals-${stamp}.csv`,
      exportPortfolioFundsCsv(allRows),
    );
  }, [allRows]);

  return (
    <div
      className="portfolio-deposits-withdrawals-table"
      style={{ height }}
    >
      <VaultActivityTableShell
        gridColumns={GRID}
        layout="terminal"
        minWidth={900}
        isEmpty={allRows.length === 0}
        emptyMessage="No deposits or withdrawals."
        header={
          <>
            <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Status</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Action</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Source</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Destination</TableHeaderCellStatic>
            <TableHeaderCellStatic right>
              Account Value Change
            </TableHeaderCellStatic>
            <TableHeaderCellStatic right>Fee</TableHeaderCellStatic>
          </>
        }
        footer={
          allRows.length > 0 ? (
            <PortfolioFundsTableFooter
              totalCount={allRows.length}
              previewLimit={PORTFOLIO_FUNDS_PREVIEW_ROW_LIMIT}
              showAll={showAll}
              onViewAll={() => setShowAll(true)}
              onExportCsv={handleExportCsv}
            />
          ) : null
        }
      >
        {visibleRows.map((row) => (
          <FundsMovementRow
            key={row.id}
            row={row}
            onExplorerClick={handleExplorerClick}
          />
        ))}
      </VaultActivityTableShell>
    </div>
  );
}

export default React.memo(PortfolioDepositsWithdrawalsTable);
