import React from "react";

import {
  LeaderboardPageHeader,
  LeaderboardTable,
  LeaderboardToolbar,
} from "../components/leaderboard";
import { useLeaderboardData } from "../hooks/useLeaderboardData";
import { useOnboard } from "../hooks/useOnboard";
import { isWalletConnected } from "../utils/walletConnection";
import "./LeaderboardPage.css";

const LEADERBOARD_DISCLAIMER =
  "Excludes accounts with less than 100k USDC account value and less than 10M USDC trading volume. ROI = PNL / max(100, starting account value + maximum net deposits) for the time window.";

export interface LeaderboardPageProps {
  shellManagesOnboard?: boolean;
  shellWalletAddress?: string;
}

function LeaderboardPageContent({
  shellManagesOnboard = false,
  shellWalletAddress,
}: LeaderboardPageProps): JSX.Element {
  const onboard = useOnboard();
  const effectiveWalletAddress = shellManagesOnboard
    ? shellWalletAddress ?? ""
    : onboard.walletAddress;
  const walletConnected = isWalletConnected(effectiveWalletAddress);

  const {
    query,
    setQuery,
    timeframe,
    setTimeframe,
    sortField,
    sortDirection,
    handleSort,
    pinnedRow,
    pageRows,
    page,
    pageSize,
    totalCount,
    loading,
    error,
    setPage,
    setPageSize,
  } = useLeaderboardData({
    walletAddress: walletConnected ? effectiveWalletAddress : "",
  });

  return (
    <div className="leaderboard-page">
      <LeaderboardPageHeader />
      <LeaderboardToolbar
        query={query}
        timeframe={timeframe}
        onQueryChange={setQuery}
        onTimeframeChange={setTimeframe}
      />
      <LeaderboardTable
        timeframe={timeframe}
        sortField={sortField}
        sortDirection={sortDirection}
        onSort={handleSort}
        pinnedRow={pinnedRow}
        pageRows={pageRows}
        page={page}
        pageSize={pageSize}
        totalCount={totalCount}
        loading={loading}
        error={error}
        onPageChange={setPage}
        onPageSizeChange={setPageSize}
      />
      <p className="terminal-text-muted leaderboard-disclaimer">
        {LEADERBOARD_DISCLAIMER}
      </p>
    </div>
  );
}

export default function LeaderboardPage({
  shellManagesOnboard = false,
  shellWalletAddress,
}: LeaderboardPageProps): JSX.Element {
  return (
    <div className="App-dex-content App-dex-content--leaderboard">
      <LeaderboardPageContent
        shellManagesOnboard={shellManagesOnboard}
        shellWalletAddress={shellWalletAddress}
      />
    </div>
  );
}
