import React from "react";
import { useSyncExternalStore } from "react";

import { formatVaultTvl, getTotalVaultTvl } from "../../../offline/mock_data/vaultCatalog";
import {
  getRegistryRevision,
  subscribeVaultRegistry,
} from "../../../offline/mock_data/vaultRegistryStorage";
import {
  getTotalUserValueLockedUsd,
  getVaultUserStateRevision,
  subscribeVaultUserState,
} from "../../../offline/mock_data/vaultUserState";
import "./vault.css";

export interface VaultTvlCardProps {
  height?: string;
  walletAddress?: string;
}

export default function VaultTvlCard({
  height = "100%",
  walletAddress = "",
}: VaultTvlCardProps): JSX.Element {
  const depositRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  void depositRevision;
  void registryRevision;
  const tvl = getTotalVaultTvl();
  const userValueLocked = getTotalUserValueLockedUsd(walletAddress);

  return (
    <div className="vault-slot vault-tvl-card vault-tvl-card--band-left" style={{ height }}>
      <div className="vault-tvl-metrics">
        <div className="vault-tvl-metric">
          <p className="terminal-label">Total Value Locked</p>
          <p className="terminal-report-value">{formatVaultTvl(tvl)}</p>
        </div>
        <div className="vault-tvl-metric">
          <p className="terminal-label">User Value Locked</p>
          <p className="terminal-report-value">{formatVaultTvl(userValueLocked)}</p>
        </div>
      </div>
    </div>
  );
}
