import React from "react";
import "./portfolio.css";
import "./portfolioPanelSkeleton.css";

export type PortfolioPanelSkeletonVariant =
  | "volume"
  | "fees"
  | "equity"
  | "charts"
  | "metrics"
  | "accounts"
  | "leaderboard";

export interface PortfolioPanelSkeletonProps {
  variant: PortfolioPanelSkeletonVariant;
  height?: string;
  className?: string;
}

function SkeletonBlock({
  className,
}: {
  className: string;
}): JSX.Element {
  return <div className={`portfolio-panel-skeleton-block ${className}`} aria-hidden />;
}

function VolumeSkeleton(): JSX.Element {
  return (
    <>
      <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
      <SkeletonBlock className="portfolio-panel-skeleton-block--value" />
      <SkeletonBlock className="portfolio-panel-skeleton-block--bar" />
      <SkeletonBlock className="portfolio-panel-skeleton-block--bar-short" />
    </>
  );
}

function FeesSkeleton(): JSX.Element {
  return (
    <>
      <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
      <SkeletonBlock className="portfolio-panel-skeleton-block--value" />
      <SkeletonBlock className="portfolio-panel-skeleton-block--bar-short" />
    </>
  );
}

function EquitySkeleton(): JSX.Element {
  return (
    <>
      <div className="portfolio-panel-skeleton-donut" aria-hidden />
      <div className="portfolio-panel-skeleton-legend">
        {[0, 1, 2].map((index) => (
          <div key={index} className="portfolio-panel-skeleton-legend-row">
            <span className="portfolio-panel-skeleton-legend-dot" aria-hidden />
            <span className="portfolio-panel-skeleton-legend-line" aria-hidden />
          </div>
        ))}
      </div>
    </>
  );
}

function ChartsSkeleton(): JSX.Element {
  return (
    <>
      <div className="portfolio-panel-skeleton-tab-strip" aria-hidden />
      <div className="portfolio-panel-skeleton-chart-area" aria-hidden />
    </>
  );
}

function MetricsSkeleton(): JSX.Element {
  return (
    <>
      {[0, 1, 2, 3].map((index) => (
        <div key={index} className="portfolio-panel-skeleton-metric">
          <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
          <SkeletonBlock className="portfolio-panel-skeleton-block--value" />
        </div>
      ))}
    </>
  );
}

function AccountsSkeleton(): JSX.Element {
  return (
    <>
      <div className="portfolio-panel-skeleton-ledger-header">
        <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
        <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
        <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
      </div>
      {[0, 1, 2, 3, 4].map((index) => (
        <div key={index} className="portfolio-panel-skeleton-ledger-row">
          <SkeletonBlock className="portfolio-panel-skeleton-block--bar" />
          <SkeletonBlock className="portfolio-panel-skeleton-block--bar" />
          <SkeletonBlock className="portfolio-panel-skeleton-block--bar" />
        </div>
      ))}
    </>
  );
}

function LeaderboardSkeleton(): JSX.Element {
  return (
    <>
      {[0, 1, 2, 3, 4].map((index) => (
        <div key={index} className="portfolio-panel-skeleton-rank-row">
          <div className="portfolio-panel-skeleton-rank-avatar" aria-hidden />
          <div className="portfolio-panel-skeleton-rank-lines">
            <SkeletonBlock className="portfolio-panel-skeleton-block--label" />
            <SkeletonBlock className="portfolio-panel-skeleton-block--bar-short" />
          </div>
        </div>
      ))}
    </>
  );
}

const VARIANT_CONTENT: Record<
  PortfolioPanelSkeletonVariant,
  () => JSX.Element
> = {
  volume: VolumeSkeleton,
  fees: FeesSkeleton,
  equity: EquitySkeleton,
  charts: ChartsSkeleton,
  metrics: MetricsSkeleton,
  accounts: AccountsSkeleton,
  leaderboard: LeaderboardSkeleton,
};

function PortfolioPanelSkeleton({
  variant,
  height = "100%",
  className,
}: PortfolioPanelSkeletonProps): JSX.Element {
  const Content = VARIANT_CONTENT[variant];
  const rootClass = [
    "portfolio-slot",
    "portfolio-panel-skeleton",
    `portfolio-panel-skeleton--${variant}`,
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={rootClass} style={{ height }} aria-hidden="true">
      <Content />
    </div>
  );
}

export default React.memo(PortfolioPanelSkeleton);
