import { useMemo, useSyncExternalStore } from "react";
import { cloneVaultActivity } from "../../offline/mock_data/vaultActivityData";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import type { VaultActivityFilter } from "../../offline/mock_data/vaultMockData.types";
import {
  getVaultOperateStateRevision,
  getVaultTradeHistoryOverlay,
  subscribeVaultOperateState,
} from "../../offline/mock_data/vaultOperateState";
import { tradeFillToActivityRow } from "../../offline/mock_data/vaultActivityUtils";
import type { VaultActivityRow } from "../../offline/mock_data/vaultMockData.types";

export function useVaultActivity(
  vaultId: string,
  filter?: VaultActivityFilter,
): VaultActivityRow[] {
  const revision = useSyncExternalStore(
    subscribeVaultOperateState,
    getVaultOperateStateRevision,
    getVaultOperateStateRevision,
  );
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  return useMemo(() => {
    void revision;
    void cacheRevision;
    const base = cloneVaultActivity(vaultId, filter);
    if (filter?.types?.length && !filter.types.includes("perp")) {
      return base;
    }
    const overlay = getVaultTradeHistoryOverlay(vaultId, filter?.bucketId).map(
      tradeFillToActivityRow,
    );
    return [...overlay, ...base].sort((a, b) => b.time - a.time);
  }, [vaultId, filter?.bucketId, filter?.sourceKind, filter?.types?.join(","), revision, cacheRevision]);
}
