import React from "react";

import type { TradingAgent } from "../../store/types";
import AgentRolesCopyableValue from "./AgentRolesCopyableValue";

export interface AgentRolesCustodyAddressRowsProps {
  agent: TradingAgent;
}

export default function AgentRolesCustodyAddressRows({
  agent,
}: AgentRolesCustodyAddressRowsProps): JSX.Element | null {
  if (!agent.walletAddress && !agent.vaultAddress) return null;

  return (
    <>
      {agent.walletAddress ? (
        <div>
          <dt className="terminal-label">Wallet address</dt>
          <dd>
            <AgentRolesCopyableValue
              value={agent.walletAddress}
              copyLabel="wallet address"
            />
          </dd>
        </div>
      ) : null}
      {agent.vaultAddress ? (
        <div>
          <dt className="terminal-label">Vault address</dt>
          <dd>
            <AgentRolesCopyableValue
              value={agent.vaultAddress}
              copyLabel="vault address"
            />
          </dd>
        </div>
      ) : null}
    </>
  );
}
