import type { VaultRecord } from "../../offline/mock_data/vaultCatalog";
import {
  getOfflineVaultFundsSteps,
  recordVaultDeposit,
  recordVaultWithdraw,
  type OfflineVaultFundsStep,
  type VaultUserPosition,
} from "../../offline/mock_data";

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type ExecuteOfflineVaultFundsParams = {
  wallet: string;
  vault: VaultRecord;
  mode: "deposit" | "withdraw";
  amountUsd: number;
};

export type OfflineVaultFundsProgressCallbacks = {
  onStepStart?: (step: OfflineVaultFundsStep) => void;
};

export async function executeOfflineVaultFunds(
  params: ExecuteOfflineVaultFundsParams,
  callbacks?: OfflineVaultFundsProgressCallbacks,
): Promise<VaultUserPosition> {
  const wallet = params.wallet.trim();
  if (!wallet) {
    throw new Error("Wallet address is required");
  }
  if (!Number.isFinite(params.amountUsd) || params.amountUsd <= 0) {
    throw new Error("Amount must be greater than zero");
  }

  const steps = getOfflineVaultFundsSteps({
    mode: params.mode,
    amount: params.amountUsd,
    vaultName: params.vault.name,
  });

  for (const step of steps) {
    callbacks?.onStepStart?.(step);
    await delay(step.delayMs);
  }

  if (params.mode === "deposit") {
    const position = recordVaultDeposit(
      wallet,
      params.vault.id,
      params.amountUsd,
      params.vault,
    );
    if (!position) {
      throw new Error("Insufficient spot balance for deposit");
    }
    return position;
  }

  const position = recordVaultWithdraw(
    wallet,
    params.vault.id,
    params.amountUsd,
  );
  if (!position) {
    throw new Error("Withdrawal failed — amount exceeds withdrawable balance");
  }
  return position;
}
