import React, { useMemo } from "react";
import { Link } from "react-router-dom";

import {
  formatVaultApr,
  formatVaultGrade,
  formatVaultTvl,
  getTopVaultThisWeek,
  type VaultGrade,
} from "../../../offline/mock_data/vaultCatalog";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { vaultDetailPath } from "../../routes";
import { VAULT_TOUR_TARGETS } from "../../tutorials/vault-tour/constants";
import CompactMiniLineChart from "../metrics/CompactMiniLineChart";
import { Typewriter } from "../ui/Typewriter";
import { sanitizeLineDataForChart } from "../../utils/portfolioChartData";
import type { UTCTimestamp } from "lightweight-charts";
import "../metrics/metrics.css";
import "./vault.css";

const SPOTLIGHT_EYEBROW = "Analyst Pick · Top Vault This Week";

export interface VaultTopPickSpotlightProps {
  height?: string;
}

function gradeClassName(grade: VaultGrade | null): string {
  if (!grade) return "vault-grade-unrated";
  return `vault-grade-${grade.toLowerCase()}`;
}

function sparklineToChartData(values: number[]) {
  const now = Math.floor(Date.now() / 1000);
  const step = 86400;
  return sanitizeLineDataForChart(
    values.map((value, index) => ({
      time: (now - (values.length - 1 - index) * step) as UTCTimestamp,
      value,
    })),
  );
}

export default function VaultTopPickSpotlight({
  height = "100%",
}: VaultTopPickSpotlightProps): JSX.Element {
  const vault = getTopVaultThisWeek();
  const chartData = useMemo(
    () => sparklineToChartData(vault.spotlightSparkline90d),
    [vault.spotlightSparkline90d],
  );
  const verdict = vault.analystVerdict;

  return (
    <div className="vault-slot vault-spotlight vault-spotlight--band-right" style={{ height }} data-tour={VAULT_TOUR_TARGETS.listSpotlight}>
      {chartData.length >= 2 ? (
        <div className="vault-spotlight-chart-bg" aria-hidden>
          <CompactMiniLineChart
            data={chartData}
            color={TERMINAL_COLORS.brand}
            className="vault-spotlight-chart-fill"
            scaleMargins={{ top: 0, bottom: 0 }}
          />
        </div>
      ) : null}
      <div className="vault-spotlight-scrim" aria-hidden />

      <header className="vault-spotlight-header">
        <p className="eyebrow-text-wrap" title={SPOTLIGHT_EYEBROW}>
          <Typewriter
            text={SPOTLIGHT_EYEBROW}
            className="eyebrow-text"
            multiline={false}
          />
        </p>
        <span className="terminal-label">agentic ranking</span>
      </header>

      <div className="vault-spotlight-body">
        <div className="vault-spotlight-identity">
          <span className="vault-spotlight-badge" aria-hidden>
            #1
          </span>
          <div className="vault-spotlight-copy">
            <p className="vault-spotlight-name">{vault.name}</p>
            <p className="vault-spotlight-trust">
              <span className={gradeClassName(verdict.grade)}>
                Grade {formatVaultGrade(verdict.grade)}
              </span>
              {" · "}
              {verdict.verified ? "✓ Verified" : "Unverified"}
              {verdict.percentileLabel ? ` · ${verdict.percentileLabel}` : ""}
            </p>
            <p className="vault-spotlight-stats">
              APR{" "}
              <span className="terminal-value">{formatVaultApr(vault.aprPct)}</span>
              {" · TVL "}
              <span className="terminal-value">{formatVaultTvl(vault.tvlUsd)}</span>
              {" · "}
              <span className="terminal-value">{vault.ageDays}d</span> live
            </p>
          </div>
        </div>
      </div>

      <footer className="vault-spotlight-footer">
        <p className="vault-spotlight-summary">{verdict.spotlightSummary}</p>
        <Link to={vaultDetailPath(vault.id)} className="agent-primary-btn">
          View Vault →
        </Link>
      </footer>
    </div>
  );
}
