import React, { useMemo } from "react";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import {
  POSITION_PNL_COLOR_NEGATIVE,
  POSITION_PNL_COLOR_POSITIVE,
} from "../../constants";
import { formatCurrency } from "../../sdk/utils/display";
import { formatSignedPct } from "./vaultPortfolioMetrics";
import "./vault.css";

export interface VaultDetailPerfSummaryProps {
  vault: VaultRecord;
  periodPnlUsd: number;
  timeframeLabel: string;
}

function signedPctColor(value: number | null): string | undefined {
  if (value == null || value === 0) return undefined;
  return value > 0 ? POSITION_PNL_COLOR_POSITIVE : POSITION_PNL_COLOR_NEGATIVE;
}

function signedUsdColor(value: number): string | undefined {
  if (value === 0) return undefined;
  return value > 0 ? POSITION_PNL_COLOR_POSITIVE : POSITION_PNL_COLOR_NEGATIVE;
}

export default function VaultDetailPerfSummary({
  vault,
  periodPnlUsd,
  timeframeLabel,
}: VaultDetailPerfSummaryProps): JSX.Element {
  const pastMonth = vault.pastMonthReturnPct;
  const return90d = vault.analystVerdict.metrics.return90dPct;

  const periodLabel = useMemo(() => {
    if (timeframeLabel === "all") return "Period PnL (All)";
    return `Period PnL (${timeframeLabel.toUpperCase()})`;
  }, [timeframeLabel]);

  return (
    <div className="vault-detail-perf-summary" role="group" aria-label="Vault performance">
      <div className="vault-detail-perf-metric">
        <p className="terminal-label">Past month</p>
        <p className="terminal-value" style={{ color: signedPctColor(pastMonth) }}>
          {pastMonth == null ? "—" : formatSignedPct(pastMonth)}
        </p>
      </div>
      <div className="vault-detail-perf-metric">
        <p className="terminal-label">Return 90d</p>
        <p className="terminal-value" style={{ color: signedPctColor(return90d) }}>
          {return90d == null ? "—" : formatSignedPct(return90d)}
        </p>
      </div>
      <div className="vault-detail-perf-metric">
        <p className="terminal-label">{periodLabel}</p>
        <p className="terminal-value" style={{ color: signedUsdColor(periodPnlUsd) }}>
          {periodPnlUsd === 0 ? "—" : formatCurrency(periodPnlUsd)}
        </p>
      </div>
    </div>
  );
}
