import React, { useMemo, useState } from "react";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import type { VaultUserPosition } from "../../../offline/mock_data/vaultUserState";
import {
  buildVaultPerfChartData,
  buildVaultUserDepositSeed,
  type VaultPerfTimeframe,
  vaultUserRoiPct,
} from "../../../offline/mock_data/vaultPerfChartData";
import {
  POSITION_PNL_COLOR_NEGATIVE,
  POSITION_PNL_COLOR_POSITIVE,
} from "../../constants";
import { TERMINAL_COLORS } from "../../constants/terminalColors";
import { formatCurrency } from "../../sdk/utils/display";
import PortfolioTimeSeriesChart from "../portfolio/PortfolioTimeSeriesChart";
import { formatSignedPct } from "./vaultPortfolioMetrics";
import "./vault.css";

const FOCUS_COLOR = TERMINAL_COLORS.brand;

export interface VaultDetailYourPerfContentProps {
  vault: VaultRecord;
  walletConnected: boolean;
  userPosition?: VaultUserPosition;
  yourDepositsUsd: number;
  allTimeEarnedUsd: number;
}

function roiColor(roiPct: number | null): string | undefined {
  if (roiPct == null || roiPct === 0) return undefined;
  return roiPct > 0 ? POSITION_PNL_COLOR_POSITIVE : POSITION_PNL_COLOR_NEGATIVE;
}

export default function VaultDetailYourPerfContent({
  vault,
  walletConnected,
  userPosition,
  yourDepositsUsd,
  allTimeEarnedUsd,
}: VaultDetailYourPerfContentProps): JSX.Element {
  const [timeframe, setTimeframe] = useState<VaultPerfTimeframe>("all");

  const hasDeposit = yourDepositsUsd > 0.01;
  const roiPct = userPosition ? vaultUserRoiPct(userPosition) : null;

  const chartData = useMemo(() => {
    const seed = buildVaultUserDepositSeed(userPosition, vault, timeframe);
    return buildVaultPerfChartData(seed, timeframe);
  }, [userPosition, vault, timeframe]);

  if (!walletConnected) {
    return (
      <div className="vault-detail-your-perf-empty">
        <p className="terminal-label">Wallet</p>
        <p className="terminal-value">Connect a wallet to view your deposit curve.</p>
      </div>
    );
  }

  if (!hasDeposit) {
    return (
      <div className="vault-detail-your-perf-empty">
        <p className="terminal-label">No position</p>
        <p className="terminal-value">
          Deposit into this vault to track your personal performance here.
        </p>
      </div>
    );
  }

  return (
    <div className="vault-detail-your-perf-body">
      <div className="vault-detail-your-perf-metrics" role="group" aria-label="Your performance">
        <div className="vault-detail-your-perf-metric">
          <p className="terminal-label">Current value</p>
          <p className="terminal-value">{formatCurrency(yourDepositsUsd)}</p>
        </div>
        <div className="vault-detail-your-perf-metric">
          <p className="terminal-label">All-time earned</p>
          <p
            className="terminal-value"
            style={{
              color:
                allTimeEarnedUsd === 0
                  ? undefined
                  : allTimeEarnedUsd > 0
                    ? POSITION_PNL_COLOR_POSITIVE
                    : POSITION_PNL_COLOR_NEGATIVE,
            }}
          >
            {formatCurrency(allTimeEarnedUsd)}
          </p>
        </div>
        <div className="vault-detail-your-perf-metric">
          <p className="terminal-label">ROI</p>
          <p className="terminal-value" style={{ color: roiColor(roiPct) }}>
            {roiPct == null ? "—" : formatSignedPct(roiPct)}
          </p>
        </div>
      </div>

      <PortfolioTimeSeriesChart
        series={[
          {
            id: "your-deposit",
            data: chartData,
            color: FOCUS_COLOR,
          },
        ]}
        variant="area"
        className="vault-detail-your-perf-chart"
        emptyMessage="No deposit history"
      />

      <div className="vault-timeframe-pills" role="group" aria-label="Chart timeframe">
        {(["30d", "90d", "all"] as const).map((tf) => (
          <button
            key={tf}
            type="button"
            className={`vault-timeframe-pill${timeframe === tf ? " is-active" : ""}`}
            onClick={() => setTimeframe(tf)}
            aria-pressed={timeframe === tf}
          >
            {tf === "all" ? "All" : tf}
          </button>
        ))}
      </div>
    </div>
  );
}
