import type { Bucket } from "../sdk/types/data";

/** Sum of margin equity across all displayable buckets. */
export function computeBucketEquityTotal(collections: Bucket[]): number {
  return collections.reduce((sum, bucket) => sum + bucket.totalEquity, 0);
}

/**
 * Total wallet value for portfolio views: all idle spot USD + deployed bucket equity.
 * Distinct from USDC-only `spotWalletBalance` used for margin/deposit UX.
 */
export function computeTotalWalletEquity(
  idleSpotTotalUsd: number,
  collections: Bucket[],
): number {
  return idleSpotTotalUsd + computeBucketEquityTotal(collections);
}
