import type { LineData, UTCTimestamp } from "lightweight-charts";
import type { VaultRecord } from "./vaultCatalog";
import type { VaultUserPosition } from "./vaultUserState";

const DAY_MS = 24 * 60 * 60 * 1000;

export type VaultPerfTimeframe = "30d" | "90d" | "all";

const TIMEFRAME_POINTS: Record<VaultPerfTimeframe, number> = {
  "30d": 30,
  "90d": 90,
  all: 90,
};

function resampleSparkline(values: number[], pointCount: number): number[] {
  if (pointCount <= 0) return [];
  if (values.length === 0) {
    return Array.from({ length: pointCount }, () => 0.5);
  }
  if (values.length === 1) {
    return Array.from({ length: pointCount }, () => values[0]!);
  }

  const result: number[] = [];
  for (let i = 0; i < pointCount; i++) {
    const srcIdx = (i / Math.max(pointCount - 1, 1)) * (values.length - 1);
    const lo = Math.floor(srcIdx);
    const hi = Math.min(lo + 1, values.length - 1);
    const frac = srcIdx - lo;
    result.push(values[lo]! * (1 - frac) + values[hi]! * frac);
  }
  return result;
}

function pickSparkline(vault: VaultRecord): number[] {
  if (vault.spotlightSparkline90d.length > 0) {
    return vault.spotlightSparkline90d;
  }
  if (vault.snapshotSparkline.length > 0) {
    return vault.snapshotSparkline;
  }
  return [0.5, 0.52, 0.48, 0.51, 0.49, 0.5, 0.52, 0.48, 0.5, 0.51];
}

export function buildVaultAccountValueSeed(
  vault: VaultRecord,
  timeframe: VaultPerfTimeframe = "all",
): number[] {
  const pointCount = TIMEFRAME_POINTS[timeframe];
  const normalized = resampleSparkline(pickSparkline(vault), pointCount);
  const min = Math.min(...normalized);
  const max = Math.max(...normalized);
  const range = max - min || 0.01;

  return normalized.map((value, index) => {
    if (index === normalized.length - 1) return vault.tvlUsd;
    const pct = (value - min) / range;
    return vault.tvlUsd * (0.85 + pct * 0.15);
  });
}

export function buildVaultPnlSeed(
  vault: VaultRecord,
  timeframe: VaultPerfTimeframe = "all",
): number[] {
  const equity = buildVaultAccountValueSeed(vault, timeframe);
  const startEquity = equity[0] ?? vault.tvlUsd;
  return equity.map((value) => Math.round((value - startEquity) * 100) / 100);
}

/** Principal deposited before mark-to-market gains (offline demo). */
export function vaultUserPrincipalUsd(position: VaultUserPosition): number {
  return Math.max(0, position.depositUsd - position.allTimeEarnedUsd);
}

export function vaultUserRoiPct(position: VaultUserPosition): number | null {
  const principal = vaultUserPrincipalUsd(position);
  if (principal <= 0) return null;
  return Math.round((position.allTimeEarnedUsd / principal) * 1000) / 10;
}

export function buildVaultUserDepositSeed(
  position: VaultUserPosition | undefined,
  vault: VaultRecord,
  timeframe: VaultPerfTimeframe = "all",
): number[] {
  if (!position || position.depositUsd <= 0.01) return [];

  const pointCount = TIMEFRAME_POINTS[timeframe];
  const principal = vaultUserPrincipalUsd(position);
  const endValue = position.depositUsd;

  if (principal <= 0.01) {
    return Array.from({ length: pointCount }, () =>
      Math.round(endValue * 100) / 100,
    );
  }

  const normalized = resampleSparkline(pickSparkline(vault), pointCount);
  const min = Math.min(...normalized);
  const max = Math.max(...normalized);
  const range = max - min || 0.01;

  return normalized.map((value, index) => {
    if (index === normalized.length - 1) return endValue;
    const pct = (value - min) / range;
    const interpolated = principal + (endValue - principal) * pct;
    return Math.round(interpolated * 100) / 100;
  });
}

export function buildVaultUserPnlSeed(
  position: VaultUserPosition | undefined,
  vault: VaultRecord,
  timeframe: VaultPerfTimeframe = "all",
): number[] {
  const equity = buildVaultUserDepositSeed(position, vault, timeframe);
  if (equity.length === 0) return [];
  const startEquity = equity[0] ?? 0;
  return equity.map((value) => Math.round((value - startEquity) * 100) / 100);
}

function toUtcTimestamp(ms: number): UTCTimestamp {
  return Math.floor(ms / 1000) as UTCTimestamp;
}

export function buildVaultPerfChartData(
  seed: number[],
  timeframe: VaultPerfTimeframe = "all",
): LineData<UTCTimestamp>[] {
  if (seed.length === 0) return [];

  const now = Date.now();
  const spanDays =
    timeframe === "30d" ? 30 : timeframe === "90d" ? 90 : Math.max(seed.length, 90);

  return seed.map((value, index) => ({
    time: toUtcTimestamp(now - (seed.length - 1 - index) * DAY_MS),
    value,
  })).slice(-spanDays);
}
