import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";

import { GridViewerLayout } from "../components";
import {
  StakingConnectGateOverlay,
  StakingHeroHeader,
  StakingKpiRow,
  StakingPanelSkeleton,
  StakingPrimaryPanel,
  StakingTabSection,
  StakingUnlocksPanel,
} from "../components/staking";
import type { StakingPanelSkeletonVariant } from "../components/staking";
import {
  DEFAULT_STAKING_PAGE_VIEW,
  type StakingPageView,
} from "../components/staking/stakingPageView";
import {
  applyStakingLayoutSizing,
  buildStakingResponsiveLayoutConfig,
  generateStakingResponsiveLayouts,
  patchStakingPageView,
  STAKING_BASE_TAB_ROWS,
  STAKING_LAYOUT_MARGIN,
  STAKING_ROW_HEIGHT,
} from "../configs/stakingLayoutConfig";
import { useOnboard } from "../hooks/useOnboard";
import { useStakingPageData } from "../hooks/useStakingPageData";
import { toast } from "sonner";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import { isWalletConnected } from "../utils/walletConnection";
import "./StakingPage.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [STAKING_LAYOUT_MARGIN, STAKING_LAYOUT_MARGIN] as const,
  refreshInterval: 5000,
} as const;

const ROW_HEIGHT = STAKING_ROW_HEIGHT;

function buildLayouts(
  viewportHeight?: number,
  pageView: StakingPageView = DEFAULT_STAKING_PAGE_VIEW,
) {
  let base = buildStakingResponsiveLayoutConfig();
  base = patchStakingPageView(base, pageView);
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyStakingLayoutSizing(base, height);
  return generateStakingResponsiveLayouts(sized, 0);
}

export interface StakingPageProps {
  shellManagesOnboard?: boolean;
  shellWalletAddress?: string;
}

function StakingPageContent({
  shellManagesOnboard = false,
  shellWalletAddress,
}: StakingPageProps): JSX.Element {
  const onboard = useOnboard();
  const effectiveWalletAddress = shellManagesOnboard
    ? shellWalletAddress ?? ""
    : onboard.walletAddress;
  const walletConnected = isWalletConnected(effectiveWalletAddress);

  const [pageView, setPageView] = useState<StakingPageView>(
    DEFAULT_STAKING_PAGE_VIEW,
  );
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() =>
    buildLayouts(undefined, DEFAULT_STAKING_PAGE_VIEW),
  );
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const gridRef = useRef<{ getLayouts: () => ResponsiveLayouts } | null>(null);

  const stakingData = useStakingPageData({
    walletAddress: effectiveWalletAddress,
    refreshInterval: INITIAL_CONFIG.refreshInterval,
  });
  const { claimRewards, refresh: refreshStakingData, ...stakingView } = stakingData;

  const rebuildLayouts = useCallback(
    (viewportHeight?: number) => {
      setLayouts(buildLayouts(viewportHeight, pageView));
    },
    [pageView],
  );

  const onLayoutChange = useCallback(
    (_currentLayout: Layout[], allLayouts: ResponsiveLayouts) => {
      setLayouts(allLayouts);
    },
    [],
  );

  const handleLayoutMount = useCallback(() => {
    rebuildLayouts(window.innerHeight);
  }, [rebuildLayouts]);

  useEffect(() => {
    rebuildLayouts(window.innerHeight);
  }, [pageView, rebuildLayouts]);

  useEffect(() => {
    const onResize = () => {
      rebuildLayouts(window.innerHeight);
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [rebuildLayouts]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const tabRowCount = activeLayout[4]?.h ?? STAKING_BASE_TAB_ROWS;
  const isStakingView = pageView === "staking";

  const slotDimensions = useMemo(() => {
    const marginY = INITIAL_CONFIG.layoutMargin[1];
    return activeLayout.map((slot) => ({
      height: `${slot.h * ROW_HEIGHT + Math.max(0, slot.h - 1) * marginY}px`,
    }));
  }, [activeLayout]);

  const renderSkeleton = useCallback(
    (variant: StakingPanelSkeletonVariant, slotIndex: number) => (
      <StakingPanelSkeleton
        key={`skeleton-${variant}`}
        variant={variant}
        height={slotDimensions[slotIndex]?.height}
      />
    ),
    [slotDimensions],
  );

  const handleClaimRewards = useCallback(() => {
    const result = claimRewards();
    if (result.ok) {
      toast.success("Rewards claimed", {
        description: `$${result.amountUsdc.toFixed(2)} USDC`,
      });
    }
  }, [claimRewards]);

  const slotContent = useMemo(
    () => [
      <StakingHeroHeader
        key="title"
        height={slotDimensions[0]?.height}
        walletConnected={walletConnected}
        activeView={pageView}
        onViewChange={setPageView}
      />,
      walletConnected ? (
        <StakingKpiRow
          key="kpi"
          height={slotDimensions[1]?.height}
          feeTier={stakingView.feeTier}
          stakedMorm={stakingView.stakedMorm}
          totalStakedNetworkMorm={stakingView.totalStakedNetworkMorm}
          stakedSupplyPct={stakingView.stakedSupplyPct}
          usdcYieldPaidToDate={stakingView.usdcYieldPaidToDate}
          enableUsdcYield={stakingView.enableUsdcYield}
        />
      ) : (
        renderSkeleton("kpi", 1)
      ),
      walletConnected && isStakingView ? (
        <StakingPrimaryPanel
          key="primary"
          height={slotDimensions[2]?.height}
          stakedMorm={stakingView.stakedMorm}
          walletMormAvailable={stakingView.walletMormAvailable}
          walletAddress={effectiveWalletAddress}
          onSuccess={refreshStakingData}
        />
      ) : !walletConnected && isStakingView ? (
        renderSkeleton("primary", 2)
      ) : null,
      walletConnected && isStakingView ? (
        <StakingUnlocksPanel
          key="unlocks"
          height={slotDimensions[3]?.height}
          enableUsdcYield={stakingView.enableUsdcYield}
          enableDelegation={stakingView.enableDelegation}
        />
      ) : !walletConnected && isStakingView ? (
        renderSkeleton("unlocks", 3)
      ) : null,
      <StakingTabSection
        key="tabs"
        height={slotDimensions[4]?.height}
        activity={stakingView.activity}
        pendingUnstakes={stakingView.pendingUnstakes}
        usdcYieldPaidToDate={stakingView.usdcYieldPaidToDate}
        claimableUsdc={stakingView.claimableUsdc}
        enableUsdcYield={stakingView.enableUsdcYield}
        enableDelegation={stakingView.enableDelegation}
        walletAddress={effectiveWalletAddress}
        stakedMorm={stakingView.stakedMorm}
        onDelegateSuccess={refreshStakingData}
        onClaim={handleClaimRewards}
        suppressWalletGate={!walletConnected}
        defaultTab="delegate"
      />,
      null,
      null,
      null,
      null,
    ],
    [
      effectiveWalletAddress,
      handleClaimRewards,
      isStakingView,
      pageView,
      renderSkeleton,
      refreshStakingData,
      slotDimensions,
      stakingView,
      walletConnected,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--staking">
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={[]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
        onMount={handleLayoutMount}
      />
      {!walletConnected ? (
        <StakingConnectGateOverlay
          breakpoint={currentBreakpoint}
          tabRowCount={tabRowCount}
          pageView={pageView}
        />
      ) : null}
    </div>
  );
}

export default function StakingPage(props: StakingPageProps): JSX.Element {
  return <StakingPageContent {...props} />;
}
