import React from "react";

import { EmptyMessage } from "../smartlayout";
import "./vault.css";

export type VaultActivityTableLayout = "flat" | "bucket" | "terminal";

export interface VaultActivityTableShellProps {
  gridColumns?: string;
  /** CSS grid class for header + row alignment (e.g. vault-balances-grid). */
  gridClassName?: string;
  /** Terminal tab section table class (e.g. position-table). */
  tableClassName?: string;
  minWidth?: number;
  header: React.ReactNode;
  children: React.ReactNode;
  emptyMessage?: string;
  /** Pinned row inside the table frame (e.g. TOTAL). */
  pinnedFooter?: React.ReactNode;
  footer?: React.ReactNode;
  isEmpty?: boolean;
  /** bucket = vault detail frame; terminal = trade TabSection flat table. */
  layout?: VaultActivityTableLayout;
}

export default function VaultActivityTableShell({
  gridColumns = "",
  gridClassName,
  tableClassName = "",
  minWidth = 720,
  header,
  children,
  emptyMessage = "No rows.",
  pinnedFooter,
  footer,
  isEmpty = false,
  layout = "bucket",
}: VaultActivityTableShellProps): JSX.Element {
  const headerClassName = gridClassName
    ? `table-header ${gridClassName}`
    : "table-header";
  const headerStyle = gridClassName
    ? undefined
    : { gridTemplateColumns: gridColumns };

  const tableContainerClass = [
    "table-container",
    "shrinkable",
    tableClassName,
    layout === "flat" ? "vault-portfolio-table vault-table-scroll vault-activity-table" : "",
    layout === "terminal" ? "" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const panelClass =
    layout === "bucket"
      ? "vault-portfolio-table-panel vault-bucket-positions-panel"
      : layout === "terminal"
        ? ""
        : "vault-portfolio-table-panel";

  const containerStyle =
    layout === "terminal" ? undefined : minWidth ? { minWidth } : undefined;

  if (layout === "terminal") {
    if (isEmpty) {
      return (
        <div className={tableContainerClass}>
          <div className={headerClassName} style={headerStyle}>
            {header}
          </div>
          <EmptyMessage message={emptyMessage} />
        </div>
      );
    }

    return (
      <>
        <div className={tableContainerClass} style={containerStyle}>
          <div className={headerClassName} style={headerStyle}>
            {header}
          </div>
          {children}
          {pinnedFooter}
        </div>
        {footer}
      </>
    );
  }

  if (layout === "bucket") {
    if (isEmpty) {
      return (
        <div className={panelClass}>
          <div className="vault-bucket-positions-table-frame">
            <div className="vault-bucket-positions-table-header">
              <div className={headerClassName} style={headerStyle}>
                {header}
              </div>
            </div>
            <div className="vault-bucket-positions-table-scroll">
              <div className="vault-activity-table-empty">
                <EmptyMessage message={emptyMessage} />
              </div>
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className={panelClass}>
        <div className="vault-bucket-positions-table-frame">
          <div className="vault-bucket-positions-table-header">
            <div className={headerClassName} style={headerStyle}>
              {header}
            </div>
          </div>
          <div className="vault-bucket-positions-table-scroll">
            <div
              className="table-container shrinkable vault-activity-table"
              style={{ minWidth }}
            >
              {children}
            </div>
          </div>
          {pinnedFooter ? (
            <div className="vault-bucket-positions-table-footer">{pinnedFooter}</div>
          ) : null}
        </div>
        {footer}
      </div>
    );
  }

  return (
    <div className={panelClass}>
      <div
        className={
          tableContainerClass ||
          "table-container shrinkable vault-portfolio-table vault-table-scroll vault-activity-table"
        }
        style={{ minWidth }}
      >
        <div
          className={`${headerClassName} vault-activity-table-header`}
          style={headerStyle}
        >
          {header}
        </div>
        {isEmpty ? (
          <EmptyMessage message={emptyMessage} />
        ) : (
          children
        )}
      </div>
      {footer}
    </div>
  );
}
