import React from "react";

import { MOCK_FLEET_IDS, MOCK_SUPERVISOR_IDS } from "../../../../offline/mock_data/fleetSupervisors";
import type { AgentPermissionMode, AgentRole } from "../../../store/types";
import type { MintAgentWizardState } from "../../../utils/mintAgent";
import {
  PERMISSION_MODE_LABELS,
  defaultCustodyForRole,
  defaultPermissionForRole,
} from "../../../utils/mintAgent";
import { AGENT_ROLE_LABELS } from "../../../utils/agentRoles";
import { PresetCardGrid } from "../../ui/PresetCardGrid";
import type { PresetCardOption } from "../../ui/PresetCardGrid";

const ROLE_OPTIONS = Object.entries(AGENT_ROLE_LABELS) as [AgentRole, string][];

const SUPERVISOR_OPTIONS = [
  {
    id: MOCK_SUPERVISOR_IDS.soloDesk,
    fleetId: MOCK_FLEET_IDS.soloDesk,
    label: "Solo Desk",
  },
  {
    id: MOCK_SUPERVISOR_IDS.lpGuardian,
    fleetId: MOCK_FLEET_IDS.lpGuardianSwarm,
    label: "LP Guardian Swarm",
  },
] as const;

const PERMISSION_PRESET_OPTIONS = [
  {
    value: "watch_only",
    label: PERMISSION_MODE_LABELS.watch_only,
    description: "Observe and report only — no autonomous execution.",
    tone: "manual",
  },
  {
    value: "hil",
    label: PERMISSION_MODE_LABELS.hil,
    description: "Propose actions; you approve before anything executes.",
    tone: "guarded",
  },
  {
    value: "high_agency",
    label: PERMISSION_MODE_LABELS.high_agency,
    description: "Execute within mandate when confidence and risk stay in band.",
    tone: "high",
    warn: true,
  },
] as const satisfies readonly PresetCardOption<AgentPermissionMode>[];

export interface MintAgentStepRoleProps {
  state: MintAgentWizardState;
  onChange: (patch: Partial<MintAgentWizardState>) => void;
}

export default function MintAgentStepRole({
  state,
  onChange,
}: MintAgentStepRoleProps): JSX.Element {
  const handleRoleChange = (role: AgentRole) => {
    onChange({
      role,
      custodyMode: defaultCustodyForRole(role),
      permissionMode: defaultPermissionForRole(role),
    });
  };

  const handleSupervisorChange = (supervisorId: string) => {
    const option = SUPERVISOR_OPTIONS.find((entry) => entry.id === supervisorId);
    if (!option) return;
    onChange({ supervisorId: option.id, fleetId: option.fleetId });
  };

  return (
    <div className="mint-agent-step">
      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label" htmlFor="mint-role">
          Role
        </label>
        <select
          id="mint-role"
          className="form-input transfer-select"
          value={state.role}
          onChange={(e) => handleRoleChange(e.target.value as AgentRole)}
        >
          {ROLE_OPTIONS.map(([value, label]) => (
            <option key={value} value={value}>
              {label}
            </option>
          ))}
        </select>
        <p className="transfer-field-hint terminal-text-muted">
          Role gates custody, permission, and memory defaults downstream.
        </p>
      </div>

      <div className="transfer-field-group">
        <span className="terminal-label transfer-field-label">Permission</span>
        <PresetCardGrid
          options={PERMISSION_PRESET_OPTIONS}
          selected={state.permissionMode}
          onSelect={(permissionMode) => onChange({ permissionMode })}
          columns={3}
          hint="Suggested permission follows role — you can change it."
          hintClassName="transfer-field-hint"
          aria-label="Permission mode"
        />
      </div>

      <div className="transfer-field-group">
        <label className="terminal-label transfer-field-label" htmlFor="mint-fleet">
          Fleet
        </label>
        <select
          id="mint-fleet"
          className="form-input transfer-select"
          value={state.supervisorId}
          onChange={(e) => handleSupervisorChange(e.target.value)}
        >
          {SUPERVISOR_OPTIONS.map((option) => (
            <option key={option.id} value={option.id}>
              {option.label}
            </option>
          ))}
        </select>
        <p className="transfer-field-hint terminal-text-muted">
          Defaults to Solo Desk · sets mandate ceiling.
        </p>
      </div>
    </div>
  );
}
