import { vaultDetailPath } from "../../routes";
import type { CreateVaultTourStepId } from "./constants";
import { CREATE_VAULT_TOUR_DEMO_VAULT_ID } from "./constants";

export function createVaultTourDetailPath(): string {
  return vaultDetailPath(CREATE_VAULT_TOUR_DEMO_VAULT_ID);
}

export function isCreateVaultTourDetailRoute(pathname: string): boolean {
  return pathname === createVaultTourDetailPath();
}

export const CREATE_VAULT_MODAL_STEP_ORDER: CreateVaultTourStepId[] = [
  "details",
  "strategy",
  "funding",
  "fee_model",
  "visibility",
];

export function isCreateVaultModalStepAtLeast(
  current: CreateVaultTourStepId | null | undefined,
  required: CreateVaultTourStepId | undefined,
): boolean {
  if (!required) return true;
  if (!current) return false;
  return (
    CREATE_VAULT_MODAL_STEP_ORDER.indexOf(current) >=
    CREATE_VAULT_MODAL_STEP_ORDER.indexOf(required)
  );
}

export function isCreateVaultModalStepPast(
  current: CreateVaultTourStepId | null | undefined,
  required: CreateVaultTourStepId | undefined,
): boolean {
  if (!required || !current) return false;
  return (
    CREATE_VAULT_MODAL_STEP_ORDER.indexOf(current) >
    CREATE_VAULT_MODAL_STEP_ORDER.indexOf(required)
  );
}

export function isCreateVaultTourGateSatisfied(
  gateUntilModalStep: CreateVaultTourStepId | undefined,
  modalStep: CreateVaultTourStepId | null,
  gateUntilPath: "createdVaultDetail" | undefined,
  gateUntilModalSuccess: boolean | undefined,
  pathname: string,
  modalOpen: boolean,
  modalShowSuccess: boolean,
): boolean {
  if (gateUntilModalSuccess) {
    return modalOpen && modalShowSuccess;
  }
  if (gateUntilPath === "createdVaultDetail") {
    return isCreateVaultTourDetailRoute(pathname);
  }
  if (gateUntilModalStep) {
    return modalOpen && isCreateVaultModalStepAtLeast(modalStep ?? null, gateUntilModalStep);
  }
  return true;
}

export function isCreateVaultTourNextGated(
  gateUntilModalStep: CreateVaultTourStepId | undefined,
  modalStep: CreateVaultTourStepId | null,
): boolean {
  if (!gateUntilModalStep) return false;
  return !isCreateVaultModalStepAtLeast(modalStep, gateUntilModalStep);
}

export function resolveCreateVaultTourSlug(name: string): string {
  const base = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return base || CREATE_VAULT_TOUR_DEMO_VAULT_ID;
}
