import React from "react";
import { useNavigate } from "react-router-dom";

import type { VaultListingRow } from "../../hooks/useVaultListingData";
import {
  formatVaultApr,
  formatVaultGrade,
  formatVaultTvl,
  type VaultGrade,
} from "../../../offline/mock_data/vaultCatalog";
import { formatCurrency } from "../../sdk/utils/display";
import { vaultDetailPath } from "../../routes";
import { TableHeaderCellStatic } from "../smartlayout";
import CompactSparkline from "../metrics/CompactSparkline";
import VaultTableFooter from "./VaultTableFooter";
import {
  BubbleTip,
  BubbleTipInline,
  BUBBLE_TIP_IDS,
} from "../../tutorials/bubble-tip";
import "../smartlayout/layout.css";
import "./vault.css";

const LISTING_GRID =
  "minmax(160px, 1.8fr) minmax(90px, 1fr) minmax(56px, 0.6fr) minmax(64px, 0.7fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(56px, 0.6fr) minmax(72px, 0.8fr) minmax(100px, 0.9fr)";

function gradeClassName(grade: VaultGrade | null): string {
  if (!grade) return "vault-grade-unrated";
  return `vault-grade-${grade.toLowerCase()}`;
}

function VaultTableHeader(): JSX.Element {
  return (
    <div className="table-header" style={{ gridTemplateColumns: LISTING_GRID }}>
      <TableHeaderCellStatic left>Vault</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Leader</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Grade</TableHeaderCellStatic>
      <TableHeaderCellStatic left>APR</TableHeaderCellStatic>
      <TableHeaderCellStatic left>TVL</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Your Deposit</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Age(d)</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Snapshot</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Actions</TableHeaderCellStatic>
    </div>
  );
}

function VaultRow({
  vault,
  onNavigate,
  onOperateVault,
}: {
  vault: VaultListingRow;
  onNavigate: (id: string) => void;
  onOperateVault?: (id: string) => void;
}): JSX.Element {
  const prefix = vault.isPinned ? "★ " : "";

  return (
    <div
      className="table-row clickable vault-listing-table-row"
      style={{ gridTemplateColumns: LISTING_GRID }}
      role="row"
      tabIndex={0}
      onClick={() => onNavigate(vault.id)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onNavigate(vault.id);
        }
      }}
    >
      <div className="table-cell primary">
        {prefix}
        {vault.name}
      </div>
      <div className="table-cell">{vault.leader}</div>
      <div className={`table-cell ${gradeClassName(vault.grade)}`}>
        {formatVaultGrade(vault.grade)}
        {vault.analystVerdict.hasFlags ? (
          <BubbleTipInline
            id={BUBBLE_TIP_IDS.vaultGradeFlag}
            className="vault-flag-marker"
            hideLabel
            trigger="⚑"
          />
        ) : null}
      </div>
      <div className="table-cell numeric">{formatVaultApr(vault.aprPct)}</div>
      <div className="table-cell numeric">{formatVaultTvl(vault.tvlUsd)}</div>
      <div className="table-cell numeric">
        {formatCurrency(vault.yourDepositUsd)}
      </div>
      <div className="table-cell numeric">{vault.ageDays}</div>
      <div className="table-cell vault-listing-table-sparkline">
        {vault.snapshotSparkline.length >= 2 ? (
          <CompactSparkline
            values={vault.snapshotSparkline}
            className="vault-listing-sparkline"
            responsiveWidth
            strokeInset={1}
          />
        ) : (
          "·"
        )}
      </div>
      <div className="table-cell vault-listing-actions-cell">
        {vault.isOwner ? (
          <button
            type="button"
            className="vault-listing-action-btn"
            onClick={(event) => {
              event.stopPropagation();
              onOperateVault?.(vault.id);
            }}
          >
            Operate →
          </button>
        ) : (
          <button
            type="button"
            className="vault-listing-action-btn vault-listing-action-btn--secondary"
            onClick={(event) => {
              event.stopPropagation();
              onNavigate(vault.id);
            }}
          >
            View
          </button>
        )}
      </div>
    </div>
  );
}

export interface VaultListingTableProps {
  height?: string;
  protocolVaults: VaultListingRow[];
  paginatedUserVaults: VaultListingRow[];
  totalUserCount: number;
  page: number;
  pageSize: number;
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;
  onOperateVault?: (vaultId: string) => void;
}

export default function VaultListingTable({
  height = "100%",
  protocolVaults,
  paginatedUserVaults,
  totalUserCount,
  page,
  pageSize,
  onPageChange,
  onPageSizeChange,
  onOperateVault,
}: VaultListingTableProps): JSX.Element {
  const navigate = useNavigate();

  const handleNavigate = (id: string) => {
    navigate(vaultDetailPath(id));
  };

  return (
    <div className="vault-slot vault-table-section" style={{ height }}>
      <div className="vault-portfolio-table-panel">
        <div className="vault-table-scroll">
          <div className="vault-table-section-block">
            <div className="vault-table-section-heading">
              <h2 className="vault-table-section-title">
                <BubbleTip id={BUBBLE_TIP_IDS.protocolVaults}>
                  <span className="vault-table-section-title--tip">
                    Protocol Vaults
                  </span>
                </BubbleTip>
              </h2>
            </div>
            <div
              className="table-container shrinkable vault-listing-table"
              role="table"
            >
              <VaultTableHeader />
              {protocolVaults.map((vault) => (
                <VaultRow
                  key={vault.id}
                  vault={vault}
                  onNavigate={handleNavigate}
                  onOperateVault={onOperateVault}
                />
              ))}
            </div>
          </div>

          <div className="vault-table-section-block">
            <div className="vault-table-section-heading">
              <h2 className="vault-table-section-title">
                <BubbleTip id={BUBBLE_TIP_IDS.userVaults}>
                  <span className="vault-table-section-title--tip">
                    User Vaults
                  </span>
                </BubbleTip>
              </h2>
            </div>
            <div
              className="table-container shrinkable vault-listing-table"
              role="table"
            >
              <VaultTableHeader />
              {paginatedUserVaults.map((vault) => (
                <VaultRow
                  key={vault.id}
                  vault={vault}
                  onNavigate={handleNavigate}
                  onOperateVault={onOperateVault}
                />
              ))}
            </div>
          </div>
        </div>

        <VaultTableFooter
          page={page}
          pageSize={pageSize}
          totalCount={totalUserCount}
          onPageChange={onPageChange}
          onPageSizeChange={onPageSizeChange}
        />
      </div>
    </div>
  );
}
