import React, { useCallback, useMemo, useState } from "react";
import { toast } from "sonner";

import { useVaultFundsMovements } from "../../hooks/useVaultFundsMovements";
import type { VaultFundsMovementRow } from "../../../offline/mock_data/vaultMockData.types";
import { TableHeaderCellStatic } from "../smartlayout";
import VaultActivityTableShell, {
  type VaultActivityTableLayout,
} from "./VaultActivityTableShell";
import VaultTableFooter from "./VaultTableFooter";
import "../smartlayout/cross-chain/cross-chain.css";
import "./vault.css";

const GRID = "1.2fr 0.9fr 1fr 0.9fr 1.1fr 0.6fr";

export interface VaultDepositsWithdrawalsTableProps {
  vaultId: string;
  layout?: VaultActivityTableLayout;
}

function formatDateTime(value: number): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "medium",
  }).format(new Date(value));
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 6,
  }).format(value);
}

function shortHash(hash: string): string {
  if (hash.length <= 12) return hash;
  return `${hash.slice(0, 8)}…${hash.slice(-4)}`;
}

export default function VaultDepositsWithdrawalsTable({
  vaultId,
  layout = "bucket",
}: VaultDepositsWithdrawalsTableProps): JSX.Element {
  const allRows = useVaultFundsMovements(vaultId);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);

  const pageRows = useMemo(() => {
    const start = page * pageSize;
    return allRows.slice(start, start + pageSize);
  }, [allRows, page, pageSize]);

  const handleExplorerClick = useCallback(() => {
    toast.message("Demo explorer link", {
      description: "Explorer links are disabled in demo mode.",
    });
  }, []);

  return (
    <VaultActivityTableShell
      gridColumns={GRID}
      layout={layout}
      minWidth={720}
      isEmpty={allRows.length === 0}
      emptyMessage="No deposits or withdrawals."
      header={
        <>
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Tx Hash</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Status</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Action</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Account Value Change</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Fee</TableHeaderCellStatic>
        </>
      }
      footer={
        <VaultTableFooter
          page={page}
          pageSize={pageSize}
          totalCount={allRows.length}
          onPageChange={setPage}
          onPageSizeChange={setPageSize}
        />
      }
    >
      {pageRows.map((row: VaultFundsMovementRow, index) => {
        const isPositive = row.accountValueChangeUsd >= 0;
        const absChange = Math.abs(row.accountValueChangeUsd);
        const signedChange = `${isPositive ? "" : "-"}${formatNumber(absChange)} USDC`;

        return (
          <div
            key={`${row.time}-${row.action}-${row.walletAddress}-${index}`}
            className="table-row"
            style={{ gridTemplateColumns: GRID }}
          >
            <div className="table-cell">{formatDateTime(row.time)}</div>
            <div className="table-cell">
              <button
                type="button"
                className="cross-chain-explorer-link"
                onClick={handleExplorerClick}
                aria-label="View transaction on explorer"
                title={row.txHash}
              >
                {shortHash(row.txHash)} ↗
              </button>
            </div>
            <div className="table-cell">{row.status}</div>
            <div className="table-cell">{row.action}</div>
            <div
              className={`table-cell numeric ${
                isPositive ? "vault-grade-a" : "vault-grade-d"
              }`}
            >
              {signedChange}
            </div>
            <div className="table-cell numeric">
              {row.feeUsd == null ? "--" : `${formatNumber(row.feeUsd)} USDC`}
            </div>
          </div>
        );
      })}
    </VaultActivityTableShell>
  );
}
