import type { CrossChainTransferRecord } from "../types/crossChainFlow";
import type { PortfolioFundsMovementRow } from "../../offline/mock_data/portfolioFundsMovements.types";
import type { VaultFundsMovementRow } from "../../offline/mock_data/vaultMockData.types";
import { appendPortfolioFundsMovement } from "../../offline/mock_data/portfolioWalletState";

const TRADING_ACCOUNT = "Trading Account";

export function formatPortfolioFundsDateTime(time: number): string {
  const date = new Date(time);
  const datePart = date.toLocaleDateString(undefined, {
    year: "numeric",
    month: "numeric",
    day: "numeric",
  });
  const timePart = date.toLocaleTimeString(undefined, {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });
  return `${datePart} - ${timePart}`;
}

export function formatPortfolioFundsAmount(value: number, asset: string): string {
  const abs = Math.abs(value);
  const digits =
    asset === "USDC" || asset === "USDT" ? 8 : asset === "MAX" ? 4 : 6;
  const formatted = new Intl.NumberFormat(undefined, {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  }).format(abs);
  const prefix = value < 0 ? "-" : value > 0 ? "" : "";
  return `${prefix}${formatted} ${asset}`;
}

export function vaultFundsRowToPortfolio(
  row: VaultFundsMovementRow,
  vaultName: string,
): PortfolioFundsMovementRow {
  return {
    id: `vault-overlay-${row.vaultId}-${row.time}-${row.action}-${row.txHash}`,
    walletAddress: row.walletAddress,
    time: row.time,
    status: row.status,
    action: row.action,
    source: row.source,
    destination: row.destination || vaultName,
    amount: row.accountValueChangeUsd,
    asset: "USDC",
    fee: row.feeUsd,
    txHash: row.txHash,
    vaultId: row.vaultId,
  };
}

export function crossChainRecordToPortfolio(
  record: CrossChainTransferRecord,
): PortfolioFundsMovementRow | null {
  if (record.currentStage !== "complete" && !record.completedAt) {
    return null;
  }

  const completedAt = record.completedAt ?? record.startedAt;
  const isDeposit = record.mode === "deposit";
  const signedAmount = isDeposit ? record.amount : -record.amount;

  return {
    id: `xchain-${record.id}`,
    walletAddress: "",
    time: completedAt,
    status: "Completed",
    action: isDeposit ? "Deposit" : "Withdraw",
    source: isDeposit ? record.chain : TRADING_ACCOUNT,
    destination: isDeposit ? TRADING_ACCOUNT : record.chain,
    amount: signedAmount,
    asset: record.assetId.toUpperCase(),
    fee: null,
    txHash: record.destinationTxHash ?? record.originTxHash,
  };
}

export function mergePortfolioFundsMovements(
  ...arrays: PortfolioFundsMovementRow[][]
): PortfolioFundsMovementRow[] {
  if (arrays.length === 0) return [];

  const [seed = [], ...overlays] = arrays;
  const overlayRows = overlays.flat();
  const overlayTxHashes = new Set(
    overlayRows
      .map((row) => row.txHash?.trim().toLowerCase())
      .filter((hash): hash is string => Boolean(hash)),
  );

  const filteredSeed = seed.filter((row) => {
    const hash = row.txHash?.trim().toLowerCase();
    return !hash || !overlayTxHashes.has(hash);
  });

  const byId = new Map<string, PortfolioFundsMovementRow>();
  for (const row of [...filteredSeed, ...overlayRows]) {
    byId.set(row.id, row);
  }

  return [...byId.values()].sort((a, b) => b.time - a.time);
}

function csvEscape(value: string): string {
  if (/[",\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportPortfolioFundsCsv(
  rows: PortfolioFundsMovementRow[],
): string {
  const header = [
    "Time",
    "Status",
    "Action",
    "Source",
    "Destination",
    "Account Value Change",
    "Fee",
  ].join(",");

  const lines = rows.map((row) => {
    const change = formatPortfolioFundsAmount(row.amount, row.asset);
    const fee =
      row.fee == null ? "--" : formatPortfolioFundsAmount(row.fee, row.asset);
    return [
      csvEscape(formatPortfolioFundsDateTime(row.time)),
      csvEscape(row.status),
      csvEscape(row.action),
      csvEscape(row.source),
      csvEscape(row.destination),
      csvEscape(change),
      csvEscape(fee),
    ].join(",");
  });

  return [header, ...lines].join("\n");
}

export function collectWalletVaultFundsMovements(
  walletAddress: string,
  vaultIds: string[],
  getMovements: (wallet: string, vaultId: string) => VaultFundsMovementRow[],
  getVaultName: (vaultId: string) => string,
): PortfolioFundsMovementRow[] {
  if (!walletAddress.trim()) return [];
  const rows: PortfolioFundsMovementRow[] = [];
  for (const vaultId of vaultIds) {
    const movements = getMovements(walletAddress, vaultId);
    const vaultName = getVaultName(vaultId);
    for (const movement of movements) {
      rows.push(vaultFundsRowToPortfolio(movement, vaultName));
    }
  }
  return rows;
}

export function recordCrossChainPortfolioMovement(
  wallet: string,
  record: CrossChainTransferRecord,
): PortfolioFundsMovementRow | null {
  const row = crossChainRecordToPortfolio(record);
  if (!row || !wallet.trim()) return null;

  const persisted = {
    ...row,
    walletAddress: wallet.trim(),
  };
  appendPortfolioFundsMovement(wallet, persisted);
  return persisted;
}

export function shouldClearCrossChainTransferOnReset(
  record: CrossChainTransferRecord | null | undefined,
): boolean {
  if (!record?.id) return false;
  return record.currentStage !== "complete" && !record.completedAt;
}
