import type {
  VaultActivityFile,
  VaultActivityManifest,
} from "../../../../offline/mock_data/vaultActivityHistory.types";
import {
  clearVaultActivityCache as clearSharedVaultActivityCache,
  getCachedVaultActivityById as getSharedCachedVaultActivityById,
  isVaultActivityKnown,
  markVaultActivityMissing,
  setCachedVaultActivity,
} from "../../../../offline/mock_data/vaultActivityCache";
import { VAULT_ACTIVITY_MANIFEST_SNAPSHOT } from "../../../../offline/mock_data/vaultActivityManifestSnapshot";

export const VAULT_ACTIVITY_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_VAULT_ACTIVITY_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/vault-activity";

let manifestCache: VaultActivityManifest | null = null;
let manifestPromise: Promise<VaultActivityManifest> | null = null;
const historyPromises = new Map<string, Promise<VaultActivityFile | null>>();

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function clearVaultActivityCache(): void {
  manifestCache = null;
  manifestPromise = null;
  historyPromises.clear();
  clearSharedVaultActivityCache();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export async function fetchVaultActivityManifest(
  baseUrl: string = VAULT_ACTIVITY_DATA_BASE_URL,
): Promise<VaultActivityManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<VaultActivityManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  )
    .then((manifest) => {
      manifestCache = manifest;
      return manifest;
    })
    .catch(() => {
      manifestCache = VAULT_ACTIVITY_MANIFEST_SNAPSHOT;
      return VAULT_ACTIVITY_MANIFEST_SNAPSHOT;
    })
    .finally(() => {
      manifestPromise = null;
    });

  return manifestPromise;
}

export function getCachedVaultActivityManifest(): VaultActivityManifest | null {
  return manifestCache;
}

export function getManifestVaultById(
  manifest: VaultActivityManifest,
  vaultId: string,
): VaultActivityManifest["vaults"][number] | undefined {
  const normalized = vaultId.trim().toLowerCase();
  return manifest.vaults.find(
    (entry) => entry.vaultId.toLowerCase() === normalized,
  );
}

export async function fetchVaultActivityById(
  vaultId: string,
  baseUrl: string = VAULT_ACTIVITY_DATA_BASE_URL,
): Promise<VaultActivityFile | null> {
  const normalizedId = vaultId.trim();
  const cacheKey = normalizedId.toLowerCase();

  const cached = getSharedCachedVaultActivityById(normalizedId);
  if (cached) return cached;

  const inflight = historyPromises.get(cacheKey);
  if (inflight) return inflight;

  const promise = (async () => {
    try {
      const manifest = await fetchVaultActivityManifest(baseUrl);
      const entry = getManifestVaultById(manifest, normalizedId);
      if (!entry) {
        markVaultActivityMissing(normalizedId);
        return null;
      }

      const payload = await fetchJson<VaultActivityFile>(
        joinBaseUrl(baseUrl, entry.file),
      );
      setCachedVaultActivity(normalizedId, payload);
      return payload;
    } catch (err) {
      if (err instanceof Error && err.message.includes("HTTP 404")) {
        markVaultActivityMissing(normalizedId);
        return null;
      }
      throw err;
    }
  })().finally(() => {
    historyPromises.delete(cacheKey);
  });

  historyPromises.set(cacheKey, promise);
  return promise;
}

export function getCachedVaultActivityById(
  vaultId: string,
): VaultActivityFile | null {
  return getSharedCachedVaultActivityById(vaultId);
}

export function isVaultActivityLoaded(vaultId: string): boolean {
  return isVaultActivityKnown(vaultId.trim());
}

export { subscribeVaultActivityCache } from "../../../../offline/mock_data/vaultActivityCache";
