export function formatStakingMormAmount(amount: number): string {
  return amount.toLocaleString(undefined, { maximumFractionDigits: 4 });
}

export function formatValidatorStake(amount: number): string {
  return amount.toLocaleString(undefined, { maximumFractionDigits: 0 });
}

export function formatValidatorPct(value: number): string {
  return `${value.toFixed(2)}%`;
}

export function formatYourStake(amount: number | null): string {
  if (amount == null || amount <= 0) return "-";
  return formatValidatorStake(amount);
}

export function formatStakingCountdown(msRemaining: number): string {
  if (msRemaining <= 0) return "Ready to claim";
  const totalSeconds = Math.ceil(msRemaining / 1000);
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (days > 0) {
    return `${days}d ${hours}h ${minutes}m`;
  }
  if (hours > 0) {
    return `${hours}h ${minutes}m ${seconds}s`;
  }
  return `${minutes}m ${seconds}s`;
}
