import { useMemo, useState } from "react";

import type { VaultPositionRow } from "../../offline/mock_data/vaultCatalog";

export type VaultPositionSortKey =
  | "positionValue"
  | "market"
  | "unrealizedPnl"
  | "margin";

export function useVaultBucketPositions(allPositions: VaultPositionRow[]) {
  const [query, setQuery] = useState("");
  const [sideFilter, setSideFilter] = useState<"all" | "long" | "short">("all");
  const [marketFilter, setMarketFilter] = useState<string>("all");
  const [sortKey, setSortKey] = useState<VaultPositionSortKey>("positionValue");
  const [sortDir, setSortDir] = useState<"asc" | "desc">("desc");
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);

  const markets = useMemo(() => {
    const set = new Set(allPositions.map((p) => p.market));
    return Array.from(set).sort();
  }, [allPositions]);

  const filtered = useMemo(() => {
    let rows = [...allPositions];
    const q = query.trim().toLowerCase();
    if (q) {
      rows = rows.filter((p) => p.market.toLowerCase().includes(q));
    }
    if (sideFilter !== "all") {
      rows = rows.filter((p) => p.side === sideFilter);
    }
    if (marketFilter !== "all") {
      rows = rows.filter((p) => p.market === marketFilter);
    }
    rows.sort((a, b) => {
      let cmp = 0;
      if (sortKey === "positionValue") cmp = a.positionValueUsd - b.positionValueUsd;
      else if (sortKey === "market") cmp = a.market.localeCompare(b.market);
      else if (sortKey === "unrealizedPnl") cmp = a.unrealizedPnlUsd - b.unrealizedPnlUsd;
      else cmp = a.marginUsd - b.marginUsd;
      return sortDir === "desc" ? -cmp : cmp;
    });
    return rows;
  }, [allPositions, query, sideFilter, marketFilter, sortKey, sortDir]);

  const allTotals = useMemo(
    () =>
      allPositions.reduce(
        (acc, p) => ({
          count: acc.count + 1,
          positionValueUsd: acc.positionValueUsd + p.positionValueUsd,
          unrealizedPnlUsd: acc.unrealizedPnlUsd + p.unrealizedPnlUsd,
          marginUsd: acc.marginUsd + p.marginUsd,
        }),
        { count: 0, positionValueUsd: 0, unrealizedPnlUsd: 0, marginUsd: 0 },
      ),
    [allPositions],
  );

  const totals = useMemo(
    () =>
      filtered.reduce(
        (acc, p) => ({
          count: acc.count + 1,
          positionValueUsd: acc.positionValueUsd + p.positionValueUsd,
          unrealizedPnlUsd: acc.unrealizedPnlUsd + p.unrealizedPnlUsd,
          marginUsd: acc.marginUsd + p.marginUsd,
        }),
        { count: 0, positionValueUsd: 0, unrealizedPnlUsd: 0, marginUsd: 0 },
      ),
    [filtered],
  );

  const pageRows = useMemo(() => {
    const start = page * pageSize;
    return filtered.slice(start, start + pageSize);
  }, [filtered, page, pageSize]);

  return {
    query,
    setQuery,
    sideFilter,
    setSideFilter,
    marketFilter,
    setMarketFilter,
    sortKey,
    setSortKey,
    sortDir,
    setSortDir,
    page,
    setPage,
    pageSize,
    setPageSize,
    markets,
    filtered,
    pageRows,
    totalCount: filtered.length,
    totals,
    allTotals,
  };
}
