import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

import { vaultDetailPath } from "../routes";
import {
  getBrowserLocationKey,
  runAfterPreNavigateCleanup,
  subscribeBrowserPathname,
} from "../utils/preNavigateCleanup";
import {
  ensureVaultRegistryHydrated,
  getVaultById,
  type VaultBucketSummary,
  type VaultRecord,
} from "../../offline/mock_data/vaultCatalog";
import { useOnboard } from "../hooks/useOnboard";
import { isVaultOwner } from "../hooks/vaultOwnership";
import {
  ensureVaultOperateHydrated,
  getVaultBucketLive,
  getVaultOperateStateRevision,
  subscribeVaultOperateState,
} from "../../offline/mock_data/vaultOperateState";
import {
  getRegistryRevision,
  subscribeVaultRegistry,
} from "../../offline/mock_data/vaultRegistryStorage";

const VAULT_QUERY_KEY = "vault";

/** Read ?vault= from the browser URL — authoritative when React Router search stalls. */
function getBrowserVaultId(): string | null {
  if (typeof window === "undefined") return null;
  return new URLSearchParams(window.location.search).get(VAULT_QUERY_KEY);
}

function pickDefaultBucket(vault: VaultRecord): string | null {
  if (vault.buckets.length === 0) return null;
  return vault.buckets.reduce((best, bucket) =>
    bucket.equityUsd > best.equityUsd ? bucket : best,
  ).id;
}

export interface VaultOperateContextValue {
  vaultId: string | null;
  vault: VaultRecord | null;
  selectedBucketId: string | null;
  selectedBucket: VaultBucketSummary | null;
  isActive: boolean;
  enterOperate: (vaultId: string) => boolean;
  switchVault: (vaultId: string) => boolean;
  exitToVaultHome: () => void;
  selectBucket: (bucketId: string | null) => void;
}

const VaultOperateContext = createContext<VaultOperateContextValue | undefined>(
  undefined,
);

export function VaultOperateProvider({
  children,
}: {
  children: ReactNode;
}): JSX.Element {
  const { walletAddress } = useOnboard();
  const navigate = useNavigate();
  const [, setSearchParams] = useSearchParams();
  const [selectedBucketId, setSelectedBucketId] = useState<string | null>(null);

  const browserLocationKey = useSyncExternalStore(
    subscribeBrowserPathname,
    getBrowserLocationKey,
    getBrowserLocationKey,
  );

  const vaultId = useMemo(() => {
    void browserLocationKey;
    return getBrowserVaultId();
  }, [browserLocationKey]);

  const registryRevision = useSyncExternalStore(
    subscribeVaultRegistry,
    getRegistryRevision,
    getRegistryRevision,
  );

  useEffect(() => {
    ensureVaultRegistryHydrated();
    ensureVaultOperateHydrated(vaultId);
  }, [vaultId]);

  const vault = useMemo(() => {
    void registryRevision;
    if (!vaultId) return null;
    return getVaultById(vaultId) ?? null;
  }, [vaultId, registryRevision]);

  const isActive = vault != null && isVaultOwner(walletAddress, vault);

  useEffect(() => {
    if (!vaultId) {
      setSelectedBucketId(null);
      return;
    }
    if (!vault || !isVaultOwner(walletAddress, vault)) {
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          next.delete(VAULT_QUERY_KEY);
          return next;
        },
        { replace: true },
      );
      setSelectedBucketId(null);
      return;
    }
    setSelectedBucketId((current) => {
      if (current && vault.buckets.some((b) => b.id === current)) {
        return current;
      }
      return pickDefaultBucket(vault);
    });
  }, [vaultId, vault, walletAddress, setSearchParams]);

  const enterOperate = useCallback(
    (id: string): boolean => {
      const target = getVaultById(id);
      if (!target || !isVaultOwner(walletAddress, target)) return false;
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          next.set(VAULT_QUERY_KEY, id);
          return next;
        },
        { replace: false },
      );
      setSelectedBucketId(pickDefaultBucket(target));
      return true;
    },
    [walletAddress, setSearchParams],
  );

  const switchVault = useCallback(
    (id: string): boolean => {
      return enterOperate(id);
    },
    [enterOperate],
  );

  const exitToVaultHome = useCallback(() => {
    if (!vaultId) return;
    setSelectedBucketId(null);
    runAfterPreNavigateCleanup(() => {
      navigate(vaultDetailPath(vaultId), { replace: true });
    });
  }, [vaultId, navigate]);

  const selectBucket = useCallback((bucketId: string | null) => {
    setSelectedBucketId(bucketId);
  }, []);

  const operateRevision = useSyncExternalStore(
    subscribeVaultOperateState,
    getVaultOperateStateRevision,
    getVaultOperateStateRevision,
  );

  const selectedBucket = useMemo(() => {
    void operateRevision;
    if (!vaultId || !selectedBucketId) return null;
    return getVaultBucketLive(vaultId, selectedBucketId);
  }, [vaultId, selectedBucketId, operateRevision]);

  const value = useMemo(
    (): VaultOperateContextValue => ({
      vaultId: isActive ? vaultId : null,
      vault: isActive ? vault : null,
      selectedBucketId: isActive ? selectedBucketId : null,
      selectedBucket: isActive ? selectedBucket : null,
      isActive,
      enterOperate,
      switchVault,
      exitToVaultHome,
      selectBucket,
    }),
    [
      isActive,
      vaultId,
      vault,
      selectedBucketId,
      selectedBucket,
      enterOperate,
      switchVault,
      exitToVaultHome,
      selectBucket,
    ],
  );

  return (
    <VaultOperateContext.Provider value={value}>
      {children}
    </VaultOperateContext.Provider>
  );
}

export function useVaultOperate(): VaultOperateContextValue {
  const ctx = useContext(VaultOperateContext);
  if (!ctx) {
    throw new Error("useVaultOperate must be used within VaultOperateProvider");
  }
  return ctx;
}

export function useOptionalVaultOperate():
  | VaultOperateContextValue
  | undefined {
  return useContext(VaultOperateContext);
}
