import { useMemo, useSyncExternalStore } from "react";
import {
  getVaultOperateStateRevision,
  getVaultOrderHistoryOverlay,
  subscribeVaultOperateState,
} from "../../offline/mock_data/vaultOperateState";
import type { VaultOrderHistoryRow } from "../../offline/mock_data/vaultMockData.types";

export function useVaultOrderHistory(
  vaultId: string,
  bucketId?: string,
): VaultOrderHistoryRow[] {
  const revision = useSyncExternalStore(
    subscribeVaultOperateState,
    getVaultOperateStateRevision,
    getVaultOperateStateRevision,
  );

  return useMemo(() => {
    void revision;
    return getVaultOrderHistoryOverlay(vaultId, bucketId);
  }, [vaultId, bucketId, revision]);
}
