import React from "react";

import { formatCurrency } from "../../sdk/utils/display";
import "./staking.css";

export interface StakingRewardsPanelProps {
  usdcYieldPaidToDate: number;
  claimableUsdc: number;
  enableUsdcYield: boolean;
  onClaim?: () => void;
}

function StakingRewardsPanel({
  usdcYieldPaidToDate,
  claimableUsdc,
  enableUsdcYield,
  onClaim,
}: StakingRewardsPanelProps): JSX.Element {
  const canClaim = enableUsdcYield && claimableUsdc > 0;

  return (
    <div className="staking-rewards-panel">
      <p className="terminal-value">
        {usdcYieldPaidToDate > 0
          ? `$${formatCurrency(usdcYieldPaidToDate)} paid to date`
          : "$0 paid to date. Yield starts once protocol revenue is live."}
      </p>
      <p className="terminal-label">
        Real USDC from protocol revenue — not emissions.
      </p>
      <button
        type="button"
        className="btn btn-primary"
        disabled={!canClaim}
        onClick={onClaim}
      >
        Claim
      </button>
    </div>
  );
}

export default React.memo(StakingRewardsPanel);
