import React from "react";

import type { AgentListingType, TradingAgent } from "../../../store/types";
import type {
  DeployAgentWizardState,
  DeployPerAgentDetails,
} from "../../../utils/deployAgent";
import {
  DEPLOY_LISTING_CATEGORY_OPTIONS,
  computeDeployEligibility,
  getAgentMarketSymbol,
  resolveDefaultListingType,
} from "../../../utils/deployAgent";

const LISTING_TYPE_LABELS: Record<AgentListingType, string> = {
  profile: "Profile / discovery",
  service: "Service (x402)",
  vault: "Vault / allocatable",
};

export interface DeployAgentStepDetailsProps {
  agents: TradingAgent[];
  state: DeployAgentWizardState;
  onChange: (patch: Partial<DeployAgentWizardState>) => void;
}

export default function DeployAgentStepDetails({
  agents,
  state,
  onChange,
}: DeployAgentStepDetailsProps): JSX.Element {
  const selectedAgents = state.selectedAgentIds
    .map((id) => agents.find((agent) => agent.id === id))
    .filter((agent): agent is TradingAgent => Boolean(agent));

  const patchPerAgent = (agentId: string, patch: Partial<DeployPerAgentDetails>) => {
    onChange({
      perAgent: {
        ...state.perAgent,
        [agentId]: {
          ...state.perAgent[agentId],
          description: state.perAgent[agentId]?.description ?? "",
          ...patch,
        },
      },
    });
  };

  return (
    <div className="deploy-agent-step">
      <div className="deploy-agent-batch-fields">
        <label className="deploy-agent-field">
          <span className="terminal-label">Category (batch)</span>
          <select
            className="form-input transfer-select deploy-agent-select"
            value={state.batchCategory}
            onChange={(e) => onChange({ batchCategory: e.target.value })}
          >
            <option value="">Select category…</option>
            {DEPLOY_LISTING_CATEGORY_OPTIONS.map((category) => (
              <option key={category} value={category}>
                {category}
              </option>
            ))}
          </select>
        </label>

        <fieldset className="deploy-agent-target-fieldset">
          <legend className="terminal-label">Visibility</legend>
          <label className="deploy-agent-radio">
            <input
              type="radio"
              name="deploy-visibility"
              checked={state.batchVisibility === "public"}
              onChange={() => onChange({ batchVisibility: "public" })}
            />
            <span>Public</span>
          </label>
          <label className="deploy-agent-radio">
            <input
              type="radio"
              name="deploy-visibility"
              checked={state.batchVisibility === "preview"}
              onChange={() => onChange({ batchVisibility: "preview" })}
            />
            <span>Unlisted preview</span>
          </label>
        </fieldset>
      </div>

      <div className="deploy-agent-per-agent">
        <p className="terminal-label deploy-agent-per-agent-heading">Per agent</p>
        {selectedAgents.map((agent) => {
          const eligibility = computeDeployEligibility(agent);
          const details = state.perAgent[agent.id] ?? {
            description: "",
            listingType: resolveDefaultListingType(agent, eligibility),
          };
          const symbol = getAgentMarketSymbol(agent);
          const showListingType = eligibility.allowedListingTypes.length > 1;

          return (
            <div key={agent.id} className="deploy-agent-agent-row">
              <p className="terminal-value deploy-agent-agent-row-name">
                {agent.displayName}
              </p>
              <label className="deploy-agent-field">
                <span className="terminal-label">Symbol</span>
                <span className="terminal-value">{symbol}</span>
              </label>
              {showListingType ? (
                <label className="deploy-agent-field">
                  <span className="terminal-label">Listing type</span>
                  <select
                    className="form-input transfer-select deploy-agent-select"
                    value={details.listingType ?? "profile"}
                    onChange={(e) =>
                      patchPerAgent(agent.id, {
                        listingType: e.target.value as AgentListingType,
                      })
                    }
                  >
                    {eligibility.allowedListingTypes.map((type) => (
                      <option key={type} value={type}>
                        {LISTING_TYPE_LABELS[type]}
                      </option>
                    ))}
                  </select>
                </label>
              ) : null}
              <label className="deploy-agent-field deploy-agent-field--full">
                <span className="terminal-label">Description</span>
                <textarea
                  className="form-input deploy-agent-textarea"
                  rows={2}
                  value={details.description}
                  placeholder="Short public blurb…"
                  onChange={(e) =>
                    patchPerAgent(agent.id, { description: e.target.value })
                  }
                />
              </label>
            </div>
          );
        })}
      </div>
    </div>
  );
}
