import { resolveGridBreakpoint } from "../../components/smartlayout/util";
import { vaultBucketPath, vaultDetailPath } from "../../routes";
import type { VaultTourGateKind } from "./constants";
import {
  VAULT_TOUR_BUCKET_ID,
  VAULT_TOUR_VAULT_ID,
} from "./constants";

export type VaultTourStepContentNavigateBefore = "vaultDetail" | "vaultBucket";

export function inferTourBreakpointFromWidth(width: number): string {
  return resolveGridBreakpoint(width);
}

export function vaultTourDetailPath(): string {
  return vaultDetailPath(VAULT_TOUR_VAULT_ID);
}

export function vaultTourBucketPath(): string {
  return vaultBucketPath(VAULT_TOUR_VAULT_ID, VAULT_TOUR_BUCKET_ID);
}

export function resolveVaultTourNavigateBefore(
  navigateBefore: VaultTourStepContentNavigateBefore | undefined,
): string | null {
  if (navigateBefore === "vaultDetail") return vaultTourDetailPath();
  if (navigateBefore === "vaultBucket") return vaultTourBucketPath();
  return null;
}

export function isVaultTourDetailRoute(pathname: string): boolean {
  const target = vaultTourDetailPath();
  return pathname === target || pathname.startsWith(`${target}/`);
}

export function isVaultTourBucketRoute(pathname: string): boolean {
  return pathname === vaultTourBucketPath();
}

export function isVaultTourGateSatisfied(
  gateKind: VaultTourGateKind | undefined,
  pathname: string,
): boolean {
  if (!gateKind) return true;
  if (gateKind === "bucketRoute") {
    return isVaultTourBucketRoute(pathname);
  }
  return true;
}
