import { useCallback, useMemo, useState } from "react";

import { OFFLINE_STAKING_STABLE_TOAST_ID } from "../../offline/mock_data/offlineStakingSteps";
import { useWalletConnectRequest } from "../context/WalletConnectHostContext";
import { executeOfflineStakeFunds } from "../utils/executeOfflineStakeFunds";
import { formatStakingMormAmount } from "../components/staking/stakingFormat";
import { isWalletConnected } from "../utils/walletConnection";
import { createErrorCopyAction } from "../components/ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  toastUpdateLoading,
} from "../components/ui/toastTask";

export type StakingFundsMode = "stake" | "unstake";

type CtaKind =
  | "connect"
  | "enter_amount"
  | "insufficient"
  | "approve"
  | "submit"
  | "submitting";

export interface UseStakingFundsSubmitOptions {
  mode: StakingFundsMode;
  amount: number;
  stakedMorm: number;
  walletMormAvailable: number;
  walletAddress: string;
  onSuccess?: () => void;
}

export function useStakingFundsSubmit({
  mode,
  amount,
  stakedMorm,
  walletMormAvailable,
  walletAddress,
  onSuccess,
}: UseStakingFundsSubmitOptions): {
  ctaLabel: string;
  ctaDisabled: boolean;
  ctaKind: CtaKind;
  isSubmitting: boolean;
  handlePrimaryClick: () => void;
} {
  const requestConnect = useWalletConnectRequest();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [needsApprove, setNeedsApprove] = useState(false);

  const connected = isWalletConnected(walletAddress);
  const available = mode === "stake" ? walletMormAvailable : stakedMorm;

  const cta = useMemo((): { kind: CtaKind; label: string; disabled: boolean } => {
    if (isSubmitting) {
      return {
        kind: "submitting",
        label: mode === "stake" ? "Staking…" : "Unstaking…",
        disabled: true,
      };
    }
    if (!connected) {
      return { kind: "connect", label: "Connect Wallet", disabled: false };
    }
    if (amount <= 0) {
      return { kind: "enter_amount", label: "Enter an amount", disabled: true };
    }
    if (amount > available) {
      return {
        kind: "insufficient",
        label: "Insufficient balance",
        disabled: true,
      };
    }
    if (mode === "stake" && needsApprove) {
      return { kind: "approve", label: "Approve MORM", disabled: false };
    }
    return {
      kind: "submit",
      label: mode === "stake" ? "Stake" : "Unstake",
      disabled: false,
    };
  }, [amount, available, connected, isSubmitting, mode, needsApprove]);

  const runSubmit = useCallback(async () => {
    const toastId = toastLoading(
      mode === "stake" ? "Staking MORM…" : "Unstaking MORM…",
      {
        stableId: OFFLINE_STAKING_STABLE_TOAST_ID,
        description: "Signing transaction…",
      },
    );
    setIsSubmitting(true);

    try {
      await executeOfflineStakeFunds(
        {
          wallet: walletAddress,
          mode,
          amountMorm: amount,
        },
        {
          onStepStart: (step) => {
            toastUpdateLoading(toastId, step.loadingMessage, {
              description: step.loadingDescription,
            });
          },
        },
      );

      toastCompleteSuccess(
        toastId,
        mode === "stake" ? "Stake completed" : "Unstake queued",
        {
          description: `${formatStakingMormAmount(amount)} MORM ${
            mode === "stake" ? "staked" : "entering 7-day unbonding"
          }`,
        },
      );
      onSuccess?.();
    } catch (err) {
      const msg = err instanceof Error ? err.message : "Transaction failed";
      toastCompleteError(toastId, "Transaction failed", {
        description: msg,
        action: createErrorCopyAction(msg),
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [amount, mode, onSuccess, walletAddress]);

  const handlePrimaryClick = useCallback(() => {
    if (cta.disabled) return;

    if (cta.kind === "connect") {
      requestConnect?.();
      return;
    }

    if (cta.kind === "approve") {
      setNeedsApprove(false);
      return;
    }

    if (cta.kind === "submit") {
      void runSubmit();
    }
  }, [cta.disabled, cta.kind, requestConnect, runSubmit]);

  return {
    ctaLabel: cta.label,
    ctaDisabled: cta.disabled,
    ctaKind: cta.kind,
    isSubmitting,
    handlePrimaryClick,
  };
}
