import React from "react";
import { resolveTabStripOrder, TERMINAL_TAB_STRIP } from "../smartlayout";
import TabSection, {
  type TabSectionProps,
  type TabSectionTabId,
} from "../tables/TabSection";

const { tabIds: terminalTabIds } = resolveTabStripOrder(TERMINAL_TAB_STRIP);

export const PORTFOLIO_TAB_ORDER: TabSectionTabId[] = [
  "agentTasks",
  "balances",
  "depositsWithdrawals",
  ...(terminalTabIds.filter((id) => id !== "agentTasks") as TabSectionTabId[]),
];

export type PortfolioTabSectionProps = Omit<
  TabSectionProps,
  "tabOrder" | "defaultTab"
>;

function PortfolioTabSection(props: PortfolioTabSectionProps): JSX.Element {
  return (
    <TabSection
      {...props}
      tabOrder={PORTFOLIO_TAB_ORDER}
      defaultTab="agentTasks"
    />
  );
}

export default React.memo(PortfolioTabSection);
