import type { VaultActivityRow } from "../../../offline/mock_data/vaultMockData.types";
import { activityTypeLabel } from "../../../offline/mock_data/vaultActivityUtils";
import { shortHashId } from "../../utils/hashId";

export function formatVaultActivitySource(row: VaultActivityRow): string {
  if (row.sourceKind === "bucket" && row.bucketId) {
    return shortHashId(row.bucketId);
  }
  return row.sourceLabel ?? "—";
}

export function vaultActivitySourceTitle(row: VaultActivityRow): string | undefined {
  if (row.sourceKind === "bucket" && row.bucketId) {
    return row.bucketId;
  }
  return row.sourceLabel;
}

export { activityTypeLabel };
