import React, { useMemo, useState } from "react";

import {
  useStakingFundsSubmit,
  type StakingFundsMode,
} from "../../hooks/useStakingFundsSubmit";
import {
  formatStakingPanelPreviewLine,
} from "../../utils/stakingFeeSchedule";
import { TabLayoutHeaderToolBar, type TabLayoutHeaderToolBarTab } from "../smartlayout/tab-layout-header-toolbar";
import { formatStakingMormAmount } from "./stakingFormat";
import "../tables/TabSection.css";
import "./staking.css";

const STAKING_MODE_TABS: TabLayoutHeaderToolBarTab[] = [
  { id: "stake", label: "Stake" },
  { id: "unstake", label: "Unstake" },
];

export interface StakingPrimaryPanelProps {
  height?: string;
  stakedMorm: number;
  walletMormAvailable: number;
  walletAddress: string;
  onSuccess?: () => void;
}

function parseAmountInput(value: string): number {
  const parsed = Number.parseFloat(value.replace(/,/g, ""));
  return Number.isFinite(parsed) ? parsed : 0;
}

function StakingPrimaryPanel({
  height = "100%",
  stakedMorm,
  walletMormAvailable,
  walletAddress,
  onSuccess,
}: StakingPrimaryPanelProps): JSX.Element {
  const [mode, setMode] = useState<StakingFundsMode>("stake");
  const [amountInput, setAmountInput] = useState("");

  const amount = useMemo(() => parseAmountInput(amountInput), [amountInput]);
  const available = mode === "stake" ? walletMormAvailable : stakedMorm;

  const previewLine = useMemo(
    () => formatStakingPanelPreviewLine(stakedMorm, amount, mode),
    [amount, mode, stakedMorm],
  );

  const { ctaLabel, ctaDisabled, isSubmitting, handlePrimaryClick } =
    useStakingFundsSubmit({
      mode,
      amount,
      stakedMorm,
      walletMormAvailable,
      walletAddress,
      onSuccess: () => {
        setAmountInput("");
        onSuccess?.();
      },
    });

  const handleMax = () => {
    setAmountInput(String(available));
  };

  return (
    <div
      className="staking-slot staking-slot--flush staking-panel-band staking-panel-band--primary"
      style={{ height }}
    >
      <section className="staking-panel" aria-label="Stake or unstake MORM">
        <TabLayoutHeaderToolBar
          tabs={STAKING_MODE_TABS}
          activeTabId={mode}
          onTabChange={(id) => {
            if (!isSubmitting) {
              setMode(id as StakingFundsMode);
            }
          }}
        />

        <div className="staking-panel-body">
          <label className="terminal-label" htmlFor="staking-amount">
            Amount
          </label>
          <div className="staking-amount-row">
            <input
              id="staking-amount"
              className="form-input staking-amount-input"
              value={amountInput}
              onChange={(event) => setAmountInput(event.target.value)}
              inputMode="decimal"
              placeholder="0"
              disabled={isSubmitting}
            />
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleMax}
              disabled={isSubmitting}
            >
              MAX
            </button>
          </div>

          <p className="terminal-label">
            {mode === "stake" ? "Available in wallet" : "Available to unstake"}:{" "}
            {formatStakingMormAmount(available)} MORM
          </p>

          {previewLine ? (
            <p className="staking-preview-line">{previewLine}</p>
          ) : null}

          {mode === "unstake" ? (
            <p className="staking-notice-line">
              Unstaking has a 7-day lockup. Pending unstakes appear in the Pending
              Unstakes tab.
            </p>
          ) : (
            <p className="staking-notice-line">
              Unstaking later has a 7-day lockup.
            </p>
          )}

          <button
            type="button"
            className="btn btn-primary staking-panel-cta"
            disabled={ctaDisabled}
            onClick={handlePrimaryClick}
          >
            {ctaLabel}
          </button>
        </div>
      </section>
    </div>
  );
}

export default React.memo(StakingPrimaryPanel);
