import React from "react";

import TerminalCompactSettingsButton from "../preference/TerminalCompactSettingsButton";
import StakingHeroViewNav from "./StakingHeroViewNav";
import type { StakingPageView } from "./stakingPageView";
import { DEFAULT_STAKING_PAGE_VIEW } from "./stakingPageView";
import "./staking.css";

export interface StakingHeroHeaderProps {
  height?: string;
  walletConnected?: boolean;
  activeView?: StakingPageView;
  onViewChange?: (view: StakingPageView) => void;
}

function noopViewChange(): void {}

function StakingHeroHeader({
  height = "100%",
  walletConnected = false,
  activeView = DEFAULT_STAKING_PAGE_VIEW,
  onViewChange = noopViewChange,
}: StakingHeroHeaderProps): JSX.Element {
  return (
    <div
      className={`staking-slot staking-header-band staking-hero-header${walletConnected ? "" : " staking-hero-header--disconnected"}`}
      style={{ height }}
    >
      {walletConnected ? (
        <div className="terminal-header-band-actions">
          <TerminalCompactSettingsButton
            focusSection="stakingEnableYield"
            ariaLabel="Staking settings"
          />
        </div>
      ) : null}
      <div className="staking-hero-header-content">
        <p className="eyebrow-text">Fee discount</p>
        <h1 className="staking-hero-title">Staking</h1>
      </div>
      {walletConnected ? (
        <StakingHeroViewNav activeView={activeView} onViewChange={onViewChange} />
      ) : null}
    </div>
  );
}

export default React.memo(StakingHeroHeader);
