import { useCallback, useEffect, useMemo, useState } from "react";
import { InfoClient } from "../sdk";
import { toNumberFromSatoshi } from "../sdk/utils/math";
import {
  LEVERAGE_DEFAULT,
  POSITION_MODE_ONE_WAY,
  MARGIN_MODE_CROSS,
  ORDER_TYPE_MARKET,
} from "../constants";
import type { TradeOperationConfig, TradeResult } from "../sdk/types/data";
import { useMarkets } from "./useMarkets";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import { getMockMarketPrice } from "../../offline/mock_data";
import {
  changeVaultLeverage,
  placeVaultOrder,
} from "../../offline/mock_data/vaultOperateState";
import { parseVaultBucketTradeId } from "../components/vault/vaultBucketTradeAdapter";

export function useVaultTradeOperation(config: TradeOperationConfig) {
  const [infoClient, setInfoClient] = useState<InfoClient | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<TradeResult | null>(null);

  const [orderType, setOrderType] = useState<"market" | "limit">(
    ORDER_TYPE_MARKET,
  );
  const [fundPercent, setFundPercent] = useState<number>(0);
  const [sizeInput, setSizeInput] = useState<number>(0);
  const [price, setPrice] = useState<number>(0);
  const [leverage, setLeverage] = useState<number>(LEVERAGE_DEFAULT);
  const [positionMode, setPositionMode] = useState<"ONE_WAY" | "HEDGE">(
    POSITION_MODE_ONE_WAY,
  );
  const [marginMode, setMarginMode] = useState<"CROSS" | "ISOLATED">(
    MARGIN_MODE_CROSS,
  );
  const [currentPrice, setCurrentPrice] = useState<number>(0);
  const [marketId, setMarketId] = useState<string>(
    config.marketId ? String(config.marketId) : "1",
  );

  const availableBalance = config.selectedBucketBalance ?? 0;
  const isReady = isOfflineMode(config.baseURL);

  useEffect(() => {
    setInfoClient(new InfoClient({ baseURL: config.baseURL }));
  }, [config.baseURL]);

  useEffect(() => {
    if (config.marketId) {
      setMarketId(String(config.marketId));
    }
  }, [config.marketId]);

  const { markets } = useMarkets({
    baseURL: config.baseURL,
    autoFetchMarkets: true,
  });

  const { maxSizeLimit, minSizeLimit } = useMemo(() => {
    if (!marketId) return { maxSizeLimit: undefined, minSizeLimit: undefined };
    const market = markets.find((m) => m.marketIndex === marketId);
    return {
      maxSizeLimit: market?.maxSizeLimit
        ? toNumberFromSatoshi(market.maxSizeLimit)
        : undefined,
      minSizeLimit: market?.minSizeLimit
        ? toNumberFromSatoshi(market.minSizeLimit)
        : undefined,
    };
  }, [markets, marketId]);

  const loadMarketPrice = useCallback(async () => {
    if (isOfflineMode(config.baseURL)) {
      setCurrentPrice(getMockMarketPrice(marketId));
      return;
    }
    if (!infoClient) return;
    try {
      const ticker = await infoClient.getMarketStats(marketId);
      if (ticker?.lastPrice) {
        setCurrentPrice(toNumberFromSatoshi(ticker.lastPrice));
      }
    } catch (error) {
      console.error("Failed to load market price:", error);
    }
  }, [infoClient, marketId, config.baseURL]);

  useEffect(() => {
    if (isOfflineMode(config.baseURL) || infoClient) {
      void loadMarketPrice();
    }
  }, [isOfflineMode(config.baseURL), infoClient, loadMarketPrice]);

  const getOrderPrice = useCallback((): number => {
    if (orderType === "market") {
      return config.tradePrice && config.tradePrice > 0
        ? config.tradePrice
        : currentPrice;
    }
    return price || 0;
  }, [orderType, price, currentPrice, config.tradePrice]);

  const getAvailableTradeAmount = useCallback((): number => {
    return availableBalance * leverage;
  }, [availableBalance, leverage]);

  const calculateSize = useCallback((): number => {
    let size: number;
    if (sizeInput > 0) {
      size = sizeInput;
    } else {
      const availableTradeAmount = getAvailableTradeAmount();
      const sizeUSD = (availableTradeAmount * fundPercent) / 100;
      const orderPrice = getOrderPrice();
      if (orderPrice <= 0) return 0;
      size = sizeUSD / orderPrice;
    }
    if (minSizeLimit !== undefined && minSizeLimit > 0 && size < minSizeLimit) {
      return 0;
    }
    if (maxSizeLimit !== undefined && maxSizeLimit > 0 && size > maxSizeLimit) {
      return maxSizeLimit;
    }
    return size;
  }, [
    sizeInput,
    getAvailableTradeAmount,
    fundPercent,
    getOrderPrice,
    minSizeLimit,
    maxSizeLimit,
  ]);

  const calculateSizeUSD = useCallback((): number => {
    const size = calculateSize();
    const orderPrice = getOrderPrice();
    return size * orderPrice;
  }, [calculateSize, getOrderPrice]);

  const calculateValue = useCallback((): number => {
    return calculateSizeUSD();
  }, [calculateSizeUSD]);

  const calculateMargin = useCallback((): number => {
    const value = calculateValue();
    if (leverage <= 0) return value;
    return value / leverage;
  }, [calculateValue, leverage]);

  const resolveVaultScope = useCallback(() => {
    if (config.vaultId?.trim() && config.vaultBucketId?.trim()) {
      return {
        vaultId: config.vaultId,
        bucketId: config.vaultBucketId,
      };
    }
    const parsed = parseVaultBucketTradeId(config.selectedBucketId ?? "");
    if (!parsed) return null;
    return parsed;
  }, [config.vaultId, config.vaultBucketId, config.selectedBucketId]);

  const placeOrder = useCallback(
    async (side: "BUY" | "SELL") => {
      const scope = resolveVaultScope();
      if (!scope) {
        setResult({ success: false, error: "Vault bucket not selected" });
        return;
      }

      const size = calculateSize();
      if (size <= 0) {
        setResult({ success: false, error: "Invalid order size" });
        return;
      }

      const orderPrice = getOrderPrice();
      if (orderPrice <= 0) {
        setResult({
          success: false,
          error:
            orderType === "limit"
              ? "Invalid price for limit order"
              : "Market price not available",
        });
        return;
      }

      if (orderType === "limit" && !price) {
        setResult({ success: false, error: "Price is required for limit orders" });
        return;
      }

      setLoading(true);
      setResult(null);

      const response = placeVaultOrder({
        vaultId: scope.vaultId,
        bucketId: scope.bucketId,
        marketId,
        marketSymbol: config.marketSymbol,
        side,
        orderType,
        size,
        price: orderPrice,
        markPrice:
          orderType === "limit"
            ? config.tradePrice && config.tradePrice > 0
              ? config.tradePrice
              : currentPrice
            : undefined,
        leverage,
      });

      setLoading(false);
      if (response.success) {
        setResult({
          success: true,
          orderId: response.orderId,
          message: `${side === "BUY" ? "Buy" : "Sell"} order placed successfully`,
        });
      } else {
        setResult({
          success: false,
          error: response.error ?? "Order failed",
        });
      }
    },
    [
      resolveVaultScope,
      calculateSize,
      getOrderPrice,
      orderType,
      price,
      marketId,
      config.marketSymbol,
      config.tradePrice,
      leverage,
      currentPrice,
    ],
  );

  const placeBuyOrder = useCallback(async () => placeOrder("BUY"), [placeOrder]);
  const placeSellOrder = useCallback(async () => placeOrder("SELL"), [placeOrder]);

  const changeLeverageFn = useCallback(
    async (
      newLeverage: number,
      options: {
        bucketId: string;
        leverageType?: string;
        reason?: string;
      },
    ): Promise<void> => {
      void options.leverageType;
      void options.reason;
      let vaultId = config.vaultId?.trim() ?? "";
      let bucketId = config.vaultBucketId?.trim() ?? "";
      if (!vaultId || !bucketId) {
        const parsed = parseVaultBucketTradeId(options.bucketId);
        if (!parsed) {
          setResult({ success: false, error: "Vault bucket not selected" });
          return;
        }
        vaultId = parsed.vaultId;
        bucketId = parsed.bucketId;
      }
      if (newLeverage <= 0) {
        setResult({ success: false, error: "Leverage must be greater than 0" });
        return;
      }

      setLoading(true);
      setResult(null);
      const response = changeVaultLeverage({
        vaultId,
        bucketId,
        marketId,
        marketSymbol: config.marketSymbol,
        leverage: newLeverage,
      });
      setLoading(false);

      if (response.success) {
        setLeverage(newLeverage);
        setResult({ success: true, message: "Leverage changed successfully" });
      } else {
        setResult({
          success: false,
          error: response.error ?? "Leverage change failed",
        });
      }
    },
    [marketId, config.marketSymbol, config.vaultId, config.vaultBucketId],
  );

  const handleFundPercentChange = useCallback(
    (percent: number) => {
      const availableTradeAmount = getAvailableTradeAmount();
      const orderPrice = getOrderPrice();
      const sizeUSD = (availableTradeAmount * percent) / 100;
      const size = orderPrice > 0 ? sizeUSD / orderPrice : 0;
      let roundedSize = size;
      if (
        minSizeLimit !== undefined &&
        minSizeLimit > 0 &&
        roundedSize < minSizeLimit
      ) {
        roundedSize = 0;
      }
      if (
        maxSizeLimit !== undefined &&
        maxSizeLimit > 0 &&
        roundedSize > maxSizeLimit
      ) {
        roundedSize = maxSizeLimit;
      }
      setFundPercent(percent);
      setSizeInput(roundedSize);
    },
    [getAvailableTradeAmount, getOrderPrice, minSizeLimit, maxSizeLimit],
  );

  const handleSizeInputChange = useCallback(
    (value: number) => {
      let numValue = Number.isNaN(value) || value < 0 ? 0 : value;
      if (
        maxSizeLimit !== undefined &&
        maxSizeLimit > 0 &&
        numValue > maxSizeLimit
      ) {
        numValue = maxSizeLimit;
      }
      setSizeInput(numValue);
      const availableTradeAmount = getAvailableTradeAmount();
      const orderPrice = getOrderPrice();
      if (numValue > 0 && availableTradeAmount > 0 && orderPrice > 0) {
        const sizeUSD = numValue * orderPrice;
        const percent = (sizeUSD / availableTradeAmount) * 100;
        setFundPercent(Math.min(100, Math.max(0, percent)));
      } else {
        setFundPercent(0);
      }
    },
    [getAvailableTradeAmount, getOrderPrice, maxSizeLimit],
  );

  const loadBalance = useCallback(async () => {
    /* vault balance comes from selectedBucketBalance prop */
  }, []);

  return {
    orderType,
    setOrderType,
    fundPercent,
    sizeInput,
    price,
    leverage,
    positionMode,
    marginMode,
    availableBalance,
    currentPrice,
    marketId,
    isReady,
    loading,
    result,
    setFundPercent: handleFundPercentChange,
    setSizeInput: handleSizeInputChange,
    setPrice,
    setLeverage,
    setPositionMode,
    setMarginMode,
    setMarketId,
    placeBuyOrder,
    placeSellOrder,
    changeLeverage: changeLeverageFn,
    loadBalance,
    loadMarketPrice,
    calculateSize,
    calculateSizeUSD,
    calculateValue,
    calculateMargin,
    getOrderPrice,
    getAvailableTradeAmount,
  };
}
