import type { VaultBucketSummary } from "../../../offline/mock_data/vaultCatalog";
import type { Bucket } from "../../sdk/types/data";
import { bucketLeverage } from "./vaultPortfolioMetrics";

/** @deprecated Legacy prefixed trade id — prefer raw bucket id in vault scope. */
export function vaultBucketTradeId(vaultId: string, bucketId: string): string {
  return `vault:${vaultId}:${bucketId}`;
}

/** Parses legacy prefixed ids; returns null for raw bucket ids. */
export function parseVaultBucketTradeId(
  tradeBucketId: string,
): { vaultId: string; bucketId: string } | null {
  const match = /^vault:([^:]+):(.+)$/.exec(tradeBucketId);
  if (!match) return null;
  return { vaultId: match[1], bucketId: match[2] };
}

export function vaultBucketToTradeBucket(
  vaultId: string,
  bucket: VaultBucketSummary,
  leaderAddress = "",
): Bucket {
  const usedMargin = (bucket.marginUsagePct / 100) * bucket.equityUsd;
  const leverage = bucketLeverage(bucket);
  const now = new Date().toISOString();

  return {
    bucketId: bucket.id,
    address: leaderAddress,
    marginType: bucket.mode,
    collateralAssetIndex: "1",
    collateralAsset: "USDC",
    depositedMargin: bucket.equityUsd,
    totalEquity: bucket.equityUsd,
    availableMargin: Math.max(0, bucket.equityUsd - usedMargin),
    usedMargin,
    unrealizedProfit: Math.max(0, bucket.pnlUsd),
    unrealizedLoss: Math.max(0, -bucket.pnlUsd),
    realizedProfit: 0,
    realizedLoss: 0,
    unrealizedPnL: bucket.pnlUsd,
    marginRatio: bucket.riskRatio,
    imr: 10,
    totalNotionalValue: bucket.longNotionalUsd + bucket.shortNotionalUsd,
    riskLevel: bucket.riskHealth,
    maxLeverage: Math.max(leverage, 1),
    correlationOffset: 0,
    status: "active",
    createdAt: now,
    updatedAt: now,
    leverage,
    marginMode: bucket.mode,
    raw: { vaultId, vaultBucketId: bucket.id },
  };
}
