import type { VaultOpenOrderRow, VaultTradeFill } from "../../offline/mock_data/vaultMockData.types";
import type { VaultPositionRow } from "../../offline/mock_data/vaultCatalog";
import type { PendingOrder, Position, TradeHistoryRow } from "../sdk/types/data";

export function vaultPositionToPosition(
  row: VaultPositionRow,
  _vaultId: string,
  bucketId: string,
): Position {
  return {
    positionId: row.id,
    marketId: row.market,
    bucketId,
    marginMode: "CROSS",
    symbol: row.market,
    size: row.size,
    entryPrice: row.entryPrice,
    markPrice: row.markPrice,
    liquidationPrice: row.liqPrice,
    unrealizedPnL: row.unrealizedPnlUsd,
    leverage: row.leverage,
    margin: row.marginUsd,
    side: row.side === "long" ? "LONG" : "SHORT",
    raw: row,
  };
}

export function vaultOpenOrderToPending(row: VaultOpenOrderRow): PendingOrder {
  const side =
    row.side === "Buy" ? "BUY" : row.side === "Sell" ? "SELL" : row.side.toUpperCase();
  return {
    id: row.orderId,
    orderId: row.orderId,
    marketId: row.market,
    side: side as PendingOrder["side"],
    type: row.type === "Limit" ? "LIMIT" : "MARKET",
    quantity: row.size,
    price: row.price,
    filledQuantity: 0,
    remainingQuantity: row.size,
    status: "OPEN",
    timeInForce: "GTC",
    createdAt: row.time,
    updatedAt: row.time,
    raw: row,
  };
}

export function vaultTradeFillToHistoryRow(
  row: VaultTradeFill,
  index: number,
): TradeHistoryRow {
  const side: "Buy" | "Sell" =
    row.side === "B" || row.dir.toLowerCase().includes("long") ? "Buy" : "Sell";
  return {
    tradeId: `vault-fill-${row.time}-${index}`,
    coin: row.coin,
    marketId: row.coin,
    time: row.time,
    direction: row.dir,
    side,
    size: row.size,
    price: row.price,
    fee: row.fee,
    closedPnl: row.closedPnl,
    raw: row,
  };
}
