import React, { useMemo, useState } from "react";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import type { VaultUserPosition } from "../../../offline/mock_data/vaultUserState";
import { TabLayoutHeaderToolBar, buildToolbarTabs, VAULT_DETAIL_STRIP } from "../smartlayout";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import VaultAnalystVerdictContent from "./VaultAnalystVerdictContent";
import VaultDetailYourPerfContent from "./VaultDetailYourPerfContent";
import { VAULT_TOUR_TARGETS } from "../../tutorials/vault-tour/constants";
import "./vault.css";

type VaultDetailTab = "about" | "yourPerf" | "analystVerdict";

export interface VaultDetailMainPanelProps {
  height?: string;
  vault: VaultRecord;
  walletConnected: boolean;
  userPosition?: VaultUserPosition;
  yourDepositsUsd: number;
  allTimeEarnedUsd: number;
}

export default function VaultDetailMainPanel({
  height = "100%",
  vault,
  walletConnected,
  userPosition,
  yourDepositsUsd,
  allTimeEarnedUsd,
}: VaultDetailMainPanelProps): JSX.Element {
  const [activeTab, setActiveTab] = useState<VaultDetailTab>("analystVerdict");

  const tabs = useMemo(
    () =>
      buildToolbarTabs(VAULT_DETAIL_STRIP, {
        badges:
          vault.analystVerdict.flags.length > 0
            ? {
                analystVerdict: {
                  count: vault.analystVerdict.flags.length,
                },
              }
            : undefined,
      }),
    [vault.analystVerdict.flags.length],
  );

  return (
    <div
      className="vault-slot vault-detail-tab-section"
      style={{ height }}
      aria-label={`${vault.name} vault detail`}
      data-tour={VAULT_TOUR_TARGETS.detailMain}
    >
      <div className="layout-container tab-section-root vault-detail-tab-section-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={activeTab}
          onTabChange={(id) => setActiveTab(id as VaultDetailTab)}
        />

        <div className="tab-section-content">
          <div className="vault-detail-tab-body">
            {activeTab === "about" ? (
              <div className="vault-detail-about">
                <div className="vault-detail-about-field">
                  <p className="terminal-label">Leader</p>
                  <p className="terminal-value vault-detail-about-leader">{vault.leader}</p>
                </div>
                <div className="vault-detail-about-field vault-detail-about-field--grow">
                  <p className="terminal-label">Description</p>
                  <p className="terminal-value vault-detail-about-description">{vault.description}</p>
                </div>
              </div>
            ) : activeTab === "analystVerdict" ? (
              <VaultAnalystVerdictContent verdict={vault.analystVerdict} />
            ) : (
              <VaultDetailYourPerfContent
                vault={vault}
                walletConnected={walletConnected}
                userPosition={userPosition}
                yourDepositsUsd={yourDepositsUsd}
                allTimeEarnedUsd={allTimeEarnedUsd}
              />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
