import React, { useMemo } from "react";

import type { FleetSupervisor } from "../../store/types";
import { AGENT_ROLES_SUPERVISOR_BUBBLE_MAP } from "../../utils/agentRolesBubbleMap";
import {
  AGENT_ROLES_PAYMENTS_VIEW_ID,
  FLEET_SPEND_POLICY_SUMMARY,
} from "../../utils/agentRoles";
import {
  buildToolbarTabs,
  TabLayoutHeaderToolBar,
} from "../smartlayout";
import { AGENT_ROLES_SUPERVISOR_STRIP } from "../smartlayout/tabStrips";
import "../smartlayout/layout.css";
import "../tables/TabSection.css";
import "./agentroles.css";

export interface AgentRolesSupervisorBandProps {
  height?: string;
  supervisors: FleetSupervisor[];
  activeStripTabId: string;
  onStripTabChange: (tabId: string) => void;
  supervisor: FleetSupervisor | undefined;
  registryView: "fleet" | "payments";
}

function SupervisorMetaBody({
  registryView,
  supervisor,
}: {
  registryView: "fleet" | "payments";
  supervisor: FleetSupervisor | undefined;
}): JSX.Element | null {
  if (registryView === "payments") {
    return (
      <div className="agentroles-supervisor-meta-body">
        <div className="agentroles-supervisor-actions">
          <span className="agentroles-supervisor-meta-item agentroles-supervisor-meta-item--wide">
            <span className="terminal-label">Spend policy</span>
            <span className="terminal-value">{FLEET_SPEND_POLICY_SUMMARY}</span>
          </span>
          <span className="agentroles-supervisor-meta-item">
            <span className="terminal-label">View</span>
            <span className="terminal-value">Payment rail map</span>
          </span>
        </div>
      </div>
    );
  }

  if (!supervisor) return null;

  return (
    <div className="agentroles-supervisor-meta-body">
      <div className="agentroles-supervisor-actions">
        <span className="agentroles-supervisor-meta-item">
          <span className="terminal-label">Custody</span>
          <span className="terminal-value">DID only</span>
        </span>
        {supervisor.mandateSummary ? (
          <span className="agentroles-supervisor-meta-item agentroles-supervisor-meta-item--wide">
            <span className="terminal-label">Mandate</span>
            <span className="terminal-value">{supervisor.mandateSummary}</span>
          </span>
        ) : null}
        {supervisor.policyAuthority ? (
          <span className="agentroles-supervisor-meta-item agentroles-supervisor-meta-item--wide">
            <span className="terminal-label">Policy</span>
            <span className="terminal-value">{supervisor.policyAuthority}</span>
          </span>
        ) : null}
        <span className="agentroles-supervisor-meta-item agentroles-supervisor-meta-item--wide">
          <span className="terminal-label">Spend policy</span>
          <span className="terminal-value">{FLEET_SPEND_POLICY_SUMMARY}</span>
        </span>
      </div>
    </div>
  );
}

export default function AgentRolesSupervisorBand({
  height = "100%",
  supervisors,
  activeStripTabId,
  onStripTabChange,
  supervisor,
  registryView,
}: AgentRolesSupervisorBandProps): JSX.Element {
  const supervisorIds = useMemo(
    () => new Set(supervisors.map((entry) => entry.id)),
    [supervisors],
  );

  const tabs = useMemo(
    () =>
      buildToolbarTabs(AGENT_ROLES_SUPERVISOR_STRIP, {
        bubbleTips: AGENT_ROLES_SUPERVISOR_BUBBLE_MAP,
      }).filter(
        (tab) =>
          tab.id === AGENT_ROLES_PAYMENTS_VIEW_ID || supervisorIds.has(tab.id),
      ),
    [supervisorIds],
  );

  if (tabs.length === 0) {
    return (
      <div
        className="agentroles-slot agentroles-supervisor-band"
        style={{ height }}
        aria-hidden
      />
    );
  }

  return (
    <div
      className="agentroles-slot agentroles-supervisor-band"
      style={{ height }}
      aria-label="Fleet supervisor"
    >
      <div className="layout-container tab-section-root agentroles-supervisor-band-inner">
        <TabLayoutHeaderToolBar
          tabs={tabs}
          activeTabId={activeStripTabId}
          onTabChange={onStripTabChange}
          scrollActiveTabIntoView
        />
        <div className="tab-section-content">
          <SupervisorMetaBody
            registryView={registryView}
            supervisor={supervisor}
          />
        </div>
      </div>
    </div>
  );
}
