import React, { useMemo, useState } from "react";

import { useVaultTradeHistory } from "../../hooks/useVaultTradeHistory";
import type { VaultTradeFill } from "../../../offline/mock_data/vaultMockData.types";
import {
  ORDER_SIDE_COLOR_BUY_LONG,
  ORDER_SIDE_COLOR_SELL_SHORT,
} from "../../constants";
import { formatCurrency } from "../../sdk/utils/display";
import { TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import VaultActivityTableShell, {
  type VaultActivityTableLayout,
} from "./VaultActivityTableShell";
import VaultTableFooter from "./VaultTableFooter";
import "./vault.css";

const GRID =
  "1.2fr 0.7fr 1fr 0.8fr 0.8fr 0.7fr 0.8fr";

export interface VaultTradeHistoryTableProps {
  vaultId: string;
  bucketId?: string;
  layout?: VaultActivityTableLayout;
}

function formatDateTime(value: number): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(new Date(value));
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function directionColor(dir: string): string | undefined {
  const lower = dir.toLowerCase();
  if (lower.includes("long") && (lower.startsWith("open") || lower.startsWith("add"))) {
    return ORDER_SIDE_COLOR_BUY_LONG;
  }
  if (lower.includes("short") && (lower.startsWith("open") || lower.startsWith("add"))) {
    return ORDER_SIDE_COLOR_SELL_SHORT;
  }
  return undefined;
}

export default function VaultTradeHistoryTable({
  vaultId,
  bucketId,
  layout = "bucket",
}: VaultTradeHistoryTableProps): JSX.Element {
  const allRows = useVaultTradeHistory(vaultId, bucketId);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);
  const paginate = layout !== "terminal";

  const pageRows = useMemo(() => {
    if (!paginate) return allRows;
    const start = page * pageSize;
    return allRows.slice(start, start + pageSize);
  }, [allRows, page, pageSize, paginate]);

  return (
    <VaultActivityTableShell
      gridColumns={GRID}
      layout={layout}
      isEmpty={allRows.length === 0}
      emptyMessage="No trades."
      header={
        <>
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Market</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Direction</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Size</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Price</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Fee</TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.closedPnl} />
          </TableHeaderCellStatic>
        </>
      }
      footer={
        paginate ? (
          <VaultTableFooter
            page={page}
            pageSize={pageSize}
            totalCount={allRows.length}
            onPageChange={setPage}
            onPageSizeChange={setPageSize}
          />
        ) : undefined
      }
    >
      {pageRows.map((row: VaultTradeFill, index) => (
        <div
          key={`${row.time}-${row.coin}-${row.dir}-${index}`}
          className={`table-row ${index % 2 === 0 ? "even" : ""}`}
          style={{ gridTemplateColumns: GRID }}
        >
          <div className="table-cell">{formatDateTime(row.time)}</div>
          <div className="table-cell primary">{row.coin}</div>
          <div
            className="table-cell"
            style={{ color: directionColor(row.dir) }}
          >
            {row.dir}
          </div>
          <div className="table-cell numeric">
            {formatNumber(row.size)}
          </div>
          <div className="table-cell numeric">
            {formatCurrency(row.price)}
          </div>
          <div className="table-cell numeric">
            {formatCurrency(row.fee)}
          </div>
          <div
            className={`table-cell numeric ${
              row.closedPnl >= 0 ? "vault-grade-a" : "vault-grade-d"
            }`}
          >
            {row.closedPnl === 0 ? "—" : formatCurrency(row.closedPnl)}
          </div>
        </div>
      ))}
    </VaultActivityTableShell>
  );
}
