import type { Step } from "react-joyride";
import { VAULT_TOUR_STEPS_CONTENT } from "./content";
import { VAULT_TOUR_TARGETS } from "./constants";

function tourTarget(value: string): string {
  return `[data-tour="${value}"]`;
}

const STEP_TARGETS: Record<string, string> = {
  "list-spotlight": VAULT_TOUR_TARGETS.listSpotlight,
  "stat-cards": VAULT_TOUR_TARGETS.statCards,
  "detail-main": VAULT_TOUR_TARGETS.detailMain,
  "detail-perf": VAULT_TOUR_TARGETS.detailPerf,
  "portfolio-tabs": VAULT_TOUR_TARGETS.portfolioTabs,
  "bucket-table": VAULT_TOUR_TARGETS.bucketTable,
  "bucket-row": VAULT_TOUR_TARGETS.bucketRow,
  "bucket-total": VAULT_TOUR_TARGETS.bucketTotalRow,
  "bucket-drilldown": VAULT_TOUR_TARGETS.bucketRow,
  "bucket-kpi": VAULT_TOUR_TARGETS.bucketKpi,
  "bucket-health": VAULT_TOUR_TARGETS.bucketHealth,
  "bucket-positions": VAULT_TOUR_TARGETS.bucketPositions,
};

type VaultTourStepContent = (typeof VAULT_TOUR_STEPS_CONTENT)[number];

export interface VaultTourStepMeta {
  stepId: string;
  stepNumber: number;
  targetSelector: string;
  requiresClick: boolean;
  gateKind?: VaultTourStepContent["gateKind"];
  navigateBefore?: VaultTourStepContent["navigateBefore"];
}

export function buildVaultTourSteps(): Step[] {
  return VAULT_TOUR_STEPS_CONTENT.map((step, index) => {
    const targetSelector = tourTarget(STEP_TARGETS[step.id] ?? step.id);
    const requiresClick = Boolean(step.requiresClick);

    return {
      target: targetSelector,
      title: step.title,
      content: step.content,
      placement: (step.placement ?? "auto") as Step["placement"],
      skipBeacon: true,
      isFixed: false,
      spotlightClicks: requiresClick,
      disableOverlay: requiresClick,
      disableOverlayClose: true,
      hideBackButton: requiresClick,
      hideCloseButton: true,
      showSkipButton: true,
      buttons: requiresClick
        ? (["skip"] as ("back" | "skip" | "primary")[])
        : (["skip", "primary"] as ("back" | "skip" | "primary")[]),
      blockTargetInteraction: false,
      skipScroll: true,
      data: {
        stepId: step.id,
        stepNumber: index + 1,
        targetSelector,
        requiresClick,
        gateKind: step.gateKind,
        navigateBefore: step.navigateBefore,
      } satisfies VaultTourStepMeta,
    };
  });
}

export function getVaultTourStepCount(): number {
  return VAULT_TOUR_STEPS_CONTENT.length;
}

export function findVaultTourStepIndex(steps: Step[], stepId: string): number {
  return steps.findIndex(
    (s) => (s.data as VaultTourStepMeta | undefined)?.stepId === stepId,
  );
}
