import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type Ref,
} from "react";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import { appendVaultScope } from "../../routes";
import { StackTransition } from "../ui/StackTransition";
import "../ui/stackTransition.css";
import VaultOperateSwitcher from "./VaultOperateSwitcher";
import {
  VAULT_NAV_PERSONAL_KEY,
  buildVaultNavStacks,
  vaultNavDirection,
  vaultNavFocusKey,
} from "./vaultNavContext";
import "./vaultOperate.css";

const DEFAULT_LOGO_SRC = "/morhpeum-2.svg";

export type MenuBarNavItem = {
  label: string;
  href?: string;
  hasDropdown?: boolean;
  id?: string;
};

export type VaultNavTransitionProps = {
  focusKey: string;
  direction: (from: string, to: string) => 1 | -1;
  ownedVaultIds: readonly string[];
};

export function useVaultNavTransition(
  isVaultActive: boolean,
  vaultId: string | null,
  ownedVaults: readonly VaultRecord[],
): VaultNavTransitionProps {
  const ownedVaultIds = useMemo(
    () => ownedVaults.map((vault) => vault.id),
    [ownedVaults],
  );

  const focusKey = vaultNavFocusKey(isVaultActive, vaultId);

  return useMemo(
    (): VaultNavTransitionProps => ({
      focusKey,
      ownedVaultIds,
      direction: (from, to) => vaultNavDirection(from, to, ownedVaultIds),
    }),
    [focusKey, ownedVaultIds],
  );
}

function PersonalBrandTitle({ brandName }: { brandName: string }): JSX.Element {
  return <span className="menubar-brand">{brandName}</span>;
}

type VaultBrandTitleProps = {
  vaultName: string;
  showSwitcher?: boolean;
  switcherOpen?: boolean;
  onToggleSwitcher?: () => void;
  triggerRef?: Ref<HTMLButtonElement>;
};

function VaultBrandTitle({
  vaultName,
  showSwitcher = false,
  switcherOpen = false,
  onToggleSwitcher,
  triggerRef,
}: VaultBrandTitleProps): JSX.Element {
  return (
    <div className="menubar-vault-brand" aria-live="polite">
      <span className="menubar-vault-brand-label">OPERATING</span>
      <span className="menubar-vault-brand-sep" aria-hidden>
        ·
      </span>
      {showSwitcher ? (
        <button
          type="button"
          ref={triggerRef}
          className="menubar-vault-brand-trigger"
          onClick={onToggleSwitcher}
          aria-expanded={switcherOpen}
          aria-haspopup="menu"
          aria-label={`Switch vault: ${vaultName}`}
          title={vaultName}
        >
          <span className="menubar-vault-brand-name">{vaultName}</span>
          <span
            className={[
              "menubar-vault-brand-chevron",
              switcherOpen ? "menubar-vault-brand-chevron--open" : "",
            ]
              .filter(Boolean)
              .join(" ")}
            aria-hidden
          >
            <svg
              className="menubar-chevron"
              width="10"
              height="6"
              viewBox="0 0 10 6"
              fill="none"
            >
              <path
                d="M1 1L5 5L9 1"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
          </span>
        </button>
      ) : (
        <span className="menubar-vault-brand-name" title={vaultName}>
          {vaultName}
        </span>
      )}
    </div>
  );
}

type MenuBarNavStackProps = {
  variant: "personal" | "vault";
  menuItems: MenuBarNavItem[];
  vaultScopeId: string | null;
  renderMenuItem: (item: MenuBarNavItem, href: string) => ReactNode;
};

function MenuBarNavStack({
  variant,
  menuItems,
  vaultScopeId,
  renderMenuItem,
}: MenuBarNavStackProps): JSX.Element {
  const isVault = variant === "vault";

  return (
    <nav
      className={[
        "menubar-nav",
        isVault ? "menubar-nav--vault" : "menubar-nav--personal",
      ].join(" ")}
      aria-label="Main navigation"
    >
      <ul id="menubar-menu" className="menubar-menu">
        {menuItems.map((item) => {
          const baseHref = item.href ?? "#";
          const href =
            isVault && vaultScopeId
              ? appendVaultScope(baseHref, vaultScopeId)
              : baseHref;
          return <li key={item.label}>{renderMenuItem(item, href)}</li>;
        })}
      </ul>
    </nav>
  );
}

export type MenuBarPrimaryClusterProps = {
  brandName: string;
  logo?: ReactNode;
  menuItems: MenuBarNavItem[];
  /** Mobile drawer open — used for hamburger aria-expanded only. */
  mobileNavExpanded: boolean;
  isVaultActive: boolean;
  vaultId: string | null;
  ownedVaults: readonly VaultRecord[];
  onLogoClick: () => void;
  onHamburgerClick: () => void;
  onSwitchVault: (vaultId: string) => void;
  onVaultHome: () => void;
  renderMenuItem: (item: MenuBarNavItem, href: string) => ReactNode;
};

export function MenuBarPrimaryCluster({
  brandName,
  logo,
  menuItems,
  mobileNavExpanded,
  isVaultActive,
  vaultId,
  ownedVaults,
  onLogoClick,
  onHamburgerClick,
  onSwitchVault,
  onVaultHome,
  renderMenuItem,
}: MenuBarPrimaryClusterProps): JSX.Element {
  const [switcherOpen, setSwitcherOpen] = useState(false);
  const [switcherLeft, setSwitcherLeft] = useState<number | null>(null);
  const clusterRef = useRef<HTMLDivElement>(null);
  const navSlotRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const idleNavLinkLeftRef = useRef<number | null>(null);

  const { focusKey, direction, ownedVaultIds } = useVaultNavTransition(
    isVaultActive,
    vaultId,
    ownedVaults,
  );

  const showVaultSwitcher = isVaultActive && ownedVaults.length > 1;

  useEffect(() => {
    setSwitcherOpen(false);
    setSwitcherLeft(null);
  }, [vaultId]);

  const closeSwitcher = () => {
    setSwitcherOpen(false);
    setSwitcherLeft(null);
  };

  useLayoutEffect(() => {
    if (!switcherOpen) {
      setSwitcherLeft(null);
      return;
    }

    const trigger = triggerRef.current;
    const cluster = clusterRef.current;
    if (!trigger || !cluster) return;

    const triggerRect = trigger.getBoundingClientRect();
    const clusterRect = cluster.getBoundingClientRect();
    setSwitcherLeft(triggerRect.left - clusterRect.left);
  }, [switcherOpen]);

  const resolveVaultName = (id: string): string =>
    ownedVaults.find((vault) => vault.id === id)?.name ?? id;

  const transitionCommon = {
    focusKey,
    axis: "vertical" as const,
    direction,
    durationMs: 550,
  };

  const brandTitleStacks = useMemo(
    () =>
      buildVaultNavStacks(
        isVaultActive,
        vaultId,
        ownedVaultIds,
        <PersonalBrandTitle brandName={brandName} />,
        (id) => (
          <VaultBrandTitle
            vaultName={resolveVaultName(id)}
            showSwitcher={ownedVaults.length > 1}
            switcherOpen={switcherOpen}
            onToggleSwitcher={() => setSwitcherOpen((open) => !open)}
            triggerRef={id === vaultId ? triggerRef : undefined}
          />
        ),
      ),
    [isVaultActive, vaultId, ownedVaultIds, brandName, ownedVaults, switcherOpen],
  );

  const navStacks = useMemo(
    () =>
      buildVaultNavStacks(
        isVaultActive,
        vaultId,
        ownedVaultIds,
        (
          <MenuBarNavStack
            variant="personal"
            menuItems={menuItems}
            vaultScopeId={null}
            renderMenuItem={renderMenuItem}
          />
        ),
        (id) => (
          <MenuBarNavStack
            variant="vault"
            menuItems={menuItems}
            vaultScopeId={id}
            renderMenuItem={renderMenuItem}
          />
        ),
      ),
    [isVaultActive, vaultId, ownedVaultIds, menuItems, renderMenuItem],
  );

  useLayoutEffect(() => {
    const navSlot = navSlotRef.current;
    if (!navSlot) return;

    const exitLink = navSlot.querySelector<HTMLElement>(
      ".stack-transition__panel--exit .menubar-menu-item",
    );
    if (exitLink) return;

    const idleLink = navSlot.querySelector<HTMLElement>(
      ".stack-transition__panel--enter .menubar-menu-item",
    );
    if (idleLink) {
      idleNavLinkLeftRef.current = idleLink.getBoundingClientRect().left;
    }
  }, [focusKey, navStacks, menuItems, isVaultActive, vaultId]);

  return (
    <div className="menubar-primary-row">
      <div className="menubar-left">
        <button
          type="button"
          className="menubar-hamburger"
          aria-expanded={mobileNavExpanded}
          aria-controls="menubar-mobile-menu"
          aria-label="Open menu"
          onClick={onHamburgerClick}
        >
          <span />
          <span />
          <span />
        </button>
        <button
          type="button"
          className="menubar-logo-link menubar-logo-link--icon-only"
          aria-label={`${brandName} home`}
          onClick={onLogoClick}
        >
          {logo ?? (
            <img
              src={DEFAULT_LOGO_SRC}
              alt=""
              className="menubar-logo-img"
              aria-hidden
            />
          )}
        </button>
        <div className="menubar-brand-cluster" ref={clusterRef}>
          <div className="menubar-brand-slot">
            <StackTransition
              {...transitionCommon}
              stacks={brandTitleStacks}
              fitContent
              announceChanges={isVaultActive}
            />
          </div>
          {showVaultSwitcher && vaultId && switcherOpen && switcherLeft !== null ? (
            <VaultOperateSwitcher
              ownedVaults={[...ownedVaults]}
              activeVaultId={vaultId}
              open={switcherOpen}
              onClose={closeSwitcher}
              onSelectVault={onSwitchVault}
              onVaultHome={onVaultHome}
              className="vault-operate-switcher--brand"
              style={{ left: switcherLeft }}
              anchorRef={triggerRef}
            />
          ) : null}
        </div>
      </div>

      <div className="menubar-nav-slot" ref={navSlotRef}>
        <StackTransition
          {...transitionCommon}
          stacks={navStacks}
          exitAnchorXRef={idleNavLinkLeftRef}
        />
      </div>
    </div>
  );
}

export type MenuBarVaultControlsProps = {
  onVaultHome: () => void;
  vaultName?: string | null;
};

export function MenuBarVaultControls({
  onVaultHome,
  vaultName,
}: MenuBarVaultControlsProps): JSX.Element {
  const homeLabel = vaultName
    ? `Back to ${vaultName} vault`
    : "Back to vault";

  return (
    <div className="menubar-vault-controls">
      <button
        type="button"
        className="menubar-vault-exit"
        onClick={onVaultHome}
        aria-label={homeLabel}
        title={homeLabel}
      >
        ⌂
      </button>
    </div>
  );
}

export type MenuBarVaultControlsSlotProps = {
  isVaultActive: boolean;
  vaultId: string | null;
  ownedVaults: readonly VaultRecord[];
  onVaultHome: () => void;
};

export function MenuBarVaultControlsSlot({
  isVaultActive,
  vaultId,
  ownedVaults,
  onVaultHome,
}: MenuBarVaultControlsSlotProps): JSX.Element {
  const { focusKey, direction, ownedVaultIds } = useVaultNavTransition(
    isVaultActive,
    vaultId,
    ownedVaults,
  );

  const activeVaultName = useMemo(() => {
    if (!vaultId) return null;
    return ownedVaults.find((vault) => vault.id === vaultId)?.name ?? vaultId;
  }, [vaultId, ownedVaults]);

  const controlStacks = useMemo(() => {
    const emptyPanel = <span className="menubar-vault-controls-empty" aria-hidden />;

    return buildVaultNavStacks(
      isVaultActive,
      vaultId,
      ownedVaultIds,
      emptyPanel,
      () => (
        <MenuBarVaultControls
          onVaultHome={onVaultHome}
          vaultName={activeVaultName}
        />
      ),
    );
  }, [isVaultActive, vaultId, ownedVaultIds, onVaultHome, activeVaultName]);

  return (
    <div className="menubar-vault-controls-slot">
      <StackTransition
        focusKey={focusKey}
        stacks={controlStacks}
        axis="vertical"
        direction={direction}
        durationMs={550}
        fitContent
      />
    </div>
  );
}

export { VAULT_NAV_PERSONAL_KEY };
