import React from "react";
import { createPortal } from "react-dom";

import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "../ui/overlay";
import VaultFiltersPanel, {
  type VaultFiltersPanelProps,
} from "./VaultFiltersPanel";

export interface VaultFiltersSheetProps extends VaultFiltersPanelProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function VaultFiltersSheet({
  isOpen,
  onClose,
  ...panelProps
}: VaultFiltersSheetProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen,
    panelDurationMs: OVERLAY_TIMING.mobileSheetMs,
  });

  useOverlayEscapeKey(isOpen, onClose);
  useOverlayScrollLock(isOpen && mounted);

  if (!mounted) return null;

  const modalContent = (
    <StaggeredOverlayRoot className="vault-filters-sheet-overlay bucket-modal-overlay bucket-modal-overlay--sheet">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="modal-content vault-filters-sheet-panel bucket-modal-panel--sheet"
        role="dialog"
        aria-modal={true}
        aria-label="Vault filters"
      >
        <header className="vault-filters-sheet-header">
          <h2 className="vault-filters-sheet-title">Filters</h2>
          <button
            type="button"
            className="vault-filters-sheet-close"
            onClick={onClose}
            aria-label="Close filters"
          >
            ×
          </button>
        </header>
        <div className="vault-filters-sheet-body">
          <VaultFiltersPanel variant="sheet" {...panelProps} />
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}
