import {
  getEffectiveMockBalance,
  getMockPortfolioAssetPriceUsd,
  listEffectiveMockBalanceAssets,
} from "../../offline/mock_data";
import type { RawBalance } from "../sdk/types/api";
import { toNumberFromSatoshi } from "../sdk/utils/math";

const STABLECOINS = new Set(["USDC", "USDT"]);

const ASSET_NAMES: Record<string, string> = {
  USDC: "USD Coin",
  USDT: "Tether USD",
  MORM: "Morpheum",
  BTC: "Bitcoin",
  ETH: "Ethereum",
};

export interface PortfolioBalanceRow {
  symbol: string;
  name: string;
  amount: number;
  priceUsd: number;
  valueUsd: number;
}

export function resolvePortfolioAssetName(symbol: string): string {
  return ASSET_NAMES[symbol] ?? symbol;
}

export function resolvePortfolioAssetPriceUsd(symbol: string): number {
  if (STABLECOINS.has(symbol)) return 1;
  return getMockPortfolioAssetPriceUsd(symbol);
}

function resolveBalanceAsset(raw: RawBalance): string {
  if (typeof raw.asset === "string" && raw.asset.trim()) {
    return raw.asset.trim().toUpperCase();
  }
  const ticker = raw.collateralAssetIndex?.ticker;
  if (typeof ticker === "string" && ticker.trim()) {
    return ticker.trim().toUpperCase();
  }
  return "";
}

function resolveBalanceAmount(raw: RawBalance): number {
  if (typeof raw.availableBalance === "string" && raw.availableBalance.trim()) {
    return toNumberFromSatoshi(raw.availableBalance);
  }
  if (typeof raw.balance === "string" && raw.balance.trim()) {
    return toNumberFromSatoshi(raw.balance);
  }
  if (typeof raw.available === "number") {
    return raw.available;
  }
  return 0;
}

export function buildOfflinePortfolioBalanceRows(
  wallet: string,
): PortfolioBalanceRow[] {
  const rows: PortfolioBalanceRow[] = [];
  for (const symbol of listEffectiveMockBalanceAssets(wallet)) {
    const amount = getEffectiveMockBalance(wallet, symbol);
    if (amount <= 0) continue;
    const priceUsd = resolvePortfolioAssetPriceUsd(symbol);
    rows.push({
      symbol,
      name: resolvePortfolioAssetName(symbol),
      amount,
      priceUsd,
      valueUsd: amount * priceUsd,
    });
  }
  return rows;
}

export function buildLivePortfolioBalanceRows(
  balances: RawBalance[],
): PortfolioBalanceRow[] {
  const rows: PortfolioBalanceRow[] = [];
  for (const raw of balances) {
    const symbol = resolveBalanceAsset(raw);
    if (!symbol) continue;
    const amount = resolveBalanceAmount(raw);
    if (amount <= 0) continue;
    const priceUsd = resolvePortfolioAssetPriceUsd(symbol);
    rows.push({
      symbol,
      name: resolvePortfolioAssetName(symbol),
      amount,
      priceUsd,
      valueUsd: amount * priceUsd,
    });
  }
  return rows;
}

export function sumPortfolioBalanceRowsValueUsd(
  rows: PortfolioBalanceRow[],
): number {
  return rows.reduce((sum, row) => sum + row.valueUsd, 0);
}
