import type {
  VaultActivityRow,
  VaultFundingRow,
  VaultTradeFill,
} from "./vaultMockData.types";

export function tradeFillToActivityRow(fill: VaultTradeFill): VaultActivityRow {
  return {
    vaultId: fill.vaultId,
    time: fill.time,
    activityType: "perp",
    sourceKind: "bucket",
    bucketId: fill.bucketId,
    market: fill.coin,
    side: fill.dir,
    size: fill.size,
    price: fill.price,
    fee: fill.fee,
    realizedPnl: fill.closedPnl,
  };
}

export function fundingRowToActivityRow(row: VaultFundingRow): VaultActivityRow {
  const payout = row.payout;
  return {
    vaultId: row.vaultId,
    time: Date.parse(row.time),
    activityType: "funding",
    sourceKind: "bucket",
    bucketId: row.bucketId,
    market: row.symbol.replace(/-USDT$/i, "-PERP"),
    side: payout >= 0 ? "Recv" : "Pay",
    size: row.positionSize,
    price: null,
    fee: null,
    realizedPnl: payout,
  };
}

export function activityTypeLabel(type: VaultActivityRow["activityType"]): string {
  switch (type) {
    case "perp":
      return "Perp";
    case "spot":
      return "Spot";
    case "lp":
      return "LP";
    case "transfer":
      return "Xfer";
    case "funding":
      return "Fund.";
    default:
      return type;
  }
}

export function tradeFillFromActivityRow(row: VaultActivityRow): VaultTradeFill | null {
  if (
    row.activityType !== "perp"
    || row.sourceKind !== "bucket"
    || !row.bucketId
    || row.size == null
    || row.price == null
    || row.fee == null
  ) {
    return null;
  }
  const sideLower = row.side.toLowerCase();
  const side: "B" | "A" =
    sideLower.includes("short") && sideLower.startsWith("open")
      ? "A"
      : sideLower.includes("long") && sideLower.startsWith("open")
        ? "B"
        : sideLower.includes("close long")
          ? "A"
          : sideLower.includes("close short")
            ? "B"
            : "B";
  return {
    vaultId: row.vaultId,
    bucketId: row.bucketId,
    address: "",
    time: row.time,
    coin: row.market,
    dir: row.side,
    side,
    size: row.size,
    price: row.price,
    fee: row.fee,
    closedPnl: row.realizedPnl ?? 0,
  };
}

export function fundingRowFromActivity(row: VaultActivityRow): VaultFundingRow | null {
  if (
    row.activityType !== "funding"
    || row.sourceKind !== "bucket"
    || !row.bucketId
    || row.size == null
    || row.realizedPnl == null
  ) {
    return null;
  }
  const payout = row.realizedPnl;
  const positionSide = row.side === "Pay" ? "Short" : "Long";
  return {
    vaultId: row.vaultId,
    bucketId: row.bucketId,
    address: "",
    time: new Date(row.time).toISOString(),
    symbol: row.market.replace(/-PERP$/i, "-USDT"),
    side: positionSide,
    positionSize: row.size,
    payout,
    rate: 0,
  };
}
