import React, { type ReactNode } from "react";

import { StackTransition } from "../ui/StackTransition";
import { focusSlideDirection } from "./agentHeroFocus";
import "./agent.css";

type AgentFocusTransitionProps<T extends string> = {
  focusKey: T;
  stacks: Record<T, ReactNode>;
  className?: string;
  announceChanges?: boolean;
};

export function AgentFocusTransition<T extends string>({
  focusKey,
  stacks,
  className,
  announceChanges = false,
}: AgentFocusTransitionProps<T>): JSX.Element {
  return (
    <StackTransition
      focusKey={focusKey}
      stacks={stacks as Record<string, ReactNode>}
      className={["agent-focus-transition", className].filter(Boolean).join(" ")}
      axis="vertical"
      direction={(from, to) =>
        focusSlideDirection(
          from as Parameters<typeof focusSlideDirection>[0],
          to as Parameters<typeof focusSlideDirection>[1],
        )
      }
      announceChanges={announceChanges}
    />
  );
}
