import { useMemo, useSyncExternalStore } from "react";
import { cloneVaultBalances } from "../../offline/mock_data/vaultActivityData";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import type { VaultBalanceRow } from "../../offline/mock_data/vaultMockData.types";

export function useVaultBalances(vaultId: string): VaultBalanceRow[] {
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  return useMemo(() => {
    void cacheRevision;
    return cloneVaultBalances(vaultId);
  }, [vaultId, cacheRevision]);
}
