import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

export const VAULT_BUCKET_COLLAPSED_SLOTS = [5, 6, 7, 8] as const;
export const VAULT_BUCKET_ROW_HEIGHT = 30;
export const VAULT_BUCKET_LAYOUT_MARGIN = 10;

export const VAULT_BUCKET_HEADER_ROWS = 3;
/** Single-row 5-across KPI on lg/md. */
export const VAULT_BUCKET_KPI_ROWS_LG = 2;
export const VAULT_BUCKET_KPI_ROWS_MD = 2;
/** 2×N KPI grid on sm–xs (five cards). */
export const VAULT_BUCKET_KPI_ROWS_SM = 4;
export const VAULT_BUCKET_KPI_ROWS_XS = 4;
/** Extra row budget on xxs for narrow 2-col cards. */
export const VAULT_BUCKET_KPI_ROWS_XXS = 5;
/** Single-line health bar on lg/md. */
export const VAULT_BUCKET_HEALTH_ROWS_COMPACT = 1;
/** Health bar on sm–xxs (wrap room). */
export const VAULT_BUCKET_HEALTH_ROWS = 2;

export const VAULT_BUCKET_POSITIONS_SLOT_INDEX = 3;
/** @deprecated Use resolveVaultBucketPositionsStartY — lg default (3+2+1). */
export const VAULT_BUCKET_POSITIONS_START_Y = resolveVaultBucketPositionsStartY(
  VAULT_BUCKET_KPI_ROWS_LG,
  VAULT_BUCKET_HEALTH_ROWS_COMPACT,
);
export const VAULT_BUCKET_POSITIONS_FALLBACK_ROWS = 18;
export const VAULT_BUCKET_POSITIONS_MIN_ROWS = 6;
export const VAULT_BUCKET_POSITIONS_MAX_ROWS = 48;

/** MenuBar height — must match MenuBar.css */
export const VAULT_BUCKET_MENUBAR_HEIGHT = 54;
export const VAULT_BUCKET_VIEWPORT_FUDGE_PX = 4;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED, COLLAPSED];

export function resolveVaultBucketPositionsStartY(
  kpiRows: number,
  healthRows: number,
  headerRows = VAULT_BUCKET_HEADER_ROWS,
): number {
  return headerRows + kpiRows + healthRows;
}

function vaultBucketLayout(
  cols: number,
  kpiRows: number,
  healthRows: number,
): LayoutConfigLest {
  let y = 0;
  const header: LayoutDefinition = [0, y, cols, VAULT_BUCKET_HEADER_ROWS];
  y += VAULT_BUCKET_HEADER_ROWS;
  const kpi: LayoutDefinition = [0, y, cols, kpiRows];
  y += kpiRows;
  const health: LayoutDefinition = [0, y, cols, healthRows];
  y += healthRows;
  const positions: LayoutDefinition = [0, y, cols, VAULT_BUCKET_POSITIONS_FALLBACK_ROWS];
  return [header, kpi, health, positions, COLLAPSED, ...COLLAPSED_TAIL];
}

export function buildVaultBucketResponsiveLayoutConfig(): ResponsiveLayoutConfig {
  const collapseAll = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, VAULT_BUCKET_COLLAPSED_SLOTS);

  return {
    lg: collapseAll(
      vaultBucketLayout(12, VAULT_BUCKET_KPI_ROWS_LG, VAULT_BUCKET_HEALTH_ROWS_COMPACT),
    ),
    md: collapseAll(
      vaultBucketLayout(10, VAULT_BUCKET_KPI_ROWS_MD, VAULT_BUCKET_HEALTH_ROWS_COMPACT),
    ),
    sm: collapseAll(
      vaultBucketLayout(6, VAULT_BUCKET_KPI_ROWS_SM, VAULT_BUCKET_HEALTH_ROWS),
    ),
    xs: collapseAll(
      vaultBucketLayout(4, VAULT_BUCKET_KPI_ROWS_XS, VAULT_BUCKET_HEALTH_ROWS),
    ),
    xxs: collapseAll(
      vaultBucketLayout(2, VAULT_BUCKET_KPI_ROWS_XXS, VAULT_BUCKET_HEALTH_ROWS),
    ),
  };
}

export function generateVaultBucketResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

/** Compute max grid bottom row that fits in the viewport without page scroll. */
export function computeVaultBucketTargetBottomRow(
  viewportHeight: number,
  positionsStartY = VAULT_BUCKET_POSITIONS_START_Y,
  menubarHeight = VAULT_BUCKET_MENUBAR_HEIGHT,
): number {
  const minBottomRow = positionsStartY + VAULT_BUCKET_POSITIONS_MIN_ROWS;
  const available =
    viewportHeight - menubarHeight - VAULT_BUCKET_VIEWPORT_FUDGE_PX;
  const rowUnit = VAULT_BUCKET_ROW_HEIGHT + VAULT_BUCKET_LAYOUT_MARGIN;
  const rows = Math.floor((available + VAULT_BUCKET_LAYOUT_MARGIN) / rowUnit);
  return Math.max(
    minBottomRow,
    Math.min(VAULT_BUCKET_POSITIONS_MAX_ROWS, rows),
  );
}

function patchVaultBucketPositionsViewportFit(
  layout: LayoutConfigLest,
  targetBottomRow: number,
): LayoutConfigLest {
  const positionsSlot = layout[VAULT_BUCKET_POSITIONS_SLOT_INDEX];
  if (!positionsSlot || positionsSlot[2] === 0 || positionsSlot[3] === 0) {
    return layout;
  }
  const positionsStart = positionsSlot[1];
  const positionsRows = Math.max(
    VAULT_BUCKET_POSITIONS_MIN_ROWS,
    targetBottomRow - positionsStart,
  );
  return patchVaultBucketPositionsFixedRows(layout, positionsRows);
}

function patchVaultBucketPositionsFixedRows(
  layout: LayoutConfigLest,
  positionsRows: number,
): LayoutConfigLest {
  const positionsSlot = layout[VAULT_BUCKET_POSITIONS_SLOT_INDEX];
  if (!positionsSlot || positionsSlot[2] === 0 || positionsSlot[3] === 0) {
    return layout;
  }
  return layout.map((item, index) =>
    index === VAULT_BUCKET_POSITIONS_SLOT_INDEX
      ? [positionsSlot[0], positionsSlot[1], positionsSlot[2], positionsRows]
      : item,
  );
}

/** Content-sized rows for sm–xxs page scroll (all positions, no pagination). */
export function resolveVaultBucketScrollRows(
  positionCount: number,
  useCards: boolean,
): number {
  const chromePx = 48;
  let bodyPx: number;
  if (useCards) {
    const cardRows = Math.max(1, Math.ceil(Math.max(positionCount, 1) / 2));
    bodyPx = cardRows * 180;
  } else {
    const visibleRows = Math.max(positionCount, 1) + 1;
    bodyPx = 30 + visibleRows * 44;
  }
  const totalPx = chromePx + bodyPx;
  const rows = Math.floor(
    (totalPx + VAULT_BUCKET_LAYOUT_MARGIN) /
      (VAULT_BUCKET_ROW_HEIGHT + VAULT_BUCKET_LAYOUT_MARGIN),
  );
  return Math.max(VAULT_BUCKET_POSITIONS_MIN_ROWS, rows);
}

/** All breakpoints: stretch slot 3 to fill remaining viewport height. */
export function applyVaultBucketLayoutSizing(
  config: ResponsiveLayoutConfig,
  viewportHeight = 900,
  _positionCount = 3,
  _useCards = false,
): ResponsiveLayoutConfig {
  const patchViewportFit = (layout: LayoutConfigLest) => {
    const positionsSlot = layout[VAULT_BUCKET_POSITIONS_SLOT_INDEX];
    const positionsStartY = positionsSlot?.[1] ?? VAULT_BUCKET_POSITIONS_START_Y;
    const targetBottomRow = computeVaultBucketTargetBottomRow(
      viewportHeight,
      positionsStartY,
    );
    return patchVaultBucketPositionsViewportFit(layout, targetBottomRow);
  };

  return {
    lg: patchViewportFit(config.lg),
    md: patchViewportFit(config.md),
    sm: patchViewportFit(config.sm),
    xs: patchViewportFit(config.xs),
    xxs: patchViewportFit(config.xxs),
  };
}

export function validateVaultBucketLayout(config: ResponsiveLayoutConfig): void {
  for (const bp of GRID_BREAKPOINTS) {
    assertNoLayoutOverlap(config[bp], `vault-bucket-${bp}`);
  }
}
