import React from "react";

import type { StakingActivityRow } from "../../../offline/mock_data/stakingMockData.types";
import VaultActivityTableShell from "../vault/VaultActivityTableShell";
import { formatStakingMormAmount } from "./stakingFormat";
import "./staking.css";

export interface StakingActivityTableProps {
  rows: StakingActivityRow[];
  height?: string;
}

function formatTimestamp(ms: number): string {
  return new Date(ms).toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function kindLabel(kind: StakingActivityRow["kind"]): string {
  if (kind === "stake") return "Stake";
  if (kind === "unstake") return "Unstake";
  if (kind === "delegate") return "Delegate";
  if (kind === "undelegate") return "Undelegate";
  return "Claim";
}

function StakingActivityTable({
  rows,
  height = "100%",
}: StakingActivityTableProps): JSX.Element {
  return (
    <div style={{ height }}>
      <VaultActivityTableShell
        layout="terminal"
        tableClassName="position-table"
        gridClassName="staking-activity-grid"
        isEmpty={rows.length === 0}
        emptyMessage="No staking activity yet."
        header={
          <>
            <span>Time</span>
            <span>Action</span>
            <span>Amount</span>
            <span>Tx</span>
          </>
        }
      >
        {rows.map((row) => (
          <div key={row.id} className="table-row staking-activity-grid">
            <span>{formatTimestamp(row.timestampMs)}</span>
            <span>{kindLabel(row.kind)}</span>
            <span>
              {row.kind === "claim"
                ? `$${formatStakingMormAmount(row.amountMorm)}`
                : `${formatStakingMormAmount(row.amountMorm)} MORM`}
            </span>
            <span className="terminal-label">{row.txHash.slice(0, 10)}…</span>
          </div>
        ))}
      </VaultActivityTableShell>
    </div>
  );
}

export default React.memo(StakingActivityTable);
