import React from "react";

import ConnectWalletPanel from "../wallet/ConnectWalletPanel";
import { getStakingConnectGateBounds } from "./stakingHeroBandBounds";
import type { StakingPageView } from "./stakingPageView";
import "./staking.css";

export interface StakingConnectGateOverlayProps {
  breakpoint: string;
  tabRowCount: number;
  pageView?: StakingPageView;
}

function StakingConnectGateOverlay({
  breakpoint,
  tabRowCount,
  pageView = "staking",
}: StakingConnectGateOverlayProps): JSX.Element {
  const bandStyle = React.useMemo(() => {
    const { topPx, heightPx } = getStakingConnectGateBounds(
      breakpoint,
      tabRowCount,
      pageView,
    );
    return {
      top: `${topPx}px`,
      height: `${heightPx}px`,
    };
  }, [breakpoint, tabRowCount, pageView]);

  return (
    <div
      className="staking-connect-gate-overlay"
      style={bandStyle}
      role="region"
      aria-label="Connect wallet"
    >
      <div className="staking-connect-gate-overlay-scrim" aria-hidden />
      <div className="staking-connect-gate-overlay-card">
        <ConnectWalletPanel variant="portfolio" layout="inline" />
      </div>
    </div>
  );
}

export default React.memo(StakingConnectGateOverlay);
