import { useCallback, useEffect, useMemo, useState } from "react";

import {
  GUARDED_AUTONOMY,
  HIGH_AGENCY_AUTONOMY,
  MANUAL_AUTONOMY,
  type AutonomyPolicy,
} from "../components/tradeagent/autonomyPolicy";
import { isNeedsYouTask } from "../components/tradeagent/reportTier";
import { getTradingModeFromLayout } from "../configs/tradeLayoutMode";
import { useSettings } from "../context/SettingsContext";
import type { FleetSupervisor, TradingAgent } from "../store/types";
import { useTradingAgentStore } from "../store/tradingAgentStore";
import {
  AGENT_ROLES_PAYMENTS_VIEW_ID,
  agentMatchesCustodyFilter,
  agentMatchesListingFilter,
  agentMatchesModeFilter,
  agentMatchesPaymentFilter,
  agentMatchesRoleFilter,
  type AgentRegistryRow,
  type AgentRolesRegistryView,
  type AgentRolesSortKey,
  getAgentCustodyKind,
  getAgentCustodyLabel,
  getAgentPaymentLabel,
  getAgentRoleLabel,
  getListingLabel,
  resolveAgentPaymentState,
} from "../utils/agentRoles";
import { useAgentTasks } from "./useAgentTasks";

export interface AgentRolesFleetStats {
  online: number;
  withWallet: number;
  payEnabled: number;
  didOnly: number;
  listed: number;
  needsYou: number;
  executing: number;
  idle: number;
}

export interface UseAgentRolesPageDataResult {
  agents: TradingAgent[];
  supervisors: FleetSupervisor[];
  activeSupervisor: FleetSupervisor | undefined;
  activeStripTabId: string;
  registryView: AgentRolesRegistryView;
  setActiveSupervisorId: (id: string) => void;
  query: string;
  setQuery: (value: string) => void;
  roleFilter: string;
  setRoleFilter: (value: string) => void;
  custodyFilter: string;
  setCustodyFilter: (value: string) => void;
  paymentFilter: string;
  setPaymentFilter: (value: string) => void;
  listingFilter: string;
  setListingFilter: (value: string) => void;
  modeFilter: string;
  setModeFilter: (value: string) => void;
  sortKey: AgentRolesSortKey;
  sortDir: "asc" | "desc";
  handleSort: (key: AgentRolesSortKey) => void;
  resetFilters: () => void;
  filteredRows: AgentRegistryRow[];
  fleetStats: AgentRolesFleetStats;
  selectedAgentId: string | null;
  detailOpen: boolean;
  openDetail: (agentId: string) => void;
  closeDetail: () => void;
  selectedAgent: TradingAgent | undefined;
  updateAgentListingStatus: ReturnType<
    typeof useTradingAgentStore.getState
  >["updateAgentListingStatus"];
}

function autonomyPolicyForTradingMode(
  tradingMode: ReturnType<typeof getTradingModeFromLayout>,
): AutonomyPolicy {
  if (tradingMode === "highAgency") return HIGH_AGENCY_AUTONOMY;
  if (tradingMode === "humanInLoop") return GUARDED_AUTONOMY;
  return MANUAL_AUTONOMY;
}

export function useAgentRolesPageData(): UseAgentRolesPageDataResult {
  const agents = useTradingAgentStore((s) => s.agents);
  const supervisors = useTradingAgentStore((s) => s.supervisors);
  const getSupervisorById = useTradingAgentStore((s) => s.getSupervisorById);
  const getAgentsBySupervisor = useTradingAgentStore((s) => s.getAgentsBySupervisor);
  const updateAgentListingStatus = useTradingAgentStore(
    (s) => s.updateAgentListingStatus,
  );

  const { tasks } = useAgentTasks();
  const { settings } = useSettings();
  const needsYouPolicy = useMemo(
    () => autonomyPolicyForTradingMode(getTradingModeFromLayout(settings.layout)),
    [settings.layout],
  );

  const [activeStripTabId, setActiveStripTabIdState] = useState(
    supervisors[0]?.id ?? "",
  );
  const [query, setQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState("All");
  const [custodyFilter, setCustodyFilter] = useState("All");
  const [paymentFilter, setPaymentFilter] = useState("All");
  const [listingFilter, setListingFilter] = useState("All");
  const [modeFilter, setModeFilter] = useState("All");
  const [sortKey, setSortKey] = useState<AgentRolesSortKey>("name");
  const [sortDir, setSortDir] = useState<"asc" | "desc">("asc");
  const [selectedAgentId, setSelectedAgentId] = useState<string | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);

  const registryView: AgentRolesRegistryView =
    activeStripTabId === AGENT_ROLES_PAYMENTS_VIEW_ID ? "payments" : "fleet";

  const activeSupervisor = useMemo(() => {
    if (registryView === "payments") return undefined;
    return getSupervisorById(activeStripTabId) ?? supervisors[0];
  }, [activeStripTabId, getSupervisorById, registryView, supervisors]);

  const scopedAgents = useMemo(() => {
    if (registryView === "payments") return agents;
    if (!activeSupervisor) return agents;
    return getAgentsBySupervisor(activeSupervisor.id);
  }, [registryView, activeSupervisor, agents, getAgentsBySupervisor]);

  const taskMetaByAgent = useMemo(() => {
    const map = new Map<string, { active: number; needsYou: number; executing: number }>();
    for (const task of tasks) {
      if (!task.agentId) continue;
      const entry = map.get(task.agentId) ?? { active: 0, needsYou: 0, executing: 0 };
      if (
        task.status === "pending" ||
        task.status === "watching" ||
        task.status === "executing"
      ) {
        entry.active += 1;
      }
      if (task.status === "executing") {
        entry.executing += 1;
      }
      if (isNeedsYouTask(task, needsYouPolicy)) {
        entry.needsYou += 1;
      }
      map.set(task.agentId, entry);
    }
    return map;
  }, [tasks, needsYouPolicy]);

  const registryRows = useMemo((): AgentRegistryRow[] => {
    return scopedAgents.map((agent) => {
      const meta = taskMetaByAgent.get(agent.id) ?? {
        active: 0,
        needsYou: 0,
        executing: 0,
      };
      return {
        agent,
        activeTaskCount: meta.active,
        needsYouCount: meta.needsYou,
      };
    });
  }, [scopedAgents, taskMetaByAgent]);

  const fleetStats = useMemo((): AgentRolesFleetStats => {
    let online = 0;
    let withWallet = 0;
    let payEnabled = 0;
    let didOnly = 0;
    let listed = 0;
    let needsYou = 0;
    let executing = 0;
    let idle = 0;

    for (const row of registryRows) {
      const { agent } = row;
      const meta = taskMetaByAgent.get(agent.id);
      if (agent.status === "active") online += 1;
      if (agent.status === "idle" || agent.status === "paused") idle += 1;
      const custodyKind = getAgentCustodyKind(agent);
      if (custodyKind === "wallet" || custodyKind === "vault") withWallet += 1;
      if (custodyKind === "did_only") didOnly += 1;
      if (resolveAgentPaymentState(agent) === "pay_enabled") payEnabled += 1;
      if (agent.listingStatus === "listed") listed += 1;
      if (row.needsYouCount > 0) needsYou += 1;
      if ((meta?.executing ?? 0) > 0) executing += 1;
    }

    return {
      online,
      withWallet,
      payEnabled,
      didOnly,
      listed,
      needsYou,
      executing,
      idle,
    };
  }, [registryRows, taskMetaByAgent]);

  const filteredRows = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();

    const filtered = registryRows.filter(({ agent }) => {
      if (normalizedQuery) {
        const haystack = [
          agent.displayName,
          agent.versionTag,
          agent.did,
          agent.walletAddress,
          getAgentRoleLabel(agent.role),
          getAgentCustodyLabel(agent),
          getAgentPaymentLabel(agent),
        ]
          .join(" ")
          .toLowerCase();
        if (!haystack.includes(normalizedQuery)) return false;
      }
      if (!agentMatchesRoleFilter(agent, roleFilter)) return false;
      if (!agentMatchesCustodyFilter(agent, custodyFilter)) return false;
      if (!agentMatchesPaymentFilter(agent, paymentFilter)) return false;
      if (!agentMatchesListingFilter(agent, listingFilter)) return false;
      if (!agentMatchesModeFilter(agent, modeFilter)) return false;
      return true;
    });

    const dir = sortDir === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      switch (sortKey) {
        case "role":
          return (
            getAgentRoleLabel(a.agent.role).localeCompare(
              getAgentRoleLabel(b.agent.role),
            ) * dir
          );
        case "custody":
          return (
            (a.agent.walletAddress ?? "").localeCompare(
              b.agent.walletAddress ?? "",
            ) * dir
          );
        case "work":
          return (a.activeTaskCount - b.activeTaskCount) * dir;
        case "listing":
          return (
            getListingLabel(a.agent.listingStatus).localeCompare(
              getListingLabel(b.agent.listingStatus),
            ) * dir
          );
        case "revenue":
          return (
            ((a.agent.revenue30d ?? 0) - (b.agent.revenue30d ?? 0)) * dir
          );
        case "payments":
          return (
            getAgentPaymentLabel(a.agent).localeCompare(
              getAgentPaymentLabel(b.agent),
            ) * dir
          );
        case "name":
        default:
          return a.agent.displayName.localeCompare(b.agent.displayName) * dir;
      }
    });
  }, [
    registryRows,
    query,
    roleFilter,
    custodyFilter,
    paymentFilter,
    listingFilter,
    modeFilter,
    sortKey,
    sortDir,
  ]);

  const handleSort = useCallback(
    (key: AgentRolesSortKey) => {
      if (sortKey === key) {
        setSortDir((dir) => (dir === "asc" ? "desc" : "asc"));
        return;
      }
      setSortKey(key);
      setSortDir("asc");
    },
    [sortKey],
  );

  const resetFilters = useCallback(() => {
    setQuery("");
    setRoleFilter("All");
    setCustodyFilter("All");
    setPaymentFilter("All");
    setListingFilter("All");
    setModeFilter("All");
  }, []);

  const closeDetail = useCallback(() => {
    setDetailOpen(false);
    setSelectedAgentId(null);
  }, []);

  const openDetail = useCallback((agentId: string) => {
    setSelectedAgentId(agentId);
    setDetailOpen(true);
  }, []);

  const setActiveSupervisorId = useCallback(
    (id: string) => {
      setActiveStripTabIdState(id);
      if (id === AGENT_ROLES_PAYMENTS_VIEW_ID) {
        setSortKey("payments");
      } else if (sortKey === "payments") {
        setSortKey("name");
      }
      closeDetail();
    },
    [closeDetail, sortKey],
  );

  const selectedAgent = useMemo(
    () => scopedAgents.find((agent) => agent.id === selectedAgentId),
    [scopedAgents, selectedAgentId],
  );

  useEffect(() => {
    if (!detailOpen || !selectedAgentId) return;
    const visible = filteredRows.some((row) => row.agent.id === selectedAgentId);
    if (!visible) {
      closeDetail();
    }
  }, [detailOpen, selectedAgentId, filteredRows, closeDetail]);

  return {
    agents,
    supervisors,
    activeSupervisor,
    activeStripTabId,
    registryView,
    setActiveSupervisorId,
    query,
    setQuery,
    roleFilter,
    setRoleFilter,
    custodyFilter,
    setCustodyFilter,
    paymentFilter,
    setPaymentFilter,
    listingFilter,
    setListingFilter,
    modeFilter,
    setModeFilter,
    sortKey,
    sortDir,
    handleSort,
    resetFilters,
    filteredRows,
    fleetStats,
    selectedAgentId,
    detailOpen,
    openDetail,
    closeDetail,
    selectedAgent,
    updateAgentListingStatus,
  };
}
