export const OFFLINE_DEPLOY_AGENT_STABLE_TOAST_ID = "offline:deploy-agent";

export type OfflineDeployAgentStepId =
  | "sign"
  | "submit"
  | "bind"
  | "attest";

export type OfflineDeployAgentStep = {
  id: OfflineDeployAgentStepId;
  loadingMessage: string;
  loadingDescription: string;
  delayMs: number;
};

export type OfflineDeployAgentStepParams = {
  agentCount: number;
  target: "stage" | "stage_and_publish";
  category: string;
  visibility: "public" | "preview";
  /** Primary agent display name for attest step copy. */
  primaryDisplayName: string;
  /** Primary market symbol for attest step copy. */
  primarySymbol: string;
};

const BASE_STEPS: Omit<OfflineDeployAgentStep, "loadingDescription">[] = [
  {
    id: "sign",
    loadingMessage: "Signing transaction…",
    delayMs: 400,
  },
  {
    id: "submit",
    loadingMessage: "Submitting to morphcore…",
    delayMs: 500,
  },
  {
    id: "bind",
    loadingMessage: "Binding Markets catalog…",
    delayMs: 600,
  },
  {
    id: "attest",
    loadingMessage: "Awaiting consensus…",
    delayMs: 500,
  },
];

function formatTargetLabel(target: OfflineDeployAgentStepParams["target"]): string {
  return target === "stage_and_publish" ? "Stage + Publish" : "Stage draft";
}

function formatVisibilityLabel(
  visibility: OfflineDeployAgentStepParams["visibility"],
): string {
  return visibility === "public" ? "Public" : "Unlisted preview";
}

/** Staged on-chain steps for offline deploy-to-market demo toasts. */
export function getOfflineDeployAgentSteps(
  params: OfflineDeployAgentStepParams,
): OfflineDeployAgentStep[] {
  const countLabel =
    params.agentCount === 1
      ? "1 agent"
      : `${params.agentCount} agents`;

  return BASE_STEPS.map((step) => {
    let loadingDescription: string;
    switch (step.id) {
      case "sign":
        loadingDescription = "Building KYA listing EIP-712 payload";
        break;
      case "submit":
        loadingDescription = `Broadcasting listing · /tx/v1/submit · ${formatTargetLabel(params.target)}`;
        break;
      case "bind":
        loadingDescription = `${countLabel} · ${params.category} · ${formatVisibilityLabel(params.visibility)}`;
        break;
      case "attest":
        loadingDescription =
          params.agentCount === 1
            ? `Finalizing ${params.primaryDisplayName} · ${params.primarySymbol}`
            : `Finalizing ${countLabel} · ${params.primarySymbol} +${params.agentCount - 1}`;
        break;
      default:
        loadingDescription = params.primaryDisplayName;
    }
    return { ...step, loadingDescription };
  });
}
