import type { TradeTabScope } from "../../hooks/useTradeTabScope";
import { resolveTabStripOrder, TERMINAL_TAB_STRIP } from "../smartlayout/tabStrips";
import type { TabSectionTabId } from "./TabSection";

const VAULT_TRADING_TAB_IDS: TabSectionTabId[] = [
  "buckets",
  "positions",
  "openOrders",
  "tradeHistory",
  "fundingHistory",
];

const DEFAULT_TERMINAL_TAB_ORDER = resolveTabStripOrder(TERMINAL_TAB_STRIP)
  .tabIds as TabSectionTabId[];

export function resolveTabSectionTabIds(options: {
  tabOrder?: TabSectionTabId[];
  rawProDataActive: boolean;
  rawProDataTabOrder?: TabSectionTabId[];
  agentTokenCatalogId: string | null;
  scope: TradeTabScope;
}): TabSectionTabId[] {
  let effectiveOrder: TabSectionTabId[] =
    options.rawProDataActive && options.rawProDataTabOrder
      ? options.rawProDataTabOrder
      : (options.tabOrder ?? DEFAULT_TERMINAL_TAB_ORDER);

  if (options.agentTokenCatalogId) {
    if (!effectiveOrder.includes("tokenTakers")) {
      const tradeIdx = effectiveOrder.indexOf("tradeHistory");
      effectiveOrder =
        tradeIdx >= 0
          ? [
              ...effectiveOrder.slice(0, tradeIdx + 1),
              "tokenTakers",
              ...effectiveOrder.slice(tradeIdx + 1),
            ]
          : [...effectiveOrder, "tokenTakers"];
    }
  } else {
    effectiveOrder = effectiveOrder.filter((id) => id !== "tokenTakers");
  }

  if (options.scope === "vault") {
    effectiveOrder = effectiveOrder.filter(
      (id) => id !== "balances" && id !== "depositsWithdrawals",
    );
    if (
      !options.tabOrder &&
      !(options.rawProDataActive && options.rawProDataTabOrder)
    ) {
      effectiveOrder = effectiveOrder.filter((id) =>
        VAULT_TRADING_TAB_IDS.includes(id),
      );
    }
  }

  return effectiveOrder;
}
