import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { subscribeDemoBuckets } from "../../offline/mock_data";
import { InfoClient } from "../sdk";
import { isOfflineMode } from "../sdk/utils/onboardMock";
import {
  buildLivePortfolioBalanceRows,
  buildOfflinePortfolioBalanceRows,
  sumPortfolioBalanceRowsValueUsd,
  type PortfolioBalanceRow,
} from "../utils/portfolioBalanceRows";

export interface UsePortfolioIdleSpotUsdConfig {
  baseURL: string;
  walletAddress: string;
  authToken?: string;
  refreshInterval?: number;
}

export function usePortfolioIdleSpotUsd(
  config: UsePortfolioIdleSpotUsdConfig,
): {
  rows: PortfolioBalanceRow[];
  idleSpotTotalUsd: number;
  loading: boolean;
  error: string;
} {
  const [demoVersion, setDemoVersion] = useState(0);
  const [liveRows, setLiveRows] = useState<PortfolioBalanceRow[]>([]);
  const [liveLoading, setLiveLoading] = useState(() =>
    !isOfflineMode(config.baseURL),
  );
  const [liveError, setLiveError] = useState("");
  const infoClientRef = useRef<InfoClient | null>(null);
  const clientConfigKeyRef = useRef("");
  const refreshIntervalRef = useRef<number>(0);

  const isOffline = isOfflineMode(config.baseURL);

  useEffect(() => {
    if (!isOffline) return;
    return subscribeDemoBuckets(() => setDemoVersion((version) => version + 1));
  }, [isOffline]);

  const fetchLiveBalances = useCallback(async () => {
    if (isOffline) return;
    if (!config.walletAddress?.trim()) {
      setLiveRows([]);
      setLiveLoading(false);
      setLiveError("");
      return;
    }

    const clientKey = `${config.baseURL}|${config.authToken ?? ""}`;
    if (!infoClientRef.current || clientConfigKeyRef.current !== clientKey) {
      infoClientRef.current = new InfoClient({
        baseURL: config.baseURL,
        sessionToken: config.authToken,
      });
      clientConfigKeyRef.current = clientKey;
    }

    setLiveLoading(true);
    try {
      const balances = await infoClientRef.current.getBalances(
        config.walletAddress,
      );
      setLiveRows(buildLivePortfolioBalanceRows(balances));
      setLiveError("");
    } catch (err) {
      setLiveError(
        err instanceof Error ? err.message : "Failed to fetch wallet balances",
      );
      setLiveRows([]);
    } finally {
      setLiveLoading(false);
    }
  }, [config.authToken, config.baseURL, config.walletAddress, isOffline]);

  useEffect(() => {
    if (isOffline) {
      infoClientRef.current = null;
      clientConfigKeyRef.current = "";
      return;
    }

    void fetchLiveBalances();

    if (config.refreshInterval && config.refreshInterval > 0) {
      refreshIntervalRef.current = window.setInterval(() => {
        void fetchLiveBalances();
      }, config.refreshInterval);
    }

    return () => {
      if (refreshIntervalRef.current !== 0) {
        clearInterval(refreshIntervalRef.current);
        refreshIntervalRef.current = 0;
      }
    };
  }, [config.refreshInterval, fetchLiveBalances, isOffline]);

  const offlineRows = useMemo(
    () =>
      config.walletAddress?.trim()
        ? buildOfflinePortfolioBalanceRows(config.walletAddress)
        : [],
    [config.walletAddress, demoVersion],
  );

  const rows = isOffline ? offlineRows : liveRows;
  const idleSpotTotalUsd = useMemo(
    () => sumPortfolioBalanceRowsValueUsd(rows),
    [rows],
  );

  return {
    rows,
    idleSpotTotalUsd,
    loading: isOffline ? false : liveLoading,
    error: liveError,
  };
}
