import React from "react";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import { formatVaultTvl } from "../../../offline/mock_data/vaultCatalog";
import { formatCurrency } from "../../sdk/utils/display";
import { deployedEquityUsd, deploymentPct, formatPct } from "./vaultPortfolioMetrics";
import { VAULT_TOUR_TARGETS } from "../../tutorials/vault-tour/constants";
import {
  CREATE_VAULT_TOUR_DEMO_VAULT_ID,
  CREATE_VAULT_TOUR_TARGETS,
} from "../../tutorials/create-vault-tour/constants";
import "./vault.css";

export interface VaultStatCardsProps {
  height?: string;
  vault: VaultRecord;
  yourDepositsUsd: number;
  allTimeEarnedUsd: number;
}

export default function VaultStatCards({
  height = "100%",
  vault,
  yourDepositsUsd,
  allTimeEarnedUsd,
}: VaultStatCardsProps): JSX.Element {
  const deployed = deployedEquityUsd(vault.buckets);
  const deployment = deploymentPct(vault.buckets, vault.tvlUsd);

  return (
    <div
      className="vault-slot vault-slot--flush vault-stat-cards-slot"
      style={{ height }}
      data-tour={
        vault.id === CREATE_VAULT_TOUR_DEMO_VAULT_ID
          ? CREATE_VAULT_TOUR_TARGETS.newVaultStatCards
          : VAULT_TOUR_TARGETS.statCards
      }
    >
      <div className="vault-stat-cards">
        <div className="vault-stat-card">
          <p className="vault-stat-label">TVL</p>
          <p className="vault-stat-value">{formatVaultTvl(vault.tvlUsd)}</p>
        </div>
        <div className="vault-stat-card">
          <p
            className="vault-stat-label"
            title="Share of vault TVL deployed into buckets as margin equity. Complements Balances tab Weight % (idle spot)."
          >
            Deployment
          </p>
          <p className="vault-stat-value">
            <span>{formatPct(deployment)}</span>
            <span className="terminal-label vault-stat-deployment-subline">
              {formatVaultTvl(deployed)} deployed
            </span>
          </p>
        </div>
        <div className="vault-stat-card">
          <p className="vault-stat-label">Your Deposits</p>
          <p className="vault-stat-value">{formatCurrency(yourDepositsUsd)}</p>
        </div>
        <div className="vault-stat-card">
          <p className="vault-stat-label">All-time Earned</p>
          <p className="vault-stat-value">{formatCurrency(allTimeEarnedUsd)}</p>
        </div>
      </div>
    </div>
  );
}
