import { BASE_AGENT_ALLOCATION_MB } from "../store/memoryPoolStore";
import type { TradingAgent } from "../store/types";

/** Offline estimate: DID + mandate envelope reserved at mint. */
export const AGENT_MEMORY_ENVELOPE_MB = 1.2;

/** Per-note on-chain indexing overhead for offline usage estimates. */
export const NOTE_ON_CHAIN_OVERHEAD_BYTES = 200_000;

const WARNING_FILL_PCT = 85;
const CRITICAL_FILL_PCT = 95;
const BYTES_PER_MB = 1024 * 1024;

export interface AgentMemoryUsageBreakdown {
  envelopeMb: number;
  tailMb: number;
  usedMb: number;
  allocatedMb: number;
  headroomMb: number;
  noteCount: number;
  lastNoteAt: string | null;
  status: AgentMemoryUsageStatus;
  fillPct: number;
}

export type AgentMemoryUsageStatus = "ok" | "warning" | "critical";

export function formatAgentMemoryMb(valueMb: number): string {
  if (valueMb < 0.1) return "<0.1 MB";
  if (valueMb < 10) return `${valueMb.toFixed(1)} MB`;
  return `${Math.round(valueMb)} MB`;
}

export function formatAgentMemoryMeter(usedMb: number, allocatedMb: number): string {
  return `${formatAgentMemoryMb(usedMb)} / ${formatAgentMemoryMb(allocatedMb)}`;
}

export function estimateTailBytes(agent: TradingAgent): number {
  const encoder = new TextEncoder();
  return agent.memory.reduce(
    (sum, item) =>
      sum + encoder.encode(item.text).length + NOTE_ON_CHAIN_OVERHEAD_BYTES,
    0,
  );
}

function resolveAllocatedMb(agent: TradingAgent): number {
  return agent.memoryCapacity?.allocatedMb ?? BASE_AGENT_ALLOCATION_MB;
}

function resolveStatus(fillPct: number): AgentMemoryUsageStatus {
  if (fillPct >= CRITICAL_FILL_PCT) return "critical";
  if (fillPct >= WARNING_FILL_PCT) return "warning";
  return "ok";
}

export function getAgentMemoryUsage(agent: TradingAgent): AgentMemoryUsageBreakdown {
  const allocatedMb = resolveAllocatedMb(agent);
  const envelopeMb = AGENT_MEMORY_ENVELOPE_MB;
  const tailMb = estimateTailBytes(agent) / BYTES_PER_MB;
  const rawUsedMb = envelopeMb + tailMb;
  const usedMb = Math.min(allocatedMb, rawUsedMb);
  const headroomMb = Math.max(0, allocatedMb - usedMb);
  const fillPct = Math.min(
    100,
    Math.round((usedMb / allocatedMb) * 100),
  );
  const lastNoteAt =
    agent.memory.length > 0
      ? agent.memory.reduce(
          (latest, item) =>
            new Date(item.at).getTime() > new Date(latest).getTime()
              ? item.at
              : latest,
          agent.memory[0]!.at,
        )
      : null;

  return {
    envelopeMb,
    tailMb,
    usedMb,
    allocatedMb,
    headroomMb,
    noteCount: agent.memory.length,
    lastNoteAt,
    status: resolveStatus(fillPct),
    fillPct,
  };
}
