import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { Layout, ResponsiveLayouts } from "react-grid-layout";

import { GridViewerLayout, GRID_COLS } from "../components";
import {
  AgentRolesDetailSheet,
  AgentRolesDetailSlider,
  AgentRolesFiltersSheet,
  AgentRolesFiltersSidebar,
  AgentRolesFleetStats,
  AgentRolesHeroHeader,
  AgentRolesRegistryCardList,
  AgentRolesRegistryTable,
  AgentRolesSearchToolbar,
  AgentRolesSupervisorBand,
  type AgentRolesFilterLayoutMode,
} from "../components/agentroles";
import { getLayoutForBreakpoint } from "../components/smartlayout/util";
import {
  applyAgentRolesLayoutSizing,
  buildAgentRolesResponsiveLayoutConfig,
  generateAgentRolesResponsiveLayouts,
  AGENT_ROLES_LAYOUT_MARGIN,
  AGENT_ROLES_ROW_HEIGHT,
} from "../configs/agentRolesLayoutConfig";
import { useAgentRolesPageData } from "../hooks/useAgentRolesPageData";
import { useAgentTasks } from "../hooks/useAgentTasks";
import { useMintAgentModal } from "../hooks/useMintAgentModal";
import { useDeployAgentModal } from "../hooks/useDeployAgentModal";
import { pickDeployCatalogAgentId } from "../utils/agentRoles";
import MintAgentModal from "../components/agentroles/mint/MintAgentModal";
import DeployAgentModal from "../components/agentroles/deploy/DeployAgentModal";
import MorpheumLoadingOverlay from "../components/ui/MorpheumLoadingOverlay";
import "./AgentRolesPage.css";
import "../components/agentroles/agentroles.css";

const INITIAL_CONFIG = {
  compactType: "vertical" as const,
  allStatic: true,
  layoutMargin: [AGENT_ROLES_LAYOUT_MARGIN, AGENT_ROLES_LAYOUT_MARGIN] as const,
} as const;

const ROW_HEIGHT = AGENT_ROLES_ROW_HEIGHT;
const MOBILE_BREAKPOINTS = new Set(["xs", "xxs"]);

function buildLayouts(
  viewportHeight?: number,
  advancedFilters = false,
) {
  const base = buildAgentRolesResponsiveLayoutConfig(advancedFilters);
  const height =
    viewportHeight ??
    (typeof window !== "undefined" ? window.innerHeight : 900);
  const sized = applyAgentRolesLayoutSizing(base, height, advancedFilters);
  return generateAgentRolesResponsiveLayouts(sized, 0);
}

function hasActiveAgentRolesFilters(page: {
  roleFilter: string;
  custodyFilter: string;
  paymentFilter: string;
  listingFilter: string;
  modeFilter: string;
}): boolean {
  return (
    page.roleFilter !== "All" ||
    page.custodyFilter !== "All" ||
    page.paymentFilter !== "All" ||
    page.listingFilter !== "All" ||
    page.modeFilter !== "All"
  );
}

export default function AgentRolesPage(): JSX.Element {
  const [layouts, setLayouts] = useState<ResponsiveLayouts>(() => buildLayouts());
  const [currentBreakpoint, setCurrentBreakpoint] = useState("lg");
  const [filterLayoutMode, setFilterLayoutMode] =
    useState<AgentRolesFilterLayoutMode>("compact");
  const [isLayoutMounted, setIsLayoutMounted] = useState(false);
  const [layoutsHydrated, setLayoutsHydrated] = useState(false);
  const [isPageReady, setIsPageReady] = useState(false);
  const [filtersSheetOpen, setFiltersSheetOpen] = useState(false);
  const gridRef = useRef<React.ComponentRef<typeof GridViewerLayout>>(null);

  const { tasks } = useAgentTasks();
  const page = useAgentRolesPageData();
  const mintModal = useMintAgentModal();
  const deployModal = useDeployAgentModal();

  const isMobile = MOBILE_BREAKPOINTS.has(currentBreakpoint);
  const isLg = currentBreakpoint === "lg";
  const showFiltersSidebar = isLg && filterLayoutMode === "advanced";
  const showFiltersSheetTrigger = !isLg;
  const filtersActive = hasActiveAgentRolesFilters(page);

  const handleLayoutMount = useCallback(() => setIsLayoutMounted(true), []);

  const applyViewportLayouts = useCallback(() => {
    const advancedFilters = isLg && filterLayoutMode === "advanced";
    const nextLayouts = buildLayouts(window.innerHeight, advancedFilters);
    setLayouts(nextLayouts);
    gridRef.current?.applyLayouts(nextLayouts);
  }, [filterLayoutMode, isLg]);

  useEffect(() => {
    applyViewportLayouts();
    setLayoutsHydrated(true);
    window.addEventListener("resize", applyViewportLayouts);
    return () => window.removeEventListener("resize", applyViewportLayouts);
  }, [applyViewportLayouts]);

  useEffect(() => {
    if (!isLayoutMounted || !layoutsHydrated) return;
    const id = requestAnimationFrame(() => setIsPageReady(true));
    return () => cancelAnimationFrame(id);
  }, [isLayoutMounted, layoutsHydrated]);

  useEffect(() => {
    if (showFiltersSidebar) {
      setFiltersSheetOpen(false);
    }
  }, [showFiltersSidebar]);

  useEffect(() => {
    if (isLg) return;
    setFilterLayoutMode("compact");
  }, [isLg]);

  const activeLayout = useMemo(
    () => getLayoutForBreakpoint(layouts, currentBreakpoint),
    [layouts, currentBreakpoint],
  );

  const slotDimensions = useMemo(() => {
    if (activeLayout.length === 0) return {};
    const cols = GRID_COLS[currentBreakpoint] ?? 12;
    const dimensions: Record<number, { width: string; height: string }> = {};
    for (let slotIndex = 0; slotIndex <= 8; slotIndex++) {
      const layoutItem = activeLayout.find(
        (item) => (item as unknown as { i: string }).i === slotIndex.toString(),
      );
      if (layoutItem) {
        const itemLayout = layoutItem as unknown as { w: number; h: number };
        const pixelHeight =
          itemLayout.h * ROW_HEIGHT +
          (itemLayout.h - 1) * INITIAL_CONFIG.layoutMargin[1];
        dimensions[slotIndex] = {
          width: `${(itemLayout.w / cols) * 100}%`,
          height: `${pixelHeight}px`,
        };
      }
    }
    return dimensions;
  }, [activeLayout, currentBreakpoint]);

  const onLayoutChange = useCallback(
    (_newLayout: Layout[], updatedLayouts: ResponsiveLayouts) => {
      if (INITIAL_CONFIG.allStatic) return;
      setLayouts(updatedLayouts);
    },
    [],
  );

  const selectedRow = useMemo(
    () =>
      page.filteredRows.find((row) => row.agent.id === page.selectedAgentId),
    [page.filteredRows, page.selectedAgentId],
  );

  const handleDeployToMarket = useCallback(() => {
    const agent = page.selectedAgent;
    if (!agent) return;
    const { listingStatus, id } = agent;
    if (listingStatus === "private") {
      page.updateAgentListingStatus(id, "staged");
      return;
    }
    if (listingStatus === "staged") {
      const usedCatalogIds = page.agents
        .map((entry) => entry.catalogAgentId)
        .filter((catalogId): catalogId is string => Boolean(catalogId));
      const catalogAgentId = pickDeployCatalogAgentId(id, usedCatalogIds);
      if (!catalogAgentId) return;
      page.updateAgentListingStatus(id, "listed", catalogAgentId);
    }
  }, [page.selectedAgent, page.agents, page.updateAgentListingStatus]);

  const handleRelistToMarket = useCallback(() => {
    const agent = page.selectedAgent;
    if (!agent || agent.listingStatus !== "delisted") return;
    page.updateAgentListingStatus(agent.id, "staged");
  }, [page.selectedAgent, page.updateAgentListingStatus]);

  const handleDuplicateAgent = useCallback(() => {
    const agent = page.selectedAgent;
    if (!agent) return;
    mintModal.open({ duplicateFrom: agent.id });
  }, [page.selectedAgent, mintModal.open]);

  const filterPanelProps = useMemo(
    () => ({
      roleFilter: page.roleFilter,
      custodyFilter: page.custodyFilter,
      paymentFilter: page.paymentFilter,
      listingFilter: page.listingFilter,
      modeFilter: page.modeFilter,
      onRoleFilterChange: page.setRoleFilter,
      onCustodyFilterChange: page.setCustodyFilter,
      onPaymentFilterChange: page.setPaymentFilter,
      onListingFilterChange: page.setListingFilter,
      onModeFilterChange: page.setModeFilter,
      onReset: page.resetFilters,
    }),
    [page],
  );

  const detailSlider = !isMobile ? (
    <AgentRolesDetailSlider
      isOpen={page.detailOpen}
      agent={page.selectedAgent}
      tasks={tasks}
      needsYouCount={selectedRow?.needsYouCount ?? 0}
      onClose={page.closeDetail}
      onDeployToMarket={handleDeployToMarket}
      onRelistToMarket={handleRelistToMarket}
      onDuplicateAgent={handleDuplicateAgent}
    />
  ) : null;

  const slotContent = useMemo(
    () => [
      <AgentRolesHeroHeader
        key="hero"
        height={slotDimensions[0]?.height}
      />,
      <AgentRolesSearchToolbar
        key="toolbar"
        height={slotDimensions[1]?.height}
        query={page.query}
        onQueryChange={page.setQuery}
        onMintAgent={mintModal.open}
        onDeployToMarket={() =>
          deployModal.open({
            preselectedIds: page.selectedAgentId
              ? [page.selectedAgentId]
              : [],
          })
        }
        onOpenFiltersSheet={() => setFiltersSheetOpen(true)}
        showFiltersSheetTrigger={showFiltersSheetTrigger}
        filterLayoutMode={filterLayoutMode}
        onFilterLayoutModeChange={
          isLg ? setFilterLayoutMode : undefined
        }
        filtersActive={filtersActive}
        filtersSheetOpen={filtersSheetOpen}
      />,
      showFiltersSidebar ? (
        <AgentRolesFiltersSidebar
          key="filters"
          height={slotDimensions[2]?.height}
          {...filterPanelProps}
        />
      ) : null,
      isMobile ? (
        <AgentRolesRegistryCardList
          key="cards"
          height={slotDimensions[3]?.height ?? "100%"}
          rows={page.filteredRows}
          viewMode={page.registryView}
          onRowSelect={page.openDetail}
        />
      ) : (
        <AgentRolesRegistryTable
          key="table"
          height={slotDimensions[3]?.height ?? "100%"}
          rows={page.filteredRows}
          sortKey={page.sortKey}
          sortDir={page.sortDir}
          selectedAgentId={page.selectedAgentId}
          detailOpen={page.detailOpen}
          viewMode={page.registryView}
          onSort={page.handleSort}
          onRowSelect={page.openDetail}
          detailPanel={detailSlider}
        />
      ),
      <AgentRolesSupervisorBand
        key="supervisor"
        height={slotDimensions[4]?.height}
        supervisors={page.supervisors}
        activeStripTabId={page.activeStripTabId}
        onStripTabChange={page.setActiveSupervisorId}
        supervisor={page.activeSupervisor}
        registryView={page.registryView}
      />,
      <AgentRolesFleetStats
        key="metrics"
        height={slotDimensions[5]?.height}
        stats={page.fleetStats}
      />,
      null,
      null,
      null,
    ],
    [
      slotDimensions,
      page,
      isMobile,
      isLg,
      filterLayoutMode,
      showFiltersSidebar,
      showFiltersSheetTrigger,
      filtersActive,
      filtersSheetOpen,
      filterPanelProps,
      detailSlider,
      mintModal.open,
      deployModal.open,
    ],
  );

  return (
    <div className="App-dex-content App-dex-content--agent-roles">
      {!isPageReady ? (
        <MorpheumLoadingOverlay
          layout="absolute"
          label="Loading agents..."
          matrixText
        />
      ) : null}
      <GridViewerLayout
        ref={gridRef}
        margin={INITIAL_CONFIG.layoutMargin}
        initialLayouts={layouts}
        slotContent={slotContent}
        mobileHiddenSlots={showFiltersSidebar ? [] : [2]}
        allStatic={INITIAL_CONFIG.allStatic}
        compactType={INITIAL_CONFIG.compactType}
        onLayoutChange={onLayoutChange}
        onBreakpointChange={setCurrentBreakpoint}
        onMount={handleLayoutMount}
      />
      <AgentRolesFiltersSheet
        isOpen={filtersSheetOpen}
        onClose={() => setFiltersSheetOpen(false)}
        {...filterPanelProps}
      />
      {isMobile ? (
        <AgentRolesDetailSheet
          isOpen={page.detailOpen}
          agent={page.selectedAgent}
          tasks={tasks}
          needsYouCount={selectedRow?.needsYouCount ?? 0}
          onClose={page.closeDetail}
          onDeployToMarket={handleDeployToMarket}
          onRelistToMarket={handleRelistToMarket}
          onDuplicateAgent={handleDuplicateAgent}
        />
      ) : null}
      <DeployAgentModal modal={deployModal} onMintAgent={mintModal.open} />
      <MintAgentModal modal={mintModal} />
    </div>
  );
}
