import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { Link } from "react-router-dom";

import type { VaultRecord } from "../../../offline/mock_data/vaultCatalog";
import { formatVaultApr } from "../../../offline/mock_data/vaultCatalog";
import { resolveVaultFeeModel } from "../../../offline/mock_data/vaultFeeModel";
import {
  VAULT_LOCKUP_DAYS,
  VAULT_WITHDRAW_FEE_PCT,
  type VaultUserPosition,
} from "../../../offline/mock_data/vaultUserState";
import { OFFLINE_VAULT_FUNDS_STABLE_TOAST_ID } from "../../../offline/mock_data/offlineVaultFundsSteps";
import { APP_ROUTES, vaultDetailPath } from "../../routes";
import { useBucketCollections } from "../../hooks/useBucketCollections";
import { formatCurrency } from "../../sdk/utils/display";
import { NumberPad } from "../smartlayout/number-pad";
import "../smartlayout/layout.css";
import { ModalTabBar } from "../smartlayout/modal-tab-bar";
import { FilledRangeSlider } from "../ui/FilledRangeSlider";
import { PresetCardGrid } from "../ui/PresetCardGrid";
import type { PresetCardOption } from "../ui/PresetCardGrid";
import ModalHeader from "../ui/ModalHeader";
import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useCenteredStaggeredOverlay,
  useOverlayEscapeKey,
} from "../ui/overlay";
import { createErrorCopyAction } from "../ui/Toaster";
import {
  toastCompleteError,
  toastCompleteSuccess,
  toastLoading,
  toastUpdateLoading,
} from "../ui/toastTask";
import { executeOfflineVaultFunds } from "../../utils/executeOfflineVaultFunds";
import "./vault.css";

const OFFLINE_BASE_URL = "offline://local";

type FundsTab = "deposit" | "withdraw";
type WithdrawUnit = "usdc" | "shares";

const TABS = [
  { id: "deposit" as const, label: "Deposit" },
  { id: "withdraw" as const, label: "Withdraw" },
];

const WITHDRAW_UNIT_OPTIONS: PresetCardOption<WithdrawUnit>[] = [
  {
    value: "usdc",
    label: "USDC",
    description: "Withdraw by dollar value from withdrawable balance",
  },
  {
    value: "shares",
    label: "Shares",
    description: "Withdraw by vault share count",
  },
];

const MIN_AMOUNT = 1;

export interface VaultFundsModalProps {
  isOpen: boolean;
  onClose: () => void;
  vault: VaultRecord;
  walletAddress: string;
  initialTab?: FundsTab;
  userPosition?: VaultUserPosition;
}

function maxWithdrawableShares(
  userPosition: VaultUserPosition | undefined,
  withdrawableUsd: number,
): number {
  if (!userPosition || userPosition.depositUsd <= 0) return 0;
  return userPosition.shares * (withdrawableUsd / userPosition.depositUsd);
}

export default function VaultFundsModal({
  isOpen,
  onClose,
  vault,
  walletAddress,
  initialTab = "deposit",
  userPosition,
}: VaultFundsModalProps): JSX.Element | null {
  const { mounted, panelOpen, backdropVisible, backdropStyle } =
    useCenteredStaggeredOverlay(isOpen);
  const isClosing = mounted && !isOpen;

  const [tab, setTab] = useState<FundsTab>(initialTab);
  const [amount, setAmount] = useState(0);
  const [withdrawUnit, setWithdrawUnit] = useState<WithdrawUnit>("usdc");
  const [lockupAck, setLockupAck] = useState(false);
  const [isNumberPadOpen, setIsNumberPadOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { spotWalletBalance } = useBucketCollections({
    baseURL: OFFLINE_BASE_URL,
    walletAddress,
    refreshInterval: 5000,
    useWebSocket: false,
  });

  const walletUsdc = spotWalletBalance;

  const withdrawable = useMemo(() => {
    if (!userPosition) return 0;
    return Math.max(0, userPosition.depositUsd - userPosition.lockedUsd);
  }, [userPosition]);

  const maxWithdrawShares = useMemo(
    () => maxWithdrawableShares(userPosition, withdrawable),
    [userPosition, withdrawable],
  );

  const minAmount = MIN_AMOUNT;
  const maxAmount =
    tab === "deposit"
      ? walletUsdc
      : withdrawUnit === "usdc"
        ? withdrawable
        : maxWithdrawShares;

  const canEnterAmount = maxAmount >= minAmount;

  useOverlayEscapeKey(isOpen && !isNumberPadOpen && !isSubmitting, onClose);

  useEffect(() => {
    if (isOpen) {
      setTab(initialTab);
      setAmount(0);
      setWithdrawUnit("usdc");
      setLockupAck(false);
      setIsNumberPadOpen(false);
      setIsSubmitting(false);
    }
  }, [isOpen, initialTab]);

  useEffect(() => {
    setAmount(0);
    setIsNumberPadOpen(false);
  }, [tab, withdrawUnit]);

  const feeModel = useMemo(() => resolveVaultFeeModel(vault), [vault]);

  const depositPreview = useMemo(() => {
    const sharePrice = vault.tvlUsd > 0 ? vault.tvlUsd / 1000 : 1;
    const shares =
      (amount / sharePrice) * (1 - feeModel.depositFeePct / 100) * 0.985;
    const sharePct = vault.tvlUsd > 0 ? (amount / vault.tvlUsd) * 100 : 0;
    return { shares, sharePct };
  }, [amount, vault.tvlUsd, feeModel.depositFeePct]);

  const withdrawUsdAmount = useMemo(() => {
    if (withdrawUnit === "shares" && userPosition) {
      const ratio =
        userPosition.shares > 0 ? amount / userPosition.shares : 0;
      return userPosition.depositUsd * ratio;
    }
    return amount;
  }, [amount, withdrawUnit, userPosition]);

  const withdrawPreview = useMemo(() => {
    const gross =
      withdrawUnit === "shares" ? withdrawUsdAmount : amount;
    const withdrawFeePct = feeModel.withdrawalFeePct ?? VAULT_WITHDRAW_FEE_PCT;
    return gross * (1 - withdrawFeePct / 100);
  }, [amount, withdrawUnit, withdrawUsdAmount, feeModel.withdrawalFeePct]);

  const lockedCountdown = useMemo(() => {
    if (!userPosition?.lockedUnlockAtMs) return null;
    const ms = userPosition.lockedUnlockAtMs - Date.now();
    if (ms <= 0) return "unlocks soon";
    const days = Math.floor(ms / (24 * 60 * 60 * 1000));
    const hours = Math.floor((ms % (24 * 60 * 60 * 1000)) / (60 * 60 * 1000));
    return `${days}d ${hours}h`;
  }, [userPosition]);

  const withdrawUnitHint =
    withdrawUnit === "usdc"
      ? "Amount is denominated in USDC from your withdrawable balance."
      : "Amount is denominated in vault shares (converted to USDC on withdraw).";

  const amountLabel =
    tab === "deposit"
      ? "Amount to deposit"
      : "Amount to withdraw";

  const availableLabel =
    tab === "deposit"
      ? "Wallet"
      : withdrawUnit === "usdc"
        ? "Withdrawable"
        : "Shares avail.";

  const availableValue =
    tab === "deposit"
      ? `${formatCurrency(walletUsdc)} USDC`
      : withdrawUnit === "usdc"
        ? formatCurrency(withdrawable)
        : (userPosition?.shares ?? 0).toFixed(1);

  const formatAmountDisplay = useCallback(
    (value: number) => {
      if (tab === "withdraw" && withdrawUnit === "shares") {
        return value.toFixed(2);
      }
      return formatCurrency(value);
    },
    [tab, withdrawUnit],
  );

  const canSubmit = useMemo(() => {
    if (!walletAddress.trim() || amount < minAmount || amount > maxAmount) {
      return false;
    }
    if (tab === "deposit") {
      return lockupAck;
    }
    return withdrawUsdAmount <= withdrawable;
  }, [
    walletAddress,
    amount,
    minAmount,
    maxAmount,
    tab,
    lockupAck,
    withdrawUsdAmount,
    withdrawable,
  ]);

  const openNumberPad = useCallback(() => {
    if (canEnterAmount) {
      setIsNumberPadOpen(true);
    }
  }, [canEnterAmount]);

  const handleAmountDisplayKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openNumberPad();
      }
    },
    [openNumberPad],
  );

  const handleNumberPadConfirm = useCallback((value: number) => {
    setAmount(value);
    setIsNumberPadOpen(false);
  }, []);

  const handleSubmit = useCallback(async () => {
    if (!canSubmit || isSubmitting) return;

    const mode = tab;
    const actionLabel = mode === "deposit" ? "Deposit" : "Withdraw";
    const amountUsd =
      mode === "deposit"
        ? amount
        : Math.min(withdrawUsdAmount, withdrawable);

    const toastId = toastLoading(`Processing ${actionLabel.toLowerCase()}…`, {
      stableId: OFFLINE_VAULT_FUNDS_STABLE_TOAST_ID,
      description: "Signing transaction…",
    });
    setIsSubmitting(true);

    try {
      await executeOfflineVaultFunds(
        {
          wallet: walletAddress,
          vault,
          mode,
          amountUsd,
        },
        {
          onStepStart: (step) => {
            toastUpdateLoading(toastId, step.loadingMessage, {
              description: step.loadingDescription,
            });
          },
        },
      );

      toastCompleteSuccess(toastId, `${actionLabel} completed`, {
        description: `${formatCurrency(amountUsd)} USDC ${mode === "deposit" ? "deposited to" : "withdrawn from"} ${vault.name}`,
      });
      onClose();
    } catch (err) {
      const msg =
        err instanceof Error ? err.message : `${actionLabel} failed`;
      toastCompleteError(toastId, `${actionLabel} failed`, {
        description: msg,
        action: createErrorCopyAction(msg),
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [
    canSubmit,
    isSubmitting,
    tab,
    amount,
    withdrawUsdAmount,
    withdrawable,
    walletAddress,
    vault,
    onClose,
  ]);

  const modalContent = (
    <StaggeredOverlayRoot passThrough={!isOpen}>
      <StaggeredOverlayBackdrop
        visible={backdropVisible && isOpen}
        style={backdropStyle}
        onClose={isSubmitting ? () => {} : onClose}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className={`modal-content terminal-overlay-panel-shell vault-modal-content staggered-overlay-panel--scale${isClosing ? " bucket-modal-panel--closing" : ""}`}
        aria-label="Manage vault funds"
      >
        <ModalHeader
          multiline
          onClose={onClose}
          closeDisabled={isClosing || isSubmitting}
          leading={
            <h2 className="terminal-panel-title">{vault.name} · Manage funds</h2>
          }
        />

        <ModalTabBar
          tabs={TABS}
          activeTabId={tab}
          onTabChange={setTab}
          disabled={isClosing || isSubmitting}
          aria-label="Deposit or withdraw"
        />

        <div className="modal-body">
          {isSubmitting ? (
            <div className="transfer-create-processing">
              <p className="terminal-label">
                {tab === "deposit" ? "Processing deposit…" : "Processing withdraw…"}
              </p>
              <p className="terminal-value">
                On-chain progress is shown in the notification.
              </p>
            </div>
          ) : tab === "deposit" ? (
            <>
              <div className="transfer-field-group">
                <div className="transfer-amount-header">
                  <label className="terminal-label transfer-field-label">
                    {amountLabel}
                  </label>
                  <div className="transfer-available-balance">
                    <span className="terminal-label">{availableLabel}</span>
                    <span className="terminal-value">{availableValue}</span>
                  </div>
                </div>
                {canEnterAmount ? (
                  <>
                    <div
                      className="transfer-amount-display transfer-amount-display--interactive"
                      onClick={openNumberPad}
                      onKeyDown={handleAmountDisplayKeyDown}
                      role="button"
                      tabIndex={0}
                      aria-label="Edit deposit amount"
                    >
                      <span className="terminal-price transfer-amount-value">
                        {formatAmountDisplay(amount)}
                      </span>
                    </div>
                    <div className="transfer-amount-container">
                      <FilledRangeSlider
                        variant="info"
                        min={minAmount}
                        max={maxAmount}
                        step={0.01}
                        value={amount}
                        onChange={setAmount}
                      />
                      <div className="transfer-amount-labels">
                        <span className="terminal-value">
                          {formatCurrency(minAmount)}
                        </span>
                        <span className="terminal-value">
                          {formatCurrency(maxAmount)}
                        </span>
                      </div>
                    </div>
                  </>
                ) : (
                  <div className="transfer-insufficient-funds">
                    Insufficient funds. Minimum required:{" "}
                    {formatCurrency(minAmount)}
                  </div>
                )}
              </div>

              <div className="vault-modal-preview">
                <span>
                  You receive ~ {depositPreview.shares.toFixed(1)} vault shares
                </span>
                <span>
                  Your share of vault ~ {depositPreview.sharePct.toFixed(2)}%
                </span>
                <span>Est. APR {formatVaultApr(vault.aprPct)} (variable)</span>
                <span>
                  Performance fee {feeModel.performanceFeePct.toFixed(1)}% (HWM
                  applies)
                </span>
                <span>Deposit fee {feeModel.depositFeePct.toFixed(2)}%</span>
              </div>

              <p className="vault-modal-lockup">
                Lockup — deposits are locked for {VAULT_LOCKUP_DAYS} days before
                they can be withdrawn (HLP/MLP-style lockup).
              </p>

              <label className="vault-modal-lockup-ack">
                <input
                  type="checkbox"
                  checked={lockupAck}
                  onChange={(e) => setLockupAck(e.target.checked)}
                />
                <span>
                  I understand the lockup and that vault returns can vary
                </span>
              </label>
            </>
          ) : (
            <>
              <section className="transfer-field-group">
                <h4 className="vault-modal-section-title">Your position</h4>
                <div className="vault-modal-preview">
                  <span>
                    Vault shares {userPosition?.shares.toFixed(1) ?? "0"}
                  </span>
                  <span>
                    Current value {formatCurrency(userPosition?.depositUsd ?? 0)}{" "}
                    (+{formatCurrency(userPosition?.allTimeEarnedUsd ?? 0)}{" "}
                    all-time)
                  </span>
                  <span>Withdrawable now {formatCurrency(withdrawable)}</span>
                  <span>
                    Locked (unbonding){" "}
                    {formatCurrency(userPosition?.lockedUsd ?? 0)}
                    {lockedCountdown ? ` · unlocks in ${lockedCountdown}` : ""}
                  </span>
                </div>
              </section>

              <section className="transfer-field-group">
                <h4 className="vault-modal-section-title">Withdraw as</h4>
                <PresetCardGrid
                  options={WITHDRAW_UNIT_OPTIONS}
                  selected={withdrawUnit}
                  onSelect={setWithdrawUnit}
                  columns={2}
                  hint={withdrawUnitHint}
                  aria-label="Withdraw unit"
                />
              </section>

              <div className="transfer-field-group">
                <div className="transfer-amount-header">
                  <label className="terminal-label transfer-field-label">
                    {amountLabel}
                  </label>
                  <div className="transfer-available-balance">
                    <span className="terminal-label">{availableLabel}</span>
                    <span className="terminal-value">{availableValue}</span>
                  </div>
                </div>
                {canEnterAmount ? (
                  <>
                    <div
                      className="transfer-amount-display transfer-amount-display--interactive"
                      onClick={openNumberPad}
                      onKeyDown={handleAmountDisplayKeyDown}
                      role="button"
                      tabIndex={0}
                      aria-label="Edit withdraw amount"
                    >
                      <span className="terminal-price transfer-amount-value">
                        {formatAmountDisplay(amount)}
                      </span>
                    </div>
                    <div className="transfer-amount-container">
                      <FilledRangeSlider
                        variant="info"
                        min={minAmount}
                        max={maxAmount}
                        step={0.01}
                        value={amount}
                        onChange={setAmount}
                      />
                      <div className="transfer-amount-labels">
                        <span className="terminal-value">
                          {withdrawUnit === "shares"
                            ? minAmount.toFixed(2)
                            : formatCurrency(minAmount)}
                        </span>
                        <span className="terminal-value">
                          {withdrawUnit === "shares"
                            ? maxAmount.toFixed(2)
                            : formatCurrency(maxAmount)}
                        </span>
                      </div>
                    </div>
                  </>
                ) : (
                  <div className="transfer-insufficient-funds">
                    Nothing withdrawable yet. Minimum required:{" "}
                    {withdrawUnit === "shares"
                      ? minAmount.toFixed(2)
                      : formatCurrency(minAmount)}
                  </div>
                )}
              </div>

              <div className="vault-modal-preview">
                <span>You receive ~ {formatCurrency(withdrawPreview)} USDC</span>
                <span>
                  Withdrawal fee {feeModel.withdrawalFeePct.toFixed(2)}%
                </span>
              </div>

              <p className="vault-modal-lockup">
                Amounts still inside the {VAULT_LOCKUP_DAYS}-day lockup window
                show as Locked above and cannot be withdrawn until they unbond.
              </p>
            </>
          )}
        </div>

        <div className="modal-footer">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={onClose}
            disabled={isClosing || isSubmitting}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => void handleSubmit()}
            disabled={!canSubmit || isClosing || isSubmitting}
          >
            {isSubmitting
              ? tab === "deposit"
                ? "Depositing…"
                : "Withdrawing…"
              : tab === "deposit"
                ? "Deposit USDC"
                : "Withdraw"}
          </button>
        </div>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return (
    <>
      {mounted && typeof document !== "undefined"
        ? createPortal(modalContent, document.body)
        : null}
      <NumberPad
        isOpen={isNumberPadOpen}
        value={amount}
        min={minAmount}
        max={maxAmount}
        onConfirm={handleNumberPadConfirm}
        onCancel={() => setIsNumberPadOpen(false)}
      />
    </>
  );
}
