import React from "react";

import "./vault.css";

export interface VaultTableFooterProps {
  page: number;
  pageSize: number;
  totalCount: number;
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;
}

export default function VaultTableFooter({
  page,
  pageSize,
  totalCount,
  onPageChange,
  onPageSizeChange,
}: VaultTableFooterProps): JSX.Element {
  const start = totalCount === 0 ? 0 : page * pageSize + 1;
  const end = Math.min(totalCount, (page + 1) * pageSize);
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));

  return (
    <div className="vault-table-footer">
      <div className="vault-table-footer-controls">
        <span>Rows per page:</span>
        <select
          className="vault-filter-select"
          value={pageSize}
          onChange={(e) => {
            onPageSizeChange(Number(e.target.value));
            onPageChange(0);
          }}
          aria-label="Rows per page"
        >
          <option value={10}>10</option>
          <option value={25}>25</option>
          <option value={50}>50</option>
        </select>
      </div>
      <span>
        {start}–{end} of {totalCount}
      </span>
      <div className="vault-table-footer-controls">
        <button
          type="button"
          className="vault-table-footer-btn"
          disabled={page <= 0}
          onClick={() => onPageChange(page - 1)}
          aria-label="Previous page"
        >
          &lt;
        </button>
        <button
          type="button"
          className="vault-table-footer-btn"
          disabled={page >= totalPages - 1}
          onClick={() => onPageChange(page + 1)}
          aria-label="Next page"
        >
          &gt;
        </button>
      </div>
    </div>
  );
}
