import React from "react";

import type { MintWizardStep } from "../../../utils/mintAgent";

const STEP_LABELS = ["Role", "Identity", "Namespace"] as const;

function stepIndex(step: MintWizardStep): number {
  if (step === "role") return 0;
  if (step === "identity") return 1;
  if (step === "memory" || step === "review") return 2;
  return -1;
}

export interface MintAgentStepIndicatorProps {
  step: MintWizardStep;
}

export default function MintAgentStepIndicator({
  step,
}: MintAgentStepIndicatorProps): JSX.Element | null {
  if (step === "express") return null;

  const activeIndex = stepIndex(step);
  const displayStep = step === "review" ? 3 : activeIndex + 1;

  return (
    <div className="mint-agent-step-indicator" aria-hidden={step === "review"}>
      <span className="mint-agent-step-count">Step {displayStep} of 3</span>
      <div className="mint-agent-step-track">
        {STEP_LABELS.map((label, index) => (
          <React.Fragment key={label}>
            <span
              className={`mint-agent-step-dot${
                index <= activeIndex ? " is-active" : ""
              }${step === "review" && index === 2 ? " is-active" : ""}`}
            />
            {index < STEP_LABELS.length - 1 ? (
              <span
                className={`mint-agent-step-line${
                  index < activeIndex || step === "review" ? " is-active" : ""
                }`}
              />
            ) : null}
          </React.Fragment>
        ))}
      </div>
      <span className="mint-agent-step-labels">
        {STEP_LABELS.join(" · ")}
      </span>
    </div>
  );
}
