import { useMemo, useSyncExternalStore } from "react";
import { cloneVaultFundsMovements } from "../../offline/mock_data/vaultActivityData";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import type { VaultFundsMovementRow } from "../../offline/mock_data/vaultMockData.types";
import {
  getVaultUserStateRevision,
  getWalletFundsMovements,
  mergeVaultFundsMovements,
  subscribeVaultUserState,
} from "../../offline/mock_data/vaultUserState";
import { useOnboard } from "./useOnboard";

export function useVaultFundsMovements(vaultId: string): VaultFundsMovementRow[] {
  const { walletAddress } = useOnboard();
  const revision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );

  return useMemo(() => {
    void revision;
    void cacheRevision;
    const base = cloneVaultFundsMovements(vaultId);
    const overlay = getWalletFundsMovements(walletAddress, vaultId);
    return mergeVaultFundsMovements(base, overlay);
  }, [vaultId, walletAddress, revision, cacheRevision]);
}
