import type {
  TraderLeaderboardFile,
  TraderLeaderboardManifest,
} from "../../../../offline/mock_data/traderLeaderboard.types";
import {
  clearTraderLeaderboardCache as clearSharedTraderLeaderboardCache,
  getCachedTraderLeaderboard as getSharedCachedTraderLeaderboard,
  isTraderLeaderboardLoaded,
  markTraderLeaderboardEmpty,
  setCachedTraderLeaderboard,
} from "../../../../offline/mock_data/traderLeaderboardCache";
import {
  TRADER_LEADERBOARD_MANIFEST_SNAPSHOT,
  TRADER_LEADERBOARD_SNAPSHOT,
} from "../../../../offline/mock_data/traderLeaderboardManifestSnapshot";

export const TRADER_LEADERBOARD_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_TRADER_LEADERBOARD_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/trader-leaderboard";

let manifestCache: TraderLeaderboardManifest | null = null;
let manifestPromise: Promise<TraderLeaderboardManifest> | null = null;
let tradersPromise: Promise<TraderLeaderboardFile | null> | null = null;

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function clearTraderLeaderboardClientCache(): void {
  manifestCache = null;
  manifestPromise = null;
  tradersPromise = null;
  clearSharedTraderLeaderboardCache();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

function hydrateFromSnapshot(): TraderLeaderboardFile {
  const payload: TraderLeaderboardFile = {
    traders: TRADER_LEADERBOARD_SNAPSHOT.traders.map((row) => ({
      ...row,
      byTimeframe: {
        all: { ...row.byTimeframe.all },
        "30d": { ...row.byTimeframe["30d"] },
        "7d": { ...row.byTimeframe["7d"] },
      },
    })),
  };
  setCachedTraderLeaderboard(payload);
  manifestCache = TRADER_LEADERBOARD_MANIFEST_SNAPSHOT;
  return getSharedCachedTraderLeaderboard()!;
}

export async function fetchTraderLeaderboardManifest(
  baseUrl: string = TRADER_LEADERBOARD_DATA_BASE_URL,
): Promise<TraderLeaderboardManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<TraderLeaderboardManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  )
    .then((manifest) => {
      manifestCache = manifest;
      return manifest;
    })
    .catch(() => {
      manifestCache = TRADER_LEADERBOARD_MANIFEST_SNAPSHOT;
      return TRADER_LEADERBOARD_MANIFEST_SNAPSHOT;
    })
    .finally(() => {
      manifestPromise = null;
    });

  return manifestPromise;
}

export function getCachedTraderLeaderboardManifest(): TraderLeaderboardManifest | null {
  return manifestCache;
}

export async function fetchTraderLeaderboard(
  baseUrl: string = TRADER_LEADERBOARD_DATA_BASE_URL,
): Promise<TraderLeaderboardFile | null> {
  const cached = getSharedCachedTraderLeaderboard();
  if (cached) return cached;

  if (tradersPromise) return tradersPromise;

  tradersPromise = (async () => {
    try {
      const manifest = await fetchTraderLeaderboardManifest(baseUrl);
      const payload = await fetchJson<TraderLeaderboardFile>(
        joinBaseUrl(baseUrl, manifest.file),
      );
      setCachedTraderLeaderboard(payload);
      return payload;
    } catch (err) {
      if (err instanceof Error && err.message.includes("HTTP 404")) {
        markTraderLeaderboardEmpty();
        return { traders: [] };
      }
      return hydrateFromSnapshot();
    }
  })().finally(() => {
    tradersPromise = null;
  });

  return tradersPromise;
}

export function getCachedTraderLeaderboardData(): TraderLeaderboardFile | null {
  return getSharedCachedTraderLeaderboard();
}

export function isTraderLeaderboardDataLoaded(): boolean {
  return isTraderLeaderboardLoaded();
}

export { subscribeTraderLeaderboardCache } from "../../../../offline/mock_data/traderLeaderboardCache";
