import React from "react";

import type { VaultPositionRow } from "../../../offline/mock_data/vaultCatalog";
import {
  POSITION_PNL_COLOR_NEGATIVE,
  POSITION_PNL_COLOR_POSITIVE,
} from "../../constants";
import {
  formatMargin,
  formatPnL,
  formatPrice,
  formatSize,
} from "../../sdk/utils/display";
import type { useVaultBucketPositions } from "../../hooks/useVaultBucketPositions";
import { EmptyMessage, TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import "../smartlayout/layout.css";
import "./vault.css";
import "../tables/position.css";

type PositionsState = ReturnType<typeof useVaultBucketPositions>;

export type VaultPositionsTableLayout = "bucket" | "terminal";

export interface VaultPositionsTableProps {
  positionsState: PositionsState;
  allPositions: VaultPositionRow[];
  layout?: VaultPositionsTableLayout;
}

const GRID =
  "1.2fr 0.85fr 0.8fr 1fr 1fr 1fr 1fr 1.15fr 1fr";

function VaultPositionsTableHeader(): JSX.Element {
  return (
    <div className="table-header" style={{ gridTemplateColumns: GRID }}>
      <TableHeaderCellStatic left>Market</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Side</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Size</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Pos.Value</TableHeaderCellStatic>
      <TableHeaderCellStatic left>
        <TableHeaderLabel {...TABLE_HEADER_LABELS.entryPrice} />
      </TableHeaderCellStatic>
      <TableHeaderCellStatic left>Mark</TableHeaderCellStatic>
      <TableHeaderCellStatic left>
        <TableHeaderLabel {...TABLE_HEADER_LABELS.liqPrice} />
      </TableHeaderCellStatic>
      <TableHeaderCellStatic left>P/L</TableHeaderCellStatic>
      <TableHeaderCellStatic left>Margin</TableHeaderCellStatic>
    </div>
  );
}

function VaultPositionsTotalRow({
  allPositions,
  allTotals,
}: {
  allPositions: VaultPositionRow[];
  allTotals: PositionsState["allTotals"];
}): JSX.Element {
  return (
    <div
      className="table-row vault-positions-total-row"
      style={{ gridTemplateColumns: GRID }}
    >
      <div className="table-cell primary">TOTAL ({allPositions.length})</div>
      <div />
      <div />
      <div className="table-cell numeric">
        {formatPrice(allTotals.positionValueUsd)}
      </div>
      <div />
      <div />
      <div />
      <div
        className="table-cell numeric"
        style={{
          color:
            allTotals.unrealizedPnlUsd >= 0
              ? POSITION_PNL_COLOR_POSITIVE
              : POSITION_PNL_COLOR_NEGATIVE,
        }}
      >
        {formatPnL(allTotals.unrealizedPnlUsd)}
      </div>
      <div className="table-cell numeric">{formatMargin(allTotals.marginUsd)}</div>
    </div>
  );
}

function VaultPositionRows({
  filtered,
}: {
  filtered: VaultPositionRow[];
}): JSX.Element {
  return (
    <>
      {filtered.map((row, index) => {
        const isLong = row.side === "long";
        const pnlColor =
          row.unrealizedPnlUsd >= 0
            ? POSITION_PNL_COLOR_POSITIVE
            : POSITION_PNL_COLOR_NEGATIVE;

        return (
          <div
            key={row.id}
            className={`table-row ${index % 2 === 0 ? "even" : ""}`}
            style={{ gridTemplateColumns: GRID }}
          >
            <div className="table-cell primary">
              <span>{row.market}</span>
            </div>
            <div className={isLong ? "terminal-long" : "terminal-short"}>
              {row.leverage}x {isLong ? "LONG" : "SHORT"}
            </div>
            <div className="table-cell numeric">{formatSize(row.size)}</div>
            <div className="table-cell numeric">
              {formatPrice(row.positionValueUsd)}
            </div>
            <div className="table-cell numeric">{formatPrice(row.entryPrice)}</div>
            <div className="table-cell numeric">{formatPrice(row.markPrice)}</div>
            <div className="table-cell numeric">{formatPrice(row.liqPrice)}</div>
            <div className="table-cell numeric" style={{ color: pnlColor }}>
              {formatPnL(row.unrealizedPnlUsd)} ({row.roePct >= 0 ? "+" : ""}
              {row.roePct}%)
            </div>
            <div className="table-cell numeric">{formatMargin(row.marginUsd)}</div>
          </div>
        );
      })}
    </>
  );
}

export default function VaultPositionsTable({
  positionsState,
  allPositions,
  layout = "bucket",
}: VaultPositionsTableProps): JSX.Element {
  const { filtered, allTotals } = positionsState;

  if (filtered.length === 0) {
    return (
      <div className="table-container shrinkable position-table">
        <VaultPositionsTableHeader />
        <EmptyMessage message="No positions." />
      </div>
    );
  }

  if (layout === "terminal") {
    return (
      <div className="table-container shrinkable position-table">
        <VaultPositionsTableHeader />
        <VaultPositionRows filtered={filtered} />
        <VaultPositionsTotalRow allPositions={allPositions} allTotals={allTotals} />
      </div>
    );
  }

  return (
    <div className="vault-portfolio-table-panel vault-bucket-positions-panel">
      <div className="vault-bucket-positions-table-frame">
        <div className="vault-bucket-positions-table-header">
          <VaultPositionsTableHeader />
        </div>
        <div className="vault-bucket-positions-table-scroll">
          <div className="table-container shrinkable position-table">
            <VaultPositionRows filtered={filtered} />
          </div>
        </div>
        <div className="vault-bucket-positions-table-footer">
          <VaultPositionsTotalRow
            allPositions={allPositions}
            allTotals={allTotals}
          />
        </div>
      </div>
    </div>
  );
}
