import type {
  StakingValidatorsFile,
} from "./stakingValidators.types";

let cachedValidators: StakingValidatorsFile | null = null;
const listeners = new Set<() => void>();

let revision = 0;

export function getStakingValidatorsCacheRevision(): number {
  return revision;
}

export function subscribeStakingValidatorsCache(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notifyStakingValidatorsCache(): void {
  revision += 1;
  for (const listener of listeners) {
    listener();
  }
}

export function setCachedStakingValidators(data: StakingValidatorsFile): void {
  cachedValidators = data;
  notifyStakingValidatorsCache();
}

export function getCachedStakingValidators(): StakingValidatorsFile | null {
  return cachedValidators;
}

export function clearStakingValidatorsCache(): void {
  cachedValidators = null;
  notifyStakingValidatorsCache();
}

export function isStakingValidatorsLoaded(): boolean {
  return cachedValidators != null;
}

export function markStakingValidatorsEmpty(): void {
  cachedValidators = { validators: [] };
  notifyStakingValidatorsCache();
}
