/**
 * Wallet-scoped validator delegation (offline demo).
 */

import { generateDemoTxHash } from "../../mormv1/stores/crossChainTransferStore";
import type { StakingActivityRow } from "./stakingMockData.types";
import {
  getStakingUserState,
  pushStakingActivity,
} from "./stakingUserState";

const STORAGE_PREFIX = "offline_staking_delegation_";

let stateRevision = 0;
const listeners = new Set<() => void>();
const memoryDelegations = new Map<string, StakingDelegationMap>();

export type StakingDelegationMap = Record<string, number>;

function storageKey(wallet: string): string {
  return `${STORAGE_PREFIX}${wallet.trim().toLowerCase()}`;
}

function emptyDelegations(): StakingDelegationMap {
  return {};
}

function normalizeDelegations(raw: StakingDelegationMap): StakingDelegationMap {
  const next: StakingDelegationMap = {};
  for (const [validatorId, amount] of Object.entries(raw)) {
    if (!validatorId || !Number.isFinite(amount) || amount <= 0) continue;
    next[validatorId] = amount;
  }
  return next;
}

function loadDelegations(wallet: string): StakingDelegationMap {
  const key = storageKey(wallet);
  if (typeof localStorage !== "undefined") {
    try {
      const raw = localStorage.getItem(key);
      if (raw) return normalizeDelegations(JSON.parse(raw) as StakingDelegationMap);
    } catch {
      return memoryDelegations.get(key) ?? emptyDelegations();
    }
  }
  return memoryDelegations.get(key) ?? emptyDelegations();
}

function saveDelegations(wallet: string, delegations: StakingDelegationMap): void {
  const key = storageKey(wallet);
  if (typeof localStorage !== "undefined") {
    localStorage.setItem(key, JSON.stringify(delegations));
  }
  memoryDelegations.set(key, delegations);
}

function bumpRevision(): void {
  stateRevision += 1;
  listeners.forEach((listener) => listener());
}

export function getStakingDelegationRevision(): number {
  return stateRevision;
}

export function subscribeStakingDelegationState(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function getStakingDelegations(
  wallet: string | null | undefined,
): StakingDelegationMap {
  if (!wallet?.trim()) return emptyDelegations();
  return loadDelegations(wallet);
}

export function getTotalDelegatedMorm(
  wallet: string | null | undefined,
): number {
  const delegations = getStakingDelegations(wallet);
  return Object.values(delegations).reduce((sum, amount) => sum + amount, 0);
}

export function getDelegatableMorm(
  wallet: string | null | undefined,
  stakedMorm?: number,
): number {
  if (!wallet?.trim()) return 0;
  const staked = stakedMorm ?? getStakingUserState(wallet).stakedMorm;
  return Math.max(0, staked - getTotalDelegatedMorm(wallet));
}

export function getValidatorDelegation(
  wallet: string | null | undefined,
  validatorId: string,
): number {
  if (!wallet?.trim()) return 0;
  return getStakingDelegations(wallet)[validatorId] ?? 0;
}

export function recordDelegate(
  wallet: string,
  validatorId: string,
  amountMorm: number,
): { ok: true; txHash: string } | { ok: false; reason: "insufficient" | "invalid" } {
  if (!wallet?.trim() || !validatorId?.trim()) {
    return { ok: false, reason: "invalid" };
  }
  if (!Number.isFinite(amountMorm) || amountMorm <= 0) {
    return { ok: false, reason: "invalid" };
  }

  const delegatable = getDelegatableMorm(wallet);
  if (amountMorm > delegatable) {
    return { ok: false, reason: "insufficient" };
  }

  const delegations = loadDelegations(wallet);
  delegations[validatorId] = (delegations[validatorId] ?? 0) + amountMorm;
  saveDelegations(wallet, delegations);

  const txHash = generateDemoTxHash("dg");
  const activity: StakingActivityRow = {
    id: txHash,
    kind: "delegate",
    amountMorm,
    timestampMs: Date.now(),
    txHash,
  };
  pushStakingActivity(wallet, activity);
  bumpRevision();
  return { ok: true, txHash };
}

export function recordUndelegate(
  wallet: string,
  validatorId: string,
  amountMorm: number,
): { ok: true; txHash: string } | { ok: false; reason: "insufficient" | "invalid" } {
  if (!wallet?.trim() || !validatorId?.trim()) {
    return { ok: false, reason: "invalid" };
  }
  if (!Number.isFinite(amountMorm) || amountMorm <= 0) {
    return { ok: false, reason: "invalid" };
  }

  const delegations = loadDelegations(wallet);
  const current = delegations[validatorId] ?? 0;
  if (amountMorm > current) {
    return { ok: false, reason: "insufficient" };
  }

  const nextAmount = current - amountMorm;
  if (nextAmount <= 0) {
    delete delegations[validatorId];
  } else {
    delegations[validatorId] = nextAmount;
  }
  saveDelegations(wallet, delegations);

  const txHash = generateDemoTxHash("ud");
  const activity: StakingActivityRow = {
    id: txHash,
    kind: "undelegate",
    amountMorm,
    timestampMs: Date.now(),
    txHash,
  };
  pushStakingActivity(wallet, activity);
  bumpRevision();
  return { ok: true, txHash };
}

/** Test helper: reset delegation state for a wallet. */
export function resetStakingDelegationState(wallet?: string | null): void {
  if (wallet?.trim()) {
    const key = storageKey(wallet);
    if (typeof localStorage !== "undefined") {
      localStorage.removeItem(key);
    }
    memoryDelegations.delete(key);
  }
  bumpRevision();
}
