import type { ResponsiveLayouts } from "react-grid-layout";
import {
  assertNoLayoutOverlap,
  patchCollapseSlots,
  type LayoutConfigLest,
  type LayoutDefinition,
  type ResponsiveLayoutConfig,
} from "./terminalLayoutConfig";
import {
  generateLayout,
  GRID_BREAKPOINTS,
  type GridBreakpoint,
} from "../components/smartlayout/util";

/** Grid slot indices for the Agents & Roles page layout */
export const AGENT_ROLES_SLOT_INDICES = {
  hero: 0,
  toolbar: 1,
  filters: 2,
  table: 3,
  supervisor: 4,
  metrics: 5,
} as const;

export const AGENT_ROLES_TABLE_SLOT_INDEX = AGENT_ROLES_SLOT_INDICES.table;

/** Slots collapsed on all breakpoints */
export const AGENT_ROLES_COLLAPSED_SLOTS = [6, 7, 8] as const;

export const AGENT_ROLES_ROW_HEIGHT = 30;
export const AGENT_ROLES_MENUBAR_HEIGHT = 54;
export const AGENT_ROLES_LAYOUT_MARGIN = 10;
export const AGENT_ROLES_VIEWPORT_FUDGE_PX = 4;

export const AGENT_ROLES_TITLE_ROWS = 2;
export const AGENT_ROLES_METRICS_ROWS = 2;
export const AGENT_ROLES_SUPERVISOR_ROWS = 2;
export const AGENT_ROLES_TOOLBAR_ROWS = 2;
export const AGENT_ROLES_FILTERS_ROWS_STACKED = 8;
export const AGENT_ROLES_BASE_TABLE_ROWS = 12;
export const AGENT_ROLES_SCROLL_TABLE_ROWS = 20;

export const AGENT_ROLES_TITLE_COLS_LG = 3;
export const AGENT_ROLES_METRICS_COLS_LG = 9;
export const AGENT_ROLES_FILTERS_COLS_LG = 3;
export const AGENT_ROLES_TABLE_COLS_LG = 9;

export const AGENT_ROLES_SUPERVISOR_START_ROW = AGENT_ROLES_TITLE_ROWS;
export const AGENT_ROLES_TOOLBAR_START_ROW =
  AGENT_ROLES_SUPERVISOR_START_ROW + AGENT_ROLES_SUPERVISOR_ROWS;
export const AGENT_ROLES_BODY_START_ROW =
  AGENT_ROLES_TOOLBAR_START_ROW + AGENT_ROLES_TOOLBAR_ROWS;

export const AGENT_ROLES_STACKED_METRICS_START_ROW = AGENT_ROLES_TITLE_ROWS;
export const AGENT_ROLES_STACKED_SUPERVISOR_START_ROW =
  AGENT_ROLES_STACKED_METRICS_START_ROW + AGENT_ROLES_METRICS_ROWS;
export const AGENT_ROLES_STACKED_TOOLBAR_START_ROW =
  AGENT_ROLES_STACKED_SUPERVISOR_START_ROW + AGENT_ROLES_SUPERVISOR_ROWS;
export const AGENT_ROLES_STACKED_FILTERS_START_ROW =
  AGENT_ROLES_STACKED_TOOLBAR_START_ROW + AGENT_ROLES_TOOLBAR_ROWS;
/** md/sm compact — table starts immediately below toolbar (filters in sheet) */
export const AGENT_ROLES_COMPACT_TABLE_START_ROW = AGENT_ROLES_BODY_START_ROW;
/** xs/xxs compact — table starts immediately below toolbar */
export const AGENT_ROLES_MOBILE_COMPACT_TABLE_START_ROW =
  AGENT_ROLES_STACKED_FILTERS_START_ROW;

const COLLAPSED: LayoutDefinition = [0, 0, 0, 0];
const COLLAPSED_TAIL: LayoutConfigLest = [COLLAPSED, COLLAPSED, COLLAPSED];

function splitTitleMetricsCols(cols: number): {
  titleW: number;
  metricsW: number;
  metricsX: number;
} {
  const titleW = Math.round(cols / 3);
  const metricsW = cols - titleW;
  return { titleW, metricsW, metricsX: titleW };
}

function titleMetricsSlot5(
  cols: number,
  stacked: boolean,
): [LayoutDefinition, LayoutDefinition] {
  if (stacked) {
    return [
      [0, 0, cols, AGENT_ROLES_TITLE_ROWS],
      [
        0,
        AGENT_ROLES_STACKED_METRICS_START_ROW,
        cols,
        AGENT_ROLES_METRICS_ROWS,
      ],
    ];
  }

  if (cols === 12) {
    return [
      [0, 0, AGENT_ROLES_TITLE_COLS_LG, AGENT_ROLES_TITLE_ROWS],
      [
        AGENT_ROLES_TITLE_COLS_LG,
        0,
        AGENT_ROLES_METRICS_COLS_LG,
        AGENT_ROLES_METRICS_ROWS,
      ],
    ];
  }

  const { titleW, metricsW, metricsX } = splitTitleMetricsCols(cols);
  return [
    [0, 0, titleW, AGENT_ROLES_TITLE_ROWS],
    [metricsX, 0, metricsW, AGENT_ROLES_METRICS_ROWS],
  ];
}

/** lg — compact default: full-width table; filters live in bottom sheet */
function desktopAgentRolesLayoutCompact(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, AGENT_ROLES_TOOLBAR_START_ROW, cols, AGENT_ROLES_TOOLBAR_ROWS],
    COLLAPSED,
    [0, AGENT_ROLES_BODY_START_ROW, cols, AGENT_ROLES_BASE_TABLE_ROWS],
    [
      0,
      AGENT_ROLES_SUPERVISOR_START_ROW,
      cols,
      AGENT_ROLES_SUPERVISOR_ROWS,
    ],
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

/** lg — advanced alternative layout: left filter rail + table split */
function desktopAgentRolesLayoutAdvanced(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, AGENT_ROLES_TOOLBAR_START_ROW, cols, AGENT_ROLES_TOOLBAR_ROWS],
    [
      0,
      AGENT_ROLES_BODY_START_ROW,
      AGENT_ROLES_FILTERS_COLS_LG,
      AGENT_ROLES_BASE_TABLE_ROWS,
    ],
    [
      AGENT_ROLES_FILTERS_COLS_LG,
      AGENT_ROLES_BODY_START_ROW,
      AGENT_ROLES_TABLE_COLS_LG,
      AGENT_ROLES_BASE_TABLE_ROWS,
    ],
    [
      0,
      AGENT_ROLES_SUPERVISOR_START_ROW,
      cols,
      AGENT_ROLES_SUPERVISOR_ROWS,
    ],
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

/** md/sm — compact stack; filters in bottom sheet only */
function stackedAgentRolesLayoutCompact(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, false);
  return [
    titleSlot,
    [0, AGENT_ROLES_TOOLBAR_START_ROW, cols, AGENT_ROLES_TOOLBAR_ROWS],
    COLLAPSED,
    [
      0,
      AGENT_ROLES_COMPACT_TABLE_START_ROW,
      cols,
      AGENT_ROLES_BASE_TABLE_ROWS,
    ],
    [
      0,
      AGENT_ROLES_SUPERVISOR_START_ROW,
      cols,
      AGENT_ROLES_SUPERVISOR_ROWS,
    ],
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

/** xs/xxs — compact mobile stack; filters in bottom sheet only */
function mobileAgentRolesLayoutCompact(cols: number): LayoutConfigLest {
  const [titleSlot, metricsSlot] = titleMetricsSlot5(cols, true);
  return [
    titleSlot,
    [
      0,
      AGENT_ROLES_STACKED_TOOLBAR_START_ROW,
      cols,
      AGENT_ROLES_TOOLBAR_ROWS,
    ],
    COLLAPSED,
    [
      0,
      AGENT_ROLES_MOBILE_COMPACT_TABLE_START_ROW,
      cols,
      AGENT_ROLES_BASE_TABLE_ROWS,
    ],
    [
      0,
      AGENT_ROLES_STACKED_SUPERVISOR_START_ROW,
      cols,
      AGENT_ROLES_SUPERVISOR_ROWS,
    ],
    metricsSlot,
    ...COLLAPSED_TAIL,
  ];
}

export const agentRolesLayoutLg: LayoutConfigLest =
  desktopAgentRolesLayoutCompact(12);
export const agentRolesLayoutLgAdvanced: LayoutConfigLest =
  desktopAgentRolesLayoutAdvanced(12);
export const agentRolesLayoutMd: LayoutConfigLest =
  stackedAgentRolesLayoutCompact(10);
export const agentRolesLayoutSm: LayoutConfigLest =
  stackedAgentRolesLayoutCompact(6);
export const agentRolesLayoutXs: LayoutConfigLest =
  mobileAgentRolesLayoutCompact(4);
export const agentRolesLayoutXxs: LayoutConfigLest =
  mobileAgentRolesLayoutCompact(2);

export function buildAgentRolesResponsiveLayoutConfig(
  advancedFilters = false,
): ResponsiveLayoutConfig {
  const collapseAll = (layout: LayoutConfigLest) =>
    patchCollapseSlots(layout, AGENT_ROLES_COLLAPSED_SLOTS);

  const lgLayout = advancedFilters
    ? agentRolesLayoutLgAdvanced
    : agentRolesLayoutLg;

  return {
    lg: collapseAll(lgLayout),
    md: collapseAll(agentRolesLayoutMd),
    sm: collapseAll(agentRolesLayoutSm),
    xs: collapseAll(agentRolesLayoutXs),
    xxs: collapseAll(agentRolesLayoutXxs),
  };
}

export function generateAgentRolesResponsiveLayouts(
  configs: Record<GridBreakpoint, LayoutConfigLest>,
  totalItems = 0,
): ResponsiveLayouts {
  const result: ResponsiveLayouts = {};
  for (const bp of GRID_BREAKPOINTS) {
    result[bp] = generateLayout(
      configs[bp],
      totalItems,
    ) as unknown as ResponsiveLayouts[string];
  }
  return result;
}

function patchTableSlotHeight(
  layout: LayoutConfigLest,
  tableRows: number,
): LayoutConfigLest {
  const tableSlot = layout[AGENT_ROLES_TABLE_SLOT_INDEX];
  const filtersSlot = layout[AGENT_ROLES_SLOT_INDICES.filters];
  if (!tableSlot || tableSlot[2] === 0 || tableSlot[3] === 0) return layout;

  const tableStart = tableSlot[1];
  const nextTable: LayoutDefinition = [
    tableSlot[0],
    tableStart,
    tableSlot[2],
    tableRows,
  ];

  let nextFilters = filtersSlot;
  if (
    filtersSlot &&
    filtersSlot[2] !== 0 &&
    filtersSlot[3] !== 0 &&
    filtersSlot[1] === tableStart &&
    filtersSlot[0] !== tableSlot[0]
  ) {
    nextFilters = [filtersSlot[0], tableStart, filtersSlot[2], tableRows];
  }

  return layout.map((item, index) => {
    if (index === AGENT_ROLES_TABLE_SLOT_INDEX) return nextTable;
    if (index === AGENT_ROLES_SLOT_INDICES.filters && nextFilters) {
      return nextFilters;
    }
    return item;
  });
}

export function patchAgentRolesScrollTableHeights(
  config: ResponsiveLayoutConfig,
): ResponsiveLayoutConfig {
  const patch = (layout: LayoutConfigLest) =>
    patchTableSlotHeight(layout, AGENT_ROLES_SCROLL_TABLE_ROWS);

  return {
    lg: patch(config.lg),
    md: patch(config.md),
    sm: patch(config.sm),
    xs: patch(config.xs),
    xxs: patch(config.xxs),
  };
}

export function applyAgentRolesLayoutSizing(
  config: ResponsiveLayoutConfig,
  _viewportHeight?: number,
  _advancedFilters = false,
): ResponsiveLayoutConfig {
  return patchAgentRolesScrollTableHeights(config);
}

export function assertAgentRolesLayoutValid(
  config: ResponsiveLayoutConfig,
): void {
  for (const bp of ["lg", "md", "sm", "xs", "xxs"] as const) {
    assertNoLayoutOverlap(config[bp], `agentRoles ${bp}`);
  }
}
