import { useMemo } from "react";
import { sortIdleBalances, weightPct } from "../components/vault/vaultPortfolioMetrics";
import type { VaultBalanceRow } from "../../offline/mock_data/vaultMockData.types";
import { useBucketCollections } from "./useBucketCollections";
import { usePortfolioIdleSpotUsd } from "./usePortfolioIdleSpotUsd";
import {
  type PortfolioBalanceRow,
  buildOfflinePortfolioBalanceRows,
} from "../utils/portfolioBalanceRows";
import { computeTotalWalletEquity } from "../utils/portfolioWalletEquity";

export type { PortfolioBalanceRow } from "../utils/portfolioBalanceRows";
export { buildOfflinePortfolioBalanceRows } from "../utils/portfolioBalanceRows";

export interface UsePortfolioBalancesConfig {
  baseURL: string;
  walletAddress: string;
  authToken?: string;
  refreshInterval?: number;
}

function toSortableRows(rows: PortfolioBalanceRow[]): VaultBalanceRow[] {
  return rows.map((row) => ({
    vaultId: "",
    ...row,
  }));
}

export function usePortfolioBalances(config: UsePortfolioBalancesConfig): {
  rows: PortfolioBalanceRow[];
  sortedRows: PortfolioBalanceRow[];
  accountEquity: number;
  idleSpotTotalUsd: number;
  loading: boolean;
  error: string;
} {
  const {
    rows,
    idleSpotTotalUsd,
    loading: idleSpotLoading,
    error: idleSpotError,
  } = usePortfolioIdleSpotUsd(config);

  const {
    collections,
    loading: bucketsLoading,
    error: bucketsError,
  } = useBucketCollections({
    baseURL: config.baseURL,
    walletAddress: config.walletAddress,
    authToken: config.authToken,
    refreshInterval: config.refreshInterval,
    useWebSocket: false,
  });

  const sortedRows = useMemo(
    () => sortIdleBalances(toSortableRows(rows)) as PortfolioBalanceRow[],
    [rows],
  );

  const accountEquity = useMemo(
    () => computeTotalWalletEquity(idleSpotTotalUsd, collections),
    [idleSpotTotalUsd, collections],
  );

  return {
    rows,
    sortedRows,
    accountEquity,
    idleSpotTotalUsd,
    loading: idleSpotLoading || bucketsLoading,
    error: bucketsError || idleSpotError,
  };
}

export { weightPct };
