/**
 * Runtime vault-operate overlay — persisted for user-created vaults in offline demo.
 */

import { getVaultById } from "./vaultCatalog";
import type {
  VaultBucketSummary,
  VaultPositionRow,
} from "./vaultCatalog";
import { getBucketPositions, getVaultBucket } from "./vaultCatalog";
import type {
  VaultOpenOrderRow,
  VaultOrderHistoryRow,
  VaultTradeFill,
} from "./vaultMockData.types";
import { cloneVaultOpenOrders } from "./vaultActivityData";

const STORAGE_KEY = "offline_vault_operate:v1";

export interface PlaceVaultOrderParams {
  vaultId: string;
  bucketId: string;
  marketId: string;
  marketSymbol?: string;
  side: "BUY" | "SELL";
  orderType: "market" | "limit";
  size: number;
  price: number;
  leverage: number;
  leaderAddress?: string;
  /** Reference mark for marketable limit checks; defaults to price when omitted. */
  markPrice?: number;
}

export interface ChangeVaultLeverageParams {
  vaultId: string;
  bucketId: string;
  marketId: string;
  marketSymbol?: string;
  leverage: number;
}

interface RuntimeState {
  bucketEquityDelta: Record<string, number>;
  openPositionCountDelta: Record<string, number>;
  addedOpenOrders: VaultOpenOrderRow[];
  addedTradeFills: VaultTradeFill[];
  addedPositions: Record<string, VaultPositionRow[]>;
  leverageByPosition: Record<string, number>;
  removedBasePositionIds: Record<string, Set<string>>;
  removedBaseOrderIds: Set<string>;
  cancelledOrderSnapshots: VaultOrderHistoryRow[];
}

interface SerializedRuntimeState {
  bucketEquityDelta: Record<string, number>;
  openPositionCountDelta: Record<string, number>;
  addedOpenOrders: VaultOpenOrderRow[];
  addedTradeFills: VaultTradeFill[];
  addedPositions: Record<string, VaultPositionRow[]>;
  leverageByPosition: Record<string, number>;
  removedBasePositionIds: Record<string, string[]>;
  removedBaseOrderIds: string[];
  cancelledOrderSnapshots: VaultOrderHistoryRow[];
}

interface OperateStorageShard {
  byVaultId: Record<string, SerializedRuntimeState>;
}

let stateRevision = 0;
const listeners = new Set<() => void>();

const sessionRuntime = emptyRuntime();
const persistedRuntimes = new Map<string, RuntimeState>();
const hydratedVaultIds = new Set<string>();
let storageHydrated = false;

function emptyRuntime(): RuntimeState {
  return {
    bucketEquityDelta: {},
    openPositionCountDelta: {},
    addedOpenOrders: [],
    addedTradeFills: [],
    addedPositions: {},
    leverageByPosition: {},
    removedBasePositionIds: {},
    removedBaseOrderIds: new Set(),
    cancelledOrderSnapshots: [],
  };
}

function emptyShard(): OperateStorageShard {
  return { byVaultId: {} };
}

function readShard(): OperateStorageShard {
  if (typeof localStorage === "undefined") return emptyShard();
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return emptyShard();
    const parsed = JSON.parse(raw) as Partial<OperateStorageShard>;
    return {
      byVaultId:
        parsed.byVaultId && typeof parsed.byVaultId === "object"
          ? parsed.byVaultId
          : {},
    };
  } catch {
    return emptyShard();
  }
}

function writeShard(shard: OperateStorageShard): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(STORAGE_KEY, JSON.stringify(shard));
}

function serializeRuntime(state: RuntimeState): SerializedRuntimeState {
  const removedBasePositionIds: Record<string, string[]> = {};
  for (const [key, ids] of Object.entries(state.removedBasePositionIds)) {
    removedBasePositionIds[key] = [...ids];
  }
  return {
    bucketEquityDelta: { ...state.bucketEquityDelta },
    openPositionCountDelta: { ...state.openPositionCountDelta },
    addedOpenOrders: [...state.addedOpenOrders],
    addedTradeFills: [...state.addedTradeFills],
    addedPositions: { ...state.addedPositions },
    leverageByPosition: { ...state.leverageByPosition },
    removedBasePositionIds,
    removedBaseOrderIds: [...state.removedBaseOrderIds],
    cancelledOrderSnapshots: [...state.cancelledOrderSnapshots],
  };
}

function deserializeRuntime(serialized: SerializedRuntimeState): RuntimeState {
  const removedBasePositionIds: Record<string, Set<string>> = {};
  for (const [key, ids] of Object.entries(serialized.removedBasePositionIds)) {
    removedBasePositionIds[key] = new Set(ids);
  }
  return {
    bucketEquityDelta: { ...serialized.bucketEquityDelta },
    openPositionCountDelta: { ...serialized.openPositionCountDelta },
    addedOpenOrders: [...serialized.addedOpenOrders],
    addedTradeFills: [...serialized.addedTradeFills],
    addedPositions: { ...serialized.addedPositions },
    leverageByPosition: { ...serialized.leverageByPosition },
    removedBasePositionIds,
    removedBaseOrderIds: new Set(serialized.removedBaseOrderIds ?? []),
    cancelledOrderSnapshots: [...(serialized.cancelledOrderSnapshots ?? [])],
  };
}

function isPersistedUserVault(vaultId: string): boolean {
  return getVaultById(vaultId)?.kind === "user";
}

function loadStorageIfNeeded(): void {
  if (storageHydrated) return;
  storageHydrated = true;
  const shard = readShard();
  for (const [vaultId, serialized] of Object.entries(shard.byVaultId)) {
    persistedRuntimes.set(vaultId, deserializeRuntime(serialized));
    hydratedVaultIds.add(vaultId);
  }
}

function persistVaultRuntime(vaultId: string): void {
  if (!isPersistedUserVault(vaultId)) return;
  const runtime = persistedRuntimes.get(vaultId);
  if (!runtime) return;

  const shard = readShard();
  shard.byVaultId[vaultId] = serializeRuntime(runtime);
  writeShard(shard);
}

function getRuntime(vaultId: string): RuntimeState {
  if (isPersistedUserVault(vaultId)) {
    loadStorageIfNeeded();
    if (!persistedRuntimes.has(vaultId)) {
      const shard = readShard();
      const serialized = shard.byVaultId[vaultId];
      persistedRuntimes.set(
        vaultId,
        serialized ? deserializeRuntime(serialized) : emptyRuntime(),
      );
      hydratedVaultIds.add(vaultId);
    }
    return persistedRuntimes.get(vaultId)!;
  }
  return sessionRuntime;
}

function overlayKey(vaultId: string, bucketId: string): string {
  return `${vaultId}:${bucketId}`;
}

function positionKey(vaultId: string, bucketId: string): string {
  return `${vaultId}:${bucketId}`;
}

function leverageKey(
  vaultId: string,
  bucketId: string,
  market: string,
  side: string,
): string {
  return `${vaultId}:${bucketId}:${market}:${side}`;
}

function notify(): void {
  stateRevision += 1;
  listeners.forEach((fn) => fn());
}

function notifyAndPersist(vaultId: string): void {
  notify();
  persistVaultRuntime(vaultId);
}

export function getVaultOperateStateRevision(): number {
  return stateRevision;
}

export function subscribeVaultOperateState(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function ensureVaultOperateHydrated(vaultId?: string | null): void {
  loadStorageIfNeeded();
  if (vaultId?.trim()) {
    void getRuntime(vaultId);
  }
}

export function getVaultBucketLive(
  vaultId: string,
  bucketId: string,
): VaultBucketSummary | null {
  const base = getVaultBucket(vaultId, bucketId);
  if (!base) return null;
  const runtime = getRuntime(vaultId);
  const key = overlayKey(vaultId, bucketId);
  const equityDelta = runtime.bucketEquityDelta[key] ?? 0;
  const countDelta = runtime.openPositionCountDelta[key] ?? 0;
  return {
    ...base,
    equityUsd: Math.max(0, base.equityUsd + equityDelta),
    openPositionCount: Math.max(0, base.openPositionCount + countDelta),
  };
}

export function getRemovedBaseOrderIds(vaultId: string): Set<string> {
  return getRuntime(vaultId).removedBaseOrderIds;
}

export function getVaultOrderHistoryOverlay(
  vaultId: string,
  bucketId?: string,
): VaultOrderHistoryRow[] {
  const runtime = getRuntime(vaultId);
  return runtime.cancelledOrderSnapshots.filter((row) => {
    if (row.vaultId !== vaultId) return false;
    if (bucketId && row.bucketId !== bucketId) return false;
    return true;
  });
}

function openOrderToHistory(
  row: VaultOpenOrderRow,
  status: VaultOrderHistoryRow["status"],
  time = Date.now(),
): VaultOrderHistoryRow {
  return {
    vaultId: row.vaultId,
    bucketId: row.bucketId,
    orderId: row.orderId,
    time,
    market: row.market,
    side: row.side,
    type: row.type,
    size: row.size,
    price: row.price,
    status,
    orderValueUsd: row.orderValueUsd,
  };
}

function appendOrderHistory(
  runtime: RuntimeState,
  row: VaultOrderHistoryRow,
): void {
  runtime.cancelledOrderSnapshots.unshift(row);
}

export function getVaultOpenOrdersOverlay(
  vaultId: string,
  bucketId?: string,
): VaultOpenOrderRow[] {
  const runtime = getRuntime(vaultId);
  return runtime.addedOpenOrders.filter((row) => {
    if (row.vaultId !== vaultId) return false;
    if (bucketId && row.bucketId !== bucketId) return false;
    return true;
  });
}

export function getVaultTradeHistoryOverlay(
  vaultId: string,
  bucketId?: string,
): VaultTradeFill[] {
  const runtime = getRuntime(vaultId);
  return runtime.addedTradeFills.filter((row) => {
    if (row.vaultId !== vaultId) return false;
    if (bucketId && row.bucketId !== bucketId) return false;
    return true;
  });
}

export function getVaultPositionsOverlay(
  vaultId: string,
  bucketId: string,
): VaultPositionRow[] {
  const runtime = getRuntime(vaultId);
  return runtime.addedPositions[positionKey(vaultId, bucketId)] ?? [];
}

function mergePositionLeverage(
  row: VaultPositionRow,
  vaultId: string,
  bucketId: string,
  runtime: RuntimeState,
): VaultPositionRow {
  const key = leverageKey(vaultId, bucketId, row.market, row.side);
  const override = runtime.leverageByPosition[key];
  if (override == null) return row;
  return { ...row, leverage: override };
}

export function mergeVaultPositions(
  base: VaultPositionRow[],
  vaultId: string,
  bucketId: string,
): VaultPositionRow[] {
  const runtime = getRuntime(vaultId);
  const removed =
    runtime.removedBasePositionIds[overlayKey(vaultId, bucketId)] ?? new Set();
  const filteredBase = base.filter((row) => !removed.has(row.id));
  const overlay = getVaultPositionsOverlay(vaultId, bucketId);
  const merged = [...filteredBase, ...overlay];
  return merged.map((row) => mergePositionLeverage(row, vaultId, bucketId, runtime));
}

function isLimitOrderMarketable(
  side: "BUY" | "SELL",
  limitPrice: number,
  marketPrice: number,
): boolean {
  if (side === "BUY") return limitPrice >= marketPrice;
  return limitPrice <= marketPrice;
}

function ensurePositionBucket(
  runtime: RuntimeState,
  posKey: string,
): VaultPositionRow[] {
  if (!runtime.addedPositions[posKey]) {
    runtime.addedPositions[posKey] = [];
  }
  return runtime.addedPositions[posKey];
}

function adjustOpenPositionCount(
  runtime: RuntimeState,
  overlayKeyValue: string,
  delta: number,
): void {
  runtime.openPositionCountDelta[overlayKeyValue] =
    (runtime.openPositionCountDelta[overlayKeyValue] ?? 0) + delta;
}

function recordMarketFill(params: {
  vaultId: string;
  bucketId: string;
  coin: string;
  side: "BUY" | "SELL";
  size: number;
  price: number;
  leverage: number;
  leaderAddress: string;
  orderId: string;
}): void {
  const {
    vaultId,
    bucketId,
    coin,
    side,
    size,
    price,
    leverage,
    leaderAddress,
    orderId,
  } = params;

  const runtime = getRuntime(vaultId);
  const key = overlayKey(vaultId, bucketId);
  const posKey = positionKey(vaultId, bucketId);
  const now = Date.now();
  const fee = size * price * 0.0004;
  const positions = ensurePositionBucket(runtime, posKey);

  const closingSide = side === "SELL" ? "long" : "short";
  const openSide = side === "BUY" ? "long" : "short";
  let remaining = size;

  const closingIndex = positions.findIndex(
    (pos) => pos.market === coin && pos.side === closingSide,
  );

  if (closingIndex >= 0) {
    const existing = positions[closingIndex];
    const closedSize = Math.min(existing.size, remaining);
    remaining -= closedSize;

    const fill: VaultTradeFill = {
      vaultId,
      bucketId,
      address: leaderAddress,
      time: now,
      coin,
      dir: side === "SELL" ? "Close Long" : "Close Short",
      side: side === "SELL" ? "A" : "B",
      size: closedSize,
      price,
      closedPnl: 0,
      fee: closedSize * price * 0.0004,
    };
    runtime.addedTradeFills.unshift(fill);

    if (closedSize >= existing.size) {
      positions.splice(closingIndex, 1);
      adjustOpenPositionCount(runtime, key, -1);
    } else {
      const nextSize = existing.size - closedSize;
      const positionValueUsd = nextSize * price;
      positions[closingIndex] = {
        ...existing,
        size: nextSize,
        positionValueUsd,
        markPrice: price,
      };
    }
  }

  if (remaining > 0) {
    const fill: VaultTradeFill = {
      vaultId,
      bucketId,
      address: leaderAddress,
      time: now,
      coin,
      dir: side === "BUY" ? "Open Long" : "Open Short",
      side: side === "BUY" ? "B" : "A",
      size: remaining,
      price,
      closedPnl: 0,
      fee: remaining * price * 0.0004,
    };
    runtime.addedTradeFills.unshift(fill);

    const positionValueUsd = remaining * price;
    const marginUsd = positionValueUsd / Math.max(leverage, 1);
    positions.push({
      id: `vault-pos-${orderId}`,
      market: coin,
      leverage,
      side: openSide,
      size: remaining,
      positionValueUsd,
      entryPrice: price,
      markPrice: price,
      liqPrice: side === "BUY" ? price * 0.85 : price * 1.15,
      unrealizedPnlUsd: 0,
      roePct: 0,
      marginUsd,
    });
    adjustOpenPositionCount(runtime, key, 1);
  }

  runtime.bucketEquityDelta[key] = (runtime.bucketEquityDelta[key] ?? 0) - fee;
}

export function placeVaultOrder(params: PlaceVaultOrderParams): {
  success: boolean;
  orderId?: string;
  error?: string;
} {
  const {
    vaultId,
    bucketId,
    marketId,
    marketSymbol,
    side,
    orderType,
    size,
    price,
    leverage,
    leaderAddress = "0x0000000000000000000000000000000000000000",
    markPrice,
  } = params;

  if (size <= 0 || price <= 0) {
    return { success: false, error: "Invalid order size or price" };
  }

  const runtime = getRuntime(vaultId);
  const coin = marketSymbol ?? `MKT-${marketId}`;
  const orderId = `vault-order-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const sideLabel = side === "BUY" ? "Buy" : "Sell";
  const referenceMark = markPrice ?? price;

  if (orderType === "limit") {
    if (!isLimitOrderMarketable(side, price, referenceMark)) {
      const openOrder: VaultOpenOrderRow = {
        vaultId,
        bucketId,
        address: leaderAddress,
        orderId,
        time: Date.now(),
        market: coin,
        side: sideLabel,
        type: "Limit",
        size,
        price,
        orderValueUsd: size * price,
      };
      runtime.addedOpenOrders.unshift(openOrder);
      notifyAndPersist(vaultId);
      return { success: true, orderId };
    }
  }

  appendOrderHistory(runtime, {
    vaultId,
    bucketId,
    orderId,
    time: Date.now(),
    market: coin,
    side: sideLabel,
    type: orderType === "limit" ? "Limit" : "Market",
    size,
    price,
    status: "Filled",
    orderValueUsd: size * price,
  });

  recordMarketFill({
    vaultId,
    bucketId,
    coin,
    side,
    size,
    price,
    leverage,
    leaderAddress,
    orderId,
  });

  notifyAndPersist(vaultId);
  return { success: true, orderId };
}

export function changeVaultLeverage(
  params: ChangeVaultLeverageParams,
): { success: boolean; error?: string } {
  const { vaultId, bucketId, marketId, marketSymbol, leverage } = params;
  if (leverage <= 0) {
    return { success: false, error: "Leverage must be greater than 0" };
  }

  const runtime = getRuntime(vaultId);
  const posKey = positionKey(vaultId, bucketId);
  const positions = runtime.addedPositions[posKey] ?? [];
  const marketLabel = `MKT-${marketId}`;
  const coin = marketSymbol ?? marketLabel;
  let updated = false;

  for (const pos of positions) {
    if (
      pos.market === marketLabel ||
      pos.market === coin ||
      pos.market.includes(marketId)
    ) {
      const key = leverageKey(vaultId, bucketId, pos.market, pos.side);
      runtime.leverageByPosition[key] = leverage;
      pos.leverage = leverage;
      updated = true;
    }
  }

  if (!updated) {
    runtime.leverageByPosition[
      leverageKey(vaultId, bucketId, coin, "long")
    ] = leverage;
    runtime.leverageByPosition[
      leverageKey(vaultId, bucketId, coin, "short")
    ] = leverage;
  }

  notifyAndPersist(vaultId);
  return { success: true };
}

export function cancelVaultOrder(
  vaultId: string,
  orderId: string,
): boolean {
  const runtime = getRuntime(vaultId);
  const overlayIndex = runtime.addedOpenOrders.findIndex(
    (row) => row.vaultId === vaultId && row.orderId === orderId,
  );
  if (overlayIndex >= 0) {
    const [removed] = runtime.addedOpenOrders.splice(overlayIndex, 1);
    if (removed) {
      appendOrderHistory(
        runtime,
        openOrderToHistory(removed, "Canceled", Date.now()),
      );
    }
    notifyAndPersist(vaultId);
    return true;
  }

  if (runtime.removedBaseOrderIds.has(orderId)) {
    return true;
  }

  const baseOrder = cloneVaultOpenOrders(vaultId).find(
    (row) => row.orderId === orderId,
  );
  if (!baseOrder) return false;

  runtime.removedBaseOrderIds.add(orderId);
  appendOrderHistory(
    runtime,
    openOrderToHistory(baseOrder, "Canceled", Date.now()),
  );
  notifyAndPersist(vaultId);
  return true;
}

export function closeVaultPosition(params: {
  vaultId: string;
  bucketId: string;
  positionId: string;
  leaderAddress?: string;
}): { success: boolean; error?: string } {
  const {
    vaultId,
    bucketId,
    positionId,
    leaderAddress = "0x0000000000000000000000000000000000000000",
  } = params;
  const runtime = getRuntime(vaultId);
  const key = overlayKey(vaultId, bucketId);
  const base = getBucketPositions(vaultId, bucketId);
  const overlay = getVaultPositionsOverlay(vaultId, bucketId);
  const overlayIndex = overlay.findIndex((row) => row.id === positionId);
  const basePos = base.find((row) => row.id === positionId);

  if (overlayIndex < 0 && !basePos) {
    return { success: false, error: "Position not found" };
  }

  const pos = overlayIndex >= 0 ? overlay[overlayIndex] : basePos!;
  const side: "BUY" | "SELL" = pos.side === "long" ? "SELL" : "BUY";

  if (overlayIndex >= 0) {
    recordMarketFill({
      vaultId,
      bucketId,
      coin: pos.market,
      side,
      size: pos.size,
      price: pos.markPrice,
      leverage: pos.leverage,
      leaderAddress,
      orderId: `vault-close-${Date.now()}`,
    });
    notifyAndPersist(vaultId);
    return { success: true };
  }

  runtime.addedTradeFills.unshift({
    vaultId,
    bucketId,
    address: leaderAddress,
    time: Date.now(),
    coin: pos.market,
    dir: side === "SELL" ? "Close Long" : "Close Short",
    side: side === "SELL" ? "A" : "B",
    size: pos.size,
    price: pos.markPrice,
    closedPnl: pos.unrealizedPnlUsd,
    fee: pos.size * pos.markPrice * 0.0004,
  });

  if (!runtime.removedBasePositionIds[key]) {
    runtime.removedBasePositionIds[key] = new Set();
  }
  runtime.removedBasePositionIds[key].add(positionId);
  adjustOpenPositionCount(runtime, key, -1);
  runtime.bucketEquityDelta[key] =
    (runtime.bucketEquityDelta[key] ?? 0) - pos.size * pos.markPrice * 0.0004;

  notifyAndPersist(vaultId);
  return { success: true };
}

/** Test helper — simulate page reload while keeping persisted localStorage. */
export function reloadVaultOperateFromStorageForTests(): void {
  Object.assign(sessionRuntime, emptyRuntime());
  persistedRuntimes.clear();
  hydratedVaultIds.clear();
  storageHydrated = false;
  notify();
}

/** Test helper — reset runtime overlay between tests. */
export function resetVaultOperateStateForTests(): void {
  Object.assign(sessionRuntime, emptyRuntime());
  persistedRuntimes.clear();
  hydratedVaultIds.clear();
  storageHydrated = false;
  if (typeof localStorage !== "undefined") {
    localStorage.removeItem(STORAGE_KEY);
  }
  notify();
}

export function resetVaultOperateStorage(): void {
  resetVaultOperateStateForTests();
}
