import React from "react";

import type {
  VaultListFilterKey,
  VaultListSortKey,
  VaultListTimeframe,
} from "../../hooks/useVaultListingData";
import { CREATE_VAULT_TOUR_TARGETS } from "../../tutorials/create-vault-tour/constants";

function vaultFilterToggleClass(active: boolean): string {
  return active ? "vault-filter-toggle is-active" : "vault-filter-toggle";
}

export type VaultFiltersBarLayout = "inline" | "stacked";

export interface VaultFiltersPanelProps {
  variant?: "bar" | "sheet";
  barLayout?: VaultFiltersBarLayout;
  sortKey: VaultListSortKey;
  onSortChange: (key: VaultListSortKey) => void;
  filterKey: VaultListFilterKey;
  onFilterChange: (key: VaultListFilterKey) => void;
  timeframe: VaultListTimeframe;
  onTimeframeChange: (tf: VaultListTimeframe) => void;
  onCreateVault?: () => void;
  ownedVaultCount?: number;
  myVaultsOnly?: boolean;
  onMyVaultsToggle?: () => void;
  investedVaultCount?: number;
  investedOnly?: boolean;
  onInvestedToggle?: () => void;
  searchQuery: string;
  onSearchChange: (value: string) => void;
}

export default function VaultFiltersPanel({
  variant = "bar",
  barLayout = "inline",
  sortKey,
  onSortChange,
  filterKey,
  onFilterChange,
  timeframe,
  onTimeframeChange,
  onCreateVault,
  ownedVaultCount = 0,
  myVaultsOnly = false,
  onMyVaultsToggle,
  investedVaultCount = 0,
  investedOnly = false,
  onInvestedToggle,
  searchQuery,
  onSearchChange,
}: VaultFiltersPanelProps): JSX.Element {
  const isSheet = variant === "sheet";
  const includeCreateVault = !isSheet && Boolean(onCreateVault);
  const showInvestedAction = investedVaultCount > 0 && onInvestedToggle;
  const showMyVaultsAction = ownedVaultCount > 0 && onMyVaultsToggle;
  const showActions =
    showInvestedAction || showMyVaultsAction || includeCreateVault;

  const rootClassName = isSheet
    ? "vault-filters-panel vault-filters-panel--sheet"
    : `vault-filters-panel vault-filters-panel--bar${
        barLayout === "stacked" ? " vault-filters-panel--bar-stacked" : ""
      }`;

  const controlsClassName = isSheet
    ? "vault-filters-panel-controls vault-filters-panel-controls--sheet"
    : "vault-filters-bar-controls";

  const actionsClassName = isSheet
    ? "vault-filters-panel-actions vault-filters-panel-actions--sheet"
    : "vault-filters-bar-actions";

  return (
    <div className={rootClassName}>
      <div className={controlsClassName}>
        <div className="terminal-search-field vault-search-field">
          <input
            className="terminal-search-input"
            type="search"
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            placeholder="Search by address / name / leader"
            aria-label="Search vaults"
          />
        </div>
        <select
          className="vault-filter-select"
          value={sortKey}
          onChange={(e) => onSortChange(e.target.value as VaultListSortKey)}
          aria-label="Sort vaults"
        >
          <option value="analystScore">Sort: Analyst score</option>
          <option value="apr">Sort: APR</option>
          <option value="tvl">Sort: TVL</option>
          <option value="age">Sort: Age</option>
        </select>
        <select
          className="vault-filter-select"
          value={filterKey}
          onChange={(e) => onFilterChange(e.target.value as VaultListFilterKey)}
          aria-label="Filter vaults"
        >
          <option value="all">All vaults</option>
          <option value="leading">Leading</option>
          <option value="deposited">Deposited</option>
          <option value="others">Others</option>
        </select>
        <select
          className="vault-filter-select"
          value={timeframe}
          onChange={(e) => onTimeframeChange(e.target.value as VaultListTimeframe)}
          aria-label="Timeframe"
        >
          <option value="all-time">All-time</option>
          <option value="90d">90d</option>
          <option value="30d">30d</option>
        </select>
      </div>
      {showActions ? (
        <div className={actionsClassName}>
          {showInvestedAction ? (
            <button
              type="button"
              className={vaultFilterToggleClass(investedOnly)}
              aria-pressed={investedOnly}
              onClick={onInvestedToggle}
            >
              Invested
              {investedVaultCount > 1 ? ` (${investedVaultCount})` : ""}
            </button>
          ) : null}
          {showMyVaultsAction ? (
            <button
              type="button"
              className={vaultFilterToggleClass(myVaultsOnly)}
              aria-pressed={myVaultsOnly}
              onClick={onMyVaultsToggle}
            >
              My Vaults
              {ownedVaultCount > 1 ? ` (${ownedVaultCount})` : ""}
            </button>
          ) : null}
          {includeCreateVault ? (
            <button
              type="button"
              className="vault-filter-create-btn"
              onClick={onCreateVault}
              data-tour={CREATE_VAULT_TOUR_TARGETS.createBtn}
            >
              Create Vault
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
