import React, { useEffect, useRef, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { useLocation } from "react-router-dom";

import { appendVaultScope } from "../routes";
import {
  OVERLAY_TIMING,
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
  useOverlayScrollLock,
  useStaggeredOverlay,
} from "./ui/overlay";
import type { MenuBarNavItem } from "./vault/MenuBarVaultOperate";
import "./MenuBarMobileDrawer.css";

export type MenuBarMobileDrawerProps = {
  open: boolean;
  onClose: () => void;
  brandName: string;
  menuItems: MenuBarNavItem[];
  isVaultActive: boolean;
  vaultId: string | null;
  vaultName?: string | null;
  renderMenuItem: (item: MenuBarNavItem, href: string) => ReactNode;
  onSettingsClick?: () => void;
};

export function MenuBarMobileDrawer({
  open,
  onClose,
  brandName,
  menuItems,
  isVaultActive,
  vaultId,
  vaultName,
  renderMenuItem,
  onSettingsClick,
}: MenuBarMobileDrawerProps): JSX.Element | null {
  const location = useLocation();

  const { mounted, panelOpen, backdropVisible, backdropStyle } = useStaggeredOverlay({
    isOpen: open,
    panelDurationMs: OVERLAY_TIMING.mobileSheetMs,
    backdropFadeMs: OVERLAY_TIMING.mobileSheetMs,
    enableBackdrop: true,
    staggerBackdrop: false,
  });

  useOverlayEscapeKey(open, onClose);
  useOverlayScrollLock(open && mounted);

  const locationKey = `${location.pathname}${location.search}${location.hash}`;
  const prevLocationKeyRef = useRef(locationKey);

  useEffect(() => {
    if (prevLocationKeyRef.current === locationKey) return;
    prevLocationKeyRef.current = locationKey;
    onClose();
  }, [locationKey, onClose]);

  if (typeof document === "undefined" || !mounted) {
    return null;
  }

  const drawerContent = (
    <StaggeredOverlayRoot className="menubar-mobile-drawer-root">
      <StaggeredOverlayBackdrop
        visible={backdropVisible}
        onClose={onClose}
        style={backdropStyle}
        className="staggered-overlay-backdrop--deep"
      />
      <StaggeredOverlayPanel
        open={panelOpen}
        className="menubar-mobile-drawer-panel"
        aria-label="Main navigation"
        role="dialog"
      >
        <header className="menubar-mobile-drawer-header">
          <div>
            {isVaultActive && vaultName ? (
              <>
                <span className="menubar-mobile-drawer-vault-label">Operating</span>
                <span className="menubar-mobile-drawer-brand">{vaultName}</span>
              </>
            ) : (
              <span className="menubar-mobile-drawer-brand">{brandName}</span>
            )}
          </div>
          <button
            type="button"
            className="menubar-mobile-drawer-close"
            onClick={onClose}
            aria-label="Close menu"
          >
            ×
          </button>
        </header>
        <nav className="menubar-mobile-drawer-nav" aria-label="Main navigation">
          <ul id="menubar-mobile-menu" className="menubar-mobile-drawer-menu">
            {menuItems.map((item) => {
              const baseHref = item.href ?? "#";
              const href =
                isVaultActive && vaultId
                  ? appendVaultScope(baseHref, vaultId)
                  : baseHref;
              return <li key={item.label}>{renderMenuItem(item, href)}</li>;
            })}
            {onSettingsClick ? (
              <li>
                <button
                  type="button"
                  className="menubar-menu-item terminal-nav-link"
                  onClick={() => {
                    onSettingsClick();
                    onClose();
                  }}
                >
                  Settings
                </button>
              </li>
            ) : null}
          </ul>
        </nav>
      </StaggeredOverlayPanel>
    </StaggeredOverlayRoot>
  );

  return createPortal(drawerContent, document.body);
}
