import React, { useMemo } from "react";

import { useTradingAgents } from "../../hooks/useTradingAgents";
import { shortHashId } from "../../utils/hashId";
import TerminalCompactSettingsButton from "../preference/TerminalCompactSettingsButton";
import PortfolioHeroViewNav from "./PortfolioHeroViewNav";
import type { PortfolioHeroView } from "./portfolioHeroView";
import "../tables/agentTasks.css";
import "./portfolio.css";

export interface PortfolioHeroTitleProps {
  height?: string;
  walletAddress?: string;
  activeView?: PortfolioHeroView;
  onViewChange?: (view: PortfolioHeroView) => void;
}

function noopViewChange(): void {}

function formatMasterKeyDisplay(walletAddress: string): string {
  const trimmed = walletAddress.trim();
  if (!trimmed) return "—";
  if (trimmed.length > 10) {
    return `${trimmed.slice(0, 6)}…${trimmed.slice(-4)}`;
  }
  return trimmed;
}

function buildMasterEyebrow(walletAddress: string): string {
  const trimmed = walletAddress.trim();
  if (!trimmed) return "Master · Not connected";
  const display = formatMasterKeyDisplay(trimmed);
  return `Master · ${display || shortHashId(trimmed)}`;
}

function PortfolioHeroTitle({
  height = "100%",
  walletAddress = "",
  activeView = "overview",
  onViewChange = noopViewChange,
}: PortfolioHeroTitleProps): JSX.Element {
  const { selectedAgentId, setSelectedAgentId, getAgentById } =
    useTradingAgents();
  const focusedAgent = selectedAgentId
    ? getAgentById(selectedAgentId)
    : undefined;

  const trimmedWallet = walletAddress.trim();
  const eyebrow = useMemo(
    () => buildMasterEyebrow(walletAddress),
    [walletAddress],
  );
  const showFocus = focusedAgent != null;

  return (
    <div
      className="portfolio-slot portfolio-header-band portfolio-header-band--title portfolio-hero-header portfolio-hero-title-slot"
      style={{ height }}
    >
      <div className="terminal-header-band-actions">
        <TerminalCompactSettingsButton
          focusSection="portfolioDefaultTab"
          ariaLabel="Portfolio settings"
        />
      </div>

      <div className="portfolio-hero-header-content">
        <p
          className="eyebrow-text-wrap"
          title={trimmedWallet.length > 0 ? trimmedWallet : undefined}
        >
          <span className="eyebrow-text">{eyebrow}</span>
        </p>
        <div className="portfolio-hero-title-row">
          <h1 className="portfolio-hero-title">Portfolio</h1>
          {showFocus ? (
            <span
              className="portfolio-hero-title-focus"
              aria-label={`Focused on ${focusedAgent.displayName}`}
            >
              <span className="portfolio-hero-title-focus-label">Focused</span>
              {focusedAgent.icon ? (
                <span aria-hidden>{focusedAgent.icon}</span>
              ) : null}
              <span className="portfolio-hero-title-focus-name">
                {focusedAgent.displayName}
              </span>
              <span className="task-id-chip" title={focusedAgent.id}>
                {shortHashId(focusedAgent.id)}
              </span>
              <button
                type="button"
                className="portfolio-hero-title-focus-clear"
                onClick={() => setSelectedAgentId(null)}
                aria-label="Clear agent focus"
              >
                ×
              </button>
            </span>
          ) : null}
        </div>
      </div>

      <PortfolioHeroViewNav
        activeView={activeView}
        onViewChange={onViewChange}
      />
    </div>
  );
}

export default React.memo(PortfolioHeroTitle);
