import React from "react";

import AgentRolesCopyableValue from "./AgentRolesCopyableValue";

export interface AgentRolesRegistryWalletCellProps {
  walletAddress?: string;
}

export default function AgentRolesRegistryWalletCell({
  walletAddress,
}: AgentRolesRegistryWalletCellProps): JSX.Element {
  if (!walletAddress?.trim()) {
    return (
      <div className="agentroles-wallet-cell">
        <span className="terminal-text-muted">—</span>
      </div>
    );
  }

  return (
    <div
      className="agentroles-wallet-cell"
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      <AgentRolesCopyableValue
        value={walletAddress}
        copyLabel="wallet address"
        className="agentroles-wallet-cell__copy"
      />
    </div>
  );
}
