import React, { useCallback, useMemo, useState } from "react";

import type { StakingValidatorRow } from "../../../offline/mock_data/stakingValidators.types";
import { useStakingValidators } from "../../hooks/useStakingValidators";
import type { StakingDelegateMode } from "../../utils/executeOfflineDelegateFunds";
import VaultPanelLoadingGate from "../vault/VaultPanelLoadingGate";
import StakingDelegateModal from "./StakingDelegateModal";
import StakingValidatorsTable from "./StakingValidatorsTable";
import "./staking.css";

export interface StakingValidatorsPanelProps {
  height?: string;
  walletAddress: string;
  stakedMorm: number;
  onSuccess?: () => void;
}

function StakingValidatorsPanel({
  height = "100%",
  walletAddress,
  stakedMorm,
  onSuccess,
}: StakingValidatorsPanelProps): JSX.Element {
  const { validators, loading } = useStakingValidators(walletAddress);
  const [selectedValidator, setSelectedValidator] =
    useState<StakingValidatorRow | null>(null);
  const [initialMode, setInitialMode] = useState<StakingDelegateMode>("delegate");

  const validatorById = useMemo(() => {
    const map = new Map<string, StakingValidatorRow>();
    for (const row of validators) {
      map.set(row.validatorId, row);
    }
    return map;
  }, [validators]);

  const handleManage = useCallback(
    (validatorId: string, mode: StakingDelegateMode) => {
      const row = validatorById.get(validatorId);
      if (!row) return;
      setInitialMode(mode);
      setSelectedValidator(row);
    },
    [validatorById],
  );

  const handleCloseModal = useCallback(() => {
    setSelectedValidator(null);
  }, []);

  return (
    <>
      <VaultPanelLoadingGate
        loading={loading}
        label="Loading validators…"
        className="staking-validators-loading-gate"
        style={{ height }}
      >
        <StakingValidatorsTable
          rows={validators}
          height="100%"
          onManage={handleManage}
        />
      </VaultPanelLoadingGate>
      <StakingDelegateModal
        isOpen={selectedValidator != null}
        onClose={handleCloseModal}
        validator={selectedValidator}
        walletAddress={walletAddress}
        stakedMorm={stakedMorm}
        initialMode={initialMode}
        onSuccess={onSuccess}
      />
    </>
  );
}

export default React.memo(StakingValidatorsPanel);
