import React from "react";
import "./portfolio.css";

export interface PortfolioLedgerPanelShellProps {
  height?: string;
  title: string;
  ariaLabel: string;
  controls?: React.ReactNode;
  children: React.ReactNode;
  bodyClassName?: string;
}

function PortfolioLedgerPanelShell({
  height = "100%",
  title,
  ariaLabel,
  controls,
  children,
  bodyClassName = "",
}: PortfolioLedgerPanelShellProps): JSX.Element {
  return (
    <div className="portfolio-slot" style={{ height }}>
      <section className="portfolio-ledger-shell" aria-label={ariaLabel}>
        <div className="portfolio-ledger-shell-header">
          <h2 className="portfolio-ledger-shell-title">{title}</h2>
          {controls ? (
            <div className="portfolio-ledger-shell-controls">{controls}</div>
          ) : null}
        </div>
        <div
          className={`portfolio-ledger-shell-body${bodyClassName ? ` ${bodyClassName}` : ""}`}
        >
          {children}
        </div>
      </section>
    </div>
  );
}

export default React.memo(PortfolioLedgerPanelShell);
