import React from "react";

import type { TradingAgent } from "../../../store/types";
import type { DeployAgentWizardState, DeployTarget } from "../../../utils/deployAgent";
import {
  computeDeployEligibility,
  formatDeployAgentRowLabel,
} from "../../../utils/deployAgent";
import { getAgentRoleLabel, getListingLabel } from "../../../utils/agentRoles";

export interface DeployAgentStepSelectProps {
  agents: TradingAgent[];
  state: DeployAgentWizardState;
  onChange: (patch: Partial<DeployAgentWizardState>) => void;
  onMintAgent?: () => void;
}

function EligibilityChip({
  agent,
}: {
  agent: TradingAgent;
}): JSX.Element {
  const eligibility = computeDeployEligibility(agent);
  if (!eligibility.canSelect) {
    return (
      <span className="deploy-agent-eligibility deploy-agent-eligibility--blocked">
        {eligibility.reason ?? "Ineligible"}
      </span>
    );
  }
  if (!eligibility.canPublish && eligibility.reason) {
    return (
      <span className="deploy-agent-eligibility deploy-agent-eligibility--warn">
        {eligibility.reason}
      </span>
    );
  }
  return (
    <span className="deploy-agent-eligibility deploy-agent-eligibility--ok">
      eligible
    </span>
  );
}

export default function DeployAgentStepSelect({
  agents,
  state,
  onChange,
  onMintAgent,
}: DeployAgentStepSelectProps): JSX.Element {
  const eligibleCount = agents.filter(
    (agent) => computeDeployEligibility(agent).canSelect,
  ).length;

  const toggleAgent = (agentId: string) => {
    const agent = agents.find((entry) => entry.id === agentId);
    if (!agent || !computeDeployEligibility(agent).canSelect) return;

    const selected = state.selectedAgentIds.includes(agentId);
    const selectedAgentIds = selected
      ? state.selectedAgentIds.filter((id) => id !== agentId)
      : [...state.selectedAgentIds, agentId];
    onChange({ selectedAgentIds });
  };

  const setTarget = (target: DeployTarget) => {
    onChange({ target });
  };

  if (eligibleCount === 0) {
    return (
      <div className="deploy-agent-step deploy-agent-empty">
        <p className="terminal-text-muted">
          No eligible agents to deploy. Mint a KYA agent first.
        </p>
        {onMintAgent ? (
          <button
            type="button"
            className="btn btn-secondary deploy-agent-mint-link"
            onClick={onMintAgent}
          >
            + Mint Agent
          </button>
        ) : null}
      </div>
    );
  }

  return (
    <div className="deploy-agent-step">
      <p className="terminal-label deploy-agent-step-intro">
        Select agents to stage or publish to Markets.
      </p>
      <ul className="deploy-agent-select-list">
        {agents.map((agent) => {
          const eligibility = computeDeployEligibility(agent);
          const checked = state.selectedAgentIds.includes(agent.id);
          const disabled = !eligibility.canSelect;

          return (
            <li key={agent.id} className="deploy-agent-select-row">
              <label
                className={`deploy-agent-select-label${
                  disabled ? " is-disabled" : ""
                }`}
              >
                <input
                  type="checkbox"
                  checked={checked}
                  disabled={disabled}
                  onChange={() => toggleAgent(agent.id)}
                />
                <span className="deploy-agent-select-name terminal-value">
                  {agent.displayName}
                </span>
                <span className="deploy-agent-select-meta terminal-label">
                  {getAgentRoleLabel(agent.role)} ·{" "}
                  {getListingLabel(agent.listingStatus)}
                </span>
                <EligibilityChip agent={agent} />
              </label>
            </li>
          );
        })}
      </ul>

      <fieldset className="deploy-agent-target-fieldset">
        <legend className="terminal-label">Target</legend>
        <label className="deploy-agent-radio">
          <input
            type="radio"
            name="deploy-target"
            checked={state.target === "stage"}
            onChange={() => setTarget("stage")}
          />
          <span>Stage draft</span>
        </label>
        <label className="deploy-agent-radio">
          <input
            type="radio"
            name="deploy-target"
            checked={state.target === "stage_and_publish"}
            onChange={() => setTarget("stage_and_publish")}
          />
          <span>Stage + Publish</span>
        </label>
      </fieldset>

      {state.selectedAgentIds.length > 0 ? (
        <p className="terminal-label deploy-agent-selection-count">
          {state.selectedAgentIds.length} selected —{" "}
          {state.selectedAgentIds
            .map((id) => agents.find((a) => a.id === id))
            .filter(Boolean)
            .map((agent) => formatDeployAgentRowLabel(agent!))
            .join("; ")}
        </p>
      ) : null}
    </div>
  );
}
