import React from "react";

export interface PortfolioFundsTableFooterProps {
  totalCount: number;
  previewLimit: number;
  showAll: boolean;
  onViewAll: () => void;
  onExportCsv: () => void;
}

function PortfolioFundsTableFooter({
  totalCount,
  previewLimit,
  showAll,
  onViewAll,
  onExportCsv,
}: PortfolioFundsTableFooterProps): JSX.Element {
  const showViewAll = !showAll && totalCount > previewLimit;

  return (
    <div className="portfolio-funds-table-footer">
      <div className="portfolio-funds-table-footer-links">
        {showViewAll ? (
          <button
            type="button"
            className="portfolio-funds-table-footer-link"
            onClick={onViewAll}
          >
            View All
          </button>
        ) : null}
        <button
          type="button"
          className="portfolio-funds-table-footer-link"
          onClick={onExportCsv}
        >
          Export as CSV
        </button>
      </div>
      {showAll && totalCount > 0 ? (
        <span className="portfolio-funds-table-footer-count">
          Showing {totalCount} entries
        </span>
      ) : null}
    </div>
  );
}

export default React.memo(PortfolioFundsTableFooter);
