import { getAgentProfileById } from "../../offline/mock_data";
import { APP_ROUTES } from "../routes";

export const MAX_AGENT_COMPARE = 5;

export function parseCompareIds(raw: string | null): string[] {
  if (!raw?.trim()) return [];

  const seen = new Set<string>();
  const ids: string[] = [];

  for (const part of raw.split(",")) {
    const id = part.trim();
    if (!id || seen.has(id)) continue;
    if (!getAgentProfileById(id)) continue;
    seen.add(id);
    ids.push(id);
    if (ids.length >= MAX_AGENT_COMPARE) break;
  }

  return ids;
}

export function buildCompareSearch(ids: string[]): string {
  const valid = parseCompareIds(ids.join(","));
  if (valid.length === 0) return "";
  return `?ids=${valid.join(",")}`;
}

export function buildComparePath(ids: string[]): string {
  return `${APP_ROUTES.agentCompare}${buildCompareSearch(ids)}`;
}

export function appendCompareId(currentIds: string[], id: string): string[] {
  if (!getAgentProfileById(id)) return currentIds;
  if (currentIds.includes(id)) return currentIds;
  if (currentIds.length >= MAX_AGENT_COMPARE) return currentIds;
  return [...currentIds, id];
}

export function replaceCompareSlot(
  currentIds: string[],
  slotIndex: number,
  newId: string,
): string[] {
  if (!getAgentProfileById(newId)) return currentIds;
  if (slotIndex < 0) return currentIds;

  const existingIndex = currentIds.indexOf(newId);

  if (slotIndex < currentIds.length) {
    const targetId = currentIds[slotIndex];
    if (targetId === newId) return currentIds;

    const next = [...currentIds];
    if (existingIndex >= 0) {
      next[slotIndex] = newId;
      next[existingIndex] = targetId;
      return next;
    }
    next[slotIndex] = newId;
    return next;
  }

  if (slotIndex === currentIds.length) {
    if (existingIndex >= 0) return currentIds;
    if (currentIds.length >= MAX_AGENT_COMPARE) return currentIds;
    return [...currentIds, newId];
  }

  return currentIds;
}

export function toggleCompareId(
  currentIds: string[],
  id: string,
): string[] {
  if (!getAgentProfileById(id)) return currentIds;

  const index = currentIds.indexOf(id);
  if (index >= 0) {
    return currentIds.filter((entry) => entry !== id);
  }

  if (currentIds.length >= MAX_AGENT_COMPARE) {
    return [...currentIds.slice(1), id];
  }

  return [...currentIds, id];
}
