import type {
  StakingValidatorsFile,
  StakingValidatorsManifest,
} from "../../../../offline/mock_data/stakingValidators.types";
import {
  clearStakingValidatorsCache as clearSharedStakingValidatorsCache,
  getCachedStakingValidators as getSharedCachedStakingValidators,
  isStakingValidatorsLoaded,
  markStakingValidatorsEmpty,
  setCachedStakingValidators,
} from "../../../../offline/mock_data/stakingValidatorsCache";
import {
  STAKING_VALIDATORS_MANIFEST_SNAPSHOT,
  STAKING_VALIDATORS_SNAPSHOT,
} from "../../../../offline/mock_data/stakingValidatorsManifestSnapshot";

export const STAKING_VALIDATORS_DATA_BASE_URL =
  (typeof import.meta !== "undefined"
    && (import.meta as ImportMeta & { env?: Record<string, string> }).env
      ?.VITE_STAKING_VALIDATORS_BASE_URL)
  || "https://raw.githubusercontent.com/noro-dex/mock-system-data/main/staking-validators";

let manifestCache: StakingValidatorsManifest | null = null;
let manifestPromise: Promise<StakingValidatorsManifest> | null = null;
let validatorsPromise: Promise<StakingValidatorsFile | null> | null = null;

function normalizeBaseUrl(baseUrl: string): string {
  return baseUrl.replace(/\/+$/, "");
}

function joinBaseUrl(baseUrl: string, fileName: string): string {
  return `${normalizeBaseUrl(baseUrl)}/${fileName.replace(/^\//, "")}`;
}

export function clearStakingValidatorsClientCache(): void {
  manifestCache = null;
  manifestPromise = null;
  validatorsPromise = null;
  clearSharedStakingValidatorsCache();
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: HTTP ${response.status}`);
  }
  return response.json() as Promise<T>;
}

function hydrateFromSnapshot(): StakingValidatorsFile {
  setCachedStakingValidators({
    validators: STAKING_VALIDATORS_SNAPSHOT.validators.map((row) => ({
      ...row,
    })),
  });
  manifestCache = STAKING_VALIDATORS_MANIFEST_SNAPSHOT;
  return getSharedCachedStakingValidators()!;
}

export async function fetchStakingValidatorsManifest(
  baseUrl: string = STAKING_VALIDATORS_DATA_BASE_URL,
): Promise<StakingValidatorsManifest> {
  if (manifestCache) return manifestCache;
  if (manifestPromise) return manifestPromise;

  manifestPromise = fetchJson<StakingValidatorsManifest>(
    joinBaseUrl(baseUrl, "manifest.json"),
  )
    .then((manifest) => {
      manifestCache = manifest;
      return manifest;
    })
    .catch(() => {
      manifestCache = STAKING_VALIDATORS_MANIFEST_SNAPSHOT;
      return STAKING_VALIDATORS_MANIFEST_SNAPSHOT;
    })
    .finally(() => {
      manifestPromise = null;
    });

  return manifestPromise;
}

export function getCachedStakingValidatorsManifest(): StakingValidatorsManifest | null {
  return manifestCache;
}

export async function fetchStakingValidators(
  baseUrl: string = STAKING_VALIDATORS_DATA_BASE_URL,
): Promise<StakingValidatorsFile | null> {
  const cached = getSharedCachedStakingValidators();
  if (cached) return cached;

  if (validatorsPromise) return validatorsPromise;

  validatorsPromise = (async () => {
    try {
      const manifest = await fetchStakingValidatorsManifest(baseUrl);
      const payload = await fetchJson<StakingValidatorsFile>(
        joinBaseUrl(baseUrl, manifest.file),
      );
      setCachedStakingValidators(payload);
      return payload;
    } catch (err) {
      if (err instanceof Error && err.message.includes("HTTP 404")) {
        markStakingValidatorsEmpty();
        return { validators: [] };
      }
      return hydrateFromSnapshot();
    }
  })().finally(() => {
    validatorsPromise = null;
  });

  return validatorsPromise;
}

export function getCachedStakingValidatorsData(): StakingValidatorsFile | null {
  return getSharedCachedStakingValidators();
}

export function isStakingValidatorsDataLoaded(): boolean {
  return isStakingValidatorsLoaded();
}

export { subscribeStakingValidatorsCache } from "../../../../offline/mock_data/stakingValidatorsCache";
