/**
 * Simulated on-chain vault registry — durable user-created vault metadata.
 */

import { mockHashId } from "./mockHashId";
import type { VaultBucketSummary, VaultRecord } from "./vaultCatalog";

const STORAGE_KEY = "offline_vault_registry:v1";

export interface VaultRegistryShard {
  vaults: VaultRecord[];
}

let stateRevision = 0;
let hydrated = false;
let cache: VaultRecord[] = [];

const listeners = new Set<() => void>();

function notify(): void {
  stateRevision += 1;
  listeners.forEach((fn) => fn());
}

export function getRegistryRevision(): number {
  return stateRevision;
}

export function subscribeVaultRegistry(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function emptyShard(): VaultRegistryShard {
  return { vaults: [] };
}

function readShard(): VaultRegistryShard {
  if (typeof localStorage === "undefined") return emptyShard();
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return emptyShard();
    const parsed = JSON.parse(raw) as Partial<VaultRegistryShard>;
    return {
      vaults: Array.isArray(parsed.vaults) ? parsed.vaults : [],
    };
  } catch {
    return emptyShard();
  }
}

function writeShard(shard: VaultRegistryShard): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(STORAGE_KEY, JSON.stringify(shard));
}

function syncCacheFromStorage(): void {
  cache = readShard().vaults.filter((v) => v.kind === "user");
  hydrated = true;
}

/** Load registry from localStorage into memory cache (idempotent). */
export function ensureVaultRegistryHydrated(): void {
  if (hydrated) return;
  syncCacheFromStorage();
  notify();
}

export function getPersistedVaults(): VaultRecord[] {
  ensureVaultRegistryHydrated();
  return [...cache];
}

export function getPersistedVaultById(id: string): VaultRecord | undefined {
  ensureVaultRegistryHydrated();
  return cache.find((v) => v.id === id);
}

export function upsertVaultRecord(vault: VaultRecord): void {
  ensureVaultRegistryHydrated();
  const index = cache.findIndex((v) => v.id === vault.id);
  if (index >= 0) {
    cache[index] = vault;
  } else {
    cache.push(vault);
  }
  writeShard({ vaults: cache });
  notify();
}

export function patchVaultRecord(
  id: string,
  patch: Partial<VaultRecord> & {
    buckets?: VaultBucketSummary[];
  },
): VaultRecord | undefined {
  ensureVaultRegistryHydrated();
  const index = cache.findIndex((v) => v.id === id);
  if (index < 0) return undefined;

  const current = cache[index];
  const next: VaultRecord = {
    ...current,
    ...patch,
    analystVerdict: patch.analystVerdict
      ? { ...current.analystVerdict, ...patch.analystVerdict }
      : current.analystVerdict,
    buckets: patch.buckets ?? current.buckets,
  };
  cache[index] = next;
  writeShard({ vaults: cache });
  notify();
  return next;
}

export function removeVaultRecord(id: string): boolean {
  ensureVaultRegistryHydrated();
  const before = cache.length;
  cache = cache.filter((v) => v.id !== id);
  if (cache.length === before) return false;
  writeShard({ vaults: cache });
  notify();
  return true;
}

export function slugifyVaultName(name: string): string {
  return (
    name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "") || "vault"
  );
}

/** Allocate a unique vault id, checking static catalog + registry via isTaken. */
export function allocateUniqueVaultId(
  name: string,
  wallet: string,
  isTaken: (id: string) => boolean,
  forcedId?: string,
): string {
  if (forcedId?.trim()) {
    return forcedId.trim();
  }

  const slug = slugifyVaultName(name);
  let attempt = 0;
  while (attempt < 32) {
    const suffix = mockHashId(`${wallet}:${name}:${Date.now()}:${attempt}`).slice(
      0,
      6,
    );
    const candidate = `${slug}-${suffix}`;
    if (!isTaken(candidate)) {
      return candidate;
    }
    attempt += 1;
  }

  return `${slug}-${Date.now().toString(36)}`;
}

/** Remove ghost vaults with zero TVL and no wallet position references. */
export function reconcileRegistryWithWalletPositions(
  vaultIdsWithPositions: Set<string>,
): void {
  ensureVaultRegistryHydrated();
  const before = cache.length;
  cache = cache.filter(
    (vault) => vault.tvlUsd > 0 || vaultIdsWithPositions.has(vault.id),
  );
  if (cache.length !== before) {
    writeShard({ vaults: cache });
    notify();
  }
}

export function resetVaultRegistryStorage(): void {
  cache = [];
  hydrated = false;
  if (typeof localStorage !== "undefined") {
    localStorage.removeItem(STORAGE_KEY);
  }
  notify();
}

/** Test helper — force re-read from localStorage on next access. */
export function invalidateVaultRegistryCache(): void {
  hydrated = false;
  cache = [];
}
