import { useMemo, useSyncExternalStore, useEffect } from "react";

import { getVaultBuckets } from "../../offline/mock_data/vaultCatalog";
import {
  getVaultActivityCacheRevision,
  subscribeVaultActivityCache,
} from "../../offline/mock_data/vaultActivityCache";
import {
  getVaultBucketLive,
  getVaultOperateStateRevision,
  subscribeVaultOperateState,
} from "../../offline/mock_data/vaultOperateState";
import { vaultBucketToTradeBucket } from "../components/vault/vaultBucketTradeAdapter";
import type { Bucket } from "../sdk/types/data";
import { useAgentTaskStore } from "../store/agentTaskStore";
import { useVaultSystemData } from "./useVaultSystemData";

export function useVaultBucketCollections(
  vaultId: string | null,
  leaderAddress = "",
): {
  collections: Bucket[];
  loading: boolean;
  error: Error | null;
  spotWalletBalance: number;
} {
  const revision = useSyncExternalStore(
    subscribeVaultOperateState,
    getVaultOperateStateRevision,
    getVaultOperateStateRevision,
  );
  const cacheRevision = useSyncExternalStore(
    subscribeVaultActivityCache,
    getVaultActivityCacheRevision,
    getVaultActivityCacheRevision,
  );
  const { loading: systemLoading } = useVaultSystemData(vaultId ?? "");

  const collections = useMemo(() => {
    void revision;
    void cacheRevision;
    if (!vaultId) return [];
    return getVaultBuckets(vaultId)
      .map((bucket) => getVaultBucketLive(vaultId, bucket.id))
      .filter((bucket): bucket is NonNullable<typeof bucket> => bucket != null)
      .map((bucket) => vaultBucketToTradeBucket(vaultId, bucket, leaderAddress));
  }, [vaultId, leaderAddress, revision, cacheRevision]);

  useEffect(() => {
    if (!vaultId || collections.length === 0) return;
    useAgentTaskStore
      .getState()
      .linkSeedTasksToBuckets(collections.map((bucket) => bucket.bucketId));
  }, [vaultId, collections]);

  return {
    collections,
    loading: Boolean(vaultId) && systemLoading,
    error: null,
    spotWalletBalance: 0,
  };
}
