import React from "react";

import type { DeployWizardStep } from "../../../utils/deployAgent";

const STEP_LABELS = ["Select", "Details", "Review"] as const;

function stepIndex(step: DeployWizardStep): number {
  if (step === "select") return 0;
  if (step === "details") return 1;
  return 2;
}

export interface DeployAgentStepIndicatorProps {
  step: DeployWizardStep;
}

export default function DeployAgentStepIndicator({
  step,
}: DeployAgentStepIndicatorProps): JSX.Element {
  const activeIndex = stepIndex(step);
  const displayStep = activeIndex + 1;

  return (
    <div className="deploy-agent-step-indicator" aria-hidden={step === "review"}>
      <span className="deploy-agent-step-count">Step {displayStep} of 3</span>
      <div className="deploy-agent-step-track">
        {STEP_LABELS.map((label, index) => (
          <React.Fragment key={label}>
            <span
              className={`deploy-agent-step-dot${
                index <= activeIndex ? " is-active" : ""
              }`}
            />
            {index < STEP_LABELS.length - 1 ? (
              <span
                className={`deploy-agent-step-line${
                  index < activeIndex ? " is-active" : ""
                }`}
              />
            ) : null}
          </React.Fragment>
        ))}
      </div>
      <span className="deploy-agent-step-labels">
        {STEP_LABELS.join(" · ")}
      </span>
    </div>
  );
}
