import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from "react";

import { cloneTraderLeaderboardRows } from "../../offline/mock_data/traderLeaderboardData";
import {
  getTraderLeaderboardCacheRevision,
  subscribeTraderLeaderboardCache,
} from "../../offline/mock_data/traderLeaderboardCache";
import {
  buildLeaderboardRankedRows,
  buildLeaderboardViewRows,
  normalizeLeaderboardAddress,
  type LeaderboardSortField,
  type LeaderboardTimeframe,
  type TraderLeaderboardViewRow,
} from "../utils/leaderboardMetrics";
import {
  fetchTraderLeaderboard,
  isTraderLeaderboardDataLoaded,
} from "../sdk/api/traderLeaderboard/traderLeaderboardClient";

export interface UseLeaderboardDataConfig {
  walletAddress?: string;
}

export interface UseLeaderboardDataResult {
  query: string;
  setQuery: (value: string) => void;
  timeframe: LeaderboardTimeframe;
  setTimeframe: (value: LeaderboardTimeframe) => void;
  sortField: LeaderboardSortField;
  sortDirection: "asc" | "desc";
  handleSort: (field: LeaderboardSortField) => void;
  pinnedRow: TraderLeaderboardViewRow | null;
  pageRows: TraderLeaderboardViewRow[];
  page: number;
  pageSize: number;
  totalCount: number;
  loading: boolean;
  error: string | null;
  setPage: (page: number) => void;
  setPageSize: (size: number) => void;
  reload: () => void;
}

export function useLeaderboardData({
  walletAddress = "",
}: UseLeaderboardDataConfig = {}): UseLeaderboardDataResult {
  const cacheRevision = useSyncExternalStore(
    subscribeTraderLeaderboardCache,
    getTraderLeaderboardCacheRevision,
    getTraderLeaderboardCacheRevision,
  );

  const [query, setQueryState] = useState("");
  const [timeframe, setTimeframeState] = useState<LeaderboardTimeframe>("all");
  const [sortField, setSortField] = useState<LeaderboardSortField>("volumeUsd");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");
  const [page, setPage] = useState(0);
  const [pageSize, setPageSizeState] = useState(50);
  const [loading, setLoading] = useState(
    () => !isTraderLeaderboardDataLoaded(),
  );
  const [error, setError] = useState<string | null>(null);
  const [reloadToken, setReloadToken] = useState(0);

  const reload = useCallback(() => {
    setReloadToken((value) => value + 1);
  }, []);

  useEffect(() => {
    if (isTraderLeaderboardDataLoaded()) {
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchTraderLeaderboard()
      .then(() => {
        if (cancelled) return;
        setError(null);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(
          err instanceof Error ? err.message : "Failed to load leaderboard",
        );
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [reloadToken]);

  const setQuery = useCallback((value: string) => {
    setQueryState(value);
    setPage(0);
  }, []);

  const setTimeframe = useCallback((value: LeaderboardTimeframe) => {
    setTimeframeState(value);
    setPage(0);
  }, []);

  const handleSort = useCallback(
    (field: LeaderboardSortField) => {
      if (sortField === field) {
        setSortDirection((current) => (current === "asc" ? "desc" : "asc"));
      } else {
        setSortField(field);
        setSortDirection("desc");
      }
      setPage(0);
    },
    [sortField],
  );

  const setPageSize = useCallback((size: number) => {
    setPageSizeState(size);
    setPage(0);
  }, []);

  const normalizedWallet = normalizeLeaderboardAddress(walletAddress);

  const sourceRows = useMemo(() => {
    void cacheRevision;
    return cloneTraderLeaderboardRows();
  }, [cacheRevision]);

  const rankedRows = useMemo(
    () =>
      buildLeaderboardRankedRows(
        sourceRows,
        timeframe,
        sortField,
        sortDirection,
      ),
    [sourceRows, timeframe, sortField, sortDirection],
  );

  const filteredRows = useMemo(
    () =>
      buildLeaderboardViewRows(
        sourceRows,
        timeframe,
        sortField,
        sortDirection,
        query,
      ),
    [sourceRows, timeframe, sortField, sortDirection, query],
  );

  const pinnedRow = useMemo(() => {
    if (!normalizedWallet) return null;
    const match = rankedRows.find((row) => row.address === normalizedWallet);
    if (!match) return null;
    return { ...match, isYou: true };
  }, [normalizedWallet, rankedRows]);

  const paginatedPool = useMemo(() => {
    if (!pinnedRow) return filteredRows;
    return filteredRows.filter((row) => row.address !== pinnedRow.address);
  }, [filteredRows, pinnedRow]);

  const totalCount = paginatedPool.length;

  useEffect(() => {
    const maxPage = Math.max(0, Math.ceil(totalCount / pageSize) - 1);
    if (page > maxPage) {
      setPage(maxPage);
    }
  }, [page, pageSize, totalCount]);

  const pageRows = useMemo(() => {
    const start = page * pageSize;
    return paginatedPool.slice(start, start + pageSize);
  }, [paginatedPool, page, pageSize]);

  return {
    query,
    setQuery,
    timeframe,
    setTimeframe,
    sortField,
    sortDirection,
    handleSort,
    pinnedRow,
    pageRows,
    page,
    pageSize,
    totalCount,
    loading,
    error,
    setPage,
    setPageSize,
    reload,
  };
}
