import React from "react";

import { CREATE_VAULT_TOUR_TARGETS } from "../../tutorials/create-vault-tour/constants";
import "./vault.css";

export interface VaultHeroHeaderProps {
  height?: string;
  showMobileActions?: boolean;
  onOpenFilters?: () => void;
  onCreateVault?: () => void;
  filtersActive?: boolean;
  filtersSheetOpen?: boolean;
}

export default function VaultHeroHeader({
  height = "100%",
  showMobileActions = false,
  onOpenFilters,
  onCreateVault,
  filtersActive = false,
  filtersSheetOpen = false,
}: VaultHeroHeaderProps): JSX.Element {
  const filtersPressed = filtersSheetOpen || filtersActive;

  return (
    <div
      className={`vault-slot vault-header-band vault-header-band--title vault-hero-header${
        showMobileActions ? " vault-hero-header--with-actions" : ""
      }`}
      style={{ height }}
    >
      <div className="vault-hero-header-content">
        <p className="eyebrow-text">MORPHEUM · LIQUIDITY</p>
        <h1 className="vault-hero-title">Vaults</h1>
      </div>
      {showMobileActions ? (
        <div className="vault-hero-header-actions">
          {onOpenFilters ? (
            <button
              type="button"
              className={
                filtersPressed
                  ? "vault-filter-toggle is-active"
                  : "vault-filter-toggle"
              }
              aria-pressed={filtersPressed}
              aria-expanded={filtersSheetOpen}
              aria-haspopup="dialog"
              onClick={onOpenFilters}
              data-tour={CREATE_VAULT_TOUR_TARGETS.listFilters}
            >
              Filters
            </button>
          ) : null}
          {onCreateVault ? (
            <button
              type="button"
              className="vault-filter-create-btn"
              onClick={onCreateVault}
              data-tour={CREATE_VAULT_TOUR_TARGETS.createBtn}
            >
              Create Vault
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
