import type { VaultAnalystVerdict } from "../../../offline/mock_data/vaultCatalog";
import { formatVaultTvl } from "../../../offline/mock_data/vaultCatalog";

const MIN_TRACK_DAYS_FOR_SCORE = 30;

/** Vaults without a score use a single human passage instead of the full metric chain. */
export function isInsufficientVerdict(verdict: VaultAnalystVerdict): boolean {
  return verdict.score == null;
}

function isLegacySummaryFormat(text: string): boolean {
  return (
    /^(Not yet rated|Not rated yet)/i.test(text) ||
    /^Pending\s*[—-]/i.test(text) ||
    text.includes(" · ")
  );
}

function humanTrackAge(days: number): string {
  if (days <= 0) {
    return "it just went live";
  }
  if (days === 1) {
    return "it's only been live for a day";
  }
  if (days < 7) {
    return `it's only been live for ${days} days`;
  }
  if (days < 14) {
    return "it's only been live for about a week";
  }
  if (days < 30) {
    const weeks = Math.max(2, Math.round(days / 7));
    return `it's only been live for about ${weeks} weeks`;
  }
  if (days < 45) {
    return "it's been live for about a month";
  }
  if (days < 75) {
    return "it's been live for a couple of months";
  }
  return `it's been live for about ${Math.round(days / 30)} months`;
}

function buildInsufficientPassageTemplate(verdict: VaultAnalystVerdict): string {
  const { metrics } = verdict;
  const agePhrase = humanTrackAge(metrics.trackRecordDays);
  const tvlPhrase =
    metrics.tvlUsd > 0 ? ` At ${formatVaultTvl(metrics.tvlUsd)} TVL` : "";

  if (metrics.trackRecordDays < MIN_TRACK_DAYS_FOR_SCORE) {
    return `We're not grading this vault yet — ${agePhrase}.${tvlPhrase}, there isn't enough trading history to judge return, drawdown, or how steady the strategy really is. Once it's had a full month in market, we'll come back with a proper score and verdict.`;
  }

  return `We don't have a score for this vault yet.${tvlPhrase ? `${tvlPhrase}, and` : " And"} ${agePhrase}, but the performance series still isn't complete enough for us to stand behind a grade. Check back once we have a fuller picture.`;
}

/** Audience-facing paragraph when the vault cannot receive a full analyst verdict yet. */
export function resolveInsufficientPassage(verdict: VaultAnalystVerdict): string {
  const explicit = verdict.insufficientPassage?.trim();
  if (explicit) {
    return explicit;
  }

  const summary = verdict.summary.trim();
  if (summary && !isLegacySummaryFormat(summary)) {
    return summary;
  }

  return buildInsufficientPassageTemplate(verdict);
}
