import { Link } from "react-router-dom";

import type { TradingAgent } from "../../store/types";
import {
  formatAgentMemoryMb,
  formatAgentMemoryMeter,
  getAgentMemoryUsage,
} from "../../utils/agentMemoryCapacity";
import { agentRolesConsolePath } from "../../routes";

export interface AgentMemoryCapacityBlockProps {
  agent: TradingAgent;
  variant: "full";
}

function formatRelativeTime(iso: string): string {
  const delta = Date.now() - new Date(iso).getTime();
  const minutes = Math.floor(delta / 60000);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export default function AgentMemoryCapacityBlock({
  agent,
}: AgentMemoryCapacityBlockProps): JSX.Element {
  const usage = getAgentMemoryUsage(agent);
  const meterClass =
    usage.status === "critical"
      ? "agentroles-memory-capacity-meter--critical"
      : usage.status === "warning"
        ? "agentroles-memory-capacity-meter--warning"
        : "";

  return (
    <section
      className="agentroles-memory-capacity"
      aria-label="On-chain memory capacity"
    >
      <div className="agentroles-memory-capacity-head">
        <span className="terminal-label">On-chain memory</span>
        <span className="terminal-value">
          {formatAgentMemoryMeter(usage.usedMb, usage.allocatedMb)}
        </span>
      </div>

      <div
        className={`agentroles-memory-capacity-meter ${meterClass}`.trim()}
        role="progressbar"
        aria-valuenow={usage.fillPct}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={`Memory ${usage.fillPct}% used`}
      >
        <span
          className="agentroles-memory-capacity-meter-fill"
          style={{ width: `${usage.fillPct}%` }}
        />
      </div>

      <dl className="agentroles-detail-dl agentroles-memory-capacity-dl">
        <div>
          <dt className="terminal-label">Envelope (DID · mandate)</dt>
          <dd className="terminal-value">~{formatAgentMemoryMb(usage.envelopeMb)}</dd>
        </div>
        <div>
          <dt className="terminal-label">Memory tail</dt>
          <dd className="terminal-value">
            ~{formatAgentMemoryMb(usage.tailMb)} · {usage.noteCount} note
            {usage.noteCount === 1 ? "" : "s"}
          </dd>
        </div>
        <div>
          <dt className="terminal-label">Headroom</dt>
          <dd className="terminal-value">~{formatAgentMemoryMb(usage.headroomMb)}</dd>
        </div>
        <div>
          <dt className="terminal-label">Last note</dt>
          <dd className="terminal-value">
            {usage.lastNoteAt ? formatRelativeTime(usage.lastNoteAt) : "—"}
          </dd>
        </div>
      </dl>

      {usage.status !== "ok" ? (
        <p className="agentroles-memory-capacity-alert terminal-text-muted">
          {usage.status === "critical" ? "At capacity" : "Near capacity"} — expand
          memory in{" "}
          <Link
            to={agentRolesConsolePath(agent.id)}
            className="agentroles-memory-capacity-console-link"
          >
            Agent Console
          </Link>
          .
        </p>
      ) : null}

      <p className="transfer-field-hint terminal-text-muted agentroles-memory-capacity-hint">
        Paid in MORM from the master account pool.
      </p>
    </section>
  );
}
