import React from "react";

import type { VaultPositionRow } from "../../../offline/mock_data/vaultCatalog";
import { formatCurrency } from "../../sdk/utils/display";
import "./vault.css";

export interface VaultPositionCardProps {
  position: VaultPositionRow;
}

export default function VaultPositionCard({
  position,
}: VaultPositionCardProps): JSX.Element {
  const liqDistance =
    position.side === "long"
      ? ((position.markPrice - position.liqPrice) / position.markPrice) * 100
      : ((position.liqPrice - position.markPrice) / position.markPrice) * 100;

  return (
    <div className="vault-position-card">
      <strong>
        {position.market} · {position.side === "long" ? "Long" : "Short"} ·{" "}
        {position.leverage}x
      </strong>
      <span>
        Size {position.size} · Value {formatCurrency(position.positionValueUsd)}
      </span>
      <span>
        Entry {position.entryPrice.toLocaleString()} · Mark{" "}
        {position.markPrice.toLocaleString()}
      </span>
      <span>
        Liq {position.liqPrice.toLocaleString()} ({Math.round(liqDistance)}% away) · Mgn{" "}
        {formatCurrency(position.marginUsd)}
      </span>
      <span>
        uPnL {position.unrealizedPnlUsd >= 0 ? "+" : ""}
        {formatCurrency(position.unrealizedPnlUsd)} ({position.roePct >= 0 ? "+" : ""}
        {position.roePct}%)
        {position.fundingUsd8h != null
          ? ` · Fund ${position.fundingUsd8h >= 0 ? "+" : ""}$${Math.abs(position.fundingUsd8h)}/8h`
          : ""}
      </span>
    </div>
  );
}
