import { useMemo, useSyncExternalStore } from "react";
import { getAllVaults } from "../../offline/mock_data/vaultCatalog";
import { getPortfolioFundsMovementsSeed } from "../../offline/mock_data/portfolioFundsMovementsData";
import type { PortfolioFundsMovementRow } from "../../offline/mock_data/portfolioFundsMovements.types";
import {
  getVaultUserStateRevision,
  getWalletFundsMovements,
  subscribeVaultUserState,
} from "../../offline/mock_data/vaultUserState";
import {
  getPortfolioWalletStateRevision,
  getWalletPortfolioFundsMovements,
  subscribePortfolioWalletState,
} from "../../offline/mock_data/portfolioWalletState";
import {
  crossChainRecordToPortfolio,
  collectWalletVaultFundsMovements,
  mergePortfolioFundsMovements,
} from "../utils/portfolioFundsMovements";
import {
  getCrossChainTransferRevision,
  getCrossChainTransfers,
  subscribeCrossChainTransfers,
} from "../stores/crossChainTransferStore";

export function resolvePortfolioFundsMovements(
  walletAddress: string,
): PortfolioFundsMovementRow[] {
  if (!walletAddress.trim()) return [];

  const seed = getPortfolioFundsMovementsSeed(walletAddress).map((row) => ({
    ...row,
    walletAddress: walletAddress.trim(),
  }));

  const vaultIds = getAllVaults().map((vault) => vault.id);
  const vaultRows = collectWalletVaultFundsMovements(
    walletAddress,
    vaultIds,
    getWalletFundsMovements,
    (vaultId) => getAllVaults().find((v) => v.id === vaultId)?.name ?? vaultId,
  );

  const crossChainRows = getCrossChainTransfers()
    .map((record) => {
      const row = crossChainRecordToPortfolio(record);
      if (!row) return null;
      return { ...row, walletAddress: walletAddress.trim() };
    })
    .filter((row): row is PortfolioFundsMovementRow => row != null);

  const walletLedger = getWalletPortfolioFundsMovements(walletAddress);

  return mergePortfolioFundsMovements(
    seed,
    vaultRows,
    crossChainRows,
    walletLedger,
  );
}

export function usePortfolioFundsMovements(
  walletAddress: string,
): PortfolioFundsMovementRow[] {
  const vaultRevision = useSyncExternalStore(
    subscribeVaultUserState,
    getVaultUserStateRevision,
    getVaultUserStateRevision,
  );
  const crossChainRevision = useSyncExternalStore(
    subscribeCrossChainTransfers,
    getCrossChainTransferRevision,
    getCrossChainTransferRevision,
  );
  const portfolioWalletRevision = useSyncExternalStore(
    subscribePortfolioWalletState,
    getPortfolioWalletStateRevision,
    getPortfolioWalletStateRevision,
  );

  return useMemo(() => {
    void vaultRevision;
    void crossChainRevision;
    void portfolioWalletRevision;
    return resolvePortfolioFundsMovements(walletAddress);
  }, [walletAddress, vaultRevision, crossChainRevision, portfolioWalletRevision]);
}
