export function normalizeTabStripEntry(
  entry: TabStripEntry,
): { id: string; labelKey: TabLabelKey } {
  if (typeof entry === "string") {
    return { id: entry, labelKey: entry };
  }
  return entry;
}

export interface ResolvedTabStripOrder {
  tabIds: string[];
  labelKeyOverrides: Partial<Record<string, TabLabelKey>>;
}

export function resolveTabStripOrder(
  strip: readonly TabStripEntry[],
): ResolvedTabStripOrder {
  const tabIds: string[] = [];
  const labelKeyOverrides: Partial<Record<string, TabLabelKey>> = {};

  for (const entry of strip) {
    const { id, labelKey } = normalizeTabStripEntry(entry);
    tabIds.push(id);
    if (labelKey !== id) {
      labelKeyOverrides[id] = labelKey;
    }
  }

  return { tabIds, labelKeyOverrides };
}
