import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useNavigate } from "react-router-dom";
import {
  Joyride,
  type CallBackProps,
  type Step,
  type TooltipRenderProps,
  EVENTS,
  STATUS,
} from "react-joyride";
import { toast } from "sonner";

import { isDesktopTourBreakpoint } from "../welcome-tour/constants";
import { welcomeTourLocale, welcomeTourStyles } from "../welcome-tour/welcomeTourStyles";
import { useVaultTour } from "./VaultTourContext";
import { prepareVaultTourTarget } from "./vaultTourDom";
import {
  isVaultTourGateSatisfied,
  resolveVaultTourNavigateBefore,
} from "./vaultTourFlowSync";
import {
  buildVaultTourSteps,
  type VaultTourStepMeta,
} from "./vaultTourSteps";
import { vaultTourDefaultOptions } from "./vaultTourStyles";
import "../welcome-tour/WelcomeModal.css";

interface VaultTourTooltipActions {
  advanceFromTooltip: (index: number, isLastStep: boolean) => void;
  isNextDisabled: (meta: VaultTourStepMeta | undefined) => boolean;
  waitHint: (meta: VaultTourStepMeta | undefined) => string | null;
}

const VaultTourTooltipActionsContext =
  createContext<VaultTourTooltipActions | null>(null);

const GATE_HINTS: Record<string, string> = {
  bucketRoute: "Click the bucket row to continue…",
};

function VaultTourTooltip({
  continuous,
  index,
  isLastStep,
  skipProps,
  step,
  tooltipProps,
  size,
}: TooltipRenderProps): JSX.Element {
  const actions = useContext(VaultTourTooltipActionsContext);
  const meta = step.data as VaultTourStepMeta | undefined;
  const stepNumber = meta?.stepNumber ?? index + 1;
  const requiresClick = meta?.requiresClick ?? false;
  const nextDisabled = actions?.isNextDisabled(meta) ?? false;
  const waitHint = actions?.waitHint(meta);

  return (
    <div {...tooltipProps} className="welcome-tour-tooltip">
      <div className="welcome-tour-tooltip-header">
        <span className="welcome-tour-step-badge">
          {stepNumber} / {size}
        </span>
        {step.title ? (
          <h4 className="welcome-tour-tooltip-title">{step.title}</h4>
        ) : null}
      </div>
      <div className="welcome-tour-tooltip-body">{step.content}</div>
      <div className="welcome-tour-tooltip-footer">
        <button type="button" className="welcome-tour-skip" {...skipProps}>
          {skipProps.title}
        </button>
        {!requiresClick && continuous ? (
          <div className="welcome-tour-tooltip-nav">
            {nextDisabled && waitHint ? (
              <p
                className="welcome-tour-wait-hint"
                style={{
                  margin: 0,
                  fontSize: "0.75rem",
                  color: "var(--terminal-text-muted)",
                }}
              >
                {waitHint}
              </p>
            ) : null}
            <button
              type="button"
              className="welcome-tour-next"
              disabled={nextDisabled}
              aria-disabled={nextDisabled}
              onClick={() => actions?.advanceFromTooltip(index, isLastStep)}
            >
              {isLastStep ? "Finish" : "Next"}
            </button>
          </div>
        ) : requiresClick ? (
          <p
            className="welcome-tour-click-hint"
            style={{
              margin: 0,
              fontSize: "0.75rem",
              color: "var(--terminal-text-muted)",
            }}
          >
            {waitHint ?? "Click the highlighted control to continue"}
          </p>
        ) : null}
      </div>
    </div>
  );
}

export function VaultTourJoyride(): JSX.Element {
  const navigate = useNavigate();
  const {
    runTour,
    stepIndex,
    setStepIndex,
    currentBreakpoint,
    pathname,
    stopTour,
    onTourComplete,
  } = useVaultTour();

  const isDesktop = isDesktopTourBreakpoint(currentBreakpoint);
  const shouldRun = runTour && isDesktop;
  const [tourSession, setTourSession] = useState(0);
  const prevRunRef = useRef(false);
  const stepIndexRef = useRef(stepIndex);
  const setStepIndexRef = useRef(setStepIndex);
  const onTourCompleteRef = useRef(onTourComplete);
  stepIndexRef.current = stepIndex;
  setStepIndexRef.current = setStepIndex;
  onTourCompleteRef.current = onTourComplete;

  const steps = useMemo(() => buildVaultTourSteps(), []);
  const stepCount = steps.length;

  const scheduleStepIndex = useCallback((index: number) => {
    window.setTimeout(() => {
      setStepIndexRef.current(index);
      stepIndexRef.current = index;
    }, 120);
  }, []);

  const advanceFromTooltip = useCallback(
    (index: number, isLastStep: boolean) => {
      const meta = steps[index]?.data as VaultTourStepMeta | undefined;
      if (!isVaultTourGateSatisfied(meta?.gateKind, pathname)) {
        return;
      }
      if (isLastStep) {
        onTourCompleteRef.current();
        return;
      }
      scheduleStepIndex(index + 1);
    },
    [pathname, scheduleStepIndex, steps],
  );

  const isNextDisabled = useCallback(
    (meta: VaultTourStepMeta | undefined) =>
      !isVaultTourGateSatisfied(meta?.gateKind, pathname),
    [pathname],
  );

  const waitHint = useCallback((meta: VaultTourStepMeta | undefined) => {
    if (!meta?.gateKind) return null;
    return GATE_HINTS[meta.gateKind] ?? null;
  }, []);

  const tooltipActions = useMemo(
    (): VaultTourTooltipActions => ({
      advanceFromTooltip,
      isNextDisabled,
      waitHint,
    }),
    [advanceFromTooltip, isNextDisabled, waitHint],
  );

  useEffect(() => {
    if (shouldRun && !prevRunRef.current) {
      setTourSession((s) => s + 1);
    }
    prevRunRef.current = shouldRun;
  }, [shouldRun]);

  useEffect(() => {
    if (shouldRun) {
      document.body.setAttribute("data-vault-tour-active", "true");
    } else {
      document.body.removeAttribute("data-vault-tour-active");
    }
    return () => {
      document.body.removeAttribute("data-vault-tour-active");
    };
  }, [shouldRun]);

  useEffect(() => {
    if (runTour && !isDesktop) {
      stopTour();
      toast.info(
        "Vault tour is available on desktop and tablet view. Widen your window to explore step-by-step.",
      );
    }
  }, [runTour, isDesktop, stopTour]);

  const stepsWithBefore = useMemo((): Step[] => {
    return steps.map((step) => {
      const meta = step.data as VaultTourStepMeta | undefined;
      const targetSelector = meta?.targetSelector;
      if (!targetSelector) return step;

      return {
        ...step,
        before: async () => {
          const navigateTo = resolveVaultTourNavigateBefore(meta?.navigateBefore);
          if (navigateTo && pathname !== navigateTo) {
            navigate(navigateTo);
            await prepareVaultTourTarget(targetSelector, 6000);
            return;
          }
          const ready = await prepareVaultTourTarget(targetSelector, 4000);
          if (!ready) {
            toast.error("Tour spotlight could not find this step", {
              description: "Navigate to the vault page or use Skip tour to exit.",
            });
          }
        },
      };
    });
  }, [navigate, pathname, steps]);

  useEffect(() => {
    if (!shouldRun || steps.length === 0) return;
    const meta = steps[stepIndex]?.data as VaultTourStepMeta | undefined;
    if (!meta?.requiresClick || !meta.targetSelector) return;

    const el = document.querySelector(meta.targetSelector);
    if (!el) return;

    const capturedIndex = stepIndex;

    const onClick = () => {
      window.setTimeout(() => {
        if (stepIndexRef.current !== capturedIndex) return;
        if (meta.gateKind && !isVaultTourGateSatisfied(meta.gateKind, window.location.pathname)) {
          return;
        }
        if (capturedIndex >= stepCount - 1) {
          onTourCompleteRef.current();
          return;
        }
        scheduleStepIndex(capturedIndex + 1);
      }, 200);
    };

    el.addEventListener("click", onClick, true);
    return () => {
      el.removeEventListener("click", onClick, true);
    };
  }, [shouldRun, stepIndex, steps, stepCount, scheduleStepIndex]);

  useEffect(() => {
    if (!shouldRun) return;
    const meta = steps[stepIndex]?.data as VaultTourStepMeta | undefined;
    if (!meta?.gateKind || meta.requiresClick) return;
    if (isVaultTourGateSatisfied(meta.gateKind, pathname)) return;
    // Wait for gate on click steps — handled by click listener
  }, [shouldRun, stepIndex, steps, pathname]);

  const handleCallback = useCallback(
    (data: CallBackProps) => {
      const { status, type, index } = data;

      if (status === STATUS.SKIPPED) {
        stopTour();
        onTourComplete();
        return;
      }

      if (type === EVENTS.TARGET_NOT_FOUND) {
        toast.error("Tour step target not found", {
          description: "Ensure you are on the vault page, or skip the tour.",
        });
        if (index > 0) {
          scheduleStepIndex(index - 1);
        } else {
          stopTour();
        }
        return;
      }

      if (type === EVENTS.TOUR_END && status === STATUS.FINISHED) {
        onTourComplete();
      }
    },
    [stopTour, onTourComplete, scheduleStepIndex],
  );

  return (
    <VaultTourTooltipActionsContext.Provider value={tooltipActions}>
      <Joyride
        key={tourSession}
        steps={stepsWithBefore}
        run={shouldRun}
        stepIndex={stepIndex}
        continuous
        scrollToFirstStep={false}
        disableScrolling
        disableOverlayClose
        callback={handleCallback}
        locale={welcomeTourLocale}
        options={vaultTourDefaultOptions}
        styles={welcomeTourStyles}
        loaderComponent={null}
        tooltipComponent={(props) => (
          <VaultTourTooltip {...props} size={stepCount} />
        )}
      />
    </VaultTourTooltipActionsContext.Provider>
  );
}
