import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import {
  Joyride,
  type CallBackProps,
  type Step,
  type TooltipRenderProps,
  EVENTS,
  STATUS,
} from "react-joyride";
import { toast } from "sonner";

import MorpheumLoadingOverlay from "../../components/ui/MorpheumLoadingOverlay";
import { isDesktopTourBreakpoint } from "../welcome-tour/constants";
import { welcomeTourLocale, welcomeTourStyles } from "../welcome-tour/welcomeTourStyles";
import { useCreateVaultTour } from "./CreateVaultTourContext";
import {
  createVaultTourAdvanceDelayMs,
  prepareCreateVaultTourTarget,
} from "./createVaultTourDom";
import {
  isCreateVaultTourGateSatisfied,
  isCreateVaultTourNextGated,
} from "./createVaultTourFlowSync";
import {
  buildCreateVaultTourSteps,
  findCreateVaultTourStepIndex,
  type CreateVaultTourStepMeta,
} from "./createVaultTourSteps";
import { createVaultTourDefaultOptions } from "./createVaultTourStyles";
import "../welcome-tour/WelcomeModal.css";

interface CreateVaultTourTooltipActions {
  advanceFromTooltip: (index: number, isLastStep: boolean) => void;
  isNextDisabled: (meta: CreateVaultTourStepMeta | undefined) => boolean;
  waitHint: (meta: CreateVaultTourStepMeta | undefined) => string | null;
}

const CreateVaultTourTooltipActionsContext =
  createContext<CreateVaultTourTooltipActions | null>(null);

function CreateVaultTourTooltip({
  continuous,
  index,
  isLastStep,
  skipProps,
  step,
  tooltipProps,
  size,
}: TooltipRenderProps): JSX.Element {
  const actions = useContext(CreateVaultTourTooltipActionsContext);
  const meta = step.data as CreateVaultTourStepMeta | undefined;
  const stepNumber = meta?.stepNumber ?? index + 1;
  const requiresClick = meta?.requiresClick ?? false;
  const nextDisabled = actions?.isNextDisabled(meta) ?? false;
  const waitHint = actions?.waitHint(meta);

  return (
    <div {...tooltipProps} className="welcome-tour-tooltip">
      <div className="welcome-tour-tooltip-header">
        <span className="welcome-tour-step-badge">
          {stepNumber} / {size}
        </span>
        {step.title ? (
          <h4 className="welcome-tour-tooltip-title">{step.title}</h4>
        ) : null}
      </div>
      <div className="welcome-tour-tooltip-body">{step.content}</div>
      <div className="welcome-tour-tooltip-footer">
        <button type="button" className="welcome-tour-skip" {...skipProps}>
          {skipProps.title}
        </button>
        {!requiresClick && continuous ? (
          <div className="welcome-tour-tooltip-nav">
            {nextDisabled && waitHint ? (
              <p
                className="welcome-tour-wait-hint"
                style={{
                  margin: 0,
                  fontSize: "0.75rem",
                  color: "var(--terminal-text-muted)",
                }}
              >
                {waitHint}
              </p>
            ) : null}
            <button
              type="button"
              className="welcome-tour-next"
              disabled={nextDisabled}
              aria-disabled={nextDisabled}
              onClick={() => actions?.advanceFromTooltip(index, isLastStep)}
            >
              {isLastStep ? "Finish" : "Next"}
            </button>
          </div>
        ) : requiresClick ? (
          <p
            className="welcome-tour-click-hint"
            style={{
              margin: 0,
              fontSize: "0.75rem",
              color: "var(--terminal-text-muted)",
            }}
          >
            {waitHint ?? "Click the highlighted control to continue"}
          </p>
        ) : null}
      </div>
    </div>
  );
}

export function CreateVaultTourJoyride(): JSX.Element {
  const {
    runTour,
    stepIndex,
    setStepIndex,
    currentBreakpoint,
    pathname,
    modalState,
    stopTour,
    onTourComplete,
    openCreateVaultForTour,
    setModalStepForTour,
  } = useCreateVaultTour();

  const isDesktop = isDesktopTourBreakpoint(currentBreakpoint);
  const shouldRun = runTour && isDesktop;
  const [tourSession, setTourSession] = useState(0);
  const [preparingStep, setPreparingStep] = useState(false);
  const prevRunRef = useRef(false);
  const setPreparingStepRef = useRef(setPreparingStep);
  setPreparingStepRef.current = setPreparingStep;
  const stepIndexRef = useRef(stepIndex);
  const setStepIndexRef = useRef(setStepIndex);
  const onTourCompleteRef = useRef(onTourComplete);
  stepIndexRef.current = stepIndex;
  setStepIndexRef.current = setStepIndex;
  onTourCompleteRef.current = onTourComplete;

  const steps = useMemo(() => buildCreateVaultTourSteps(), []);
  const stepCount = steps.length;

  const scheduleStepIndex = useCallback((index: number, delayMs = 120) => {
    window.setTimeout(() => {
      setStepIndexRef.current(index);
      stepIndexRef.current = index;
    }, delayMs);
  }, []);

  const advanceFromTooltip = useCallback(
    (index: number, isLastStep: boolean) => {
      const meta = steps[index]?.data as CreateVaultTourStepMeta | undefined;
      if (
        !isCreateVaultTourGateSatisfied(
          meta?.gateUntilModalStep,
          modalState.step,
          meta?.gateUntilPath,
          meta?.gateUntilModalSuccess,
          pathname,
          modalState.isOpen,
          modalState.showSuccess ?? false,
        )
      ) {
        return;
      }
      if (isLastStep) {
        onTourCompleteRef.current();
        return;
      }
      scheduleStepIndex(index + 1);
    },
    [modalState.isOpen, modalState.step, modalState.showSuccess, pathname, scheduleStepIndex, steps],
  );

  const isNextDisabled = useCallback(
    (meta: CreateVaultTourStepMeta | undefined) => {
      if (
        (meta?.gateUntilPath || meta?.gateUntilModalSuccess) &&
        !isCreateVaultTourGateSatisfied(
          undefined,
          modalState.step,
          meta?.gateUntilPath,
          meta?.gateUntilModalSuccess,
          pathname,
          modalState.isOpen,
          modalState.showSuccess ?? false,
        )
      ) {
        return true;
      }
      return isCreateVaultTourNextGated(meta?.gateUntilModalStep, modalState.step);
    },
    [modalState.isOpen, modalState.step, modalState.showSuccess, pathname],
  );

  const waitHint = useCallback(
    (meta: CreateVaultTourStepMeta | undefined) => {
      if (meta?.gateUntilModalSuccess) {
        return "Click Create to finish…";
      }
      if (meta?.gateUntilPath === "createdVaultDetail") {
        return "Click View vault to continue…";
      }
      if (meta?.requiresClick && meta.stepId === "create-btn") {
        return "Click Create Vault to open the wizard";
      }
      if (meta?.requiresClick && meta.syncModalStep) {
        return "Click Continue to advance the wizard";
      }
      return null;
    },
    [],
  );

  const tooltipActions = useMemo(
    (): CreateVaultTourTooltipActions => ({
      advanceFromTooltip,
      isNextDisabled,
      waitHint,
    }),
    [advanceFromTooltip, isNextDisabled, waitHint],
  );

  useEffect(() => {
    if (shouldRun && !prevRunRef.current) {
      setTourSession((s) => s + 1);
    }
    prevRunRef.current = shouldRun;
  }, [shouldRun]);

  useEffect(() => {
    if (shouldRun) {
      document.body.setAttribute("data-create-vault-tour-active", "true");
    } else {
      document.body.removeAttribute("data-create-vault-tour-active");
    }
    return () => {
      document.body.removeAttribute("data-create-vault-tour-active");
    };
  }, [shouldRun]);

  useEffect(() => {
    if (runTour && !isDesktop) {
      stopTour();
      toast.info(
        "Create vault tour is available on desktop and tablet view. Widen your window to explore step-by-step.",
      );
    }
  }, [runTour, isDesktop, stopTour]);

  const stepsWithBefore = useMemo((): Step[] => {
    return steps.map((step) => {
      const meta = step.data as CreateVaultTourStepMeta | undefined;
      const targetSelector = meta?.targetSelector;
      if (!targetSelector) return step;

      return {
        ...step,
        before: async () => {
          setPreparingStepRef.current(true);
          try {
            if (meta.syncModalStep) {
              setModalStepForTour(meta.syncModalStep);
            }
            const prepSelector = meta.prepareSelector ?? targetSelector;
            const ready = await prepareCreateVaultTourTarget(prepSelector, 5000);
            if (!ready) {
              toast.error("Tour spotlight could not find this step", {
                description: "Keep the Create Vault modal open or skip the tour.",
              });
            }
          } finally {
            setPreparingStepRef.current(false);
          }
        },
      };
    });
  }, [steps, setModalStepForTour]);

  useEffect(() => {
    if (!shouldRun || steps.length === 0) return;
    const meta = steps[stepIndex]?.data as CreateVaultTourStepMeta | undefined;
    if (!meta?.requiresClick || !meta.targetSelector) return;

    const el = document.querySelector(meta.targetSelector);
    if (!el) return;

    const capturedIndex = stepIndex;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const onClick = () => {
      if (meta.stepId === "create-btn") {
        openCreateVaultForTour();
      }
      timer = window.setTimeout(() => {
        if (stepIndexRef.current !== capturedIndex) return;
        if (meta.gateUntilPath === "createdVaultDetail") {
          if (!pathname.includes("demo-tour-vault")) return;
        }
        if (capturedIndex >= stepCount - 1) {
          onTourCompleteRef.current();
          return;
        }
        scheduleStepIndex(capturedIndex + 1);
      }, createVaultTourAdvanceDelayMs(meta.stepId));
    };

    el.addEventListener("click", onClick, true);
    return () => {
      el.removeEventListener("click", onClick, true);
      if (timer !== undefined) {
        window.clearTimeout(timer);
      }
    };
  }, [shouldRun, stepIndex, steps, stepCount, scheduleStepIndex, pathname, openCreateVaultForTour]);

  useEffect(() => {
    if (!shouldRun) return;
    const submitIdx = findCreateVaultTourStepIndex(steps, "submit");
    if (submitIdx < 0 || stepIndexRef.current !== submitIdx) return;
    if (!modalState.isOpen || !modalState.showSuccess) return;
    scheduleStepIndex(submitIdx + 1);
  }, [
    shouldRun,
    modalState.isOpen,
    modalState.showSuccess,
    steps,
    scheduleStepIndex,
  ]);

  useEffect(() => {
    if (!shouldRun) return;
    const meta = steps[stepIndex]?.data as CreateVaultTourStepMeta | undefined;
    if (meta?.gateUntilPath !== "createdVaultDetail") return;
    if (!pathname.includes("demo-tour-vault")) return;
    const submitIdx = findCreateVaultTourStepIndex(steps, "submit");
    if (submitIdx < 0 || stepIndexRef.current !== submitIdx) return;
    scheduleStepIndex(submitIdx + 1);
  }, [shouldRun, pathname, steps, stepIndex, scheduleStepIndex]);

  const handleCallback = useCallback(
    (data: CallBackProps) => {
      const { status, type, index } = data;

      if (status === STATUS.SKIPPED) {
        stopTour();
        onTourComplete();
        return;
      }

      if (type === EVENTS.TARGET_NOT_FOUND) {
        toast.error("Tour step target not found", {
          description: "Open Create Vault from the listing or skip the tour.",
        });
        if (index > 0) {
          scheduleStepIndex(index - 1);
        } else {
          stopTour();
        }
        return;
      }

      if (type === EVENTS.TOUR_END && status === STATUS.FINISHED) {
        onTourComplete();
      }
    },
    [stopTour, onTourComplete, scheduleStepIndex],
  );

  return (
    <CreateVaultTourTooltipActionsContext.Provider value={tooltipActions}>
      {preparingStep
        ? createPortal(
            <MorpheumLoadingOverlay
              layout="fixed"
              className="welcome-tour-loading-overlay"
              label="Loading tour step..."
              matrixText={true}
            />,
            document.body,
          )
        : null}
      <Joyride
        key={tourSession}
        steps={stepsWithBefore}
        run={shouldRun}
        stepIndex={stepIndex}
        continuous
        scrollToFirstStep={false}
        disableScrolling
        disableOverlayClose
        callback={handleCallback}
        locale={welcomeTourLocale}
        options={createVaultTourDefaultOptions}
        styles={welcomeTourStyles}
        loaderComponent={null}
        tooltipComponent={(props) => (
          <CreateVaultTourTooltip {...props} size={stepCount} />
        )}
      />
    </CreateVaultTourTooltipActionsContext.Provider>
  );
}
