export const VAULT_NAV_PERSONAL_KEY = "personal";

export function vaultNavFocusKey(
  isActive: boolean,
  vaultId: string | null | undefined,
): string {
  if (!isActive || !vaultId) return VAULT_NAV_PERSONAL_KEY;
  return `vault:${vaultId}`;
}

function vaultIdFromFocusKey(key: string): string | null {
  if (key === VAULT_NAV_PERSONAL_KEY) return null;
  if (!key.startsWith("vault:")) return null;
  return key.slice("vault:".length) || null;
}

/** 1 = forward (enter from below/right), -1 = backward. */
export function vaultNavDirection(
  from: string,
  to: string,
  ownedVaultIds: readonly string[],
): 1 | -1 {
  if (from === to) return 1;

  const fromPersonal = from === VAULT_NAV_PERSONAL_KEY;
  const toPersonal = to === VAULT_NAV_PERSONAL_KEY;

  if (fromPersonal && !toPersonal) return 1;
  if (!fromPersonal && toPersonal) return -1;

  const fromId = vaultIdFromFocusKey(from);
  const toId = vaultIdFromFocusKey(to);
  if (!fromId || !toId) return 1;

  const fromIndex = ownedVaultIds.indexOf(fromId);
  const toIndex = ownedVaultIds.indexOf(toId);
  if (fromIndex < 0 || toIndex < 0) return 1;
  if (fromIndex === toIndex) return 1;

  const count = ownedVaultIds.length;
  const forward = (toIndex - fromIndex + count) % count;
  const backward = (fromIndex - toIndex + count) % count;
  return forward <= backward ? 1 : -1;
}

export function buildVaultNavStacks<T>(
  isActive: boolean,
  vaultId: string | null | undefined,
  ownedVaultIds: readonly string[],
  personalStack: T,
  vaultStackForId: (id: string) => T,
): Record<string, T> {
  const stacks: Record<string, T> = {
    [VAULT_NAV_PERSONAL_KEY]: personalStack,
  };

  if (isActive && vaultId) {
    stacks[`vault:${vaultId}`] = vaultStackForId(vaultId);
  }

  for (const id of ownedVaultIds) {
    const key = `vault:${id}`;
    if (!(key in stacks)) {
      stacks[key] = vaultStackForId(id);
    }
  }

  return stacks;
}
