import React from "react";
import { createPortal } from "react-dom";

import {
  StaggeredOverlayBackdrop,
  StaggeredOverlayPanel,
  StaggeredOverlayRoot,
  useOverlayEscapeKey,
} from "../../ui/overlay";
import {
  useCopyAgentModalOverlay,
  type UseBucketModalOverlayResult,
} from "../../tables/useBucketModalOverlay";
import "../../smartlayout/layout.css";
import "../../tables/bucketCollection.css";
import "../agentroles.css";
import "./deployAgent.css";

export interface DeployAgentModalShellProps {
  open: boolean;
  onClose: () => void;
  ariaLabel: string;
  onAfterUnmount?: () => void;
  children: React.ReactNode;
}

export type DeployAgentModalShellContext = {
  isSheet: boolean;
  overlay: UseBucketModalOverlayResult;
};

export const DeployAgentModalShellContext =
  React.createContext<DeployAgentModalShellContext | null>(null);

export function useDeployAgentModalShell(): DeployAgentModalShellContext {
  const ctx = React.useContext(DeployAgentModalShellContext);
  if (!ctx) {
    throw new Error(
      "useDeployAgentModalShell must be used within DeployAgentModalShell",
    );
  }
  return ctx;
}

function DeployAgentModalShell({
  open,
  onClose,
  ariaLabel,
  onAfterUnmount,
  children,
}: DeployAgentModalShellProps): JSX.Element | null {
  const overlay = useCopyAgentModalOverlay(open, { onAfterUnmount });
  const isSheet = overlay.isMobile;

  useOverlayEscapeKey(open, onClose);

  if (!overlay.mounted) return null;

  const panelClassName = [
    "modal-content",
    "terminal-overlay-panel-shell",
    "deploy-agent-modal-content",
    isSheet ? "bucket-modal-panel--sheet" : "staggered-overlay-panel--scale",
    overlay.isClosing ? "bucket-modal-panel--closing" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const modalContent = (
    <DeployAgentModalShellContext.Provider value={{ isSheet, overlay }}>
      <StaggeredOverlayRoot
        passThrough={!open}
        className={
          isSheet
            ? "bucket-modal-overlay bucket-modal-overlay--sheet deploy-agent-sheet-overlay"
            : undefined
        }
      >
        <StaggeredOverlayBackdrop
          visible={overlay.backdropVisible && open}
          onClose={onClose}
          style={overlay.backdropStyle}
          className="staggered-overlay-backdrop--deep"
        />
        <StaggeredOverlayPanel
          open={overlay.panelOpen}
          className={panelClassName}
          aria-label={ariaLabel}
          role="dialog"
          aria-modal={true}
        >
          {children}
        </StaggeredOverlayPanel>
      </StaggeredOverlayRoot>
    </DeployAgentModalShellContext.Provider>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : null;
}

export default React.memo(DeployAgentModalShell);
