export interface VaultPortfolioTablePrefs {
  showAllocation: boolean;
  showExposureLegs: boolean;
  showLeverage: boolean;
  showFunding: boolean;
}

export const DEFAULT_VAULT_PORTFOLIO_TABLE_PREFS: VaultPortfolioTablePrefs = {
  showAllocation: false,
  showExposureLegs: false,
  showLeverage: false,
  showFunding: false,
};

export type VaultPortfolioColumnId =
  | "bucket"
  | "mode"
  | "equity"
  | "allocation"
  | "risk"
  | "netExposure"
  | "exposureLegs"
  | "leverage"
  | "margin"
  | "funding"
  | "upnl";

const COLUMN_WIDTHS: Record<VaultPortfolioColumnId, string> = {
  bucket: "minmax(140px,1.4fr)",
  mode: "minmax(72px,0.7fr)",
  equity: "minmax(90px,1fr)",
  allocation: "minmax(90px,1fr)",
  risk: "minmax(100px,1fr)",
  netExposure: "minmax(100px,1fr)",
  exposureLegs: "minmax(110px,1.1fr)",
  leverage: "minmax(72px,0.8fr)",
  margin: "minmax(72px,0.75fr)",
  funding: "minmax(90px,1fr)",
  upnl: "minmax(88px,0.9fr)",
};

export function resolveVaultPortfolioColumns(
  prefs: VaultPortfolioTablePrefs,
): VaultPortfolioColumnId[] {
  const columns: VaultPortfolioColumnId[] = [
    "bucket",
    "mode",
    "equity",
  ];
  if (prefs.showAllocation) columns.push("allocation");
  columns.push("risk", "netExposure");
  if (prefs.showExposureLegs) columns.push("exposureLegs");
  if (prefs.showLeverage) columns.push("leverage");
  columns.push("margin");
  if (prefs.showFunding) columns.push("funding");
  columns.push("upnl");
  return columns;
}

export function vaultPortfolioGridTemplate(
  prefs: VaultPortfolioTablePrefs,
): string {
  return resolveVaultPortfolioColumns(prefs)
    .map((col) => COLUMN_WIDTHS[col])
    .join(" ");
}
