import { OVERLAY_TIMING } from "../../components/ui/overlay/overlayTiming";
import {
  isElementVisible,
  waitAnimationFrames,
  waitForTourTarget,
} from "../welcome-tour/welcomeTourDom";
import { CREATE_VAULT_TOUR_TARGETS } from "./constants";

export { isElementVisible, waitAnimationFrames, waitForTourTarget };

/** Matches `.vault-create-carousel-track { transition: transform 600ms }` in vault.css */
export const CREATE_VAULT_CAROUSEL_TRANSITION_MS = 600;

export const CREATE_VAULT_MODAL_OPEN_MS = OVERLAY_TIMING.desktopScaleMs;

const CAROUSEL_TRANSITION_BUFFER_MS = 50;

const CREATE_VAULT_MODAL_SELECTOR =
  ".vault-modal-content.staggered-overlay-panel--scale.is-open";

const CREATE_VAULT_CAROUSEL_VIEWPORT_SELECTOR = ".vault-create-carousel-viewport";

const CREATE_VAULT_CAROUSEL_TRACK_SELECTOR = ".vault-create-carousel-track";

const CREATE_VAULT_CAROUSEL_TARGET_KEYS = new Set<string>([
  CREATE_VAULT_TOUR_TARGETS.details,
  CREATE_VAULT_TOUR_TARGETS.strategy,
  CREATE_VAULT_TOUR_TARGETS.funding,
  CREATE_VAULT_TOUR_TARGETS.fee,
  CREATE_VAULT_TOUR_TARGETS.visibility,
]);

const CREATE_VAULT_MODAL_TARGET_KEYS = new Set<string>([
  ...CREATE_VAULT_CAROUSEL_TARGET_KEYS,
  CREATE_VAULT_TOUR_TARGETS.continueBtn,
  CREATE_VAULT_TOUR_TARGETS.submitBtn,
  CREATE_VAULT_TOUR_TARGETS.stepMeta,
]);

const WIZARD_CLICK_ADVANCE_STEP_IDS = new Set([
  "strategy",
  "funding",
  "fee",
  "visibility",
]);

function tourTargetSelector(targetKey: string): string {
  return `[data-tour="${targetKey}"]`;
}

function extractTourTargetKey(selector: string): string | null {
  const match = selector.match(/\[data-tour="([^"]+)"\]/);
  return match?.[1] ?? null;
}

export function isCreateVaultCarouselTarget(selector: string): boolean {
  const key = extractTourTargetKey(selector);
  return key !== null && CREATE_VAULT_CAROUSEL_TARGET_KEYS.has(key);
}

export function isCreateVaultModalTarget(selector: string): boolean {
  const key = extractTourTargetKey(selector);
  return key !== null && CREATE_VAULT_MODAL_TARGET_KEYS.has(key);
}

export function isCarouselSlideActive(el: Element): boolean {
  return el.getAttribute("aria-hidden") !== "true";
}

export function isElementInCarouselViewport(el: Element): boolean {
  const viewport = el.closest(CREATE_VAULT_CAROUSEL_VIEWPORT_SELECTOR);
  if (!viewport) return false;

  const viewportRect = viewport.getBoundingClientRect();
  const targetRect = el.getBoundingClientRect();
  if (viewportRect.width <= 0 || viewportRect.height <= 0) return false;
  if (targetRect.width <= 0 || targetRect.height <= 0) return false;

  const horizontalOverlap =
    targetRect.left < viewportRect.right && targetRect.right > viewportRect.left;
  const verticalOverlap =
    targetRect.top < viewportRect.bottom && targetRect.bottom > viewportRect.top;

  return horizontalOverlap && verticalOverlap;
}

export function prefersReducedMotion(): boolean {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function waitForCssTransition(
  el: Element,
  property: string,
  maxMs: number,
): Promise<void> {
  if (prefersReducedMotion()) {
    return waitAnimationFrames(2);
  }

  return new Promise((resolve) => {
    let settled = false;
    let sawTransition = false;

    const finish = () => {
      if (settled) return;
      settled = true;
      el.removeEventListener("transitionrun", onTransitionRun);
      el.removeEventListener("transitionend", onTransitionEnd);
      window.clearTimeout(timer);
      resolve();
    };

    const matchesProperty = (event: TransitionEvent) =>
      event.target === el && event.propertyName === property;

    const onTransitionRun = (event: TransitionEvent) => {
      if (matchesProperty(event)) {
        sawTransition = true;
      }
    };

    const onTransitionEnd = (event: TransitionEvent) => {
      if (matchesProperty(event)) {
        finish();
      }
    };

    el.addEventListener("transitionrun", onTransitionRun);
    el.addEventListener("transitionend", onTransitionEnd);

    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (!sawTransition) {
          finish();
        }
      });
    });

    const timer = window.setTimeout(finish, maxMs);
  });
}

export async function waitForCreateVaultModalOpen(maxMs = 4000): Promise<boolean> {
  const start = Date.now();

  while (Date.now() - start < maxMs) {
    const panel = document.querySelector(CREATE_VAULT_MODAL_SELECTOR);
    if (panel && isElementVisible(panel)) {
      if (prefersReducedMotion()) {
        await waitAnimationFrames(2);
      } else {
        await waitForCssTransition(
          panel,
          "transform",
          CREATE_VAULT_MODAL_OPEN_MS + CAROUSEL_TRANSITION_BUFFER_MS,
        );
      }
      return true;
    }
    await waitAnimationFrames(1);
  }

  return Boolean(document.querySelector(CREATE_VAULT_MODAL_SELECTOR));
}

export async function waitForCreateVaultCarouselSlide(
  selector: string,
  maxMs = 4000,
): Promise<boolean> {
  const start = Date.now();

  while (Date.now() - start < maxMs) {
    const el = document.querySelector(selector);
    if (
      el &&
      isElementVisible(el) &&
      isCarouselSlideActive(el) &&
      isElementInCarouselViewport(el)
    ) {
      if (prefersReducedMotion()) {
        await waitAnimationFrames(2);
      } else {
        const track = el.closest(CREATE_VAULT_CAROUSEL_TRACK_SELECTOR);
        if (track) {
          await waitForCssTransition(
            track,
            "transform",
            CREATE_VAULT_CAROUSEL_TRANSITION_MS + CAROUSEL_TRANSITION_BUFFER_MS,
          );
        } else {
          await waitAnimationFrames(2);
        }
      }
      return true;
    }
    await waitAnimationFrames(1);
  }

  const el = document.querySelector(selector);
  return Boolean(
    el &&
      isElementVisible(el) &&
      isCarouselSlideActive(el) &&
      isElementInCarouselViewport(el),
  );
}

/** Delay before advancing tour index after a click on the given step. */
export function createVaultTourAdvanceDelayMs(stepId: string): number {
  if (stepId === "create-btn") {
    return CREATE_VAULT_MODAL_OPEN_MS + CAROUSEL_TRANSITION_BUFFER_MS;
  }
  if (WIZARD_CLICK_ADVANCE_STEP_IDS.has(stepId)) {
    return CREATE_VAULT_CAROUSEL_TRANSITION_MS + CAROUSEL_TRANSITION_BUFFER_MS;
  }
  if (stepId === "submit") {
    return 200;
  }
  return 120;
}

/**
 * Wait for a tour anchor, scroll it into view, and report whether it is visible.
 * Used in step `before` hooks — no React state loops.
 */
export async function prepareCreateVaultTourTarget(
  selector: string,
  maxMs = 4000,
): Promise<boolean> {
  await waitAnimationFrames(2);
  await waitForTourTarget(selector, maxMs);

  if (isCreateVaultModalTarget(selector)) {
    await waitForCreateVaultModalOpen(maxMs);
  }

  if (isCreateVaultCarouselTarget(selector)) {
    return waitForCreateVaultCarouselSlide(selector, maxMs);
  }

  let el = document.querySelector(selector);
  if (!el || !isElementVisible(el)) {
    await waitAnimationFrames(3);
    el = document.querySelector(selector);
  }
  if (!el || !isElementVisible(el)) return false;

  el.scrollIntoView({ block: "nearest", inline: "nearest" });
  await waitAnimationFrames(2);
  return true;
}

export { tourTargetSelector };
