import React from "react";

import "./vault.css";

export interface VaultDetailHeaderActionsProps {
  height?: string;
  isOwner?: boolean;
  onManageFunds?: () => void;
  onOperateVault?: () => void;
  /** When true, render only the actions row (for inline use inside VaultDetailHeader). */
  inline?: boolean;
}

function VaultDetailHeaderActionsContent({
  isOwner = false,
  onManageFunds,
  onOperateVault,
}: Pick<
  VaultDetailHeaderActionsProps,
  "isOwner" | "onManageFunds" | "onOperateVault"
>): JSX.Element {
  return (
    <>
      {isOwner ? (
        <span className="vault-detail-owner-badge">Owner · You</span>
      ) : null}
      {onManageFunds ? (
        <button
          type="button"
          className={
            isOwner
              ? "vault-detail-action-btn"
              : "vault-detail-action-btn--primary"
          }
          onClick={onManageFunds}
        >
          Deposit / Withdraw
        </button>
      ) : null}
      {isOwner && onOperateVault ? (
        <button
          type="button"
          className="vault-detail-action-btn--primary"
          onClick={onOperateVault}
        >
          Trade in Vault
        </button>
      ) : null}
    </>
  );
}

export default function VaultDetailHeaderActions({
  height = "100%",
  isOwner = false,
  onManageFunds,
  onOperateVault,
  inline = false,
}: VaultDetailHeaderActionsProps): JSX.Element {
  const actions = (
    <VaultDetailHeaderActionsContent
      isOwner={isOwner}
      onManageFunds={onManageFunds}
      onOperateVault={onOperateVault}
    />
  );

  if (inline) {
    return <div className="vault-detail-actions">{actions}</div>;
  }

  return (
    <div
      className="vault-slot vault-slot--flush vault-detail-header-actions"
      style={{ height }}
    >
      <div className="vault-detail-actions">{actions}</div>
    </div>
  );
}
