import React from "react";

import "../tables/TabSection.css";
import "./agentroles.css";

export type AgentRolesFilterLayoutMode = "compact" | "advanced";

export interface AgentRolesSearchToolbarProps {
  height?: string;
  query: string;
  onQueryChange: (value: string) => void;
  onMintAgent?: () => void;
  onDeployToMarket?: () => void;
  onOpenFiltersSheet?: () => void;
  showFiltersSheetTrigger?: boolean;
  filterLayoutMode?: AgentRolesFilterLayoutMode;
  onFilterLayoutModeChange?: (mode: AgentRolesFilterLayoutMode) => void;
  filtersActive?: boolean;
  filtersSheetOpen?: boolean;
}

export default function AgentRolesSearchToolbar({
  height = "100%",
  query,
  onQueryChange,
  onMintAgent,
  onDeployToMarket,
  onOpenFiltersSheet,
  showFiltersSheetTrigger = false,
  filterLayoutMode = "compact",
  onFilterLayoutModeChange,
  filtersActive = false,
  filtersSheetOpen = false,
}: AgentRolesSearchToolbarProps): JSX.Element {
  const filtersPressed = filtersSheetOpen || filtersActive;

  return (
    <div className="agentroles-slot agentroles-toolbar-panel" style={{ height }}>
      <div className="agentroles-toolbar-main">
        <div className="agentroles-toolbar-ctas">
          <button
            type="button"
            className="agentroles-toolbar-cta agentroles-toolbar-cta--primary"
            onClick={onMintAgent}
          >
            + Mint Agent
          </button>
          <button
            type="button"
            className="agentroles-toolbar-cta"
            onClick={onDeployToMarket}
          >
            Deploy to Market
          </button>
        </div>
        <div className="agentroles-toolbar-controls">
          <div className="terminal-search-field agentroles-search-field">
            <input
              className="terminal-search-input"
              value={query}
              onChange={(e) => onQueryChange(e.target.value)}
              placeholder="Search agents"
              aria-label="Search agents"
            />
          </div>
          {onFilterLayoutModeChange ? (
            <nav
              className="agentroles-filter-layout-toggle raw-pro-data-toggle"
              aria-label="Filter layout"
              role="tablist"
            >
              <button
                type="button"
                role="tab"
                aria-selected={filterLayoutMode === "compact"}
                className={`raw-pro-data-toggle-segment${
                  filterLayoutMode === "compact" ? " is-active" : ""
                }`}
                onClick={() => onFilterLayoutModeChange("compact")}
              >
                Compact
              </button>
              <button
                type="button"
                role="tab"
                aria-selected={filterLayoutMode === "advanced"}
                className={`raw-pro-data-toggle-segment${
                  filterLayoutMode === "advanced" ? " is-active" : ""
                }`}
                onClick={() => onFilterLayoutModeChange("advanced")}
              >
                Advanced
              </button>
            </nav>
          ) : null}
          {showFiltersSheetTrigger && onOpenFiltersSheet ? (
            <button
              type="button"
              className={`agentroles-filters-sheet-trigger${
                filtersPressed ? " is-active" : ""
              }`}
              aria-pressed={filtersPressed}
              aria-expanded={filtersSheetOpen}
              aria-haspopup="dialog"
              onClick={onOpenFiltersSheet}
            >
              Filters
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}
