import { useMemo } from "react";

import { parseVaultBucketTradeId } from "../components/vault/vaultBucketTradeAdapter";
import { getVaultBuckets } from "../../offline/mock_data/vaultCatalog";
import { useOptionalVaultOperate } from "../context/VaultOperateContext";

export type TradeTabScope = "personal" | "vault";

/** @deprecated Legacy prefixed bucket ids — raw ids are preferred. */
export function vaultBucketIdPrefix(vaultId: string): string {
  return `vault:${vaultId}:`;
}

export function isBucketInVaultScope(
  bucketId: string | null | undefined,
  vaultId: string,
): boolean {
  if (!bucketId?.trim()) return false;
  const legacy = parseVaultBucketTradeId(bucketId);
  if (legacy?.vaultId === vaultId) return true;
  return getVaultBuckets(vaultId).some((bucket) => bucket.id === bucketId);
}

export function taskMatchesVaultScope(
  task: { bucketId?: string | null },
  scope: TradeTabScope,
  vaultId: string | null | undefined,
): boolean {
  if (scope !== "vault" || !vaultId) return true;
  return isBucketInVaultScope(task.bucketId, vaultId);
}

export function resolveOrderBucketId(order: {
  bucketId?: string | null;
  raw?: { bucketId?: unknown } | null;
}): string | null {
  if (order.bucketId) return String(order.bucketId);
  const rawBucket = order.raw?.bucketId;
  if (rawBucket != null && rawBucket !== "") return String(rawBucket);
  return null;
}

export function orderMatchesVaultScope(
  order: {
    bucketId?: string | null;
    raw?: { bucketId?: unknown } | null;
  },
  scope: TradeTabScope,
  vaultId: string | null | undefined,
): boolean {
  if (scope !== "vault" || !vaultId) return true;
  const bucketId = resolveOrderBucketId(order);
  return isBucketInVaultScope(bucketId, vaultId);
}

export interface TradeTabScopeValue {
  scope: TradeTabScope;
  vaultId: string | null;
  vaultBucketId: string | null;
  tradeBucketId: string | null;
  isVaultScope: boolean;
}

export function useTradeTabScope(
  scope: TradeTabScope = "personal",
): TradeTabScopeValue {
  const vaultOperate = useOptionalVaultOperate();

  return useMemo(() => {
    const isVaultScope = scope === "vault" && (vaultOperate?.isActive ?? false);
    const vaultId = isVaultScope ? vaultOperate?.vaultId ?? null : null;
    const vaultBucketId = isVaultScope
      ? vaultOperate?.selectedBucketId ?? null
      : null;
    const tradeBucketId = vaultBucketId;

    return {
      scope: isVaultScope ? "vault" : "personal",
      vaultId,
      vaultBucketId,
      tradeBucketId,
      isVaultScope,
    };
  }, [
    scope,
    vaultOperate?.isActive,
    vaultOperate?.vaultId,
    vaultOperate?.selectedBucketId,
  ]);
}

export function resolveVaultBucketFromTradeId(
  tradeBucketId: string | null | undefined,
  vaultId?: string | null,
): { vaultId: string; bucketId: string } | null {
  if (!tradeBucketId) return null;
  const legacy = parseVaultBucketTradeId(tradeBucketId);
  if (legacy) return legacy;
  if (vaultId && isBucketInVaultScope(tradeBucketId, vaultId)) {
    return { vaultId, bucketId: tradeBucketId };
  }
  return null;
}
