import React from "react";

import {
  CUSTODY_FILTER_OPTIONS,
  LISTING_FILTER_OPTIONS,
  MODE_FILTER_OPTIONS,
  PAYMENT_FILTER_OPTIONS,
  ROLE_FILTER_OPTIONS,
} from "../../utils/agentRoles";
import "./agentroles.css";

export interface AgentRolesFiltersSidebarProps {
  height?: string;
  roleFilter: string;
  custodyFilter: string;
  paymentFilter: string;
  listingFilter: string;
  modeFilter: string;
  onRoleFilterChange: (value: string) => void;
  onCustodyFilterChange: (value: string) => void;
  onPaymentFilterChange: (value: string) => void;
  onListingFilterChange: (value: string) => void;
  onModeFilterChange: (value: string) => void;
  onReset: () => void;
  variant?: "sidebar" | "sheet";
}

function FilterChipGroup({
  label,
  options,
  value,
  onChange,
}: {
  label: string;
  options: readonly string[];
  value: string;
  onChange: (value: string) => void;
}): JSX.Element {
  return (
    <div className="agentroles-filter-group">
      <label>{label}</label>
      <div className="agentroles-chips">
        {options.map((item) => (
          <button
            type="button"
            key={item}
            className={`agentroles-pill-btn${value === item ? " active" : ""}`}
            onClick={() => onChange(item)}
          >
            {item}
          </button>
        ))}
      </div>
    </div>
  );
}

export default function AgentRolesFiltersSidebar({
  height = "100%",
  roleFilter,
  custodyFilter,
  paymentFilter,
  listingFilter,
  modeFilter,
  onRoleFilterChange,
  onCustodyFilterChange,
  onPaymentFilterChange,
  onListingFilterChange,
  onModeFilterChange,
  onReset,
  variant = "sidebar",
}: AgentRolesFiltersSidebarProps): JSX.Element {
  return (
    <aside
      className={`agentroles-slot agentroles-filters-sidebar agentroles-filters-sidebar--${variant}`}
      style={variant === "sidebar" ? { height } : undefined}
    >
      <div className="agentroles-filters-sidebar-head">
        <h2>Filters</h2>
        <button type="button" className="agentroles-reset-btn" onClick={onReset}>
          Reset
        </button>
      </div>
      <FilterChipGroup
        label="Role"
        options={ROLE_FILTER_OPTIONS}
        value={roleFilter}
        onChange={onRoleFilterChange}
      />
      <FilterChipGroup
        label="Custody"
        options={CUSTODY_FILTER_OPTIONS}
        value={custodyFilter}
        onChange={onCustodyFilterChange}
      />
      <FilterChipGroup
        label="Payments"
        options={PAYMENT_FILTER_OPTIONS}
        value={paymentFilter}
        onChange={onPaymentFilterChange}
      />
      <FilterChipGroup
        label="Listing"
        options={LISTING_FILTER_OPTIONS}
        value={listingFilter}
        onChange={onListingFilterChange}
      />
      <FilterChipGroup
        label="Mode"
        options={MODE_FILTER_OPTIONS}
        value={modeFilter}
        onChange={onModeFilterChange}
      />
    </aside>
  );
}
