import React, { useMemo, useState } from "react";

import { useVaultOpenOrders } from "../../hooks/useVaultOpenOrders";
import type { VaultOpenOrderRow } from "../../../offline/mock_data/vaultMockData.types";
import {
  ORDER_SIDE_COLOR_BUY_LONG,
  ORDER_SIDE_COLOR_SELL_SHORT,
} from "../../constants";
import { formatCurrency } from "../../sdk/utils/display";
import { TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import VaultActivityTableShell, {
  type VaultActivityTableLayout,
} from "./VaultActivityTableShell";
import VaultTableFooter from "./VaultTableFooter";
import "./vault.css";

const GRID =
  "1.2fr 0.7fr 0.8fr 0.7fr 0.8fr 0.9fr 1fr";

export interface VaultOpenOrdersTableProps {
  vaultId: string;
  bucketId?: string;
  layout?: VaultActivityTableLayout;
}

function formatDateTime(value: number): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(new Date(value));
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function sideColor(side: VaultOpenOrderRow["side"]): string | undefined {
  return side === "Buy" ? ORDER_SIDE_COLOR_BUY_LONG : ORDER_SIDE_COLOR_SELL_SHORT;
}

export default function VaultOpenOrdersTable({
  vaultId,
  bucketId,
  layout = "bucket",
}: VaultOpenOrdersTableProps): JSX.Element {
  const allRows = useVaultOpenOrders(vaultId, bucketId);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);
  const paginate = layout !== "terminal";

  const pageRows = useMemo(() => {
    if (!paginate) return allRows;
    const start = page * pageSize;
    return allRows.slice(start, start + pageSize);
  }, [allRows, page, pageSize, paginate]);

  return (
    <VaultActivityTableShell
      gridColumns={GRID}
      layout={layout}
      isEmpty={allRows.length === 0}
      emptyMessage="No open orders."
      header={
        <>
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Coin</TableHeaderCellStatic>
          <TableHeaderCellStatic center>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.orderType} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic center>Side</TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.originalSize} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic right>Price</TableHeaderCellStatic>
          <TableHeaderCellStatic right>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.orderValue} />
          </TableHeaderCellStatic>
        </>
      }
      footer={
        paginate ? (
          <VaultTableFooter
            page={page}
            pageSize={pageSize}
            totalCount={allRows.length}
            onPageChange={setPage}
            onPageSizeChange={setPageSize}
          />
        ) : undefined
      }
    >
      {pageRows.map((row, index) => (
        <div
          key={row.orderId}
          className={`table-row ${index % 2 === 0 ? "even" : ""}`}
          style={{ gridTemplateColumns: GRID }}
        >
          <div className="table-cell">{formatDateTime(row.time)}</div>
          <div className="table-cell primary">{row.market}</div>
          <div className="table-cell">{row.type}</div>
          <div className="table-cell" style={{ color: sideColor(row.side) }}>
            {row.side}
          </div>
          <div className="table-cell numeric">
            {formatNumber(row.size)}
          </div>
          <div className="table-cell numeric">
            {formatCurrency(row.price)}
          </div>
          <div className="table-cell numeric">
            {formatCurrency(row.orderValueUsd)}
          </div>
        </div>
      ))}
    </VaultActivityTableShell>
  );
}
