import React, { useMemo } from "react";

import type { VaultBucketSummary } from "../../../offline/mock_data/vaultCatalog";
import { formatVaultTvl } from "../../../offline/mock_data/vaultCatalog";
import {
  POSITION_PNL_COLOR_NEGATIVE,
  POSITION_PNL_COLOR_POSITIVE,
} from "../../constants";
import { formatCurrency } from "../../sdk/utils/display";
import { TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import { shortHashId } from "../../utils/hashId";
import {
  aggregateBucketTotals,
  allocationPct,
  bucketLeverage,
  formatLeverage,
  formatPct,
  formatSignedPct,
  pnlHoverTitle,
  riskHealthLabel,
} from "./vaultPortfolioMetrics";
import type { VaultPortfolioColumnId } from "./vaultPortfolioTableLayout";
import type { VaultPortfolioTablePrefs } from "../preference/SettingsModal";

function renderColumnHeader(column: VaultPortfolioColumnId): JSX.Element {
  switch (column) {
    case "bucket":
      return (
        <TableHeaderCellStatic left key={column}>
          <TableHeaderLabel {...TABLE_HEADER_LABELS.bucketId} />
        </TableHeaderCellStatic>
      );
    case "mode":
      return (
        <TableHeaderCellStatic left key={column}>
          Mode
        </TableHeaderCellStatic>
      );
    case "equity":
      return (
        <TableHeaderCellStatic right key={column}>
          Equity
        </TableHeaderCellStatic>
      );
    case "allocation":
      return (
        <TableHeaderCellStatic right key={column}>
          <TableHeaderLabel {...TABLE_HEADER_LABELS.allocation} />
        </TableHeaderCellStatic>
      );
    case "risk":
      return (
        <TableHeaderCellStatic right key={column}>
          <TableHeaderLabel {...TABLE_HEADER_LABELS.riskRatio} />
        </TableHeaderCellStatic>
      );
    case "netExposure":
      return (
        <TableHeaderCellStatic right key={column}>
          Net Exposure
        </TableHeaderCellStatic>
      );
    case "exposureLegs":
      return (
        <TableHeaderCellStatic right key={column}>
          <TableHeaderLabel {...TABLE_HEADER_LABELS.exposure} />
        </TableHeaderCellStatic>
      );
    case "leverage":
      return (
        <TableHeaderCellStatic right key={column}>
          <TableHeaderLabel {...TABLE_HEADER_LABELS.leverage} />
        </TableHeaderCellStatic>
      );
    case "margin":
      return (
        <TableHeaderCellStatic right key={column}>
          Margin %
        </TableHeaderCellStatic>
      );
    case "funding":
      return (
        <TableHeaderCellStatic right key={column}>
          <TableHeaderLabel {...TABLE_HEADER_LABELS.funding} />
        </TableHeaderCellStatic>
      );
    case "upnl":
      return (
        <TableHeaderCellStatic right key={column}>
          uPnL
        </TableHeaderCellStatic>
      );
    default:
      return <TableHeaderCellStatic key={column}>—</TableHeaderCellStatic>;
  }
}

function renderBucketCell(
  column: VaultPortfolioColumnId,
  bucket: VaultBucketSummary,
  vaultTvlUsd: number,
): JSX.Element {
  const alloc = allocationPct(bucket.equityUsd, vaultTvlUsd);
  const leverage = bucketLeverage(bucket);
  const pnlColor =
    bucket.pnlUsd >= 0
      ? POSITION_PNL_COLOR_POSITIVE
      : POSITION_PNL_COLOR_NEGATIVE;
  const fundingColor =
    bucket.fundingPnlUsd >= 0
      ? POSITION_PNL_COLOR_POSITIVE
      : POSITION_PNL_COLOR_NEGATIVE;

  switch (column) {
    case "bucket":
      return (
        <div className="table-cell primary vault-activity-source-hash" key={column}>
          <span title={bucket.id}>{shortHashId(bucket.id)}</span>
        </div>
      );
    case "mode":
      return (
        <div className="table-cell" key={column}>
          <span className={`vault-mode-chip vault-mode-chip--${bucket.mode}`}>
            {bucket.mode === "cross" ? "Cross" : "Isolated"}
          </span>
        </div>
      );
    case "equity":
      return (
        <div className="table-cell numeric" key={column}>
          {formatVaultTvl(bucket.equityUsd)}
        </div>
      );
    case "allocation":
      return (
        <div className="table-cell numeric" key={column}>
          {formatPct(alloc)} · {formatVaultTvl(bucket.equityUsd)}
        </div>
      );
    case "risk":
      return (
        <div className="table-cell numeric" key={column}>
          {bucket.riskRatio.toFixed(2)} {riskHealthLabel(bucket.riskHealth)}
        </div>
      );
    case "netExposure":
      return (
        <div className="table-cell numeric" key={column}>
          {bucket.netExposureLabel}
        </div>
      );
    case "exposureLegs":
      return (
        <div className="table-cell numeric" key={column}>
          {formatVaultTvl(bucket.longNotionalUsd)}/
          {formatVaultTvl(bucket.shortNotionalUsd)}
        </div>
      );
    case "leverage":
      return (
        <div className="table-cell numeric" key={column}>
          {formatLeverage(leverage)}
        </div>
      );
    case "margin":
      return (
        <div className="table-cell numeric" key={column}>
          {bucket.marginUsagePct}%
        </div>
      );
    case "funding":
      return (
        <div
          className="table-cell numeric"
          key={column}
          style={{ color: fundingColor }}
        >
          {bucket.fundingPnlUsd >= 0 ? "+" : ""}
          {formatCurrency(bucket.fundingPnlUsd)} · {formatPct(bucket.fundingAprPct, 0)} APR
        </div>
      );
    case "upnl":
      return (
        <div
          className="table-cell numeric"
          key={column}
          style={{ color: pnlColor }}
          title={pnlHoverTitle(bucket)}
        >
          {bucket.pnlUsd >= 0 ? "+" : ""}
          {formatCurrency(bucket.pnlUsd)}
          {bucket.roiPct != null ? ` · ${formatSignedPct(bucket.roiPct)}` : ""}
        </div>
      );
    default:
      return (
        <div className="table-cell numeric" key={column}>
          —
        </div>
      );
  }
}

function renderTotalCell(
  column: VaultPortfolioColumnId,
  totals: ReturnType<typeof aggregateBucketTotals>,
  prefs: VaultPortfolioTablePrefs,
): JSX.Element {
  const fundingColor =
    totals.fundingPnlUsd >= 0
      ? POSITION_PNL_COLOR_POSITIVE
      : POSITION_PNL_COLOR_NEGATIVE;
  const pnlColor =
    totals.totalPnlUsd >= 0
      ? POSITION_PNL_COLOR_POSITIVE
      : POSITION_PNL_COLOR_NEGATIVE;

  switch (column) {
    case "bucket":
      return (
        <div className="table-cell primary" key={column}>
          TOTAL
        </div>
      );
    case "equity":
      return (
        <div className="table-cell numeric" key={column}>
          {formatVaultTvl(totals.deployedEquityUsd)}
        </div>
      );
    case "allocation":
      return (
        <div className="table-cell numeric" key={column}>
          {formatPct(totals.deploymentPct)} of TVL
        </div>
      );
    case "funding":
      return (
        <div
          className="table-cell numeric"
          key={column}
          style={{ color: fundingColor }}
        >
          {totals.fundingPnlUsd >= 0 ? "+" : ""}
          {formatCurrency(totals.fundingPnlUsd)} agg
        </div>
      );
    case "upnl":
      return (
        <div className="table-cell numeric" key={column} style={{ color: pnlColor }}>
          {totals.totalPnlUsd >= 0 ? "+" : ""}
          {formatCurrency(totals.totalPnlUsd)} agg
        </div>
      );
    default:
      if (
        (column === "exposureLegs" && !prefs.showExposureLegs) ||
        (column === "leverage" && !prefs.showLeverage) ||
        (column === "funding" && !prefs.showFunding) ||
        (column === "allocation" && !prefs.showAllocation)
      ) {
        return (
          <div className="table-cell numeric" key={column}>
            —
          </div>
        );
      }
      return (
        <div className="table-cell numeric" key={column}>
          —
        </div>
      );
  }
}

export { renderColumnHeader, renderBucketCell, renderTotalCell };
