import { useCallback, useState, type Dispatch, type SetStateAction } from "react";

import { useTradingAgentStore } from "../store/tradingAgentStore";
import type { DeployAgentWizardState } from "../utils/deployAgent";
import {
  buildInitialPerAgentDetails,
  computeDeployEligibility,
  createDeployWizardState,
  goNextDeployStep,
  goPrevDeployStep,
  isDeployStepValid,
} from "../utils/deployAgent";

export interface DeployAgentOpenOptions {
  preselectedIds?: string[];
}

export interface UseDeployAgentModalResult {
  isOpen: boolean;
  state: DeployAgentWizardState;
  open: (options?: DeployAgentOpenOptions) => void;
  close: () => void;
  setState: Dispatch<SetStateAction<DeployAgentWizardState>>;
  goNext: () => void;
  goBack: () => void;
}

export function useDeployAgentModal(): UseDeployAgentModalResult {
  const [isOpen, setIsOpen] = useState(false);
  const [state, setState] = useState<DeployAgentWizardState>(() =>
    createDeployWizardState(),
  );
  const agents = useTradingAgentStore((s) => s.agents);

  const open = useCallback(
    (options?: DeployAgentOpenOptions) => {
      const preselectedIds = (options?.preselectedIds ?? []).filter((agentId) => {
        const agent = agents.find((entry) => entry.id === agentId);
        if (!agent) return false;
        return computeDeployEligibility(agent).canSelect;
      });

      setState(
        createDeployWizardState({
          selectedAgentIds: preselectedIds,
          perAgent: buildInitialPerAgentDetails(agents, preselectedIds),
        }),
      );
      setIsOpen(true);
    },
    [agents],
  );

  const close = useCallback(() => {
    setIsOpen(false);
    setState(createDeployWizardState());
  }, []);

  const goNext = useCallback(() => {
    setState((prev) => {
      if (!isDeployStepValid(prev.step, prev, agents)) return prev;
      const next = goNextDeployStep(prev);
      if (!next) return prev;
      if (next.step === "details") {
        return {
          ...next,
          perAgent: buildInitialPerAgentDetails(agents, prev.selectedAgentIds),
        };
      }
      return next;
    });
  }, [agents]);

  const goBack = useCallback(() => {
    setState((prev) => goPrevDeployStep(prev) ?? prev);
  }, []);

  return {
    isOpen,
    state,
    open,
    close,
    setState,
    goNext,
    goBack,
  };
}
