import React, { useEffect, useMemo, useRef, useState } from "react";

import {
  COMPACT_CHART_HEIGHT,
  COMPACT_CHART_NEGATIVE,
  COMPACT_CHART_POSITIVE,
  COMPACT_CHART_WIDTH,
} from "./compactChartTheme";
import type { CompactMetricTone } from "./types";
import { metricToneClassName } from "./types";

export interface CompactSparklineProps {
  values?: number[];
  tone?: CompactMetricTone;
  className?: string;
  overflow?: "visible" | "hidden";
  preserveAspectRatio?: string;
  /** Inset in viewBox units so round stroke caps stay inside the SVG bounds. */
  strokeInset?: number;
  /** Measure container width/height and map viewBox 1:1 to avoid non-uniform scaling. */
  responsiveWidth?: boolean;
}

function buildSparklinePoints(
  cleanValues: number[],
  width: number,
  height: number,
  strokeInset: number,
): string {
  const inset = Math.max(0, strokeInset);
  const innerWidth = Math.max(0, width - inset * 2);
  const innerHeight = Math.max(0, height - inset * 2);
  const flatY = inset + innerHeight / 2;

  if (cleanValues.length < 2) {
    return `${inset},${flatY} ${width - inset},${flatY}`;
  }

  const min = Math.min(...cleanValues);
  const max = Math.max(...cleanValues);

  return cleanValues
    .map((value, index) => {
      const x = inset + (index / (cleanValues.length - 1)) * innerWidth;
      const normalized = max === min ? 0.5 : (value - min) / (max - min);
      const y = inset + innerHeight - normalized * innerHeight;
      return `${x},${y}`;
    })
    .join(" ");
}

function CompactSparkline({
  values,
  tone = "neutral",
  className = "",
  overflow = "hidden",
  preserveAspectRatio,
  strokeInset = 0,
  responsiveWidth = false,
}: CompactSparklineProps): JSX.Element {
  const wrapRef = useRef<HTMLDivElement>(null);
  const [measuredSize, setMeasuredSize] = useState({
    width: COMPACT_CHART_WIDTH,
    height: COMPACT_CHART_HEIGHT,
  });

  const cleanValues = useMemo(
    () =>
      Array.isArray(values)
        ? values.filter((value) => Number.isFinite(value))
        : [],
    [values],
  );

  useEffect(() => {
    if (!responsiveWidth || !wrapRef.current) return;

    const element = wrapRef.current;

    const updateSize = () => {
      const width = element.clientWidth;
      const height = element.clientHeight;
      if (width > 0 && height > 0) {
        setMeasuredSize({ width, height });
      }
    };

    updateSize();

    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", updateSize);
      return () => window.removeEventListener("resize", updateSize);
    }

    const resizeObserver = new ResizeObserver(updateSize);
    resizeObserver.observe(element);
    return () => resizeObserver.disconnect();
  }, [responsiveWidth]);

  const chartWidth = responsiveWidth ? measuredSize.width : COMPACT_CHART_WIDTH;
  const chartHeight = responsiveWidth
    ? measuredSize.height
    : COMPACT_CHART_HEIGHT;

  const points = useMemo(
    () => buildSparklinePoints(cleanValues, chartWidth, chartHeight, strokeInset),
    [cleanValues, chartWidth, chartHeight, strokeInset],
  );

  const toneClass = metricToneClassName(tone);
  const strokeColor =
    tone === "positive"
      ? COMPACT_CHART_POSITIVE
      : tone === "negative"
        ? COMPACT_CHART_NEGATIVE
        : undefined;

  const svg = (
    <svg
      viewBox={`0 0 ${chartWidth} ${chartHeight}`}
      aria-hidden
      overflow={overflow}
      preserveAspectRatio={responsiveWidth ? undefined : preserveAspectRatio}
      className={
        responsiveWidth
          ? `compact-metric-sparkline ${toneClass}`.trim()
          : `compact-metric-sparkline ${toneClass} ${className}`.trim()
      }
      style={strokeColor ? { color: strokeColor } : undefined}
      width={responsiveWidth ? "100%" : undefined}
      height={responsiveWidth ? "100%" : undefined}
    >
      <polyline
        points={points}
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        vectorEffect={responsiveWidth ? "non-scaling-stroke" : undefined}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );

  if (responsiveWidth) {
    return (
      <div
        ref={wrapRef}
        className={`compact-sparkline-responsive-wrap ${className}`.trim()}
      >
        {svg}
      </div>
    );
  }

  return svg;
}

export default React.memo(CompactSparkline);
