import React, { useMemo, useState } from "react";

import { useVaultFundingHistory } from "../../hooks/useVaultFundingHistory";
import type { VaultFundingRow } from "../../../offline/mock_data/vaultMockData.types";
import { formatCurrency } from "../../sdk/utils/display";
import { TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import VaultActivityTableShell, {
  type VaultActivityTableLayout,
} from "./VaultActivityTableShell";
import VaultTableFooter from "./VaultTableFooter";
import "./vault.css";

const GRID = "1.2fr 0.9fr 0.7fr 0.9fr 1fr 0.8fr";

export interface VaultFundingHistoryTableProps {
  vaultId: string;
  bucketId?: string;
  layout?: VaultActivityTableLayout;
}

function formatDateTime(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(new Date(value));
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function formatRate(value: number): string {
  return `${(value * 100).toFixed(4)}%`;
}

export default function VaultFundingHistoryTable({
  vaultId,
  bucketId,
  layout = "bucket",
}: VaultFundingHistoryTableProps): JSX.Element {
  const allRows = useVaultFundingHistory(vaultId, bucketId);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);
  const paginate = layout !== "terminal";

  const pageRows = useMemo(() => {
    if (!paginate) return allRows;
    const start = page * pageSize;
    return allRows.slice(start, start + pageSize);
  }, [allRows, page, pageSize, paginate]);

  return (
    <VaultActivityTableShell
      gridColumns={GRID}
      layout={layout}
      isEmpty={allRows.length === 0}
      emptyMessage="No funding payments."
      header={
        <>
          <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Token</TableHeaderCellStatic>
          <TableHeaderCellStatic left>Side</TableHeaderCellStatic>
          <TableHeaderCellStatic left>
            <TableHeaderLabel {...TABLE_HEADER_LABELS.positionSize} />
          </TableHeaderCellStatic>
          <TableHeaderCellStatic left>Payout</TableHeaderCellStatic>
          <TableHeaderCellStatic right>Rate</TableHeaderCellStatic>
        </>
      }
      footer={
        paginate ? (
          <VaultTableFooter
            page={page}
            pageSize={pageSize}
            totalCount={allRows.length}
            onPageChange={setPage}
            onPageSizeChange={setPageSize}
          />
        ) : undefined
      }
    >
      {pageRows.map((row: VaultFundingRow, index) => (
        <div
          key={`${row.time}-${row.symbol}-${index}`}
          className="table-row"
          style={{ gridTemplateColumns: GRID }}
        >
          <div className="table-cell">{formatDateTime(row.time)}</div>
          <div className="table-cell primary">{row.symbol}</div>
          <div className="table-cell">{row.side}</div>
          <div className="table-cell numeric">
            {formatNumber(row.positionSize)}
          </div>
          <div
            className={`table-cell numeric ${
              row.payout >= 0 ? "vault-grade-a" : "vault-grade-d"
            }`}
          >
            {formatCurrency(row.payout)}
          </div>
          <div className="table-cell numeric">
            {formatRate(row.rate)}
          </div>
        </div>
      ))}
    </VaultActivityTableShell>
  );
}
