/**
 * Runtime accessors for staking validator data loaded from mock-system-data.
 * Populated by stakingValidatorsClient after fetch; empty until loaded.
 */
import { getCachedStakingValidators } from "./stakingValidatorsCache";
import { getStakingDelegations } from "./stakingDelegationState";
import type { StakingValidatorRow } from "./stakingValidators.types";

export function getStakingValidators(): StakingValidatorRow[] {
  return getCachedStakingValidators()?.validators ?? [];
}

export function cloneStakingValidators(): StakingValidatorRow[] {
  return getStakingValidators().map((row) => ({ ...row }));
}

export function cloneStakingValidatorsForWallet(
  wallet: string | null | undefined,
): StakingValidatorRow[] {
  const base = cloneStakingValidators();
  if (!wallet?.trim()) return base;

  const delegations = getStakingDelegations(wallet);
  return base.map((row) => {
    const yours = delegations[row.validatorId];
    return {
      ...row,
      yourStakeMorm: yours && yours > 0 ? yours : null,
    };
  });
}
