import type { PortfolioHeroView } from "./portfolioHeroView";
import {
  PORTFOLIO_AGENT_RANKS_STACKED_TAB_START_ROW,
  PORTFOLIO_HERO_START_ROW,
  PORTFOLIO_LAYOUT_MARGIN,
  PORTFOLIO_MD_PERFORMANCE_TAB_START_ROW,
  PORTFOLIO_OVERVIEW_PAIRED_TAB_START_ROW,
  PORTFOLIO_ROW_HEIGHT,
  PORTFOLIO_STACKED_HERO_START_ROW,
  PORTFOLIO_STACKED_PERFORMANCE_TAB_START_ROW,
  PORTFOLIO_STACKED_TAB_START_ROW,
  PORTFOLIO_TAB_START_ROW,
} from "../../configs/portfolioLayoutConfig";

const STACKED_BREAKPOINTS = new Set(["xs", "xxs"]);

export interface PortfolioHeroBandBounds {
  topPx: number;
  heightPx: number;
}

function rowStride(): number {
  return PORTFOLIO_ROW_HEIGHT + PORTFOLIO_LAYOUT_MARGIN;
}

function boundsFromTabStartRow(
  tabStartRow: number,
  heroStartRow: number,
): PortfolioHeroBandBounds {
  const stride = rowStride();
  const topPx = heroStartRow * stride;
  const heightPx = (tabStartRow - heroStartRow) * stride;
  return { topPx, heightPx };
}

/** Tab start row for overlay hero-band bounds (matches portfolio layout config). */
export function getPortfolioTabStartRow(
  breakpoint: string,
  heroView: PortfolioHeroView,
): number {
  if (STACKED_BREAKPOINTS.has(breakpoint)) {
    if (heroView === "performance") {
      return PORTFOLIO_STACKED_PERFORMANCE_TAB_START_ROW;
    }
    if (heroView === "agentRanks") {
      return PORTFOLIO_AGENT_RANKS_STACKED_TAB_START_ROW;
    }
    return PORTFOLIO_STACKED_TAB_START_ROW;
  }

  if (breakpoint === "md" || breakpoint === "sm") {
    if (heroView === "overview") {
      return PORTFOLIO_OVERVIEW_PAIRED_TAB_START_ROW;
    }
    if (heroView === "performance") {
      return PORTFOLIO_MD_PERFORMANCE_TAB_START_ROW;
    }
    if (heroView === "agentRanks" && breakpoint === "sm") {
      return PORTFOLIO_MD_PERFORMANCE_TAB_START_ROW;
    }
  }

  return PORTFOLIO_TAB_START_ROW;
}

export function getPortfolioHeroBandBounds(
  breakpoint: string,
  heroView: PortfolioHeroView,
): PortfolioHeroBandBounds {
  const heroStartRow = STACKED_BREAKPOINTS.has(breakpoint)
    ? PORTFOLIO_STACKED_HERO_START_ROW
    : PORTFOLIO_HERO_START_ROW;
  return boundsFromTabStartRow(
    getPortfolioTabStartRow(breakpoint, heroView),
    heroStartRow,
  );
}
