import { useCallback, useState, type Dispatch, type SetStateAction } from "react";

import { useTradingAgentStore } from "../store/tradingAgentStore";
import type { MintAgentWizardState } from "../utils/mintAgent";
import {
  buildExpressStateFromAgent,
  clearMintDraft,
  createMintWizardState,
  goNextStep,
  goPrevStep,
  isStepValid,
  loadMintDraft,
  saveMintDraft,
} from "../utils/mintAgent";

export interface MintAgentOpenOptions {
  duplicateFrom?: string;
}

export interface UseMintAgentModalResult {
  isOpen: boolean;
  state: MintAgentWizardState;
  open: (options?: MintAgentOpenOptions) => void;
  close: () => void;
  setState: Dispatch<SetStateAction<MintAgentWizardState>>;
  goNext: () => void;
  goBack: () => void;
  saveDraft: () => void;
}

export function useMintAgentModal(): UseMintAgentModalResult {
  const [isOpen, setIsOpen] = useState(false);
  const [state, setState] = useState<MintAgentWizardState>(() =>
    createMintWizardState(),
  );
  const getAgentById = useTradingAgentStore((s) => s.getAgentById);
  const agents = useTradingAgentStore((s) => s.agents);

  const open = useCallback(
    (options?: MintAgentOpenOptions) => {
      if (options?.duplicateFrom) {
        const source = getAgentById(options.duplicateFrom);
        if (source) {
          setState(buildExpressStateFromAgent(source));
          setIsOpen(true);
          return;
        }
      }
      const draft = loadMintDraft();
      setState(draft ?? createMintWizardState());
      setIsOpen(true);
    },
    [getAgentById],
  );

  const close = useCallback(() => {
    setIsOpen(false);
  }, []);

  const goNext = useCallback(() => {
    setState((prev) => {
      if (!isStepValid(prev.step, prev, agents)) return prev;
      return goNextStep(prev) ?? prev;
    });
  }, [agents]);

  const goBack = useCallback(() => {
    setState((prev) => goPrevStep(prev) ?? prev);
  }, []);

  const saveDraft = useCallback(() => {
    setState((prev) => {
      saveMintDraft(prev);
      return prev;
    });
  }, []);

  return {
    isOpen,
    state,
    open,
    close,
    setState,
    goNext,
    goBack,
    saveDraft,
  };
}
