import type { VaultBucketSummary } from "./vaultCatalog";

const DEFAULT_MARKETS = ["BTC", "ETH", "SOL"];

/**
 * Builds a minimal Primary trading bucket for newly created vaults.
 * Uses the same bucket id shape as personal margin buckets (hex hash).
 */
export function buildDefaultVaultTradingBucket(
  bucketId: string,
  tvlUsd: number,
  markets: string[] = DEFAULT_MARKETS,
): VaultBucketSummary {
  const tradableMarkets = markets.length > 0 ? markets : DEFAULT_MARKETS;

  return {
    id: bucketId,
    name: "Primary",
    mode: "cross",
    markets: tradableMarkets.slice(0, 3),
    equityUsd: Math.max(0, tvlUsd),
    riskRatio: 0,
    riskHealth: "healthy",
    longNotionalUsd: 0,
    shortNotionalUsd: 0,
    netExposureLabel: "Flat",
    marginUsagePct: 0,
    pnlUsd: 0,
    pricePnlUsd: 0,
    fundingPnlUsd: 0,
    fundingAprPct: 0,
    roiPct: 0,
    openPositionCount: 0,
  };
}
