export const OFFLINE_MINT_AGENT_STABLE_TOAST_ID = "offline:mint-agent";

export type OfflineMintAgentStepId =
  | "sign"
  | "submit"
  | "reserve"
  | "attest";

export type OfflineMintAgentStep = {
  id: OfflineMintAgentStepId;
  loadingMessage: string;
  loadingDescription: string;
  delayMs: number;
};

export type OfflineMintAgentStepParams = {
  displayName: string;
  handle: string;
  memoryMb: number;
  marketSymbol: string;
};

const BASE_STEPS: Omit<OfflineMintAgentStep, "loadingDescription">[] = [
  {
    id: "sign",
    loadingMessage: "Signing transaction…",
    delayMs: 400,
  },
  {
    id: "submit",
    loadingMessage: "Submitting to morphcore…",
    delayMs: 500,
  },
  {
    id: "reserve",
    loadingMessage: "Reserving on-chain memory…",
    delayMs: 600,
  },
  {
    id: "attest",
    loadingMessage: "Awaiting consensus…",
    delayMs: 500,
  },
];

/** Staged on-chain steps for offline mint-agent demo toasts. */
export function getOfflineMintAgentSteps(
  params: OfflineMintAgentStepParams,
): OfflineMintAgentStep[] {
  return BASE_STEPS.map((step) => {
    let loadingDescription: string;
    switch (step.id) {
      case "sign":
        loadingDescription = "Building KYA DID EIP-712 payload";
        break;
      case "submit":
        loadingDescription = "Broadcasting DID mint · /tx/v1/submit";
        break;
      case "reserve":
        loadingDescription = `${params.memoryMb} MB from master pool · paid in MORM`;
        break;
      case "attest":
        loadingDescription = `Finalizing ${params.handle} · ${params.marketSymbol}`;
        break;
      default:
        loadingDescription = params.displayName;
    }
    return { ...step, loadingDescription };
  });
}
