import React, { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import { useVaultActivity } from "../../hooks/useVaultActivity";
import type {
  VaultActivityRow,
  VaultActivitySourceKind,
  VaultActivityType,
} from "../../../offline/mock_data/vaultMockData.types";
import {
  POSITION_PNL_COLOR_NEGATIVE,
  POSITION_PNL_COLOR_POSITIVE,
} from "../../constants";
import { formatCurrency } from "../../sdk/utils/display";
import { shortHashId } from "../../utils/hashId";
import { vaultBucketPath } from "../../routes";
import { TableHeaderCellStatic, TableHeaderLabel } from "../smartlayout";
import { TABLE_HEADER_LABELS } from "../smartlayout/tableHeaderLabels";
import VaultActivityTableShell from "./VaultActivityTableShell";
import VaultTableFooter from "./VaultTableFooter";
import {
  activityTypeLabel,
  formatVaultActivitySource,
  vaultActivitySourceTitle,
} from "./vaultActivityFormat";
import "./vault.css";

const GRID =
  "1.1fr 0.65fr 0.75fr 0.85fr 0.75fr 0.7fr 0.75fr 0.6fr 0.75fr";

const ACTIVITY_TYPES: Array<VaultActivityType | "all"> = [
  "all",
  "perp",
  "spot",
  "lp",
  "transfer",
  "funding",
];

export interface VaultActivityTableProps {
  vaultId: string;
}

function formatDateTime(value: number): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "short",
    timeStyle: "short",
  }).format(new Date(value));
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 8,
  }).format(value);
}

function formatOptionalCurrency(value: number | null): string {
  if (value == null) return "—";
  return formatCurrency(value);
}

function formatOptionalNumber(value: number | null): string {
  if (value == null) return "—";
  return formatNumber(value);
}

type SourceFilter = "all" | `bucket:${string}` | VaultActivitySourceKind;

export default function VaultActivityTable({
  vaultId,
}: VaultActivityTableProps): JSX.Element {
  const navigate = useNavigate();
  const allRows = useVaultActivity(vaultId);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);
  const [typeFilter, setTypeFilter] = useState<VaultActivityType | "all">("all");
  const [sourceFilter, setSourceFilter] = useState<SourceFilter>("all");
  const [assetQuery, setAssetQuery] = useState("");

  const sourceOptions = useMemo(() => {
    const bucketIds = new Set<string>();
    const kinds = new Set<VaultActivitySourceKind>();
    for (const row of allRows) {
      if (row.sourceKind === "bucket" && row.bucketId) {
        bucketIds.add(row.bucketId);
      } else {
        kinds.add(row.sourceKind);
      }
    }
    return {
      bucketIds: [...bucketIds].sort(),
      kinds: [...kinds].filter((k) => k !== "bucket").sort(),
    };
  }, [allRows]);

  const filteredRows = useMemo(() => {
    const q = assetQuery.trim().toLowerCase();
    return allRows.filter((row) => {
      if (typeFilter !== "all" && row.activityType !== typeFilter) return false;
      if (sourceFilter === "all") {
        // pass
      } else if (sourceFilter.startsWith("bucket:")) {
        const bucketId = sourceFilter.slice("bucket:".length);
        if (row.bucketId !== bucketId) return false;
      } else if (row.sourceKind !== sourceFilter) {
        return false;
      }
      if (q && !row.market.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [allRows, typeFilter, sourceFilter, assetQuery]);

  const pageRows = useMemo(() => {
    const start = page * pageSize;
    return filteredRows.slice(start, start + pageSize);
  }, [filteredRows, page, pageSize]);

  const handleSourceNavigate = (row: VaultActivityRow) => {
    if (row.sourceKind !== "bucket" || !row.bucketId) return;
    navigate(vaultBucketPath(vaultId, row.bucketId));
  };

  return (
    <div className="vault-activity-table-panel">
      <div className="vault-activity-filters" role="toolbar" aria-label="Activity filters">
        <select
          className="vault-filter-select"
          value={typeFilter}
          onChange={(e) => {
            setTypeFilter(e.target.value as VaultActivityType | "all");
            setPage(0);
          }}
          aria-label="Filter by activity type"
        >
          {ACTIVITY_TYPES.map((type) => (
            <option key={type} value={type}>
              {type === "all" ? "Type: All" : `Type: ${activityTypeLabel(type)}`}
            </option>
          ))}
        </select>
        <select
          className="vault-filter-select"
          value={sourceFilter}
          onChange={(e) => {
            setSourceFilter(e.target.value as SourceFilter);
            setPage(0);
          }}
          aria-label="Filter by source"
        >
          <option value="all">Source: All</option>
          {sourceOptions.bucketIds.map((bucketId) => (
            <option key={bucketId} value={`bucket:${bucketId}`}>
              {shortHashId(bucketId)}
            </option>
          ))}
          {sourceOptions.kinds.includes("vaultSpot") ? (
            <option value="vaultSpot">Vault Spot</option>
          ) : null}
          {sourceOptions.kinds.includes("lp") ? (
            <option value="lp">LP</option>
          ) : null}
          {sourceOptions.kinds.includes("transfer") ? (
            <option value="transfer">Transfer</option>
          ) : null}
        </select>
        <div className="terminal-search-field vault-activity-search-field">
          <input
            className="terminal-search-input"
            type="search"
            placeholder="Search asset"
            value={assetQuery}
            onChange={(e) => {
              setAssetQuery(e.target.value);
              setPage(0);
            }}
            aria-label="Search asset"
          />
        </div>
      </div>

      <VaultActivityTableShell
        gridColumns={GRID}
        minWidth={960}
        isEmpty={filteredRows.length === 0}
        emptyMessage="No activity."
        header={
          <>
            <TableHeaderCellStatic left>Time</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Type</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Source</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Market</TableHeaderCellStatic>
            <TableHeaderCellStatic left>Side</TableHeaderCellStatic>
            <TableHeaderCellStatic right>Size</TableHeaderCellStatic>
            <TableHeaderCellStatic right>Price</TableHeaderCellStatic>
            <TableHeaderCellStatic right>Fee</TableHeaderCellStatic>
            <TableHeaderCellStatic right>
              <TableHeaderLabel {...TABLE_HEADER_LABELS.closedPnl} />
            </TableHeaderCellStatic>
          </>
        }
        footer={
          <VaultTableFooter
            page={page}
            pageSize={pageSize}
            totalCount={filteredRows.length}
            onPageChange={setPage}
            onPageSizeChange={setPageSize}
          />
        }
      >
        {pageRows.map((row, index) => {
          const pnl = row.realizedPnl;
          const pnlColor =
            pnl == null
              ? undefined
              : pnl >= 0
                ? POSITION_PNL_COLOR_POSITIVE
                : POSITION_PNL_COLOR_NEGATIVE;
          const source = formatVaultActivitySource(row);
          const sourceTitle = vaultActivitySourceTitle(row);
          const isBucketSource = row.sourceKind === "bucket" && row.bucketId;

          return (
            <div
              key={`${row.time}-${row.activityType}-${row.market}-${index}`}
              className={`table-row ${index % 2 === 0 ? "even" : ""}${isBucketSource ? " clickable" : ""}`}
              style={{ gridTemplateColumns: GRID }}
              title={sourceTitle}
              role={isBucketSource ? "button" : undefined}
              tabIndex={isBucketSource ? 0 : undefined}
              onClick={
                isBucketSource ? () => handleSourceNavigate(row) : undefined
              }
              onKeyDown={
                isBucketSource
                  ? (e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        handleSourceNavigate(row);
                      }
                    }
                  : undefined
              }
            >
              <div className="table-cell">{formatDateTime(row.time)}</div>
              <div className="table-cell">{activityTypeLabel(row.activityType)}</div>
              <div
                className={`table-cell primary${isBucketSource ? " vault-activity-source-hash" : ""}`}
              >
                {source}
              </div>
              <div className="table-cell primary">{row.market}</div>
              <div className="table-cell">{row.side}</div>
              <div className="table-cell numeric">
                {formatOptionalNumber(row.size)}
              </div>
              <div className="table-cell numeric">
                {formatOptionalCurrency(row.price)}
              </div>
              <div className="table-cell numeric">
                {formatOptionalCurrency(row.fee)}
              </div>
              <div className="table-cell numeric" style={{ color: pnlColor }}>
                {pnl == null || pnl === 0 ? "—" : formatCurrency(pnl)}
              </div>
            </div>
          );
        })}
      </VaultActivityTableShell>
    </div>
  );
}
